def local_name(tag):
    return tag.split("}", 1)[-1] if "}" in tag else tag

def first(root, name):
    for elem in root.iter():
        if local_name(elem.tag) == name:
            return elem
    return None

def all_of(root, name):
    return [e for e in root.iter() if local_name(e.tag) == name]

def child(parent, name):
    if parent is None:
        return None
    for c in list(parent):
        if local_name(c.tag) == name:
            return c
    return None

def text(parent, name=None, default=""):
    elem = child(parent, name) if name else parent
    if elem is not None and elem.text:
        return elem.text.strip()
    return default

def only_digits(value):
    return "".join(ch for ch in str(value or "") if ch.isdigit())

def extract_cnpjs(value):
    """Extrai um ou mais CNPJs de uma célula.

    Aceita:
    - 15.186.966/0001-32
    - 15186966000132
    - 15.186.966/0001-32; 00.000.000/0001-00
    """
    text = str(value or "")
    if not text.strip():
        return []
    found = []
    for match in re.findall(r"\d{2}\D?\d{3}\D?\d{3}\D?\d{4}\D?\d{2}", text):
        digits = only_digits(match)
        if len(digits) == 14 and digits not in found:
            found.append(digits)
    if not found:
        digits = only_digits(text)
        if len(digits) == 14:
            found.append(digits)
    return found

def format_cnpj_cpf(value):
    d = only_digits(value)
    if len(d) == 14:
        return f"{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}"
    if len(d) == 11:
        return f"{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}"
    return value or ""

def format_cep(value):
    d = only_digits(value)
    if len(d) == 8:
        return f"{d[:5]}-{d[5:]}"
    return value or ""

def money(v):
    if v in (None, ""):
        return ""
    try:
        return f"{float(str(v).replace(',', '.')):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return str(v)

def money_float(v):
    try:
        return float(str(v or "0").replace(",", "."))
    except Exception:
        return 0.0

def qty(v, casas=4):
    if v in (None, ""):
        return ""
    try:
        return f"{float(str(v).replace(',', '.')):,.{casas}f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return str(v)

def date_br(v):
    if not v:
        return ""
    try:
        return f"{v[8:10]}/{v[5:7]}/{v[0:4]} {v[11:19]}"
    except Exception:
        return v

def format_chave(chave):
    d = only_digits(chave)
    return " ".join(d[i:i+4] for i in range(0, len(d), 4))

