# ============================================================================
# FIX 2.6.42 - Controle compacto PASSIVO, sem alterar status da validação
# Motivo: a 2.6.41 usava o cálculo compacto do DACTE como validação principal.
# Isso gerava falso DIVERGENTE quando o XML tinha outros componentes/regra diferente.
# Agora o bloco compacto é somente visual/auditoria e não muda esperado/diferença/status.
# ============================================================================
try:
    APP_VERSION = "Beta 2.6.42 Controle Passivo Sem Falso Divergente"
except Exception:
    pass


def _fix2642_component_label(info):
    try:
        frete_peso, frete_peso_found = _fix2641_component_value_any(info, ["FRETE PESO"])
        if frete_peso_found and abs(_fix2641_round_money(frete_peso)) > 0:
            return frete_peso, frete_peso_found, "FRETE PESO"
        frete_valor, frete_valor_found = _fix2641_component_value_any(info, ["FRETE VALOR"])
        if frete_valor_found and abs(_fix2641_round_money(frete_valor)) > 0:
            return frete_valor, frete_valor_found, "FRETE VALOR"
        frete_any, frete_any_found = _fix2641_component_value_any(info, ["FRETE"], exclude=["GRIS", "RISCO", "PEDAG", "PEDÁG", "ICMS", "TAXA"])
        if frete_any_found and abs(_fix2641_round_money(frete_any)) > 0:
            return frete_any, frete_any_found, "FRETE"
    except Exception:
        pass
    return 0.0, [], "FRETE"


def _fix2642_status_curto_from_original(result):
    s = norm_text((result or {}).get("status") or "")
    if "OK" in s and "DIVERG" not in s and "REGRA" not in s and "NAO" not in s and "NÃO" not in s:
        return "OK"
    if "DIVERG" in s:
        return "DIVERGENTE"
    if "PEND" in s or "REVIS" in s or "AMBIG" in s or "MÚLT" in s or "MULT" in s:
        return "REVISAR"
    return (result or {}).get("status") or "PENDENTE"


def _fix2642_apply_compact_control(result, info, base_data, tables):
    """Monta o bloco CONTROLE INTERNO sem tocar na validação principal.

    Campos que NÃO devem ser alterados aqui:
    status, esperado, diferenca, valor_comparado, componente_comparado,
    modo_calculo, base_calculo, frete_peso_calculado, percentual e frete_minimo.
    """
    try:
        if not isinstance(result, dict):
            return result
        if result.get("controle_dacte_compacto"):
            return result
        if info.get("tipo") != "CT-e":
            return result

        # Guarda a decisão original para garantir que o controle visual não mude o relatório.
        original_snapshot = {k: result.get(k) for k in (
            "status", "esperado", "diferenca", "valor_comparado", "componente_comparado",
            "modo_calculo", "base_calculo", "frete_peso_calculado", "percentual", "frete_minimo",
            "valor_total_xml", "tolerancia", "detalhe"
        )}

        pid = result.get("partner_id") or identify_partner(info, tables)
        if not pid or not tables or not base_data:
            return result
        base_rows = _fix2641_valid_base_rows(info, base_data, result.get("nfs_ignoradas"))
        if not base_rows or (len(base_rows) > 1 and not base_rows_have_same_route(base_rows)):
            result.setdefault("trace", []).append("Controle compacto 2.6.42 não aplicado: base não localizada ou múltiplas rotas.")
            return result
        base_row = base_rows[0]
        rule = choose_partner_rule(pid, base_row, tables)
        if not rule:
            result.setdefault("trace", []).append("Controle compacto 2.6.42 não aplicado: regra do parceiro não encontrada para a rota.")
            return result

        rule = _fix2641_rule_component_cfg(rule)
        raw = rule.get("raw") or {}
        ton_rate = rule.get("ton_rate", 0.0) or 0.0
        if not ton_rate:
            ton_rate = parse_number_br(_fix2641_raw_get(raw, "Tonelagem Mínima (R$/Ton)", "TONELAGEMMINIMARTON", "Tonelagem", "R$/Ton", "Valor Ton"))
        if not (rule.get("controle_dacte") or rule.get("gris_ativo") or rule.get("pedagio_ativo") or ton_rate):
            return result

        peso_kg, peso_source = peso_base_kg_from_info(info)
        valor_mercadoria = parse_number_br(info.get("valor_carga", ""))
        if valor_mercadoria <= 0:
            try:
                valor_mercadoria = sum(float(r.get("valor_mercadoria", 0.0) or 0.0) for r in base_rows)
            except Exception:
                valor_mercadoria = 0.0
        total_xml = parse_number_br(info.get("valor", ""))
        tolerance = tables.get("tolerance", 1.0) if isinstance(tables, dict) else 1.0

        partes = []
        comp_total = 0.0

        frete_xml, frete_found, frete_label = _fix2642_component_label(info)
        taxa_kg = (ton_rate / 1000.0) if ton_rate else 0.0
        minimum = rule.get("minimum", 0.0) or 0.0

        # Só mostra fórmula por kg quando há peso/taxa. Se o XML trouxe FRETE VALOR e a
        # fórmula por kg não fecha, mostra o frete XML como componente, sem causar divergência.
        if peso_kg > 0 and taxa_kg > 0:
            frete_formula_calc = _fix2641_round_money(max(peso_kg * taxa_kg, minimum))
            if frete_found and abs(_fix2641_round_money(frete_xml - frete_formula_calc)) <= tolerance:
                if minimum and minimum > peso_kg * taxa_kg:
                    partes.append(f"Frete: mín.={_fix2641_fmt_money_plain(frete_formula_calc)}")
                else:
                    partes.append(f"Frete: {_fix2641_fmt_num(peso_kg)}×{_fix2641_fmt_money_plain(taxa_kg)}={_fix2641_fmt_money_plain(frete_formula_calc)}")
                comp_total += frete_formula_calc
            elif frete_found:
                partes.append(f"{frete_label}: XML {_fix2641_fmt_money_plain(frete_xml)}")
                comp_total += _fix2641_round_money(frete_xml)
            else:
                # Sem componente de frete claro, mostra a regra como referência sem somar no bloco.
                if minimum and minimum > peso_kg * taxa_kg:
                    partes.append(f"Frete ref.: mín.={_fix2641_fmt_money_plain(frete_formula_calc)}")
                else:
                    partes.append(f"Frete ref.: {_fix2641_fmt_num(peso_kg)}×{_fix2641_fmt_money_plain(taxa_kg)}={_fix2641_fmt_money_plain(frete_formula_calc)}")
        elif frete_found:
            partes.append(f"{frete_label}: XML {_fix2641_fmt_money_plain(frete_xml)}")
            comp_total += _fix2641_round_money(frete_xml)

        gris_xml, gris_found = _fix2641_component_value_any(info, ["GRIS", "GERENCIAMENTO RISCO", "RISCO"])
        if rule.get("gris_ativo") and gris_found and abs(_fix2641_round_money(gris_xml)) > 0:
            gris_percent = rule.get("gris_percentual", 0.0) or 0.0
            gris_calc = _fix2641_round_money(valor_mercadoria * gris_percent) if gris_percent and valor_mercadoria else _fix2641_round_money(gris_xml)
            # Se a fórmula não fechar, mostra o valor cobrado para não criar alarme falso no bloco.
            if abs(_fix2641_round_money(gris_xml - gris_calc)) <= tolerance:
                partes.append(f"GRIS: {_fix2641_fmt_money_plain(valor_mercadoria)}×{_fix2641_fmt_percent_short(gris_percent)}={_fix2641_fmt_money_plain(gris_calc)}")
                comp_total += gris_calc
            else:
                partes.append(f"GRIS: XML {_fix2641_fmt_money_plain(gris_xml)}")
                comp_total += _fix2641_round_money(gris_xml)

        ped_xml, ped_found = _fix2641_component_value_any(info, ["PEDAG", "PEDÁGIO", "PEDAGIO"])
        if rule.get("pedagio_ativo") and ped_found and abs(_fix2641_round_money(ped_xml)) > 0:
            import math as _math
            ped_val = rule.get("pedagio_valor", 0.0) or 0.0
            ped_frac = rule.get("pedagio_fracao_kg", 100.0) or 100.0
            ped_qtd = int(_math.ceil(peso_kg / ped_frac)) if peso_kg > 0 and ped_frac > 0 else 0
            ped_calc = _fix2641_round_money(ped_qtd * ped_val) if ped_val else _fix2641_round_money(ped_xml)
            if ped_qtd and ped_val and abs(_fix2641_round_money(ped_xml - ped_calc)) <= tolerance:
                partes.append(f"Pedágio: {ped_qtd}×{_fix2641_fmt_money_plain(ped_val)}={_fix2641_fmt_money_plain(ped_calc)}")
                comp_total += ped_calc
            else:
                partes.append(f"Pedágio: XML {_fix2641_fmt_money_plain(ped_xml)}")
                comp_total += _fix2641_round_money(ped_xml)

        if not partes:
            return result

        comp_total = _fix2641_round_money(comp_total) if comp_total else total_xml
        diff_visual = _fix2641_round_money(total_xml - comp_total) if comp_total else 0.0
        status_curto = _fix2642_status_curto_from_original(original_snapshot)
        regra_nome = rule.get("controle_regra_nome") or "RODOTEC"
        linha1 = " | ".join(partes)
        # O total do bloco é informativo. A decisão fica presa ao status original da validação.
        linha2 = f"Total comp.: {_fix2641_fmt_money_rs(comp_total)} | XML: {_fix2641_fmt_money_rs(total_xml)} | Dif. comp.: {_fix2641_fmt_money_rs(diff_visual)} | Validação: {status_curto}"

        result.update({
            "controle_dacte_regra": regra_nome,
            "controle_dacte_linha1": linha1,
            "controle_dacte_linha2": linha2,
            "controle_dacte_status": status_curto,
            "controle_dacte_compacto": f"CONTROLE INTERNO - {regra_nome}\n{linha1}\n{linha2}",
        })
        tr = result.setdefault("trace", [])
        tr.append("Controle compacto 2.6.42 aplicado em modo passivo: não altera status, esperado ou diferença do relatório.")
        if rule.get("gris_ativo") and not gris_found:
            tr.append("GRIS cadastrado, mas não cobrado no XML; ocultado no controle compacto.")
        if rule.get("pedagio_ativo") and not ped_found:
            tr.append("Pedágio cadastrado, mas não cobrado no XML; ocultado no controle compacto.")
        tr.append(f"Linha compacta passiva: {linha1}")

        # Restaura invariavelmente a validação principal para matar falso divergente.
        for k, v in original_snapshot.items():
            if v is not None:
                result[k] = v
    except Exception as e:
        try:
            result.setdefault("trace", []).append(f"Controle compacto 2.6.42 falhou: {e}")
        except Exception:
            pass
    return result


try:
    _fix2642_orig_validate_cte_value = globals().get("_fix2641_orig_validate_cte_value") or validate_cte_value
    def validate_cte_value(info, base_data, tables):
        res = _fix2642_orig_validate_cte_value(info, base_data, tables)
        return _fix2642_apply_compact_control(res, info, base_data, tables)
except Exception:
    pass

