# ============================================================================
# FIX 2.6.43 - Cálculo compacto por tipo de regra + log ativo antes do mainloop
# Objetivo:
# - Expandir o bloco compacto para parceiros com regra PERCENTUAL/FIXO/KG_TON.
# - Suportar Pedágio por KG/fração e por CT-e/CTRC.
# - Herdar GRIS/Pedágio das colunas novas, da coluna antiga "Pedágio" e de REGRAS_EXTRAS.
# - Continuar PASSIVO: não altera status/esperado/diferença da validação principal.
# - Reativar log de importação de XML antes da tela principal abrir.
# ============================================================================
try:
    APP_VERSION = "Beta 2.6.43 Controle Compacto Modular"
except Exception:
    pass


def _fix2643_norm(v):
    try:
        return norm_text(v)
    except Exception:
        return str(v or "").upper().strip()


def _fix2643_raw_get(raw, *names):
    try:
        return _fix2641_raw_get(raw, *names)
    except Exception:
        if not isinstance(raw, dict):
            return ""
        for name in names:
            key = normalize_header(name)
            if key in raw and str(raw.get(key) or "").strip() != "":
                return raw.get(key)
            if name in raw and str(raw.get(name) or "").strip() != "":
                return raw.get(name)
        return ""


def _fix2643_yes(v):
    try:
        return _fix2641_yes(v)
    except Exception:
        return _fix2643_norm(v) in {"S", "SIM", "YES", "Y", "TRUE", "1", "ATIVO", "OK"}


def _fix2643_tipo_pedagio_from_text(*values):
    txt = _fix2643_norm(" ".join(str(v or "") for v in values))
    if not txt:
        return ""
    if any(k in txt for k in ("CTE", "CT E", "CT-E", "CTRC", "CONHECIMENTO", "EMISSAO", "EMISSÃO")):
        return "CTE"
    if any(k in txt for k in ("100", "KG", "PESO", "FRACAO", "FRAÇÃO", "TON")):
        return "KG"
    return ""


def _fix2643_find_related_rule(pid, base_row, tables, current_rule=None):
    """Procura uma linha da aba REGRAS_PERCENTUAL relacionada à regra/região atual.
    Usado principalmente para herdar a coluna antiga Pedágio de parceiros como JSP.
    """
    try:
        candidates = []
        cur_reg = (current_rule or {}).get("regiao", "")
        for r in (tables or {}).get("rules", []) or []:
            if r.get("partner_id") != pid:
                continue
            score = rule_matches_location(r, base_row)
            if score is not None:
                candidates.append((score + 20, r))
                continue
            if cur_reg and r.get("regiao") == cur_reg:
                candidates.append((30, r))
        if not candidates:
            return None
        candidates.sort(key=lambda x: (x[0], x[1].get("percent", 0), x[1].get("minimum", 0)), reverse=True)
        return candidates[0][1]
    except Exception:
        return None


def _fix2643_extra_cfg(pid, tables):
    cfg = {
        "gris_ativo": False,
        "gris_percentual": 0.0,
        "pedagio_ativo": False,
        "pedagio_valor": 0.0,
        "pedagio_tipo": "",
        "pedagio_fracao_kg": 0.0,
    }
    try:
        for e in (tables or {}).get("extras", []) or []:
            if e.get("partner_id") != pid:
                continue
            tipo = _fix2643_norm(e.get("tipo_extra", ""))
            base = _fix2643_norm(e.get("base_calculo", ""))
            obs = _fix2643_norm((e.get("raw") or {}).get("OBSERVACAO", "") or e.get("observacao", ""))
            if "GRIS" in tipo:
                pct = e.get("percent", 0.0) or parse_percent(_fix2643_raw_get(e.get("raw") or {}, "Percentual", "PERCENTUAL"))
                if pct:
                    cfg["gris_ativo"] = True
                    cfg["gris_percentual"] = pct
            if "PEDAG" in tipo or "PEDÁG" in tipo:
                val = e.get("valor_fixo", 0.0) or parse_number_br(_fix2643_raw_get(e.get("raw") or {}, "Valor", "VALOR", "Taxa", "TAXA"))
                if val:
                    cfg["pedagio_ativo"] = True
                    cfg["pedagio_valor"] = val
                    cfg["pedagio_tipo"] = _fix2643_tipo_pedagio_from_text(base, obs, tipo) or "CTE"
                    if cfg["pedagio_tipo"] == "KG":
                        # Se a descrição fala em 100 kg, usar fração 100. Caso contrário mantém 100 como padrão operacional.
                        cfg["pedagio_fracao_kg"] = 100.0
    except Exception:
        pass
    return cfg


def _fix2643_cfg(rule, pid, base_row, tables):
    # Começa aproveitando o saneamento da 2.6.41/2.6.42.
    try:
        cfg = _fix2641_rule_component_cfg(rule)
    except Exception:
        cfg = dict(rule or {})
    raw = cfg.get("raw") or {}

    related = _fix2643_find_related_rule(pid, base_row, tables, cfg)
    related_raw = (related or {}).get("raw") or {}

    # Tipo de cálculo compacto explícito na tabela, com fallback por dados da regra.
    tipo_calc = (
        _fix2643_raw_get(raw, "Tipo Cálculo Compacto", "Tipo Calculo Compacto", "Controle Tipo Cálculo", "Controle Tipo Calculo", "Modo Cálculo Compacto", "Modo Calculo Compacto")
        or _fix2643_raw_get(related_raw, "Tipo Cálculo Compacto", "Tipo Calculo Compacto", "Controle Tipo Cálculo", "Controle Tipo Calculo", "Modo Cálculo Compacto", "Modo Calculo Compacto")
    )
    tipo_calc_n = _fix2643_norm(tipo_calc)
    ton_rate = cfg.get("ton_rate", 0.0) or parse_number_br(
        _fix2643_raw_get(raw, "Tonelagem Mínima (R$/Ton)", "TONELAGEMMINIMARTON", "Tonelagem", "R$/Ton", "Valor Ton")
    )
    if not tipo_calc_n:
        if ton_rate:
            tipo_calc_n = "KG_TON"
        elif cfg.get("percent", 0.0) or cfg.get("minimum", 0.0):
            tipo_calc_n = "PERCENTUAL"
        else:
            tipo_calc_n = "SEM_BLOCO"

    if "SEM" in tipo_calc_n and "BLOCO" in tipo_calc_n:
        tipo_calc_n = "SEM_BLOCO"
    elif "KG" in tipo_calc_n or "TON" in tipo_calc_n:
        tipo_calc_n = "KG_TON"
    elif "FIXO" in tipo_calc_n or "MINIMO" in tipo_calc_n or "MÍNIMO" in tipo_calc_n:
        tipo_calc_n = "FIXO_MINIMO"
    elif "PERCENT" in tipo_calc_n or "%" in tipo_calc_n:
        tipo_calc_n = "PERCENTUAL"

    # GRIS: colunas novas ou extras.
    extras = _fix2643_extra_cfg(pid, tables)
    if not cfg.get("gris_ativo") and extras.get("gris_ativo"):
        cfg["gris_ativo"] = True
        cfg["gris_percentual"] = extras.get("gris_percentual", 0.0)
    if not cfg.get("gris_percentual") and extras.get("gris_percentual"):
        cfg["gris_percentual"] = extras.get("gris_percentual", 0.0)

    # Pedágio: colunas novas, coluna antiga Pedágio, regra relacionada ou extras.
    ped_tipo_raw = (
        _fix2643_raw_get(raw, "Tipo Pedágio", "Tipo Pedagio", "PEDAGIO TIPO", "TIPOPEDAGIO")
        or _fix2643_raw_get(related_raw, "Tipo Pedágio", "Tipo Pedagio", "PEDAGIO TIPO", "TIPOPEDAGIO")
    )
    ped_val_raw = (
        _fix2643_raw_get(raw, "Valor Pedágio", "Valor Pedagio", "Pedágio Valor", "Pedagio Valor")
        or _fix2643_raw_get(related_raw, "Valor Pedágio", "Valor Pedagio", "Pedágio Valor", "Pedagio Valor")
    )
    ped_frac_raw = (
        _fix2643_raw_get(raw, "Fração Pedágio KG", "Fracao Pedagio KG", "Fração KG", "Fracao KG", "Pedágio Fração KG", "Pedagio Fracao KG")
        or _fix2643_raw_get(related_raw, "Fração Pedágio KG", "Fracao Pedagio KG", "Fração KG", "Fracao KG", "Pedágio Fração KG", "Pedagio Fracao KG")
    )
    ped_old = _fix2643_raw_get(raw, "Pedágio", "Pedagio", "PEDAGIO") or _fix2643_raw_get(related_raw, "Pedágio", "Pedagio", "PEDAGIO")
    ped_old_val = parse_number_br(ped_old)
    ped_val = cfg.get("pedagio_valor", 0.0) or parse_number_br(ped_val_raw) or ped_old_val or extras.get("pedagio_valor", 0.0)
    ped_tipo = _fix2643_tipo_pedagio_from_text(ped_tipo_raw, ped_old, _fix2643_raw_get(raw, "Base Cálculo", "Base Calculo"), _fix2643_raw_get(related_raw, "Base Cálculo", "Base Calculo")) or extras.get("pedagio_tipo", "")
    ped_frac = cfg.get("pedagio_fracao_kg", 0.0) or parse_number_br(ped_frac_raw) or extras.get("pedagio_fracao_kg", 0.0)

    # Se tem valor de pedágio e não foi explicitamente 0, ativa. Se o texto antigo é 0, mantém inativo.
    if ped_val and ped_val > 0:
        cfg["pedagio_ativo"] = True
        cfg["pedagio_valor"] = ped_val
    if ped_tipo:
        cfg["pedagio_tipo"] = ped_tipo
    elif cfg.get("pedagio_ativo"):
        cfg["pedagio_tipo"] = "KG" if ped_frac else "CTE"
    if cfg.get("pedagio_tipo") == "KG":
        cfg["pedagio_fracao_kg"] = ped_frac or 100.0
    else:
        cfg["pedagio_fracao_kg"] = ped_frac or 0.0

    cfg["ton_rate"] = ton_rate
    cfg["controle_tipo_calculo"] = tipo_calc_n
    # Habilita controle para qualquer regra numérica, mas sem mexer na validação.
    # 2.6.44: ativa automaticamente somente KG_TON e PERCENTUAL.
    # FIXO_MINIMO e outros blocos complexos ficam desligados até homologação manual.
    cfg["controle_dacte"] = bool(cfg.get("controle_dacte")) or tipo_calc_n in {"KG_TON", "PERCENTUAL"}
    if not cfg.get("controle_regra_nome"):
        cfg["controle_regra_nome"] = pid or "CONTROLE"
    return cfg


def _fix2643_round(v):
    try:
        return _fix2641_round_money(v)
    except Exception:
        return round(float(v or 0.0), 2)


def _fix2643_money(v):
    try:
        return _fix2641_fmt_money_plain(v)
    except Exception:
        return money(v)


def _fix2643_money_rs(v):
    try:
        return _fix2641_fmt_money_rs(v)
    except Exception:
        return "R$" + money(v)


def _fix2643_num(v):
    try:
        return _fix2641_fmt_num(v)
    except Exception:
        try:
            f = float(v)
            if abs(f - int(f)) < 0.0001:
                return str(int(f))
            return (f"{f:.3f}".rstrip("0").rstrip(".")).replace(".", ",")
        except Exception:
            return str(v)


def _fix2643_percent(v):
    try:
        return _fix2641_fmt_percent_short(v)
    except Exception:
        try:
            return (f"{float(v or 0)*100:.4f}".rstrip("0").rstrip(".")).replace(".", ",") + "%"
        except Exception:
            return "-"


def _fix2643_component_value(info, keywords, exclude=()):
    try:
        return _fix2641_component_value_any(info, keywords, exclude=exclude)
    except TypeError:
        return _fix2641_component_value_any(info, keywords)


def _fix2643_frete_component(info):
    try:
        return _fix2642_component_label(info)
    except Exception:
        frete_xml, frete_found = _fix2643_component_value(info, ["FRETE"], exclude=["GRIS", "RISCO", "PEDAG", "PEDÁG", "ICMS", "TAXA"])
        return frete_xml, frete_found, "FRETE"


def _fix2643_status_curto(result):
    try:
        return _fix2642_status_curto_from_original(result)
    except Exception:
        s = _fix2643_norm((result or {}).get("status", ""))
        if "OK" in s and "DIVERG" not in s:
            return "OK"
        if "DIVERG" in s:
            return "DIVERGENTE"
        if "PEND" in s or "REVIS" in s:
            return "REVISAR"
        return (result or {}).get("status") or "PENDENTE"


def _fix2643_apply_compact_control(result, info, base_data, tables):
    """Controle compacto modular e PASSIVO. Nunca altera a validação principal."""
    try:
        if not isinstance(result, dict) or not isinstance(info, dict):
            return result
        if info.get("tipo") != "CT-e":
            return result

        original_snapshot = {k: result.get(k) for k in (
            "status", "esperado", "diferenca", "valor_comparado", "componente_comparado",
            "modo_calculo", "base_calculo", "frete_peso_calculado", "percentual", "frete_minimo",
            "valor_total_xml", "tolerancia", "detalhe"
        )}

        # Remove bloco antigo para reconstruir com a regra modular.
        for k in ("controle_dacte_regra", "controle_dacte_linha1", "controle_dacte_linha2", "controle_dacte_status", "controle_dacte_compacto"):
            result.pop(k, None)

        pid = result.get("partner_id") or identify_partner(info, tables)
        if not pid or not tables:
            return result
        base_rows = _fix2641_valid_base_rows(info, base_data, result.get("nfs_ignoradas")) if base_data else []
        if not base_rows:
            result.setdefault("trace", []).append("Controle compacto 2.6.43 não aplicado: NF/base não localizada.")
            return result
        if len(base_rows) > 1 and not base_rows_have_same_route(base_rows):
            result.setdefault("trace", []).append("Controle compacto 2.6.43 não aplicado: múltiplas rotas na base.")
            return result
        base_row = base_rows[0]

        rule = choose_partner_rule(pid, base_row, tables)
        if not rule:
            result.setdefault("trace", []).append("Controle compacto 2.6.43 não aplicado: regra do parceiro não encontrada.")
            return result
        cfg = _fix2643_cfg(rule, pid, base_row, tables)
        if not cfg.get("controle_dacte"):
            return result

        total_xml = parse_number_br(info.get("valor", ""))
        tolerance = (tables or {}).get("tolerance", 1.0) if isinstance(tables, dict) else 1.0
        partes = []
        comp_total = 0.0
        calc_type = cfg.get("controle_tipo_calculo", "SEM_BLOCO")

        # Bases comuns.
        peso_kg, _peso_source = peso_base_kg_from_info(info)
        valor_mercadoria = parse_number_br(info.get("valor_carga", ""))
        if valor_mercadoria <= 0:
            try:
                valor_mercadoria = sum(float(r.get("valor_mercadoria", 0.0) or 0.0) for r in base_rows)
            except Exception:
                valor_mercadoria = 0.0

        frete_xml, frete_found, frete_label = _fix2643_frete_component(info)
        frete_xml = _fix2643_round(frete_xml)

        # Se não achou componente FRETE separado, estima o frete XML tirando GRIS/Pedágio conhecidos do total.
        gris_xml_probe, gris_found_probe = _fix2643_component_value(info, ["GRIS", "GERENCIAMENTO RISCO", "RISCO"])
        ped_xml_probe, ped_found_probe = _fix2643_component_value(info, ["PEDAG", "PEDÁGIO", "PEDAGIO"])
        if not frete_found and total_xml:
            est = _fix2643_round(total_xml - _fix2643_round(gris_xml_probe) - _fix2643_round(ped_xml_probe))
            if est > 0:
                frete_xml = est
                frete_found = [("FRETE ESTIMADO", est)]
                frete_label = "FRETE"

        frete_ref = None
        if calc_type == "KG_TON":
            ton_rate = cfg.get("ton_rate", 0.0) or 0.0
            taxa_kg = ton_rate / 1000.0 if ton_rate else 0.0
            minimum = cfg.get("minimum", 0.0) or 0.0
            if peso_kg > 0 and taxa_kg > 0:
                bruto = _fix2643_round(peso_kg * taxa_kg)
                frete_ref = _fix2643_round(max(bruto, minimum))
                if minimum and minimum > bruto:
                    label = f"Frete: mín.={_fix2643_money(frete_ref)}"
                else:
                    label = f"Frete: {_fix2643_num(peso_kg)}×{_fix2643_money(taxa_kg)}={_fix2643_money(frete_ref)}"
                if frete_found and abs(_fix2643_round(frete_xml - frete_ref)) > tolerance:
                    label = f"Frete ref.: {_fix2643_num(peso_kg)}×{_fix2643_money(taxa_kg)}={_fix2643_money(frete_ref)} (XML {_fix2643_money(frete_xml)})"
                    comp_total += frete_xml
                else:
                    comp_total += frete_ref
                partes.append(label)
        elif calc_type in {"PERCENTUAL", "FIXO_MINIMO"}:
            base_calculo = cfg.get("base_calculo", "ORIGINAL")
            try:
                calc_base, calc_sources = sum_base_for_rule(base_rows, base_calculo)
            except Exception:
                calc_base, calc_sources = (base_row.get("valor_frete", 0.0) or 0.0, ["ORIGINAL"])
            percent = cfg.get("percent", 0.0) or 0.0
            minimum = cfg.get("minimum", 0.0) or 0.0
            if percent > 0:
                bruto = _fix2643_round(calc_base * percent)
                frete_ref = _fix2643_round(max(bruto, minimum))
                if minimum and minimum > bruto:
                    label = f"Frete: {_fix2643_money(calc_base)}×{_fix2643_percent(percent)}={_fix2643_money(bruto)}→mín.{_fix2643_money(frete_ref)}"
                else:
                    label = f"Frete: {_fix2643_money(calc_base)}×{_fix2643_percent(percent)}={_fix2643_money(frete_ref)}"
            elif minimum > 0:
                frete_ref = _fix2643_round(minimum)
                label = f"Frete mín.: {_fix2643_money(frete_ref)}"
            else:
                label = ""
            if label:
                if frete_found and abs(_fix2643_round(frete_xml - frete_ref)) > tolerance:
                    label = label.replace("Frete:", "Frete ref.:", 1) + f" (XML {_fix2643_money(frete_xml)})"
                    comp_total += frete_xml
                else:
                    comp_total += frete_ref
                partes.append(label)
        elif frete_found:
            partes.append(f"{frete_label}: XML {_fix2643_money(frete_xml)}")
            comp_total += frete_xml

        # Se nenhuma fórmula principal entrou, mas existe frete no XML, mostra o valor cobrado.
        if not any(str(p).startswith(("Frete", "FRETE")) for p in partes) and frete_found:
            partes.append(f"{frete_label}: XML {_fix2643_money(frete_xml)}")
            comp_total += frete_xml

        # GRIS: só calcula se cadastrado e cobrado; se cobrado sem regra, mostra XML.
        gris_xml, gris_found = _fix2643_component_value(info, ["GRIS", "GERENCIAMENTO RISCO", "RISCO"])
        gris_xml = _fix2643_round(gris_xml)
        if gris_found and abs(gris_xml) > 0:
            if cfg.get("gris_ativo") and (cfg.get("gris_percentual", 0.0) or 0.0) and valor_mercadoria:
                pct = cfg.get("gris_percentual", 0.0) or 0.0
                gris_ref = _fix2643_round(valor_mercadoria * pct)
                if abs(_fix2643_round(gris_xml - gris_ref)) <= tolerance:
                    partes.append(f"GRIS: {_fix2643_money(valor_mercadoria)}×{_fix2643_percent(pct)}={_fix2643_money(gris_ref)}")
                    comp_total += gris_ref
                else:
                    partes.append(f"GRIS ref.: {_fix2643_money(valor_mercadoria)}×{_fix2643_percent(pct)}={_fix2643_money(gris_ref)} (XML {_fix2643_money(gris_xml)})")
                    comp_total += gris_xml
            else:
                partes.append(f"GRIS: XML {_fix2643_money(gris_xml)}")
                comp_total += gris_xml

        # Pedágio: por KG/fração ou por CT-e.
        ped_xml, ped_found = _fix2643_component_value(info, ["PEDAG", "PEDÁGIO", "PEDAGIO"])
        ped_xml = _fix2643_round(ped_xml)
        if ped_found and abs(ped_xml) > 0:
            ped_val = cfg.get("pedagio_valor", 0.0) or 0.0
            ped_tipo = cfg.get("pedagio_tipo", "")
            ped_ref = None
            label = ""
            if cfg.get("pedagio_ativo") and ped_val > 0:
                if ped_tipo == "KG":
                    import math as _math
                    fracao = cfg.get("pedagio_fracao_kg", 100.0) or 100.0
                    qtd = int(_math.ceil(peso_kg / fracao)) if peso_kg > 0 and fracao > 0 else 0
                    ped_ref = _fix2643_round(qtd * ped_val)
                    label = f"Pedágio: {qtd}×{_fix2643_money(ped_val)}={_fix2643_money(ped_ref)}"
                else:
                    qtd = 1
                    ped_ref = _fix2643_round(qtd * ped_val)
                    label = f"Pedágio: {qtd}×{_fix2643_money(ped_val)}={_fix2643_money(ped_ref)}"
                if ped_ref is not None and abs(_fix2643_round(ped_xml - ped_ref)) > tolerance:
                    label = label.replace("Pedágio:", "Pedágio ref.:", 1) + f" (XML {_fix2643_money(ped_xml)})"
                    comp_total += ped_xml
                else:
                    comp_total += ped_ref or 0.0
                partes.append(label)
            else:
                partes.append(f"Pedágio: XML {_fix2643_money(ped_xml)}")
                comp_total += ped_xml

        if not partes:
            return result

        comp_total = _fix2643_round(comp_total)
        diff_visual = _fix2643_round(total_xml - comp_total)
        status_curto = _fix2643_status_curto(original_snapshot)
        regra_nome = cfg.get("controle_regra_nome") or pid or "CONTROLE"
        linha1 = " | ".join(partes)
        linha2 = f"Total comp.: {_fix2643_money_rs(comp_total)} | XML: {_fix2643_money_rs(total_xml)} | Dif. comp.: {_fix2643_money_rs(diff_visual)} | Validação: {status_curto}"

        result.update({
            "controle_dacte_regra": regra_nome,
            "controle_dacte_linha1": linha1,
            "controle_dacte_linha2": linha2,
            "controle_dacte_status": status_curto,
            "controle_dacte_compacto": f"CONTROLE INTERNO - {regra_nome}\n{linha1}\n{linha2}",
        })
        tr = result.setdefault("trace", [])
        tr.append(f"Controle compacto 2.6.43 aplicado: tipo {calc_type}; passivo; não altera validação principal.")
        if cfg.get("gris_ativo") and not gris_found:
            tr.append("GRIS cadastrado, mas não cobrado no XML; ocultado no controle compacto.")
        if cfg.get("pedagio_ativo") and not ped_found:
            tr.append("Pedágio cadastrado, mas não cobrado no XML; ocultado no controle compacto.")
        tr.append(f"Linha compacta 2.6.43: {linha1}")

        # Restaura a validação principal.
        for k, v in original_snapshot.items():
            if v is not None:
                result[k] = v
    except Exception as e:
        try:
            result.setdefault("trace", []).append(f"Controle compacto 2.6.43 falhou: {e}")
        except Exception:
            pass
    return result


try:
    _fix2643_orig_validate_cte_value = validate_cte_value
    def validate_cte_value(info, base_data, tables):
        res = _fix2643_orig_validate_cte_value(info, base_data, tables)
        return _fix2643_apply_compact_control(res, info, base_data, tables)
except Exception:
    pass


# Log de importação ativo antes do mainloop. Mantém dedup por chave fiscal e abre a janela resumo.
def _fix2643_install_import_log():
    try:
        import tkinter as _tk
        from tkinter import ttk as _ttk
        from pathlib import Path as _Path
        import hashlib as _hashlib
        import xml.etree.ElementTree as _ET
    except Exception:
        return

    def _digits(v):
        try:
            return only_digits(v)
        except Exception:
            return re.sub(r"\D", "", str(v or ""))

    def _norm_path(p):
        try:
            return str(_Path(p).resolve()).lower()
        except Exception:
            return str(p or "").lower()

    def _sha1_file(p):
        try:
            h = _hashlib.sha1()
            with open(p, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""

    def _xml_key(path):
        p = _Path(path)
        if not p.exists():
            return "MISS:" + _norm_path(path)
        if p.suffix.lower() != ".xml":
            return "PATH:" + _norm_path(path)
        try:
            root = _ET.parse(p).getroot()
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("infCte", "infNFe", "infMDFe"):
                    d = _digits(elem.attrib.get("Id", ""))
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("chCTe", "chNFe", "chMDFe", "chave"):
                    d = _digits(elem.text or "")
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
        except Exception:
            pass
        digest = _sha1_file(p)
        return ("XMLSHA1:" + digest) if digest else ("PATH:" + _norm_path(path))

    def _info_path(info):
        if isinstance(info, dict):
            return str(info.get("path") or info.get("caminho") or info.get("arquivo_path") or info.get("arquivo") or "")
        for attr in ("path", "caminho", "arquivo_path", "arquivo"):
            try:
                v = getattr(info, attr)
                if v:
                    return str(v)
            except Exception:
                pass
        return str(info) if isinstance(info, (str, _Path)) else ""

    def _info_key(info):
        if isinstance(info, dict):
            for field in ("dedup_key", "chave", "chCTe", "chave_cte", "chave_nfe", "chNFe", "id", "Id"):
                val = info.get(field, "")
                if field == "dedup_key" and str(val or "").startswith(("CHAVE:", "XMLSHA1:", "PATH:", "META:")):
                    return str(val)
                d = _digits(val)
                if len(d) >= 44:
                    return "CHAVE:" + d[-44:]
            p = _info_path(info)
            if p:
                return _xml_key(p) if str(p).lower().endswith(".xml") else "PATH:" + _norm_path(p)
            tipo = norm_text(info.get("tipo") or "")
            numero = _digits(info.get("numero") or info.get("nCT") or "")
            serie = _digits(info.get("serie") or "")
            emit = norm_text(info.get("emitente") or "")
            if numero:
                return "META:" + "|".join([tipo, numero, serie, emit[:70]])
        p = _info_path(info)
        if p:
            return _xml_key(p) if str(p).lower().endswith(".xml") else "PATH:" + _norm_path(p)
        return "OBJ:" + str(id(info))

    def _clean(files):
        fixed, seen, removed = [], set(), []
        for info in list(files or []):
            key = _info_key(info)
            if key in seen:
                removed.append({"key": key, "arquivo": _Path(_info_path(info)).name if _info_path(info) else "", "motivo": "duplicado antigo removido"})
                continue
            if isinstance(info, dict):
                try:
                    info["dedup_key"] = key
                except Exception:
                    pass
            seen.add(key)
            fixed.append(info)
        return fixed, removed, seen

    def _fmt_key(key):
        key = str(key or "")
        if key.startswith("CHAVE:"):
            return key.split(":", 1)[1][-12:]
        if key.startswith("PATH:"):
            return _Path(key.split(":", 1)[1]).name
        if len(key) > 60:
            return key[:57] + "..."
        return key

    def _log_text(log):
        lines = [
            "LOG DE IMPORTAÇÃO DE XML/CT-e",
            "-" * 56,
            f"Arquivos selecionados: {log.get('selected', 0)}",
            f"CT-e adicionados nesta importação: {log.get('added', 0)}",
            f"CT-e repetidos ignorados: {log.get('skipped', 0)}",
        ]
        if log.get("cleaned"):
            lines.append(f"Duplicados antigos removidos da lista: {log.get('cleaned', 0)}")
        lines += [
            f"Erros: {log.get('errors_count', 0)}",
            f"Total real na lista: {log.get('total', 0)}",
        ]
        if log.get("duplicates"):
            lines += ["", "Repetidos ignorados:"]
            for rec in log.get("duplicates", [])[:250]:
                lines.append(f"- {_fmt_key(rec.get('key'))} | {rec.get('arquivo') or '-'} | {rec.get('motivo') or 'repetido'}")
        if log.get("errors"):
            lines += ["", "Erros:"]
            for err in log.get("errors", [])[:80]:
                lines.append(f"- {err}")
        return "\n".join(lines)

    def _show_log(self, log):
        text = _log_text(log)
        try:
            win = _tk.Toplevel(self)
            win.title("Log de importação de XMLs")
            win.geometry("760x500")
            win.configure(bg="#f6faff")
            _tk.Label(win, text="Log de importação de XML/CT-e", bg="#f6faff", fg="#08357c", font=("Segoe UI", 16, "bold")).pack(anchor="w", padx=16, pady=(14, 8))
            cards = _tk.Frame(win, bg="#f6faff")
            cards.pack(fill="x", padx=14)
            def card(label, value, bg, fg):
                f = _tk.Frame(cards, bg=bg, highlightbackground="#d8e5f8", highlightthickness=1)
                _tk.Label(f, text=label, bg=bg, fg=fg, font=("Segoe UI", 9, "bold")).pack(anchor="w", padx=10, pady=(8, 0))
                _tk.Label(f, text=str(value), bg=bg, fg=fg, font=("Segoe UI", 20, "bold")).pack(padx=10, pady=(0, 8))
                f.pack(side="left", fill="x", expand=True, padx=4)
            card("Selecionados", log.get("selected", 0), "#eef4ff", "#08357c")
            card("Adicionados", log.get("added", 0), "#dcfce7", "#008236")
            card("Repetidos", log.get("skipped", 0), "#fff7db", "#996b00")
            card("Total real", log.get("total", 0), "#eef4ff", "#08357c")
            body = _tk.Frame(win, bg="#f6faff")
            body.pack(fill="both", expand=True, padx=16, pady=12)
            txt = _tk.Text(body, wrap="word", font=("Consolas", 10), bg="#ffffff", fg="#0b2341", relief="solid", borderwidth=1)
            y = _ttk.Scrollbar(body, orient="vertical", command=txt.yview)
            txt.configure(yscrollcommand=y.set)
            txt.grid(row=0, column=0, sticky="nsew")
            y.grid(row=0, column=1, sticky="ns")
            body.rowconfigure(0, weight=1)
            body.columnconfigure(0, weight=1)
            txt.insert("1.0", text)
            txt.configure(state="disabled")
            footer = _tk.Frame(win, bg="#f6faff")
            footer.pack(fill="x", padx=16, pady=(0, 14))
            def copy_log():
                try:
                    self.clipboard_clear()
                    self.clipboard_append(text)
                except Exception:
                    pass
            _tk.Button(footer, text="Copiar log", command=copy_log, bg="#ffffff", fg="#08357c", font=("Segoe UI", 10, "bold"), relief="solid", borderwidth=1, padx=14, pady=5).pack(side="right", padx=(8, 0))
            _tk.Button(footer, text="Fechar", command=win.destroy, bg="#ffffff", fg="#0b2341", font=("Segoe UI", 10), relief="solid", borderwidth=1, padx=14, pady=5).pack(side="right", padx=(8, 0))
            try:
                win.lift()
                win.focus_force()
            except Exception:
                pass
        except Exception:
            try:
                messagebox.showinfo(APP_TITLE, text)
            except Exception:
                pass

    def _refresh(self):
        for name in ("refresh_table", "update_table", "refresh_xml_table", "atualizar_tabela"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                    break
                except Exception:
                    pass
        for name in ("update_stats", "update_cards"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def _add_paths_2643(self, paths):
        if getattr(self, "_fix2643_import_busy", False):
            return None
        self._fix2643_import_busy = True
        try:
            incoming = []
            for raw in list(paths or []):
                try:
                    p = _Path(raw)
                    if p.is_dir():
                        for ext in [".xml", ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".txt", ".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff"]:
                            incoming.extend(p.glob(f"*{ext}"))
                    else:
                        incoming.append(p)
                except Exception:
                    pass
            fixed, cleaned_records, known_keys = _clean(getattr(self, "files", []) or [])
            self.files = fixed
            known_paths = set(_norm_path(_info_path(i)) for i in self.files if _info_path(i))
            added = skipped = 0
            errors = []
            duplicates = []
            for p in incoming:
                try:
                    if not p.exists():
                        errors.append(f"{p}: arquivo não encontrado")
                        continue
                    npath = _norm_path(p)
                    pre_key = _xml_key(p) if p.suffix.lower() == ".xml" else "PATH:" + npath
                    if pre_key in known_keys or npath in known_paths:
                        skipped += 1
                        duplicates.append({"key": pre_key, "arquivo": p.name, "motivo": "já carregado ou duplicado no lote"})
                        continue
                    try:
                        if p.suffix.lower() == ".xml":
                            info = parse_xml(p)
                        else:
                            info = {"tipo": p.suffix.upper().replace(".", ""), "numero": "", "serie": "", "emitente": "", "destinatario": "", "valor": "", "arquivo": p.name, "path": str(p)}
                    except Exception as e:
                        errors.append(f"{p.name}: {e}")
                        continue
                    if isinstance(info, dict):
                        info.setdefault("arquivo", p.name)
                        info["path"] = str(p)
                    post_key = _info_key(info) or pre_key
                    if post_key in known_keys:
                        skipped += 1
                        duplicates.append({"key": post_key, "arquivo": p.name, "motivo": "chave fiscal já carregada"})
                        continue
                    if isinstance(info, dict):
                        info["dedup_key"] = post_key
                    try:
                        self.files.append(info)
                    except Exception:
                        self.files = [info]
                    known_keys.add(post_key)
                    known_paths.add(npath)
                    added += 1
                except Exception as e:
                    errors.append(f"{getattr(p, 'name', p)}: {e}")
            fixed2, cleaned2, _ = _clean(getattr(self, "files", []) or [])
            self.files = fixed2
            cleaned_all = (cleaned_records or []) + (cleaned2 or [])
            _refresh(self)
            log = {
                "selected": len(incoming), "added": added, "skipped": skipped,
                "cleaned": len(cleaned_all), "cleaned_records": cleaned_all,
                "errors_count": len(errors), "errors": errors, "duplicates": duplicates,
                "total": len(getattr(self, "files", []) or [])
            }
            self.last_import_log = log
            try:
                self.set_status(f"Importação XML: {added} adicionado(s), {skipped} repetido(s) ignorado(s). Total real: {log['total']}.")
            except Exception:
                pass
            if errors:
                try:
                    messagebox.showwarning(APP_TITLE, "Alguns arquivos não foram carregados:\n\n" + "\n".join(errors[:10]))
                except Exception:
                    pass
            if incoming:
                try:
                    self.after(80, lambda l=log: _show_log(self, l))
                except Exception:
                    _show_log(self, log)
            return None
        finally:
            self._fix2643_import_busy = False

    def _add_files_2643(self):
        paths = filedialog.askopenfilenames(
            title="Selecione arquivos",
            initialdir=str(self.work_folders.get("xmls", app_runtime_dir())) if hasattr(self, "work_folders") else str(app_runtime_dir()),
            filetypes=[("Documentos suportados", "*.xml *.pdf *.doc *.docx *.xls *.xlsx *.txt *.jpg *.jpeg *.png *.bmp *.tif *.tiff"), ("Todos", "*.*")]
        )
        return _add_paths_2643(self, paths)

    def _add_folder_2643(self):
        folder = filedialog.askdirectory(title="Selecione uma pasta", initialdir=str(self.work_folders.get("xmls", app_runtime_dir())) if hasattr(self, "work_folders") else str(app_runtime_dir()))
        if not folder:
            return None
        return _add_paths_2643(self, [_Path(folder)])

    try:
        AppCls = globals().get("App")
        if AppCls is not None:
            AppCls.add_paths = _add_paths_2643
            AppCls.add_files = _add_files_2643
            AppCls.add_folder = _add_folder_2643
            AppCls._hotfix_log_xml_contagem_correta_2638 = True
            AppCls._hotfix_add_paths_log_2636 = True
            AppCls._hotfix_log_importacao_xml_2636 = True
            AppCls._fix2643_import_log = True
    except Exception:
        pass


try:
    _fix2643_install_import_log()
except Exception:
    pass

