# ============================================================================
# HOTFIX Faturas Parceiros 2.6.29
# Corrige a leitura sem substituir o parser original por um parser rígido.
# Estratégia: usa o leitor nativo do programa, sanitiza fatura/parceiro,
# remove duplicidades e refaz a tabela/relatório depois do processamento.
# ============================================================================

def _central_cte_hotfix_faturas_2629_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main_with_faturas()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2629_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.29] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2629").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2629_apply(_main):
    import re as _re
    from pathlib import Path as _Path
    from datetime import datetime as _datetime, timedelta as _timedelta

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2629", False):
        return

    _orig_parse_invoice = getattr(FaturasPage, "parse_invoice_text", None)
    _orig_parse_ssw = getattr(FaturasPage, "parse_ssw_len_invoice_text", None)
    _orig_process = getattr(FaturasPage, "process_invoices", None)

    def _strip_accents(value):
        try:
            import unicodedata
            return "".join(c for c in unicodedata.normalize("NFD", str(value or "")) if unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _route_norm(value):
        text = _strip_accents(str(value or "")).upper()
        return _re.sub(r"\s+", " ", _re.sub(r"[^A-Z0-9]+", " ", text)).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        fn = getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        fn = getattr(_main, "money", None)
        if callable(fn):
            try:
                return fn(value)
            except Exception:
                pass
        try:
            return f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "0,00"

    def _is_bad_invoice(value):
        s = _norm_space(value)
        if not s:
            return True
        up = _strip_accents(s).upper()
        if up.startswith("EMISS"):
            return True
        if up in {"FAT", "FATURA", "FATURAMENTO", "DOCUMENTO", "DOC", "N", "NO", "Nº", "NUMERO", "NÚMERO", "NAO IDENTIFICADA", "NÃO IDENTIFICADA"}:
            return True
        return False

    def _format_invoice(base, dig):
        base_digits = _re.sub(r"\D", "", str(base or "")).lstrip("0") or "0"
        dig_digits = _re.sub(r"\D", "", str(dig or ""))[:1]
        if not dig_digits:
            return ""
        return f"{base_digits.zfill(7)}-{dig_digits}"

    def _normalize_invoice_id(value):
        text = _norm_space(value)
        if _is_bad_invoice(text):
            return ""
        patterns = [
            r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOC(?:UMENTO)?)\s*[^0-9]{0,20}(0*\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOC(?:UMENTO)?)\s*[^0-9]{0,20}(0*\d{3,9})\s*[-/]\s*(\d)",
        ]
        for pat in patterns:
            m = _re.search(pat, text)
            if m:
                out = _format_invoice(m.group(1), m.group(2))
                if out:
                    return out
        return ""

    def _extract_invoice_id(text, path=None):
        clean = str(text or "").replace("\xa0", " ")
        # Prioriza campos explícitos para não confundir emissão com número de fatura.
        labeled_patterns = [
            r"(?i)(?:N[ºO°.]?\s*do\s*Documento|Numero\s*do\s*Documento|Número\s*do\s*Documento)\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)(?:FATURA|FAT\.?|FATURAMENTO|DOCUMENTO|DOC)\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOCUMENTO|DOC)\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
        ]
        for pat in labeled_patterns:
            for m in _re.finditer(pat, clean):
                if len(m.groups()) >= 2 and m.group(2):
                    out = _format_invoice(m.group(1), m.group(2))
                else:
                    out = _normalize_invoice_id(m.group(1))
                if out:
                    return out
        # Depois procura qualquer 000000-0 solto.
        for m in _re.finditer(r"(?<!\d)(0*\d{4,9}\s*[-/]\s*\d)(?!\d)", clean):
            out = _normalize_invoice_id(m.group(1))
            if out:
                return out
        if path:
            stem = _Path(path).stem
            out = _normalize_invoice_id(stem)
            if out:
                return out
        return ""

    def _invalid_partner_name(value):
        s = _norm_space(value)
        if not s or s in {"-", "_"}:
            return True
        up = _strip_accents(s).upper()
        if up.startswith("FAT") and _re.search(r"\d", up):
            return True
        if _normalize_invoice_id(s):
            return True
        bad_terms = ["EMISSAO", "EMISSÃO", "VENCIMENTO", "VALOR DO DOCUMENTO", "COMPROVANTE DE ENTREGA", "FRETE TERCEIRO PAGADOR"]
        if any(term in up for term in bad_terms):
            return True
        letters = _re.sub(r"[^A-Z]", "", up)
        if len(letters) < 4:
            return True
        return False

    def _clean_partner_candidate(value):
        s = _norm_space(value)
        if not s:
            return ""
        s = _re.sub(r"(?i)\b(CNPJ|CPF|CNPJ/CPF)\b\s*[:\-]?\s*[\d./\- ]+", "", s)
        s = _re.sub(r"(?i)\b(IE|INSC\.?\s*EST\.?)\b\s*[:\-]?\s*[\d./\- ]+", "", s)
        s = _re.sub(r"(?i)\b(FATURA|FAT\.?|DOCUMENTO|DOC)\b\s*[:\-]?\s*\d+[\d()\-/ ]*", "", s)
        s = _re.sub(r"\s+(?:\d[\d./\- ]{5,})$", "", s)
        s = _norm_space(s.strip(" -–—/"))
        if _invalid_partner_name(s):
            return ""
        return s[:90]

    def _extract_partner(text, path=None):
        raw = str(text or "").replace("\xa0", " ")
        patterns = [
            r"(?im)^\s*(?:Parceiro|Transportador|Prestador|Fornecedor|Subcontratado|Favorecido|Emitente)\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*Raz[aã]o\s+Social\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*Nome\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*([A-ZÁÉÍÓÚÃÕÇ0-9 .,&/\-]{6,}?(?:TRANSP|TRANSPORT|TRANSPORTE|TRANSPORTES|LOGIST|LOGISTICA|LOGÍSTICA|CARGAS|LTDA|EIRELI|ME\b|S/A|SERVI[CÇ]OS)[A-ZÁÉÍÓÚÃÕÇ0-9 .,&/\-]*)\s*(?:CNPJ|CPF|$)",
        ]
        for pat in patterns:
            for m in _re.finditer(pat, raw, _re.I):
                cand = _clean_partner_candidate(m.group(1))
                if cand and "RODOVITOR" not in _strip_accents(cand).upper():
                    return cand
        for line in raw.splitlines():
            line2 = _norm_space(line)
            up = _strip_accents(line2).upper()
            if not line2 or "RODOVITOR" in up:
                continue
            if any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "SERVICOS", "SERVIÇOS")):
                if not any(bad in up for bad in ("FATURA", "EMISSAO", "VENCIMENTO", "VALOR", "COMPROVANTE DE ENTREGA")):
                    cand = _clean_partner_candidate(line2)
                    if cand:
                        return cand
        if path:
            stem = _Path(path).stem.replace("_", " ")
            cand = _clean_partner_candidate(stem)
            if cand:
                return cand
        return ""

    def _money_values_from_text(line):
        pat = r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}"
        return _re.findall(pat, str(line or ""))

    def _normalize_cte_label(value):
        s = _norm_space(value).upper()
        if not s:
            return ""
        m = _re.search(r"([A-Z]{2,5})\s*/\s*(\d{3,9})\s*[-/]\s*(\d)", s)
        if m:
            return f"{m.group(1)}/{m.group(2).lstrip('0') or '0'}-{m.group(3)}"
        m = _re.search(r"([A-Z]{2,5})(\d{3,9})\s*[-/]\s*(\d)", s)
        if m:
            return f"{m.group(1)}/{m.group(2).lstrip('0') or '0'}-{m.group(3)}"
        m = _re.search(r"(?:CT\s*-?\s*E|CTE|CTRC|CONHECIMENTO)\D{0,25}(\d{3,12})(?:\s*[-/]\s*(\d))?", s, _re.I)
        if m:
            num = m.group(1).lstrip("0") or "0"
            return f"CTE {num}{('-' + m.group(2)) if m.group(2) else ''}"
        return s[:50]

    def _nf_from_line(line):
        for pat in [r"(?:NF|NOTA(?:\s+FISCAL)?)\D{0,20}(\d{2,12})", r"\b(\d{5,12})\b"]:
            m = _re.search(pat, str(line or ""), _re.I)
            if m:
                return (m.group(1).lstrip("0") or m.group(1))
        return ""

    def _dedupe_items(items):
        out, seen = [], set()
        for item in items or []:
            if not isinstance(item, dict):
                continue
            cte_label = item.get("cte_ref") or item.get("cte") or item.get("ctrc") or item.get("numero") or ""
            cte_key = _norm_cmp(cte_label)
            nf_key = _norm_cmp(item.get("nf") or item.get("nota_fiscal") or item.get("nf_original") or "")
            val_key = round(_parse_money(item.get("valor_fatura") or item.get("valor_ctrc_frete") or item.get("frete") or item.get("valor")), 2)
            line_key = _norm_cmp(item.get("linha") or "")[:80]
            key = (cte_key or line_key, nf_key, val_key)
            if not key[0]:
                continue
            if key in seen:
                continue
            seen.add(key)
            if not item.get("cte_ref") and cte_label:
                item["cte_ref"] = cte_label
            if not item.get("cte") and cte_label:
                item["cte"] = cte_label
            out.append(item)
        return out

    def _fallback_parse_invoice_text(text, path):
        p = _Path(path)
        clean = str(text or "").replace("\xa0", " ")
        fat = _extract_invoice_id(clean, path) or "NÃO IDENTIFICADA"
        partner = _extract_partner(clean, path)
        items = []
        cte_patterns = [
            r"([A-Z]{2,5}\s*/\s*\d{3,9}\s*[-/]\s*\d)",
            r"\b([A-Z]{2,5}\d{3,9}\s*[-/]\s*\d)\b",
            r"(?:CT\s*-?\s*E|CTE|CTRC|CONHECIMENTO)\D{0,25}(\d{3,12}(?:\s*[-/]\s*\d)?)",
        ]
        # Lê por linha primeiro.
        for raw in clean.splitlines():
            line = _norm_space(raw)
            if not line:
                continue
            found = []
            for pat in cte_patterns:
                for m in _re.finditer(pat, line, _re.I):
                    label = _normalize_cte_label(m.group(1))
                    if label:
                        found.append(label)
            if not found:
                continue
            vals = _money_values_from_text(line)
            value = _parse_money(vals[-1]) if vals else 0.0
            nf = _nf_from_line(line)
            for cte in found:
                items.append({"cte": cte, "cte_ref": cte, "nf": nf, "valor_fatura": value, "linha": line})
        # Se o PDF veio todo colado, tenta janelas ao redor dos CT-es.
        if not items:
            for pat in cte_patterns:
                for m in _re.finditer(pat, clean, _re.I):
                    around = clean[max(0, m.start() - 120):m.end() + 180]
                    label = _normalize_cte_label(m.group(1))
                    if not label:
                        continue
                    vals = _money_values_from_text(around)
                    items.append({"cte": label, "cte_ref": label, "nf": _nf_from_line(around), "valor_fatura": _parse_money(vals[-1]) if vals else 0.0, "linha": _norm_space(around)})
        return {"arquivo": p.name, "path": str(p), "fatura": fat, "parceiro": partner, "items": _dedupe_items(items), "texto": clean[:5000]}

    def _sanitize_doc(doc, text, path):
        p = _Path(path)
        if not isinstance(doc, dict):
            doc = {}
        clean = str(text or doc.get("texto") or "").replace("\xa0", " ")
        doc.setdefault("arquivo", p.name)
        doc.setdefault("path", str(p))
        fat = _normalize_invoice_id(doc.get("fatura")) or _extract_invoice_id(clean, path)
        if not fat:
            fat = "NÃO IDENTIFICADA"
        doc["fatura"] = fat
        partner = _clean_partner_candidate(doc.get("parceiro")) or _extract_partner(clean, path)
        doc["parceiro"] = partner or "Parceiro não identificado"
        doc["items"] = _dedupe_items(doc.get("items") or [])
        if clean and not doc.get("texto"):
            doc["texto"] = clean[:5000]
        return doc

    def patched_parse_invoice_text(self, text, path):
        doc = None
        if callable(_orig_parse_invoice):
            try:
                doc = _orig_parse_invoice(self, text, path)
            except Exception:
                doc = None
        fb = None
        if not isinstance(doc, dict) or not (doc.get("items") or []):
            fb = _fallback_parse_invoice_text(text, path)
            if not isinstance(doc, dict) or (fb.get("items") and not doc.get("items")):
                doc = fb
        doc = _sanitize_doc(doc, text, path)
        return doc

    def patched_parse_ssw_len_invoice_text(self, text, path):
        doc = None
        if callable(_orig_parse_ssw):
            try:
                doc = _orig_parse_ssw(self, text, path)
            except Exception:
                doc = None
        fb = None
        if not isinstance(doc, dict) or not (doc.get("items") or []):
            fb = _fallback_parse_invoice_text(text, path)
            if not isinstance(doc, dict) or (fb.get("items") and not doc.get("items")):
                doc = fb
        return _sanitize_doc(doc, text, path)

    def _fmt_excel_datetime(value):
        s = _norm_space(value)
        if not s or s == "-":
            return ""
        if _re.search(r"\d{1,2}/\d{1,2}/\d{2,4}", s):
            return s
        nums = _re.findall(r"\d+(?:[\.,]\d+)?", s)
        if not nums:
            return s
        try:
            date_num = float(nums[0].replace(",", "."))
            if not (1 <= date_num <= 80000):
                return s
            base_dt = _datetime(1899, 12, 30) + _timedelta(days=int(date_num))
            time_txt = ""
            if len(nums) >= 2:
                frac = float(nums[1].replace(",", "."))
                if 0 <= frac < 1:
                    minutes = int(round(frac * 24 * 60))
                    hh = (minutes // 60) % 24
                    mm = minutes % 60
                    time_txt = f" {hh:02d}:{mm:02d}"
            return base_dt.strftime("%d/%m/%Y") + time_txt
        except Exception:
            return s

    def _record_cte_key(rec):
        return _norm_cmp(rec.get("CT-e fatura") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("CT-e") or "")

    def _record_is_ok(rec):
        st = _strip_accents(str(rec.get("Status final CT-e") or "")).upper()
        return st.startswith("OK") or st == "OK PAGAR"

    def _record_is_problem(rec):
        return not _record_is_ok(rec)

    def _record_value(rec):
        return _parse_money(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("Valor não pagar") or 0)

    def _record_no_pay(rec):
        v = _parse_money(rec.get("Valor não pagar"))
        if v:
            return v
        return _record_value(rec) if _record_is_problem(rec) else 0.0

    def _build_doc_maps(self):
        by_fat = {}
        by_file = {}
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            fat = _normalize_invoice_id(doc.get("fatura")) or _extract_invoice_id(doc.get("texto", ""), doc.get("path"))
            partner = _clean_partner_candidate(doc.get("parceiro")) or _extract_partner(doc.get("texto", ""), doc.get("path"))
            info = {"fatura": fat, "partner": partner, "doc": doc}
            if fat:
                by_fat.setdefault(fat, []).append(info)
            fname = str(doc.get("arquivo") or (_Path(doc.get("path", "")).name if doc.get("path") else ""))
            if fname:
                by_file.setdefault(fname, []).append(info)
        return by_fat, by_file

    def _resolve_partner_for_record(rec, by_fat, by_file):
        current = _clean_partner_candidate(rec.get("Parceiro"))
        if current:
            return current
        fat = _normalize_invoice_id(rec.get("Fatura"))
        fname = str(rec.get("Arquivo fatura") or "")
        candidates = []
        if fat:
            candidates.extend(by_fat.get(fat, []))
        if fname:
            candidates.extend(by_file.get(fname, []))
        for info in candidates:
            partner = _clean_partner_candidate(info.get("partner"))
            if partner:
                return partner
            doc = info.get("doc") or {}
            partner = _extract_partner(doc.get("texto", ""), doc.get("path"))
            if partner:
                return partner
        return "Parceiro não identificado"

    def _postprocess_invoice_output(self):
        records = list(getattr(self, "invoice_detail_records", []) or [])
        if not records:
            return
        by_fat_doc, by_file_doc = _build_doc_maps(self)
        fixed = []
        seen = set()
        for rec in records:
            if not isinstance(rec, dict):
                continue
            fat = _normalize_invoice_id(rec.get("Fatura"))
            if not fat:
                # Tenta pelo arquivo ou pelo documento original antes de aceitar não identificada.
                fname = str(rec.get("Arquivo fatura") or "")
                for info in by_file_doc.get(fname, []):
                    if info.get("fatura"):
                        fat = info.get("fatura")
                        break
            if not fat:
                fat = "NÃO IDENTIFICADA"
            rec["Fatura"] = fat
            rec["Parceiro"] = _resolve_partner_for_record(rec, by_fat_doc, by_file_doc)
            if rec.get("Data/Hora escaneamento"):
                rec["Data/Hora escaneamento"] = _fmt_excel_datetime(rec.get("Data/Hora escaneamento")) or "-"
            elif rec.get("Data escaneamento") or rec.get("Hora escaneamento"):
                rec["Data/Hora escaneamento"] = _fmt_excel_datetime(str(rec.get("Data escaneamento", "")) + " " + str(rec.get("Hora escaneamento", ""))) or "-"
            cte_key = _record_cte_key(rec)
            nf_key = _norm_cmp(rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or "")
            val_key = round(_record_value(rec), 2)
            key = (fat, cte_key, nf_key, val_key)
            if not cte_key:
                key = (fat, _norm_cmp(str(rec.get("Motivo") or ""))[:60], nf_key, val_key)
            if key in seen:
                continue
            seen.add(key)
            fixed.append(rec)
        self.invoice_detail_records = fixed

        groups = {}
        order = []
        for rec in fixed:
            fat = rec.get("Fatura") or "NÃO IDENTIFICADA"
            if fat not in groups:
                groups[fat] = []
                order.append(fat)
            groups[fat].append(rec)

        self.invoice_rows = []
        self.detail_rows_by_invoice = {}
        for fat in order:
            recs = groups[fat]
            partner = "Parceiro não identificado"
            for rec in recs:
                cand = _clean_partner_candidate(rec.get("Parceiro"))
                if cand:
                    partner = cand
                    break
            qtd = len(recs)
            ok = sum(1 for rec in recs if _record_is_ok(rec))
            problema = qtd - ok
            valor_fatura = sum(_record_value(rec) for rec in recs)
            valor_nao_pagar = sum(_record_no_pay(rec) for rec in recs)
            status = "OK PAGAR" if problema == 0 else ("PAGAR PARCIAL" if ok > 0 else "NÃO PAGAR")
            valores = f"Fatura {_money(valor_fatura)} | Não pagar {_money(valor_nao_pagar)} | A pagar {_money(max(valor_fatura - valor_nao_pagar, 0.0))}"
            dy_s = sum(1 for rec in recs if str(rec.get("DY") or "").strip().upper() == "S")
            dy_n = sum(1 for rec in recs if str(rec.get("DY") or "").strip().upper() == "N" or "SEM COMPROVANTE" in _strip_accents(str(rec.get("Comprovante") or rec.get("Status final CT-e") or "")).upper())
            comprovantes = f"OK {dy_s} | Pend. {dy_n} | Revisar {max(qtd - dy_s - dy_n, 0)}"
            row = [fat, partner, str(qtd), str(ok), str(problema), _money(valor_fatura), _money(valor_nao_pagar), valores, comprovantes, status]
            self.invoice_rows.append(row)
            self.detail_rows_by_invoice[fat] = [[
                rec.get("CT-e fatura") or rec.get("CT-e base") or rec.get("CTRC base") or "-",
                rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or "-",
                _money(_record_value(rec)),
                _money(rec.get("Valor XML") or 0),
                rec.get("Status valor") or rec.get("Valor OK?") or "-",
                rec.get("Conferência fatura base") or rec.get("Fatura Base") or "-",
                rec.get("Comprovante") or rec.get("Comprovante OK?") or "-",
                rec.get("Data/Hora escaneamento") or rec.get("Escaneamento") or "-",
                rec.get("Status final CT-e") or rec.get("Status CT-e") or "-",
                rec.get("Motivo") or rec.get("Observação") or "",
            ] for rec in recs]

        try:
            self.invoice_table.setRowCount(0)
            for row in self.invoice_rows:
                self.add_invoice_row(row)
        except Exception:
            pass
        for name in ("refresh_partner_filter", "apply_filters", "update_cards", "load_details_for_selected"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def patched_process_invoices(self):
        if callable(_orig_process):
            result = _orig_process(self)
        else:
            result = None
        try:
            _postprocess_invoice_output(self)
            if hasattr(self, "set_status"):
                self.set_status("Faturas processadas com correção 2.6.29: leitura nativa preservada, fatura/parceiro saneados e duplicidades removidas.")
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.29] pós-processamento falhou:", exc)
            except Exception:
                pass
        return result

    def patched_build_invoice_report_sheets(self, only_problem_invoices=False):
        # Garante que o Excel receba os dados limpos mesmo se a tabela foi processada antes do hotfix terminar.
        try:
            _postprocess_invoice_output(self)
        except Exception:
            pass
        orig_builder = getattr(FaturasPage, "_original_build_invoice_report_sheets_2629", None)
        if callable(orig_builder):
            return orig_builder(self, only_problem_invoices)
        return []

    if not hasattr(FaturasPage, "_original_build_invoice_report_sheets_2629"):
        FaturasPage._original_build_invoice_report_sheets_2629 = getattr(FaturasPage, "build_invoice_report_sheets", None)
    FaturasPage.parse_invoice_text = patched_parse_invoice_text
    FaturasPage.parse_ssw_len_invoice_text = patched_parse_ssw_len_invoice_text
    FaturasPage.process_invoices = patched_process_invoices
    FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets
    FaturasPage._hotfix_faturas_2629 = True

    try:
        if hasattr(_main, "APP_VERSION") and "Hotfix Faturas 2.6.29" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Hotfix Faturas 2.6.29"
    except Exception:
        pass


_central_cte_hotfix_faturas_2629_start()

# ============================================================================
# HOTFIX Faturas Parceiros 2.6.30
# Corrige a tabela visual da aba Faturas no primeiro processamento.
# Motivo: o motor só é carregado quando o usuário clica em Processar; por isso
# a correção 2.6.29 limpava o relatório exportado, mas não alcançava a chamada
# atual de process_invoices que já estava rodando. Este hotfix aplica de forma
# síncrona e reescreve add_invoice_row/current_invoice_values para a tela usar
# os mesmos dados saneados do relatório.
# ============================================================================

def _central_cte_hotfix_faturas_2630_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2630():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _try_apply_once_2630():
        mod = _find_main_with_faturas_2630()
        if mod is not None:
            try:
                _central_cte_hotfix_faturas_2630_apply(mod)
                return True
            except Exception as exc:
                try:
                    print("[HOTFIX FATURAS 2.6.30] falhou:", exc)
                except Exception:
                    pass
        return False

    # Ponto principal: tenta aplicar AGORA, durante o import do motor. Assim,
    # mesmo quando o motor for importado pelo clique em Processar, o add_row já
    # estará corrigido antes de a tabela ser preenchida.
    try:
        if _try_apply_once_2630():
            return
    except Exception:
        pass

    def _worker_2630():
        for _ in range(2400):
            if _try_apply_once_2630():
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker_2630, daemon=True, name="hotfix_faturas_2630").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2630_apply(_main):
    import re as _re
    from pathlib import Path as _Path
    from datetime import datetime as _datetime, timedelta as _timedelta

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2630", False):
        return

    _orig_current_invoice_values = getattr(FaturasPage, "current_invoice_values", None)

    def _strip_accents(value):
        try:
            import unicodedata
            return "".join(c for c in unicodedata.normalize("NFD", str(value or "")) if unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        fn = getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        fn = getattr(_main, "money", None)
        if callable(fn):
            try:
                out = fn(value)
                return out if str(out).startswith("R$") else "R$ " + str(out)
            except Exception:
                pass
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _money_plain(value):
        try:
            return f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "0,00"

    def _bad_invoice(value):
        s = _norm_space(value)
        if not s:
            return True
        up = _strip_accents(s).upper()
        return up.startswith("EMISS") or up in {"FAT", "FATURA", "FATURAMENTO", "DOCUMENTO", "DOC", "NUMERO", "NÚMERO", "NAO IDENTIFICADA", "NÃO IDENTIFICADA"}

    def _format_invoice(base, dig):
        base_digits = _re.sub(r"\D", "", str(base or "")).lstrip("0") or "0"
        dig_digits = _re.sub(r"\D", "", str(dig or ""))[:1]
        if not dig_digits:
            return ""
        return f"{base_digits.zfill(7)}-{dig_digits}"

    def _normalize_invoice_id(value):
        text = _norm_space(value)
        if _bad_invoice(text):
            return ""
        for pat in (
            r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOC(?:UMENTO)?)\s*[^0-9]{0,20}(0*\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOC(?:UMENTO)?)\s*[^0-9]{0,20}(0*\d{3,9})\s*[-/]\s*(\d)",
            r"(?i)\bFat\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
        ):
            m = _re.search(pat, text)
            if m:
                return _format_invoice(m.group(1), m.group(2))
        return ""

    def _extract_invoice_id(text, path=None):
        raw = str(text or "").replace("\xa0", " ")
        for pat in (
            r"(?i)(?:N[ºO°.]?\s*do\s*Documento|Numero\s*do\s*Documento|Número\s*do\s*Documento)\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)(?:FATURA|FAT\.?|FATURAMENTO|DOCUMENTO|DOC)\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)\b(?:FATURA|FAT\.?|FATURAMENTO|DOCUMENTO|DOC)\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
        ):
            for m in _re.finditer(pat, raw):
                if len(m.groups()) >= 2:
                    out = _format_invoice(m.group(1), m.group(2))
                else:
                    out = _normalize_invoice_id(m.group(1))
                if out:
                    return out
        out = _normalize_invoice_id(raw[:2000])
        if out:
            return out
        if path:
            return _normalize_invoice_id(_Path(path).stem)
        return ""

    def _invalid_partner_name(value):
        s = _norm_space(value)
        if not s or s in {"-", "_"}:
            return True
        up = _strip_accents(s).upper()
        if up.startswith("FAT") and _re.search(r"\d", up):
            return True
        if _normalize_invoice_id(s):
            return True
        if any(term in up for term in ("EMISSAO", "EMISSÃO", "VENCIMENTO", "VALOR DO DOCUMENTO", "COMPROVANTE DE ENTREGA", "FRETE TERCEIRO PAGADOR")):
            return True
        return len(_re.sub(r"[^A-Z]", "", up)) < 4

    def _clean_partner_candidate(value):
        s = _norm_space(value)
        if not s:
            return ""
        s = _re.sub(r"(?i)\b(CNPJ|CPF|CNPJ/CPF)\b\s*[:\-]?\s*[\d./\- ]+", "", s)
        s = _re.sub(r"(?i)\b(IE|INSC\.?\s*EST\.?)\b\s*[:\-]?\s*[\d./\- ]+", "", s)
        s = _re.sub(r"(?i)\b(FATURA|FAT\.?|DOCUMENTO|DOC)\b\s*[:\-]?\s*\d+[\d()\-/ ]*", "", s)
        s = _re.sub(r"\s+(?:\d[\d./\- ]{5,})$", "", s)
        s = _norm_space(s.strip(" -–—/"))
        if _invalid_partner_name(s):
            return ""
        return s[:90]

    def _extract_partner(text, path=None):
        raw = str(text or "").replace("\xa0", " ")
        patterns = [
            r"(?im)^\s*(?:Parceiro|Transportador|Prestador|Fornecedor|Subcontratado|Favorecido|Emitente)\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*Raz[aã]o\s+Social\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*Nome\s*[:\-]\s*(.+?)\s*$",
            r"(?im)^\s*([A-ZÁÉÍÓÚÃÕÇ0-9 .,&/\-]{6,}?(?:TRANSP|TRANSPORT|TRANSPORTE|TRANSPORTES|LOGIST|LOGISTICA|LOGÍSTICA|CARGAS|LTDA|EIRELI|ME\b|S/A|SERVI[CÇ]OS)[A-ZÁÉÍÓÚÃÕÇ0-9 .,&/\-]*)\s*(?:CNPJ|CPF|$)",
        ]
        for pat in patterns:
            for m in _re.finditer(pat, raw, _re.I):
                cand = _clean_partner_candidate(m.group(1))
                if cand and "RODOVITOR" not in _strip_accents(cand).upper():
                    return cand
        for line in raw.splitlines():
            line2 = _norm_space(line)
            up = _strip_accents(line2).upper()
            if not line2 or "RODOVITOR" in up:
                continue
            if any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "SERVICOS", "SERVIÇOS")):
                if not any(bad in up for bad in ("FATURA", "EMISSAO", "VENCIMENTO", "VALOR", "COMPROVANTE DE ENTREGA")):
                    cand = _clean_partner_candidate(line2)
                    if cand:
                        return cand
        if path:
            cand = _clean_partner_candidate(_Path(path).stem.replace("_", " "))
            if cand:
                return cand
        return ""

    def _fmt_excel_datetime(value):
        s = _norm_space(value)
        if not s:
            return "-"
        if _re.search(r"\d{1,2}/\d{1,2}/\d{2,4}", s):
            return s
        nums = _re.findall(r"\d+(?:[\.,]\d+)?", s)
        if not nums:
            return s
        try:
            date_num = float(nums[0].replace(",", "."))
            if not (1 <= date_num <= 80000):
                return s
            base_dt = _datetime(1899, 12, 30) + _timedelta(days=int(date_num))
            time_txt = ""
            if len(nums) >= 2:
                frac = float(nums[1].replace(",", "."))
                if 0 <= frac < 1:
                    minutes = int(round(frac * 24 * 60))
                    time_txt = f" {(minutes // 60) % 24:02d}:{minutes % 60:02d}"
            return base_dt.strftime("%d/%m/%Y") + time_txt
        except Exception:
            return s

    def _record_cte(rec):
        return _norm_space(rec.get("CT-e fatura") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("CT-e") or "")

    def _record_is_ok(rec):
        st = _strip_accents(str(rec.get("Status final CT-e") or rec.get("Status CT-e") or "")).upper()
        comp = _strip_accents(str(rec.get("Comprovante") or rec.get("Comprovante OK?") or "")).upper()
        return st.startswith("OK") or comp in {"COMPROVANTE OK", "SIM"}

    def _record_value(rec):
        return _parse_money(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("Valor não pagar") or rec.get("Valor Fat.") or 0)

    def _record_no_pay(rec):
        v = _parse_money(rec.get("Valor não pagar"))
        if v:
            return v
        return _record_value(rec) if not _record_is_ok(rec) else 0.0

    def _doc_fat(doc):
        return _normalize_invoice_id(doc.get("fatura")) or _extract_invoice_id(doc.get("texto", ""), doc.get("path") or doc.get("arquivo"))

    def _partner_for_fat(self, fat, row_partner=""):
        cand = _clean_partner_candidate(row_partner)
        if cand:
            return cand
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if _normalize_invoice_id(rec.get("Fatura")) == fat:
                cand = _clean_partner_candidate(rec.get("Parceiro"))
                if cand:
                    return cand
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            if _doc_fat(doc) == fat:
                cand = _clean_partner_candidate(doc.get("parceiro")) or _extract_partner(doc.get("texto", ""), doc.get("path") or doc.get("arquivo"))
                if cand:
                    return cand
        return "Parceiro não identificado"

    def _records_for_fat(self, fat):
        out = []
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if not isinstance(rec, dict):
                continue
            rec_fat = _normalize_invoice_id(rec.get("Fatura"))
            if rec_fat == fat:
                rec["Fatura"] = fat
                out.append(rec)
        return out

    def _detail_rows_from_records(recs):
        rows = []
        for rec in recs:
            scan = rec.get("Data/Hora escaneamento") or rec.get("Escaneamento") or ""
            if not scan and (rec.get("Data escaneamento") or rec.get("Hora escaneamento")):
                scan = str(rec.get("Data escaneamento", "")) + " " + str(rec.get("Hora escaneamento", ""))
            rows.append([
                _record_cte(rec) or "-",
                rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or "-",
                _money(_record_value(rec)),
                _money(rec.get("Valor XML") or 0),
                rec.get("Status valor") or rec.get("Valor OK?") or "-",
                rec.get("Conferência fatura base") or rec.get("Fatura Base") or "-",
                rec.get("Comprovante") or rec.get("Comprovante OK?") or "-",
                _fmt_excel_datetime(scan),
                rec.get("Status final CT-e") or rec.get("Status CT-e") or "-",
                rec.get("Motivo") or rec.get("Observação") or "",
            ])
        return rows

    def _summary_row_for_fat(self, fat, old_row=None):
        old = list(old_row or [])
        while len(old) < 10:
            old.append("")
        fat = _normalize_invoice_id(fat or old[0]) or str(fat or old[0] or "NÃO IDENTIFICADA")
        recs = _records_for_fat(self, fat)
        partner = _partner_for_fat(self, fat, old[1] if len(old) > 1 else "")
        if recs:
            for rec in recs:
                rec["Fatura"] = fat
                if not _clean_partner_candidate(rec.get("Parceiro")):
                    rec["Parceiro"] = partner
                if rec.get("Data/Hora escaneamento"):
                    rec["Data/Hora escaneamento"] = _fmt_excel_datetime(rec.get("Data/Hora escaneamento"))
            qtd = len(recs)
            ok = sum(1 for rec in recs if _record_is_ok(rec))
            problema = qtd - ok
            valor_fat = sum(_record_value(rec) for rec in recs)
            valor_np = sum(_record_no_pay(rec) for rec in recs)
            status = "OK PAGAR" if problema == 0 else ("PAGAR PARCIAL" if ok > 0 else "NÃO PAGAR")
            dy_s = sum(1 for rec in recs if str(rec.get("DY") or "").strip().upper() == "S")
            dy_n = sum(1 for rec in recs if str(rec.get("DY") or "").strip().upper() == "N" or "SEM COMPROVANTE" in _strip_accents(str(rec.get("Comprovante") or rec.get("Status final CT-e") or "")).upper())
            comprovantes = f"OK {dy_s} | Pend. {dy_n} | Revisar {max(qtd - dy_s - dy_n, 0)}"
            valores = f"Fatura {_money(valor_fat)} | Não pagar {_money(valor_np)} | A pagar {_money(max(valor_fat - valor_np, 0.0))}"
            detail_rows = _detail_rows_from_records(recs)
            try:
                self.detail_rows_by_invoice[fat] = detail_rows
            except Exception:
                pass
            row = [fat, partner, str(qtd), str(ok), str(problema), _money(valor_fat), _money(valor_np), valores, comprovantes, status]
        else:
            row = [fat, partner] + old[2:10]
            while len(row) < 10:
                row.append("")
        try:
            rows = list(getattr(self, "invoice_rows", []) or [])
            replaced = False
            for i, existing in enumerate(rows):
                try:
                    if _normalize_invoice_id((existing or [""])[0]) == fat:
                        rows[i] = row
                        replaced = True
                except Exception:
                    pass
            if not replaced:
                rows.append(row)
            self.invoice_rows = rows
        except Exception:
            pass
        return row

    def _widget_text(widget):
        if widget is None:
            return ""
        for attr in ("text", "currentText", "toolTip", "accessibleName"):
            try:
                fn = getattr(widget, attr, None)
                if callable(fn):
                    val = fn()
                    if val not in (None, ""):
                        return str(val)
            except Exception:
                pass
        try:
            return str(widget)
        except Exception:
            return ""

    def _write_table_row(self, row):
        table = getattr(self, "invoice_table", None)
        if table is None:
            return
        try:
            col_count = table.columnCount()
        except Exception:
            col_count = 10
        vals = list(row or [])
        while len(vals) < col_count:
            vals.append("")
        try:
            r = table.rowCount()
            table.insertRow(r)
        except Exception:
            return
        QTableWidgetItem = getattr(_main, "QTableWidgetItem", None)
        Qt = getattr(_main, "Qt", None)
        QColor = getattr(_main, "QColor", None)
        StatusBadge = getattr(_main, "StatusBadge", None)
        try:
            if QTableWidgetItem is None:
                from PySide6.QtWidgets import QTableWidgetItem as QTableWidgetItem
            if Qt is None:
                from PySide6.QtCore import Qt as Qt
            if QColor is None:
                from PySide6.QtGui import QColor as QColor
        except Exception:
            pass
        for c in range(col_count):
            txt = "" if vals[c] is None else str(vals[c])
            item = None
            if QTableWidgetItem is not None:
                try:
                    item = QTableWidgetItem(txt)
                    try:
                        item.setToolTip(txt)
                    except Exception:
                        pass
                    try:
                        if c in (2, 3, 4, 5, 6):
                            item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                    except Exception:
                        pass
                    try:
                        up = _strip_accents(txt).upper()
                        if c == 0:
                            item.setForeground(QColor(getattr(_main, "BLUE", "#1257d8")))
                        elif c in (4, 6) and txt.strip() not in ("", "0", "0,00", "R$ 0,00", "-"):
                            item.setForeground(QColor(getattr(_main, "RED", "#ed1b2f")))
                        elif "SEM COMPROVANTE" in up or "NÃO" in up or "DIVERG" in up:
                            item.setForeground(QColor(getattr(_main, "RED", "#ed1b2f")))
                    except Exception:
                        pass
                    try:
                        table.setItem(r, c, item)
                    except Exception:
                        pass
                except Exception:
                    item = None
            if c == 9 and StatusBadge is not None:
                try:
                    table.setCellWidget(r, c, StatusBadge(txt))
                except Exception:
                    pass
        try:
            density = getattr(self, "density", None)
            compact = callable(getattr(density, "currentText", None)) and density.currentText() == "Compacta"
            table.setRowHeight(r, 26 if compact else 34)
        except Exception:
            pass

    def patched_add_invoice_row(self, row):
        try:
            fat = _normalize_invoice_id((row or [""])[0]) if row else ""
            if not fat:
                fat = str((row or ["NÃO IDENTIFICADA"])[0] or "NÃO IDENTIFICADA")
            row = _summary_row_for_fat(self, fat, row)
        except Exception:
            row = list(row or [])
        _write_table_row(self, row)

    def patched_current_invoice_values(self):
        vals = []
        try:
            table = self.invoice_table
            row = table.currentRow()
            if row < 0:
                return []
            for c in range(table.columnCount()):
                item = table.item(row, c)
                if item is not None:
                    vals.append(item.text())
                else:
                    vals.append(_widget_text(table.cellWidget(row, c)))
        except Exception:
            if callable(_orig_current_invoice_values):
                try:
                    vals = list(_orig_current_invoice_values(self) or [])
                except Exception:
                    vals = []
        while len(vals) < 10:
            vals.append("")
        try:
            fat = _normalize_invoice_id(vals[0]) or vals[0]
            # Segurança: se alguma coluna visual continuar vazia, usa o cache saneado.
            if fat and (not vals[1] or not vals[2] or not vals[5]):
                for cached in getattr(self, "invoice_rows", []) or []:
                    if _normalize_invoice_id((cached or [""])[0]) == _normalize_invoice_id(fat):
                        cached = list(cached)
                        while len(cached) < 10:
                            cached.append("")
                        vals = cached[:10]
                        break
        except Exception:
            pass
        return vals

    FaturasPage.add_invoice_row = patched_add_invoice_row
    FaturasPage.current_invoice_values = patched_current_invoice_values
    FaturasPage._hotfix_faturas_2630 = True

    # Evita que a thread 2.6.29 tente reaplicar tarde demais em cima desta correção.
    try:
        FaturasPage._hotfix_faturas_2629 = True
    except Exception:
        pass

    try:
        if hasattr(_main, "APP_VERSION") and "Hotfix Faturas 2.6.30" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Hotfix Faturas 2.6.30"
    except Exception:
        pass


_central_cte_hotfix_faturas_2630_start()


# HOTFIX Controle Interno Rodotec / Componentes 2.6.31
# - Adiciona regra modular de GRIS e pedágio por parceiro/região.
# - Gera bloco compacto no DACTE/HTML após validação dos valores.
def _central_cte_hotfix_controle_componentes_2631_start():
    import math as _math
    from decimal import Decimal as _Decimal, ROUND_HALF_UP as _ROUND_HALF_UP

    # O motor é carregado pela interface com importlib.exec_module sem registrar
    # obrigatoriamente o módulo em sys.modules. Por isso não podemos usar
    # sys.modules[__name__] diretamente aqui. Este proxy aponta para os globals
    # atuais quando o módulo não estiver registrado.
    class _ModuleProxy2631:
        def __getattr__(self, name):
            try:
                return globals()[name]
            except KeyError:
                raise AttributeError(name)

        def __setattr__(self, name, value):
            globals()[name] = value

    _main = sys.modules.get(__name__) or _ModuleProxy2631()
    if getattr(_main, "_hotfix_controle_componentes_2631", False):
        return
    _main._hotfix_controle_componentes_2631 = True

    _orig_load_partner_tables = getattr(_main, "load_partner_tables", None)
    _orig_validate_cte_value = getattr(_main, "validate_cte_value", None)
    _orig_render_dacte_page = getattr(_main, "render_dacte_page", None)

    def _round_money(value):
        try:
            return float(_Decimal(str(value or 0)).quantize(_Decimal("0.01"), rounding=_ROUND_HALF_UP))
        except Exception:
            return 0.0

    def _is_yes(value):
        txt = norm_text(value)
        return txt in {"S", "SIM", "YES", "TRUE", "1", "ATIVO", "OK"}

    def _first_raw(raw, *keys):
        raw = raw or {}
        for key in keys:
            nk = normalize_header(key)
            if nk in raw and str(raw.get(nk, "") or "").strip() != "":
                return raw.get(nk)
        return ""

    def _add_component_config(item):
        raw = item.get("raw", {}) or {}
        gris_raw = _first_raw(raw, "GRIS Ativo", "GRIS", "Usa GRIS", "Cobrar GRIS")
        gris_percent_raw = _first_raw(raw, "Percentual GRIS", "GRIS Percentual", "% GRIS", "Perc GRIS")
        ped_raw = _first_raw(raw, "Pedágio Ativo", "Pedagio Ativo", "Pedágio", "Pedagio", "Usa Pedágio", "Usa Pedagio")
        ped_valor_raw = _first_raw(raw, "Valor Pedágio", "Valor Pedagio", "Pedágio Valor", "Pedagio Valor", "Pedágio por Fração", "Pedagio por Fracao")
        ped_fracao_raw = _first_raw(raw, "Fração Pedágio KG", "Fracao Pedagio KG", "Fração KG", "Fracao KG", "Pedágio Fração KG", "Pedagio Fracao KG")
        controle_raw = _first_raw(raw, "Controle DACTE", "Mostrar Controle DACTE", "Controle Interno", "Validação DACTE", "Validacao DACTE")
        regra_label = str(_first_raw(raw, "Nome Controle", "Regra Controle", "Nome Regra") or "").strip()

        gris_percent = parse_percent(gris_percent_raw)
        ped_valor = parse_optional_single_money(ped_valor_raw)
        ped_fracao = parse_number_br(ped_fracao_raw) or 100.0

        item["gris_ativo"] = _is_yes(gris_raw) or gris_percent > 0
        item["gris_percentual"] = gris_percent
        item["pedagio_ativo"] = _is_yes(ped_raw) or ped_valor > 0
        item["pedagio_valor"] = ped_valor
        item["pedagio_fracao_kg"] = ped_fracao
        item["controle_dacte"] = _is_yes(controle_raw) or item["gris_ativo"] or item["pedagio_ativo"]
        default_nome = "RODOTEC" if "RODOTEC" in norm_text(item.get("regiao", "") or raw.get("REGIAOBASE", "")) else "TABELA"
        item["controle_regra_nome"] = regra_label or default_nome
        return item

    def patched_load_partner_tables(file_path):
        tables = _orig_load_partner_tables(file_path)
        try:
            for r in tables.get("rules", []) or []:
                _add_component_config(r)
            for r in tables.get("regions", []) or []:
                _add_component_config(r)
            tables["componentes_2631"] = True
        except Exception:
            pass
        return tables

    def _fmt_num(value, casas=2, milhar=False):
        try:
            n = float(value or 0)
        except Exception:
            n = 0.0
        if abs(n - round(n)) < 0.0000001:
            return str(int(round(n)))
        if milhar:
            txt = f"{n:,.{casas}f}".replace(",", "X").replace(".", ",").replace("X", ".")
        else:
            txt = f"{n:.{casas}f}".replace(".", ",")
        return txt.rstrip("0").rstrip(",") if "," in txt else txt

    def _fmt_money_plain(value):
        try:
            n = float(value or 0)
        except Exception:
            n = 0.0
        return f"{n:.2f}".replace(".", ",")

    def _fmt_money_rs(value):
        return "R$" + _fmt_money_plain(value)

    def _fmt_percent_short(value):
        try:
            n = float(value or 0) * 100.0
        except Exception:
            n = 0.0
        txt = f"{n:.4f}".replace(".", ",").rstrip("0").rstrip(",")
        return txt + "%"

    def _component_value_any(info, aliases):
        total = 0.0
        found = []
        alias_norms = [norm_text(a) for a in aliases]
        for comp in info.get("componentes", []) or []:
            nome = norm_text(comp.get("nome", ""))
            if any(a and a in nome for a in alias_norms):
                val = parse_number_br(comp.get("valor", ""))
                total += val
                found.append((comp.get("nome", ""), val))
        return total, found

    def _get_valid_base_rows(info, base_data):
        rows = []
        for one_nf in get_nfs_from_info(info):
            base_row, base_status, _candidates = find_base_by_nf(base_data, one_nf, info)
            if base_row:
                rows.append(base_row)
        return rows

    def _calc_component_validation(info, base_data, tables, result):
        pid = result.get("partner_id") or identify_partner(info, tables)
        if not pid or not base_data or not tables:
            return result
        base_rows = _get_valid_base_rows(info, base_data)
        if not base_rows or (len(base_rows) > 1 and not base_rows_have_same_route(base_rows)):
            return result
        base_row = base_rows[0]
        rule = choose_partner_rule(pid, base_row, tables)
        if not rule:
            return result
        rule = _add_component_config(dict(rule))
        if not (rule.get("controle_dacte") or rule.get("gris_ativo") or rule.get("pedagio_ativo")):
            return result
        if not should_use_frete_peso(rule, info):
            # O bloco compacto planejado é para frete por peso + componentes.
            return result

        ton_rate = rule.get("ton_rate", 0.0) or 0.0
        peso_kg, peso_source = peso_base_kg_from_info(info)
        taxa_kg = ton_rate / 1000.0 if ton_rate else 0.0
        minimum = rule.get("minimum", 0.0) or 0.0
        tolerance = tables.get("tolerance", 1.0)
        total_xml = parse_number_br(info.get("valor", ""))
        if ton_rate <= 0 or peso_kg <= 0:
            return result

        frete_calc_raw = peso_kg * taxa_kg
        frete_calc = _round_money(frete_calc_raw)
        minimum_applied = bool(minimum and minimum > frete_calc)
        frete_final = _round_money(max(frete_calc, minimum))
        valor_mercadoria = parse_number_br(info.get("valor_carga", ""))
        if valor_mercadoria <= 0:
            try:
                valor_mercadoria = sum(float(r.get("valor_mercadoria", 0.0) or 0.0) for r in base_rows)
            except Exception:
                valor_mercadoria = 0.0

        componentes_calc = []
        partes_linha = []
        if minimum_applied:
            partes_linha.append(f"Frete: mín.={_fmt_money_plain(frete_final)}")
        else:
            partes_linha.append(f"Frete: {_fmt_num(peso_kg)}×{_fmt_money_plain(taxa_kg)}={_fmt_money_plain(frete_final)}")
        frete_xml, frete_found = _component_value_any(info, ["FRETE PESO"])
        componentes_calc.append({"nome": "FRETE PESO", "calc": frete_final, "xml": frete_xml, "found": frete_found})

        # 2.6.37: GRIS e pedágio são opcionais por CT-e.
        # Mesmo que a tabela do parceiro permita/cadastre o componente, ele só entra
        # no cálculo se o XML realmente trouxer cobrança positiva do componente.
        # Isso evita falso divergente quando o parceiro não cobrou pedágio/GRIS em
        # determinado documento.
        gris_calc = 0.0
        gris_xml, gris_found = _component_value_any(info, ["GRIS", "GERENCIAMENTO RISCO", "RISCO"])
        gris_cobrado_xml = bool(gris_found) and abs(_round_money(gris_xml)) > 0.0
        if rule.get("gris_ativo") and gris_cobrado_xml:
            gris_percent = rule.get("gris_percentual", 0.0) or 0.0
            gris_calc = _round_money(valor_mercadoria * gris_percent)
            componentes_calc.append({"nome": "GRIS", "calc": gris_calc, "xml": gris_xml, "found": gris_found})
            partes_linha.append(f"GRIS: {_fmt_money_plain(valor_mercadoria)}×{_fmt_percent_short(gris_percent)}={_fmt_money_plain(gris_calc)}")

        pedagio_calc = 0.0
        pedagio_qtd = 0
        ped_xml, ped_found = _component_value_any(info, ["PEDAG", "PEDAGIO", "PEDÁGIO"])
        pedagio_cobrado_xml = bool(ped_found) and abs(_round_money(ped_xml)) > 0.0
        if rule.get("pedagio_ativo") and pedagio_cobrado_xml:
            ped_valor = rule.get("pedagio_valor", 0.0) or 0.0
            ped_fracao = rule.get("pedagio_fracao_kg", 100.0) or 100.0
            pedagio_qtd = int(_math.ceil(peso_kg / ped_fracao)) if peso_kg > 0 and ped_fracao > 0 else 0
            pedagio_calc = _round_money(pedagio_qtd * ped_valor)
            componentes_calc.append({"nome": "PEDÁGIO", "calc": pedagio_calc, "xml": ped_xml, "found": ped_found})
            partes_linha.append(f"Pedágio: {pedagio_qtd}×{_fmt_money_plain(ped_valor)}={_fmt_money_plain(pedagio_calc)}")

        expected = _round_money(frete_final + gris_calc + pedagio_calc)
        diff = _round_money(total_xml - expected)
        status_curto = "OK" if abs(diff) <= tolerance else ("DIVERGENTE +" if diff > 0 else "DIVERGENTE -")
        regra_nome = rule.get("controle_regra_nome") or "RODOTEC"
        linha1 = " | ".join(partes_linha)
        linha2 = f"Total calc.: {_fmt_money_rs(expected)} | XML: {_fmt_money_rs(total_xml)} | Dif.: {_fmt_money_rs(diff)} | {status_curto}"

        result["modo_calculo"] = "FRETE_PESO_COMPONENTES"
        result["base_calculo"] = "FRETE_PESO+COMPONENTES"
        result["peso_base_kg"] = peso_kg
        result["peso_xml_fonte"] = peso_source
        result["peso_xml_todos"] = format_peso_xml_debug(info)
        result["tonelagem_taxa"] = ton_rate
        result["taxa_kg"] = taxa_kg
        result["frete_peso_calculado"] = frete_final
        result["gris_calculado"] = gris_calc if (rule.get("gris_ativo") and gris_cobrado_xml) else None
        result["gris_percentual"] = rule.get("gris_percentual") if (rule.get("gris_ativo") and gris_cobrado_xml) else None
        result["gris_cobrado_xml"] = bool(gris_cobrado_xml)
        result["pedagio_calculado"] = pedagio_calc if (rule.get("pedagio_ativo") and pedagio_cobrado_xml) else None
        result["pedagio_qtd"] = pedagio_qtd if (rule.get("pedagio_ativo") and pedagio_cobrado_xml) else None
        result["pedagio_valor"] = rule.get("pedagio_valor") if (rule.get("pedagio_ativo") and pedagio_cobrado_xml) else None
        result["pedagio_cobrado_xml"] = bool(pedagio_cobrado_xml)
        result["valor_total_xml"] = total_xml
        result["valor_comparado"] = total_xml
        result["componente_comparado"] = "VALOR TOTAL DO SERVIÇO"
        result["esperado"] = expected
        result["diferenca"] = diff
        result["tolerancia"] = tolerance
        result["controle_dacte_regra"] = regra_nome
        result["controle_dacte_linha1"] = linha1
        result["controle_dacte_linha2"] = linha2
        result["controle_dacte_status"] = status_curto
        result["controle_dacte_compacto"] = f"CONTROLE INTERNO - {regra_nome}\n{linha1}\n{linha2}"
        result["componentes_calculados"] = componentes_calc
        result["detalhe"] = (result.get("detalhe") or "") + f"; controle interno {regra_nome}: frete peso + componentes" 

        # Status principal passa a considerar o total do CT-e, não só o componente FRETE PESO.
        suffix = " NF PARCIAL" if result.get("validacao_parcial") else ""
        if abs(diff) <= tolerance:
            result["status"] = f"OK {regra_nome}".strip() + suffix
        elif diff > 0:
            result["status"] = f"DIVERGENTE {regra_nome} +".strip() + suffix
        else:
            result["status"] = f"DIVERGENTE {regra_nome} -".strip() + suffix

        trace = result.setdefault("trace", [])
        trace.append(f"Controle interno {regra_nome}: cálculo composto ativado pela tabela do parceiro.")
        if rule.get("gris_ativo") and not gris_cobrado_xml:
            trace.append("GRIS cadastrado para a regra, mas não cobrado no XML; componente opcional ignorado no total esperado.")
        if rule.get("pedagio_ativo") and not pedagio_cobrado_xml:
            trace.append("Pedágio cadastrado para a regra, mas não cobrado no XML; componente opcional ignorado no total esperado.")
        trace.append(f"Linha compacta: {linha1}")
        trace.append(f"Conferência total: {linha2}")
        for comp in componentes_calc:
            c_diff = _round_money((comp.get("xml") or 0.0) - (comp.get("calc") or 0.0))
            c_status = "OK" if abs(c_diff) <= tolerance else "DIVERGENTE"
            trace.append(f"Componente {comp.get('nome')}: calculado R$ {money(comp.get('calc'))}; XML R$ {money(comp.get('xml'))}; diferença R$ {money(c_diff)}; {c_status}.")
        return result

    def patched_validate_cte_value(info, base_data, tables):
        result = _orig_validate_cte_value(info, base_data, tables)
        try:
            result = _calc_component_validation(info, base_data, tables, result)
        except Exception as e:
            try:
                result.setdefault("trace", []).append(f"Controle interno 2.6.31 não foi aplicado: {e}")
            except Exception:
                pass
        return result

    def _controle_html_from_info(info):
        result = info.get("validacao") or {}
        bloco = str(result.get("controle_dacte_compacto") or "").strip()
        if not bloco:
            return ""
        regra = escape(str(result.get("controle_dacte_regra") or "RODOTEC"))
        linha1 = escape(str(result.get("controle_dacte_linha1") or ""))
        linha2 = escape(str(result.get("controle_dacte_linha2") or ""))
        status = norm_text(result.get("controle_dacte_status") or result.get("status") or "")
        cls = "ok" if "OK" in status and "DIVERG" not in status else "bad"
        return (
            f'<div class="controle-rodotec {cls}">'
            f'<b>CONTROLE INTERNO - {regra}</b><br>'
            f'{linha1}<br>{linha2}'
            f'</div>'
        )

    def patched_render_dacte_page(info):
        html = _orig_render_dacte_page(info)
        try:
            bloco = _controle_html_from_info(info)
            if bloco:
                marker = '    <div class="section-title">INFORMAÇÕES RELATIVAS AO IMPOSTO</div>'
                html = html.replace(marker, f"    {bloco}\n\n{marker}", 1)
        except Exception:
            pass
        return html

    try:
        if callable(_orig_load_partner_tables):
            _main.load_partner_tables = patched_load_partner_tables
        if callable(_orig_validate_cte_value):
            _main.validate_cte_value = patched_validate_cte_value
        if callable(_orig_render_dacte_page):
            _main.render_dacte_page = patched_render_dacte_page
        if hasattr(_main, "CSS") and "controle-rodotec" not in str(_main.CSS):
            _main.CSS += """
.controle-rodotec { border: 1px solid #111; border-top: 0; padding: 2px 5px; font-size: 7.4px; line-height: 1.18; font-family: Arial, sans-serif; }
.controle-rodotec.ok { background: #f4fff4; }
.controle-rodotec.bad { background: #fff4f4; }
"""
        if hasattr(_main, "APP_VERSION") and "Controle Componentes 2.6.31.1 + Opcionais XML 2.6.37" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Controle Componentes 2.6.31.1 + Opcionais XML 2.6.37"
    except Exception:
        pass

_central_cte_hotfix_controle_componentes_2631_start()



# ============================================================================
# HOTFIX Faturas Parceiros 2.6.32
# - Bloqueia/limpa documentos repetidos na lista principal e na aba Parceiros.
# - Repara linhas visuais de fatura que ficavam só com o número da fatura.
# - Limpa histórico/opções do filtro de parceiro ao limpar a aba Parceiros.
# - Atualiza a mensagem ao parceiro: retirar CT-e da fatura atual e lançar em próxima fatura.
# ============================================================================
def _central_cte_hotfix_faturas_2632_start():
    import sys as _sys, time as _time, threading as _threading, re as _re, os as _os
    from pathlib import Path as _Path

    def _strip_acc(s):
        try:
            import unicodedata as _unicodedata
            return "".join(c for c in _unicodedata.normalize("NFD", str(s or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(s or "")

    def _norm(s):
        return _re.sub(r"\s+", " ", _strip_acc(str(s or "")).strip()).upper()

    def _money_to_float(value):
        s = str(value or "").strip()
        if not s:
            return 0.0
        s = s.replace("R$", "").replace(" ", "")
        s = _re.sub(r"[^0-9,.-]", "", s)
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_fmt(value):
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _norm_invoice(value):
        s = str(value or "")
        if not s or _norm(s).startswith("EMISS"):
            return ""
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            m = _re.search(r"(?i)\bFat\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]", s)
        if not m:
            return ""
        base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
        dig = _re.sub(r"\D", "", m.group(2))[:1]
        return f"{base.zfill(7)}-{dig}" if dig else ""

    def _doc_ctes(doc):
        ctes = []
        if isinstance(doc, dict):
            for it in doc.get("items") or []:
                if isinstance(it, dict):
                    val = it.get("cte") or it.get("cte_ref") or it.get("CT-e") or ""
                    if val:
                        ctes.append(_norm(val))
            txt = str(doc.get("texto") or "")[:3000]
            for m in _re.finditer(r"\b[A-Z]{2,4}\s*/\s*\d{3,7}\s*-\s*\d\b|\b\d{3,9}\s*-\s*\d\b", txt, _re.I):
                ctes.append(_norm(m.group(0)))
        return tuple(sorted(set(x for x in ctes if x)))

    def _doc_key(doc):
        if not isinstance(doc, dict):
            return ("obj", id(doc))
        path = str(doc.get("path") or "").strip()
        if path:
            try:
                return ("path", _os.path.normcase(_os.path.abspath(path)))
            except Exception:
                return ("path", path.lower())
        fat = _norm_invoice(doc.get("fatura")) or _norm(doc.get("fatura"))
        arq = _norm(doc.get("arquivo"))
        ctes = _doc_ctes(doc)
        if fat and ctes:
            return ("fat_ctes", fat, ctes)
        if fat and arq:
            return ("fat_file", fat, arq)
        return ("raw", fat, arq, ctes)

    def _xml_info_key(info):
        if not isinstance(info, dict):
            return ("obj", id(info))
        path = str(info.get("path") or "").strip()
        if path:
            try:
                path_key = _os.path.normcase(_os.path.abspath(path))
            except Exception:
                path_key = path.lower()
        else:
            path_key = ""
        # Chave de CT-e tem prioridade sobre caminho: evita o mesmo CT-e entrando de pastas diferentes.
        chave = _norm(info.get("chave") or info.get("chCTe") or info.get("chave_cte") or "")
        if chave and len(_re.sub(r"\D", "", chave)) >= 20:
            return ("chave", _re.sub(r"\D", "", chave))
        tipo = _norm(info.get("tipo"))
        numero = _norm(info.get("numero"))
        serie = _norm(info.get("serie"))
        emit = _norm(info.get("emitente"))
        if tipo or numero or serie or emit:
            return ("doc", tipo, numero, serie, emit)
        return ("path", path_key)

    def _call_refresh_faturas(self, hard=False):
        for name in ("refresh_invoice_list", "refresh_faturas_list", "refresh_docs", "refresh_table", "apply_filters", "refresh_partner_filter", "update_cards", "load_details_for_selected"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass
        if hard:
            try:
                table = getattr(self, "invoice_table", None)
                if table is not None and hasattr(table, "viewport"):
                    table.viewport().update()
            except Exception:
                pass

    def _dedupe_invoice_docs(self):
        docs = list(getattr(self, "invoice_docs", []) or [])
        if not docs:
            return 0
        fixed, seen, removed = [], set(), 0
        for doc in docs:
            key = _doc_key(doc)
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            fixed.append(doc)
        if removed:
            try:
                self.invoice_docs = fixed
            except Exception:
                pass
            # Mantém caches paralelos coerentes, quando existirem.
            for attr in ("invoice_files", "fatura_docs", "faturas_docs"):
                if hasattr(self, attr):
                    try:
                        val = getattr(self, attr)
                        if isinstance(val, list) and len(val) == len(docs):
                            setattr(self, attr, fixed)
                    except Exception:
                        pass
        return removed

    def _dedupe_xml_files(self):
        files = list(getattr(self, "files", []) or [])
        if not files:
            return 0
        fixed, seen, removed = [], set(), 0
        for info in files:
            key = _xml_info_key(info)
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            fixed.append(info)
        if removed:
            try:
                self.files = fixed
            except Exception:
                pass
            try:
                valid_paths = {f.get("path") for f in fixed if isinstance(f, dict)}
                if hasattr(self, "selected_paths"):
                    self.selected_paths = {p for p in self.selected_paths if p in valid_paths}
            except Exception:
                pass
        return removed

    def _table_text(table, row, col):
        try:
            item = table.item(row, col)
            if item is not None:
                return str(item.text() or "")
        except Exception:
            pass
        try:
            w = table.cellWidget(row, col)
            if w is not None:
                for attr in ("text", "currentText"):
                    fn = getattr(w, attr, None)
                    if callable(fn):
                        val = fn()
                        if val not in (None, ""):
                            return str(val)
        except Exception:
            pass
        return ""

    def _set_table_text(table, row, col, text, main_mod=None):
        text = "" if text is None else str(text)
        item = None
        try:
            item = table.item(row, col)
        except Exception:
            item = None
        if item is not None:
            try:
                item.setText(text)
                item.setToolTip(text)
                return
            except Exception:
                pass
        QTableWidgetItem = getattr(main_mod, "QTableWidgetItem", None) if main_mod is not None else None
        if QTableWidgetItem is None:
            try:
                from PySide6.QtWidgets import QTableWidgetItem as QTableWidgetItem
            except Exception:
                QTableWidgetItem = None
        if QTableWidgetItem is not None:
            try:
                item = QTableWidgetItem(text)
                item.setToolTip(text)
                table.setItem(row, col, item)
            except Exception:
                pass

    def _record_status_ok(detail_row):
        vals = list(detail_row or [])
        comp = _norm(vals[6] if len(vals) > 6 else "")
        st = _norm(vals[8] if len(vals) > 8 else "")
        return st.startswith("OK") or comp in {"COMPROVANTE OK", "OK", "SIM"}

    def _derive_row_from_details(self, fat, old=None):
        old = list(old or [])
        while len(old) < 10:
            old.append("")
        details = []
        try:
            details = list((getattr(self, "detail_rows_by_invoice", {}) or {}).get(fat) or [])
        except Exception:
            details = []
        if not details:
            return None
        partner = old[1]
        if not partner or _norm(partner) in {"PARCEIRO NAO IDENTIFICADO", "TODOS"}:
            # Tenta localizar pelo documento original.
            for doc in getattr(self, "invoice_docs", []) or []:
                if isinstance(doc, dict) and (_norm_invoice(doc.get("fatura")) == fat):
                    p = str(doc.get("parceiro") or "").strip()
                    if p and _norm(p) not in {"PARCEIRO NAO IDENTIFICADO", "TODOS"}:
                        partner = p
                        break
            # Tenta localizar por registros de detalhe.
            if not partner:
                for rec in getattr(self, "invoice_detail_records", []) or []:
                    if isinstance(rec, dict) and _norm_invoice(rec.get("Fatura")) == fat:
                        p = str(rec.get("Parceiro") or "").strip()
                        if p and _norm(p) not in {"PARCEIRO NAO IDENTIFICADO", "TODOS"}:
                            partner = p
                            break
        qtd = len(details)
        ok = sum(1 for d in details if _record_status_ok(d))
        problema = qtd - ok
        valor_fat = sum(_money_to_float((list(d) + [""] * 3)[2]) for d in details)
        valor_np = sum(_money_to_float((list(d) + [""] * 10)[2]) for d in details if not _record_status_ok(d))
        valores = f"Fatura {_money_fmt(valor_fat)} | Não pagar {_money_fmt(valor_np)} | A pagar {_money_fmt(max(valor_fat - valor_np, 0.0))}"
        comprovantes = f"OK {ok} | Pend. {problema} | Revisar 0"
        status = "OK PAGAR" if problema == 0 else ("PAGAR PARCIAL" if ok else "NÃO PAGAR")
        return [fat, partner or "Parceiro não identificado", str(qtd), str(ok), str(problema), _money_fmt(valor_fat), _money_fmt(valor_np), valores, comprovantes, status]

    def _repair_invoice_summary_ui(self, main_mod=None):
        table = getattr(self, "invoice_table", None)
        if table is None:
            return 0
        try:
            row_count = table.rowCount()
            col_count = table.columnCount()
        except Exception:
            return 0
        cache_rows = []
        try:
            cache_rows = list(getattr(self, "invoice_rows", []) or [])
        except Exception:
            cache_rows = []
        fixed = 0
        for r in range(row_count):
            vals = [_table_text(table, r, c) for c in range(min(col_count, 10))]
            while len(vals) < 10:
                vals.append("")
            fat = _norm_invoice(vals[0]) or vals[0]
            if not fat:
                continue
            needs = not vals[1].strip() or not vals[2].strip() or not vals[5].strip()
            if not needs:
                continue
            replacement = None
            for row in cache_rows:
                row2 = list(row or [])
                while len(row2) < 10:
                    row2.append("")
                if (_norm_invoice(row2[0]) or row2[0]) == fat and row2[1].strip() and row2[2].strip():
                    replacement = row2[:10]
                    break
            if replacement is None:
                replacement = _derive_row_from_details(self, fat, vals)
            if replacement:
                for c, text in enumerate(replacement[:min(col_count, 10)]):
                    _set_table_text(table, r, c, text, main_mod)
                fixed += 1
                try:
                    # Atualiza o cache para os detalhes e filtros não voltarem ao estado velho.
                    rows = list(getattr(self, "invoice_rows", []) or [])
                    replaced = False
                    for i, row in enumerate(rows):
                        if (_norm_invoice((row or [""])[0]) or (row or [""])[0]) == fat:
                            rows[i] = replacement
                            replaced = True
                            break
                    if not replaced:
                        rows.append(replacement)
                    self.invoice_rows = rows
                except Exception:
                    pass
        return fixed

    def _collect_partners_from_current_data(self):
        partners = []
        for row in getattr(self, "invoice_rows", []) or []:
            try:
                p = str((row or ["", ""])[1] or "").strip()
                if p and _norm(p) not in {"PARCEIRO NAO IDENTIFICADO", "TODOS"}:
                    partners.append(p)
            except Exception:
                pass
        for doc in getattr(self, "invoice_docs", []) or []:
            if isinstance(doc, dict):
                p = str(doc.get("parceiro") or "").strip()
                if p and _norm(p) not in {"PARCEIRO NAO IDENTIFICADO", "TODOS"}:
                    partners.append(p)
        # Ordem estável e sem duplicar por acento/caixa.
        out, seen = ["Todos"], {"TODOS"}
        for p in partners:
            k = _norm(p)
            if k not in seen:
                seen.add(k)
                out.append(p)
        return out

    def _set_combo_values(combo, values):
        if combo is None:
            return False
        if not (hasattr(combo, "clear") and hasattr(combo, "addItems")):
            return False
        cur = ""
        try:
            cur = combo.currentText()
        except Exception:
            cur = ""
        try:
            combo.blockSignals(True)
        except Exception:
            pass
        try:
            combo.clear()
            combo.addItems(list(values))
            if _norm(cur) in {_norm(v) for v in values}:
                try:
                    combo.setCurrentText(cur)
                except Exception:
                    pass
            else:
                try:
                    combo.setCurrentIndex(0)
                except Exception:
                    try:
                        combo.setCurrentText("Todos")
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            combo.blockSignals(False)
        except Exception:
            pass
        return True

    def _sync_partner_filter_options(self, force_empty=False):
        values = ["Todos"] if force_empty else _collect_partners_from_current_data(self)
        changed = False
        for attr in dir(self):
            low = attr.lower()
            if "partner" in low and "filter" in low:
                try:
                    changed = _set_combo_values(getattr(self, attr), values) or changed
                except Exception:
                    pass
            if "parceiro" in low and "filter" in low:
                try:
                    changed = _set_combo_values(getattr(self, attr), values) or changed
                except Exception:
                    pass
        # Alguns nomes usados no PySide costumam não ter "filter" no atributo.
        for attr in ("partner_combo", "combo_partner", "cmb_partner", "parceiro_combo", "combo_parceiro"):
            try:
                changed = _set_combo_values(getattr(self, attr, None), values) or changed
            except Exception:
                pass
        for attr in ("partner_values", "partners", "filter_partners", "partner_filter_values"):
            if hasattr(self, attr):
                try:
                    val = getattr(self, attr)
                    if isinstance(val, list):
                        setattr(self, attr, values[:])
                    elif isinstance(val, set):
                        setattr(self, attr, set(values))
                except Exception:
                    pass
        return changed

    def _reset_faturas_state(self):
        for attr, empty in (
            ("invoice_docs", []),
            ("invoice_rows", []),
            ("invoice_detail_records", []),
            ("detail_rows_by_invoice", {}),
        ):
            if hasattr(self, attr):
                try:
                    setattr(self, attr, empty.copy() if hasattr(empty, "copy") else empty)
                except Exception:
                    pass
        _sync_partner_filter_options(self, force_empty=True)
        try:
            table = getattr(self, "invoice_table", None)
            if table is not None:
                table.setRowCount(0)
        except Exception:
            pass

    def _rewrite_partner_message_text(text):
        original = str(text or "")
        if not original.strip():
            return original
        t = original.replace("Valor bloqueado", "Valor a retirar")
        t = t.replace("Faturas/CT-es pendentes:", "CT-e(s) a retirar da fatura atual:")
        m = _re.search(r"Prezados,\s*identificamos pendência de comprovante de entrega referente ao parceiro\s+(.+?)\.", t, _re.I)
        if m:
            parceiro = m.group(1).strip()
            novo_inicio = (
                f"Prezados,\n\n"
                f"Identificamos CT-e(s) sem comprovante de entrega na fatura do parceiro {parceiro}.\n\n"
                "Solicitamos, por gentileza, retirar o(s) CT-e(s) abaixo da fatura atual e incluí-lo(s) em uma próxima fatura somente após o envio/regularização do comprovante de entrega."
            )
            t = t[:m.start()] + novo_inicio + t[m.end():]
        elif "Solicitamos, por gentileza, retirar" not in t and "sem comprovante" in _norm(t):
            t = "Prezados,\n\nSolicitamos, por gentileza, retirar da fatura atual os CT-e(s) sem comprovante e incluí-lo(s) em próxima fatura somente após regularização.\n\n" + t
        t = _re.sub(
            r"Valor temporariamente bloqueado por comprovante pendente:\s*(R\$\s*[\d.,]+)\.",
            r"Valor a retirar da fatura atual: \1.",
            t,
            flags=_re.I,
        )
        t = _re.sub(
            r"Valor de referência liberado,\s*desconsiderando estes CT-es pendentes:\s*(R\$\s*[\d.,]+)\.",
            r"Valor liberado para pagamento nesta análise, desconsiderando esses CT-e(s): \1.",
            t,
            flags=_re.I,
        )
        t = _re.sub(
            r"Favor regularizar/enviar os comprovantes para nova análise e liberação do pagamento pendente\.",
            "Após o envio do comprovante, o(s) CT-e(s) poderá(ão) ser reapresentado(s) nas próximas faturas para nova análise.",
            t,
            flags=_re.I,
        )
        # Limpa excesso de linhas em branco sem esmagar os blocos.
        t = _re.sub(r"\n{3,}", "\n\n", t).strip() + "\n"
        return t

    def _rewrite_obj_messages(obj):
        if isinstance(obj, str):
            return _rewrite_partner_message_text(obj)
        if isinstance(obj, list):
            return [_rewrite_obj_messages(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_rewrite_obj_messages(x) for x in obj)
        if isinstance(obj, dict):
            return {k: _rewrite_obj_messages(v) for k, v in obj.items()}
        return obj

    def _message_roots(main_mod=None):
        roots = []
        for fn_name in ("app_runtime_dir", "runtime_dir"):
            fn = globals().get(fn_name) or (getattr(main_mod, fn_name, None) if main_mod is not None else None)
            if callable(fn):
                try:
                    roots.append(_Path(fn()))
                except Exception:
                    pass
        try:
            roots.append(_Path.cwd())
        except Exception:
            pass
        try:
            roots.append(_Path(getattr(_sys, "executable", "")).resolve().parent)
        except Exception:
            pass
        out = []
        for r in roots:
            if r and r.exists() and r not in out:
                out.append(r)
        return out

    def _rewrite_message_files(main_mod=None):
        touched = 0
        for root in _message_roots(main_mod):
            rel = root / "relatorios"
            if not rel.exists():
                continue
            try:
                files = list(rel.glob("mensagens_parceiros*/mensagem*.txt")) + list(rel.glob("**/mensagem*.txt"))
            except Exception:
                files = []
            seen = set()
            for p in files:
                try:
                    if p in seen or not p.is_file():
                        continue
                    seen.add(p)
                    txt = p.read_text(encoding="utf-8", errors="ignore")
                    new = _rewrite_partner_message_text(txt)
                    if new != txt:
                        p.write_text(new, encoding="utf-8")
                        touched += 1
                except Exception:
                    pass
        return touched

    def _wrap_method(cls, name, wrapper_factory):
        if not hasattr(cls, name):
            return False
        key = f"_hotfix_2632_wrapped_{name}"
        if getattr(cls, key, False):
            return False
        orig = getattr(cls, name)
        if not callable(orig):
            return False
        try:
            setattr(cls, f"_original_{name}_2632", orig)
            setattr(cls, name, wrapper_factory(orig))
            setattr(cls, key, True)
            return True
        except Exception:
            return False

    def _patch_app_class(AppCls, main_mod=None):
        if AppCls is None or getattr(AppCls, "_hotfix_dedup_docs_2632", False):
            return
        def make_add_paths(orig):
            def wrapped(self, paths, *args, **kwargs):
                before = len(getattr(self, "files", []) or [])
                result = orig(self, paths, *args, **kwargs)
                try:
                    removed = _dedupe_xml_files(self)
                    if removed:
                        for fn_name in ("refresh_table", "update_stats", "update_filter_options"):
                            fn = getattr(self, fn_name, None)
                            if callable(fn):
                                try:
                                    fn()
                                except Exception:
                                    pass
                        if hasattr(self, "set_status"):
                            self.set_status(f"Documento repetido bloqueado/removido: {removed}. Total: {len(getattr(self, 'files', []) or [])}.")
                except Exception:
                    pass
                return result
            return wrapped
        _wrap_method(AppCls, "add_paths", make_add_paths)
        AppCls._hotfix_dedup_docs_2632 = True

    def _patch_faturas_class(FaturasPage, main_mod=None):
        if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2632", False):
            return

        def after_common(self, removed_msg=True):
            try:
                removed = _dedupe_invoice_docs(self)
                _repair_invoice_summary_ui(self, main_mod)
                _sync_partner_filter_options(self, force_empty=not bool(getattr(self, "invoice_docs", []) or getattr(self, "invoice_rows", [])))
                if removed and removed_msg and hasattr(self, "set_status"):
                    self.set_status(f"Documento de fatura repetido bloqueado/removido: {removed}.")
            except Exception:
                pass

        def make_after(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                after_common(self)
                return result
            return wrapped

        def make_clear(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    _reset_faturas_state(self)
                    if hasattr(self, "set_status"):
                        self.set_status("Lista de faturas limpa. Filtros e histórico visual também foram limpos.")
                except Exception:
                    pass
                return result
            return wrapped

        def make_refresh_partner(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    _sync_partner_filter_options(self, force_empty=not bool(getattr(self, "invoice_docs", []) or getattr(self, "invoice_rows", [])))
                except Exception:
                    pass
                return result
            return wrapped

        def make_message(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    return _rewrite_obj_messages(result)
                except Exception:
                    return result
            return wrapped

        def make_export(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    _rewrite_message_files(main_mod)
                except Exception:
                    pass
                return result
            return wrapped

        # Métodos que normalmente adicionam/processam/filtram faturas.
        for name in (
            "add_invoices", "add_invoice_files", "add_faturas", "add_invoice_docs", "add_files",
            "load_invoices", "load_invoice_files", "load_faturas", "process_invoices",
            "apply_filters", "refresh_table", "add_invoice_row", "load_details_for_selected"
        ):
            _wrap_method(FaturasPage, name, make_after)

        for name in ("refresh_partner_filter", "update_partner_filter", "refresh_filters", "update_filters"):
            _wrap_method(FaturasPage, name, make_refresh_partner)

        # Limpeza da aba. Só aplica em nomes existentes para não inventar comportamento.
        for name in (
            "clear_list", "clear_invoices", "clear_faturas", "clear_invoice_list", "clear_all", "clear_files",
            "clear_docs", "clear_documents", "clear_faturas_list", "clear_invoice_docs", "reset_invoices",
            "limpar_lista", "limpar_faturas", "limpar_documentos", "remove_all_invoices"
        ):
            _wrap_method(FaturasPage, name, make_clear)

        # Varredura segura: cobre nomes próprios da classe que limpam lista de faturas/documentos.
        for name in getattr(FaturasPage, "__dict__", {}):
            low = str(name).lower()
            if low.startswith("_"):
                continue
            if ("clear" in low or "limpar" in low or "reset" in low) and any(k in low for k in ("invoice", "fatura", "doc", "file", "list", "lista")):
                _wrap_method(FaturasPage, name, make_clear)

        # Qualquer método explícito de mensagem recebe o novo texto.
        for name in dir(FaturasPage):
            low = name.lower()
            if ("mensag" in low or "message" in low) and not low.startswith("_"):
                _wrap_method(FaturasPage, name, make_message)
            if (("export" in low or "relatorio" in low or "report" in low) and not low.startswith("_")):
                _wrap_method(FaturasPage, name, make_export)

        # Build report já era hotfixado em versões anteriores; também varremos mensagens após gerar.
        _wrap_method(FaturasPage, "build_invoice_report_sheets", make_export)
        FaturasPage._hotfix_faturas_2632 = True
        try:
            if hasattr(main_mod, "APP_VERSION") and "Faturas 2.6.32" not in str(main_mod.APP_VERSION):
                main_mod.APP_VERSION = str(main_mod.APP_VERSION) + " + Faturas 2.6.32"
        except Exception:
            pass

    def _find_and_patch():
        patched = False
        mods = []
        main_mod = _sys.modules.get("__main__")
        if main_mod is not None:
            mods.append(main_mod)
        mods.extend(list(_sys.modules.values()))
        seen_mods = set()
        for mod in mods:
            if mod is None or id(mod) in seen_mods:
                continue
            seen_mods.add(id(mod))
            try:
                if hasattr(mod, "FaturasPage"):
                    _patch_faturas_class(getattr(mod, "FaturasPage"), mod)
                    patched = True
                if hasattr(mod, "App"):
                    _patch_app_class(getattr(mod, "App"), mod)
                    patched = True
            except Exception:
                pass
        # Também aplica no App desta engine, se existir.
        try:
            _patch_app_class(globals().get("App"), _sys.modules.get(__name__))
            patched = True
        except Exception:
            pass
        return patched

    def _worker():
        for _ in range(80):
            try:
                _find_and_patch()
            except Exception:
                pass
            _time.sleep(0.25)

    try:
        _find_and_patch()
        _threading.Thread(target=_worker, daemon=True).start()
    except Exception:
        pass

_central_cte_hotfix_faturas_2632_start()


# ============================================================================
# HOTFIX XML Dedup 2.6.33
# - Bloqueia XML repetido por chave do CT-e/NF-e, mesmo se o arquivo vier com
#   outro nome ou de outra pasta.
# - Revalida a lista antes de atualizar a tabela, evitando histórico visual
#   duplicado depois de sessão, pasta ou adição em lote.
# - Aplica também em páginas/módulos PySide que tenham lista própria de XMLs.
# ============================================================================
def _central_cte_hotfix_xml_dedup_2633_start():
    import os as _os, re as _re, sys as _sys, time as _time, threading as _threading, hashlib as _hashlib
    from pathlib import Path as _Path
    import xml.etree.ElementTree as _ET

    def _digits(value):
        return _re.sub(r"\D", "", str(value or ""))

    def _norm_path(value):
        try:
            return _os.path.normcase(_os.path.abspath(str(value or "")))
        except Exception:
            return str(value or "").strip().lower()

    def _sha1_file(path):
        try:
            h = _hashlib.sha1()
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""

    def _xml_key_from_file(path):
        p = _Path(path)
        if not p.exists():
            return ("missing", _norm_path(path))
        if p.suffix.lower() != ".xml":
            return ("path", _norm_path(path))
        try:
            root = _ET.parse(p).getroot()
            # Chave do CT-e/NF-e pelo Id da tag infCte/infNFe.
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("infCte", "infNFe", "infMDFe"):
                    raw_id = str(elem.attrib.get("Id", "") or "")
                    d = _digits(raw_id)
                    if len(d) >= 44:
                        return (tag.lower(), d[-44:])
            # Fallback por tags de protocolo/documento.
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("chCTe", "chNFe", "chMDFe", "chave"):
                    d = _digits(elem.text or "")
                    if len(d) >= 44:
                        return (tag.lower(), d[-44:])
        except Exception:
            pass
        # XML sem chave clara: usa hash do conteúdo para pegar cópia com outro nome.
        digest = _sha1_file(p)
        if digest:
            return ("xml_sha1", digest)
        return ("path", _norm_path(path))

    def _info_path(info):
        if isinstance(info, dict):
            return str(info.get("path") or info.get("caminho") or info.get("arquivo_path") or "")
        for attr in ("path", "caminho", "arquivo_path"):
            try:
                v = getattr(info, attr)
                if v:
                    return str(v)
            except Exception:
                pass
        if isinstance(info, (str, _Path)):
            return str(info)
        return ""

    def _info_xml_key(info):
        if isinstance(info, dict):
            for field in ("chave", "chCTe", "chave_cte", "chave_nfe", "chNFe", "id", "Id"):
                d = _digits(info.get(field, ""))
                if len(d) >= 44:
                    return ("xml_chave", d[-44:])
            p = _info_path(info)
            if p:
                return _xml_key_from_file(p)
            tipo = str(info.get("tipo") or "").upper()
            numero = str(info.get("numero") or "").strip()
            serie = str(info.get("serie") or "").strip()
            emitente = str(info.get("emitente") or "").strip().upper()
            valor = str(info.get("valor") or "").strip()
            if tipo or numero or serie or emitente or valor:
                return ("xml_meta", tipo, numero, serie, emitente, valor)
        p = _info_path(info)
        if p:
            return _xml_key_from_file(p)
        return ("obj", id(info))

    def _dedupe_list(seq):
        fixed = []
        seen = set()
        removed = 0
        for item in list(seq or []):
            key = _info_xml_key(item)
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            fixed.append(item)
        return fixed, removed

    def _refresh_app_like(self):
        for name in ("refresh_table", "update_stats", "update_filter_options", "refresh_filter_chips", "update_cards", "refresh_docs", "apply_filters"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def _dedupe_common_xml_attrs(self):
        removed_total = 0
        # Listas comuns no app Tk e nas páginas PySide.
        for attr in (
            "files", "xmls", "xml_files", "xml_docs", "xml_infos", "infos_xml", "cte_files", "cte_docs",
            "documentos_xml", "lista_xmls", "loaded_xmls", "loaded_files", "documents", "docs"
        ):
            try:
                val = getattr(self, attr, None)
            except Exception:
                continue
            if not isinstance(val, list) or not val:
                continue
            # Só mexe quando a lista tem XML/dict de documento; evita tocar em listas internas não relacionadas.
            looks_xml = False
            for item in val[:8]:
                p = _info_path(item)
                if p.lower().endswith(".xml"):
                    looks_xml = True
                    break
                if isinstance(item, dict) and str(item.get("tipo") or "").upper() in ("CT-E", "NF-E", "XML", "XML INVÁLIDO"):
                    looks_xml = True
                    break
            if not looks_xml and attr not in ("files", "xml_files", "xml_docs", "xmls"):
                continue
            fixed, removed = _dedupe_list(val)
            if removed:
                try:
                    setattr(self, attr, fixed)
                    removed_total += removed
                except Exception:
                    pass
        # Mantém seleção sem caminhos removidos.
        try:
            if hasattr(self, "files") and hasattr(self, "selected_paths"):
                valid = {_info_path(x) for x in getattr(self, "files", []) if _info_path(x)}
                self.selected_paths = {p for p in getattr(self, "selected_paths", set()) if p in valid}
        except Exception:
            pass
        return removed_total

    def _replace_app_add_paths(AppCls):
        if AppCls is None or getattr(AppCls, "_hotfix_xml_dedup_2633_app", False):
            return
        orig_add_paths = getattr(AppCls, "add_paths", None)
        if not callable(orig_add_paths):
            return

        def add_paths_dedup(self, paths):
            added = 0
            skipped = 0
            errors = []
            existing = set()
            try:
                for info in getattr(self, "files", []) or []:
                    existing.add(_info_xml_key(info))
            except Exception:
                existing = set()
            # Também inclui chaves de XML já removidas por path igual.
            seen = set(existing)
            for raw in list(paths or []):
                p = _Path(raw)
                if not p.exists():
                    continue
                key = _xml_key_from_file(p)
                if key in seen:
                    skipped += 1
                    continue
                seen.add(key)
                try:
                    if p.suffix.lower() == ".xml":
                        info = parse_xml(p)
                    else:
                        # Para não quebrar o fluxo original, arquivos não XML continuam aceitos por caminho.
                        info = {
                            "tipo": p.suffix.upper().replace(".", ""),
                            "numero": "", "serie": "", "emitente": "",
                            "destinatario": "", "valor": "",
                            "arquivo": p.name, "path": str(p)
                        }
                    if isinstance(info, dict):
                        info["dedup_key"] = "|".join(map(str, key))
                    self.files.append(info)
                    added += 1
                except Exception as e:
                    errors.append(f"{p.name}: {e}")
            removed = _dedupe_common_xml_attrs(self)
            _refresh_app_like(self)
            try:
                self.update_stats()
            except Exception:
                pass
            if errors:
                try:
                    messagebox.showwarning(APP_TITLE, "Alguns arquivos não foram carregados:\n\n" + "\n".join(errors[:10]))
                except Exception:
                    pass
            msg = f"{added} arquivo(s) adicionado(s). Total: {len(getattr(self, 'files', []) or [])}."
            if skipped or removed:
                msg += f" XML/documento repetido ignorado/removido: {skipped + removed}."
            try:
                self.set_status(msg)
            except Exception:
                pass

        def refresh_table_dedup(orig_refresh):
            def wrapped(self, *args, **kwargs):
                try:
                    _dedupe_common_xml_attrs(self)
                except Exception:
                    pass
                return orig_refresh(self, *args, **kwargs)
            return wrapped

        try:
            AppCls._original_add_paths_2633 = orig_add_paths
            AppCls.add_paths = add_paths_dedup
            if callable(getattr(AppCls, "refresh_table", None)) and not getattr(AppCls, "_hotfix_xml_dedup_2633_refresh", False):
                AppCls._original_refresh_table_2633 = getattr(AppCls, "refresh_table")
                AppCls.refresh_table = refresh_table_dedup(getattr(AppCls, "refresh_table"))
                AppCls._hotfix_xml_dedup_2633_refresh = True
            AppCls._hotfix_xml_dedup_2633_app = True
        except Exception:
            pass

    def _wrap_method(cls, name, wrapper_factory):
        try:
            if not hasattr(cls, name):
                return False
            key = f"_hotfix_xml_dedup_2633_wrapped_{name}"
            if getattr(cls, key, False):
                return False
            orig = getattr(cls, name)
            if not callable(orig):
                return False
            setattr(cls, f"_original_{name}_xml_dedup_2633", orig)
            setattr(cls, name, wrapper_factory(orig))
            setattr(cls, key, True)
            return True
        except Exception:
            return False

    def _patch_xml_owner_class(Cls, main_mod=None):
        if Cls is None or getattr(Cls, "_hotfix_xml_dedup_2633_generic", False):
            return
        def after(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    removed = _dedupe_common_xml_attrs(self)
                    if removed:
                        _refresh_app_like(self)
                        fn = getattr(self, "set_status", None) or getattr(self, "status", None)
                        if callable(fn):
                            try:
                                fn(f"XML repetido bloqueado/removido: {removed}.")
                            except Exception:
                                pass
                except Exception:
                    pass
                return result
            return wrapped
        # Métodos com cara de carregar/adicionar XML/documento.
        for name in dir(Cls):
            low = str(name).lower()
            if low.startswith("_"):
                continue
            if ("xml" in low or "arquivo" in low or "file" in low or "doc" in low) and any(k in low for k in ("add", "adicion", "load", "carreg", "open", "process", "refresh", "clear", "limpar")):
                _wrap_method(Cls, name, after)
        try:
            Cls._hotfix_xml_dedup_2633_generic = True
        except Exception:
            pass

    def _find_and_patch():
        main_mod = _sys.modules.get("__main__")
        mods = []
        if main_mod is not None:
            mods.append(main_mod)
        mods.extend(list(_sys.modules.values()))
        seen = set()
        for mod in mods:
            if mod is None or id(mod) in seen:
                continue
            seen.add(id(mod))
            try:
                if hasattr(mod, "App"):
                    _replace_app_add_paths(getattr(mod, "App"))
                if hasattr(mod, "FaturasPage"):
                    _patch_xml_owner_class(getattr(mod, "FaturasPage"), mod)
                # Páginas com nome relacionado a XML/DACTE/CTE também recebem dedupe.
                for cls_name in ("XmlPage", "XMLPage", "DactePage", "CTePage", "MainWindow"):
                    if hasattr(mod, cls_name):
                        _patch_xml_owner_class(getattr(mod, cls_name), mod)
                if hasattr(mod, "APP_VERSION") and "XML Dedup 2.6.33" not in str(getattr(mod, "APP_VERSION")):
                    try:
                        mod.APP_VERSION = str(mod.APP_VERSION) + " + XML Dedup 2.6.33"
                    except Exception:
                        pass
            except Exception:
                pass
        try:
            _replace_app_add_paths(globals().get("App"))
        except Exception:
            pass

    def _worker():
        for _ in range(100):
            try:
                _find_and_patch()
            except Exception:
                pass
            _time.sleep(0.20)

    try:
        _find_and_patch()
        _threading.Thread(target=_worker, daemon=True).start()
    except Exception:
        pass

# 2.6.40: chamada desativada; add_paths direto do App já faz dedup + log correto.
