# ============================================================================
# HOTFIX Faturas Parceiros 2.6.34
# - Recalcula a tela de resumo pelo detalhe real dos CT-es, não pela linha antiga.
# - Corrige fatura parcial aparecendo como OK PAGAR na interface.
# - Padroniza o badge do status e força largura/alinhamento das colunas.
# ============================================================================
def _central_cte_hotfix_faturas_2634_start():
    import sys as _sys, time as _time, threading as _threading, re as _re

    def _strip_acc(s):
        try:
            import unicodedata as _unicodedata
            return "".join(c for c in _unicodedata.normalize("NFD", str(s or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(s or "")

    def _norm(s):
        return _re.sub(r"\s+", " ", _strip_acc(str(s or "")).strip()).upper()

    def _norm_invoice(value):
        s = str(value or "")
        if not s or _norm(s).startswith("EMISS"):
            return ""
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            m = _re.search(r"(?i)\bFat\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]", s)
        if not m:
            return ""
        base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
        dig = _re.sub(r"\D", "", m.group(2))[:1]
        return f"{base.zfill(7)}-{dig}" if dig else ""

    def _money_to_float(value):
        if isinstance(value, (int, float)):
            try:
                return float(value)
            except Exception:
                return 0.0
        s = str(value or "").strip()
        if not s:
            return 0.0
        s = s.replace("R$", "").replace(" ", "")
        s = _re.sub(r"[^0-9,.-]", "", s)
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_fmt(value):
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _clean_partner(value):
        s = _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()
        if not s:
            return ""
        up = _norm(s)
        if up in {"TODOS", "PARCEIRO NAO IDENTIFICADO", "NAO IDENTIFICADO", "NÃO IDENTIFICADO"}:
            return ""
        if up.startswith("FAT") and _re.search(r"\d", up):
            return ""
        if _norm_invoice(s):
            return ""
        return s[:90]

    def _record_cte(rec):
        if isinstance(rec, dict):
            return str(rec.get("CT-e fatura") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("CT-e") or rec.get("cte") or "").strip()
        vals = list(rec or [])
        return str(vals[0] if len(vals) > 0 else "").strip()

    def _record_nf(rec):
        if isinstance(rec, dict):
            return str(rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or rec.get("nf") or "").strip()
        vals = list(rec or [])
        return str(vals[1] if len(vals) > 1 else "").strip()

    def _record_value(rec):
        if isinstance(rec, dict):
            return _money_to_float(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("Valor Fat.") or rec.get("valor") or rec.get("Valor não pagar") or 0)
        vals = list(rec or [])
        return _money_to_float(vals[2] if len(vals) > 2 else 0)

    def _record_comp(rec):
        if isinstance(rec, dict):
            return str(rec.get("Comprovante") or rec.get("Comprovante OK?") or rec.get("comprovante") or "").strip()
        vals = list(rec or [])
        return str(vals[6] if len(vals) > 6 else "").strip()

    def _record_dy(rec):
        if isinstance(rec, dict):
            return str(rec.get("DY") or rec.get("dy") or "").strip().upper()
        return ""

    def _record_scan(rec):
        if isinstance(rec, dict):
            return str(rec.get("Data/Hora escaneamento") or rec.get("Escaneamento") or "").strip() or "-"
        vals = list(rec or [])
        return str(vals[7] if len(vals) > 7 else "-").strip() or "-"

    def _record_status(rec):
        if isinstance(rec, dict):
            return str(rec.get("Status final CT-e") or rec.get("Status CT-e") or rec.get("status") or "").strip()
        vals = list(rec or [])
        return str(vals[8] if len(vals) > 8 else "").strip()

    def _record_obs(rec):
        if isinstance(rec, dict):
            return str(rec.get("Motivo") or rec.get("Observação") or rec.get("observacao") or "").strip()
        vals = list(rec or [])
        return str(vals[9] if len(vals) > 9 else "").strip()

    def _record_is_ok(rec):
        dy = _record_dy(rec)
        comp = _norm(_record_comp(rec))
        st = _norm(_record_status(rec))
        obs = _norm(_record_obs(rec))
        if dy == "N" or comp in {"NAO", "NÃO"} or "SEM COMPROVANTE" in st or "SEM COMPROVANTE" in comp or "SEM COMPROVANTE" in obs:
            return False
        if dy == "S" or comp in {"SIM", "OK", "COMPROVANTE OK"} or st.startswith("OK"):
            return True
        return False

    def _partner_by_fat_from_existing(self):
        out = {}
        for row in getattr(self, "invoice_rows", []) or []:
            try:
                fat = _norm_invoice((row or [""])[0])
                p = _clean_partner((row or ["", ""])[1])
                if fat and p and fat not in out:
                    out[fat] = p
            except Exception:
                pass
        for rec in getattr(self, "invoice_detail_records", []) or []:
            try:
                fat = _norm_invoice(rec.get("Fatura")) if isinstance(rec, dict) else ""
                p = _clean_partner(rec.get("Parceiro")) if isinstance(rec, dict) else ""
                if fat and p and fat not in out:
                    out[fat] = p
            except Exception:
                pass
        for doc in getattr(self, "invoice_docs", []) or []:
            try:
                if not isinstance(doc, dict):
                    continue
                fat = _norm_invoice(doc.get("fatura") or doc.get("Fatura") or doc.get("arquivo") or doc.get("path"))
                p = _clean_partner(doc.get("parceiro") or doc.get("partner") or doc.get("Parceiro"))
                if fat and p and fat not in out:
                    out[fat] = p
            except Exception:
                pass
        return out

    def _collect_canonical_details(self):
        partner_map = _partner_by_fat_from_existing(self)
        groups = {}
        order = []
        seen = set()

        def add(fat, partner, rec):
            fat = _norm_invoice(fat) or _norm_invoice(str(fat or ""))
            if not fat:
                return
            cte = _record_cte(rec) or "-"
            nf = _record_nf(rec) or "-"
            val = round(_record_value(rec), 2)
            st = _record_status(rec)
            comp = _record_comp(rec)
            key = (fat, _norm(cte), _norm(nf), val, _norm(st), _norm(comp))
            if key in seen:
                return
            seen.add(key)
            p = _clean_partner(partner) or partner_map.get(fat) or "Parceiro não identificado"
            detail = {
                "fat": fat,
                "partner": p,
                "cte": cte,
                "nf": nf,
                "value": val,
                "xml_value": _money_to_float(rec.get("Valor XML") or 0) if isinstance(rec, dict) else _money_to_float((list(rec or []) + [""] * 4)[3]),
                "status_valor": (str(rec.get("Status valor") or rec.get("Valor OK?") or "-") if isinstance(rec, dict) else str((list(rec or []) + [""] * 5)[4] or "-")),
                "fatura_base": (str(rec.get("Conferência fatura base") or rec.get("Fatura Base") or "-") if isinstance(rec, dict) else str((list(rec or []) + [""] * 6)[5] or "-")),
                "comp": comp or ("COMPROVANTE OK" if _record_is_ok(rec) else "SEM COMPROVANTE"),
                "scan": _record_scan(rec),
                "status": st or ("OK PAGAR" if _record_is_ok(rec) else "SEM COMPROVANTE"),
                "obs": _record_obs(rec),
                "ok": _record_is_ok(rec),
            }
            if fat not in groups:
                groups[fat] = []
                order.append(fat)
            groups[fat].append(detail)
            if p and p != "Parceiro não identificado" and fat not in partner_map:
                partner_map[fat] = p

        # Fonte principal: registros detalhados do processamento.
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if not isinstance(rec, dict):
                continue
            add(rec.get("Fatura"), rec.get("Parceiro"), rec)

        # Fonte complementar: cache visual de detalhes por fatura.
        try:
            detail_map = getattr(self, "detail_rows_by_invoice", {}) or {}
            for fat, details in detail_map.items():
                for d in details or []:
                    add(fat, partner_map.get(_norm_invoice(fat), ""), d)
        except Exception:
            pass

        # Ordem preferida: mantém a ordem já mostrada na tabela/resumo.
        preferred = []
        for row in getattr(self, "invoice_rows", []) or []:
            try:
                fat = _norm_invoice((row or [""])[0])
                if fat and fat in groups and fat not in preferred:
                    preferred.append(fat)
            except Exception:
                pass
        for fat in order:
            if fat not in preferred:
                preferred.append(fat)
        return groups, preferred, partner_map

    def _summary_from_groups(self):
        groups, order, partner_map = _collect_canonical_details(self)
        rows = []
        detail_rows = {}
        for fat in order:
            details = groups.get(fat) or []
            if not details:
                continue
            partner = next((_clean_partner(d.get("partner")) for d in details if _clean_partner(d.get("partner"))), None) or partner_map.get(fat) or "Parceiro não identificado"
            qtd = len(details)
            ok = sum(1 for d in details if bool(d.get("ok")))
            problema = qtd - ok
            valor_fat = sum(float(d.get("value") or 0.0) for d in details)
            valor_np = sum(float(d.get("value") or 0.0) for d in details if not bool(d.get("ok")))
            status = "OK PAGAR" if problema == 0 else ("PAGAR PARCIAL" if ok > 0 else "NÃO PAGAR")
            valores = f"Fatura {_money_fmt(valor_fat)} | Não pagar {_money_fmt(valor_np)} | A pagar {_money_fmt(max(valor_fat - valor_np, 0.0))}"
            comprovantes = f"OK {ok} | Pend. {problema} | Revisar 0"
            rows.append([fat, partner, str(qtd), str(ok), str(problema), _money_fmt(valor_fat), _money_fmt(valor_np), valores, comprovantes, status])
            detail_rows[fat] = [[
                d.get("cte") or "-", d.get("nf") or "-", _money_fmt(d.get("value") or 0.0),
                _money_fmt(d.get("xml_value") or 0.0), d.get("status_valor") or "-", d.get("fatura_base") or "-",
                d.get("comp") or "-", d.get("scan") or "-", d.get("status") or "-", d.get("obs") or "",
            ] for d in details]
        return rows, detail_rows

    def _status_colors(status):
        st = _norm(status)
        if "PARCIAL" in st:
            return "#fff7db", "#996b00", "#ffd872"
        if st.startswith("OK"):
            return "#dcfce7", "#008236", "#b7efc5"
        if "NAO" in st or "NÃO" in st or "DIVERG" in st or "SEM" in st:
            return "#ffe1e1", "#c8001f", "#ffc4c4"
        return "#eef4ff", "#08357c", "#cfe0ff"

    def _make_status_widget(text, main_mod=None):
        bg, fg, border = _status_colors(text)
        StatusBadge = getattr(main_mod, "StatusBadge", None) if main_mod is not None else None
        if StatusBadge is not None:
            try:
                w = StatusBadge(str(text or ""))
                try:
                    w.setToolTip(str(text or ""))
                except Exception:
                    pass
                return w
            except Exception:
                pass
        try:
            QLabel = getattr(main_mod, "QLabel", None) if main_mod is not None else None
            Qt = getattr(main_mod, "Qt", None) if main_mod is not None else None
            if QLabel is None:
                from PySide6.QtWidgets import QLabel as QLabel
            if Qt is None:
                from PySide6.QtCore import Qt as Qt
            w = QLabel(str(text or ""))
            w.setAlignment(Qt.AlignCenter)
            w.setMinimumHeight(22)
            w.setStyleSheet(f"QLabel {{ background:{bg}; color:{fg}; border:1px solid {border}; border-radius:7px; padding:2px 8px; font-weight:700; }}")
            w.setToolTip(str(text or ""))
            return w
        except Exception:
            return None

    def _style_invoice_table(table, main_mod=None):
        if table is None:
            return
        try:
            Qt = getattr(main_mod, "Qt", None) if main_mod is not None else None
            QHeaderView = getattr(main_mod, "QHeaderView", None) if main_mod is not None else None
            if Qt is None:
                from PySide6.QtCore import Qt as Qt
            if QHeaderView is None:
                from PySide6.QtWidgets import QHeaderView as QHeaderView
            try:
                table.setWordWrap(False)
            except Exception:
                pass
            header = table.horizontalHeader()
            try:
                header.setDefaultAlignment(Qt.AlignCenter)
            except Exception:
                pass
            widths = [110, 230, 60, 60, 82, 122, 132, 270, 195, 135]
            for i, w in enumerate(widths):
                try:
                    if i < table.columnCount():
                        table.setColumnWidth(i, w)
                        header.setSectionResizeMode(i, QHeaderView.Interactive)
                except Exception:
                    pass
            try:
                table.verticalHeader().setVisible(False)
            except Exception:
                pass
        except Exception:
            pass

    def _insert_summary_row(table, row, main_mod=None):
        try:
            from PySide6.QtWidgets import QTableWidgetItem as _QTableWidgetItem
            from PySide6.QtCore import Qt as _Qt
            from PySide6.QtGui import QColor as _QColor
        except Exception:
            _QTableWidgetItem = getattr(main_mod, "QTableWidgetItem", None) if main_mod is not None else None
            _Qt = getattr(main_mod, "Qt", None) if main_mod is not None else None
            _QColor = getattr(main_mod, "QColor", None) if main_mod is not None else None
        try:
            r = table.rowCount()
            table.insertRow(r)
            col_count = table.columnCount()
        except Exception:
            return
        vals = list(row or [])
        while len(vals) < col_count:
            vals.append("")
        for c in range(col_count):
            txt = "" if vals[c] is None else str(vals[c])
            if _QTableWidgetItem is not None:
                try:
                    item = _QTableWidgetItem(txt)
                    item.setToolTip(txt)
                    if _Qt is not None:
                        if c in (2, 3, 4, 5, 6):
                            item.setTextAlignment(_Qt.AlignRight | _Qt.AlignVCenter)
                        else:
                            item.setTextAlignment(_Qt.AlignLeft | _Qt.AlignVCenter)
                    if _QColor is not None:
                        if c == 0:
                            item.setForeground(_QColor("#1257d8"))
                        elif c in (4, 6) and txt.strip() not in ("", "0", "0,00", "R$ 0,00", "-"):
                            item.setForeground(_QColor("#ed1b2f"))
                    table.setItem(r, c, item)
                except Exception:
                    pass
            if c == 9:
                try:
                    w = _make_status_widget(txt, main_mod)
                    if w is not None:
                        table.setCellWidget(r, c, w)
                except Exception:
                    pass
        try:
            table.setRowHeight(r, 32)
        except Exception:
            pass

    def _sync_invoice_ui_from_details(self, main_mod=None, rebuild=True):
        try:
            rows, detail_rows = _summary_from_groups(self)
        except Exception:
            rows, detail_rows = [], {}
        if not rows:
            try:
                _style_invoice_table(getattr(self, "invoice_table", None), main_mod)
            except Exception:
                pass
            return 0
        try:
            self.invoice_rows = rows
            self.detail_rows_by_invoice = detail_rows
        except Exception:
            pass
        table = getattr(self, "invoice_table", None)
        if table is None:
            return len(rows)
        if rebuild:
            try:
                table.setSortingEnabled(False)
            except Exception:
                pass
            try:
                table.setRowCount(0)
                for row in rows:
                    _insert_summary_row(table, row, main_mod)
            except Exception:
                pass
        else:
            # Apenas reestiliza o que estiver visível, útil após filtro.
            try:
                for r in range(table.rowCount()):
                    txt = ""
                    try:
                        item = table.item(r, 9)
                        txt = item.text() if item is not None else ""
                    except Exception:
                        pass
                    if not txt:
                        try:
                            w = table.cellWidget(r, 9)
                            txt = w.text() if hasattr(w, "text") else ""
                        except Exception:
                            pass
                    w = _make_status_widget(txt, main_mod)
                    if w is not None:
                        table.setCellWidget(r, 9, w)
            except Exception:
                pass
        try:
            _style_invoice_table(table, main_mod)
        except Exception:
            pass
        try:
            current = table.currentRow()
            if current < 0 and table.rowCount() > 0:
                table.selectRow(0)
        except Exception:
            pass
        return len(rows)

    def _schedule_sync(self, main_mod=None, rebuild=True):
        try:
            _sync_invoice_ui_from_details(self, main_mod, rebuild=rebuild)
        except Exception:
            pass
        # Garante uma segunda passada depois que a interface terminar de repintar.
        try:
            QTimer = getattr(main_mod, "QTimer", None) if main_mod is not None else None
            if QTimer is None:
                from PySide6.QtCore import QTimer as QTimer
            QTimer.singleShot(80, lambda: _sync_invoice_ui_from_details(self, main_mod, rebuild=rebuild))
            QTimer.singleShot(250, lambda: _sync_invoice_ui_from_details(self, main_mod, rebuild=rebuild))
        except Exception:
            pass

    def _wrap_method(cls, name, wrapper_factory):
        if not hasattr(cls, name):
            return False
        key = f"_hotfix_2634_wrapped_{name}"
        if getattr(cls, key, False):
            return False
        orig = getattr(cls, name)
        if not callable(orig):
            return False
        try:
            setattr(cls, f"_original_{name}_2634", orig)
            setattr(cls, name, wrapper_factory(orig))
            setattr(cls, key, True)
            return True
        except Exception:
            return False

    def _patch_faturas_class(FaturasPage, main_mod=None):
        if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2634", False):
            return

        def make_process(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    _schedule_sync(self, main_mod, rebuild=True)
                    if hasattr(self, "set_status"):
                        self.set_status("Faturas processadas: resumo visual recalculado por CT-e, com status parcial e colunas alinhadas.")
                except Exception:
                    pass
                return result
            return wrapped

        def make_refresh(orig):
            def wrapped(self, *args, **kwargs):
                result = orig(self, *args, **kwargs)
                try:
                    _schedule_sync(self, main_mod, rebuild=False)
                except Exception:
                    pass
                return result
            return wrapped

        def make_report(orig):
            def wrapped(self, *args, **kwargs):
                try:
                    _sync_invoice_ui_from_details(self, main_mod, rebuild=True)
                except Exception:
                    pass
                result = orig(self, *args, **kwargs)
                try:
                    _schedule_sync(self, main_mod, rebuild=True)
                except Exception:
                    pass
                return result
            return wrapped

        _wrap_method(FaturasPage, "process_invoices", make_process)
        for name in ("build_invoice_report_sheets", "export_report", "export_invoice_report", "exportar_relatorio"):
            _wrap_method(FaturasPage, name, make_report)
        for name in ("apply_filters", "refresh_table", "refresh_invoice_list", "load_details_for_selected"):
            _wrap_method(FaturasPage, name, make_refresh)

        # Expor utilitário para diagnóstico manual, caso necessário.
        try:
            FaturasPage._sync_invoice_ui_2634 = lambda self: _sync_invoice_ui_from_details(self, main_mod, rebuild=True)
        except Exception:
            pass
        FaturasPage._hotfix_faturas_2634 = True
        try:
            if hasattr(main_mod, "APP_VERSION") and "Faturas 2.6.34" not in str(main_mod.APP_VERSION):
                main_mod.APP_VERSION = str(main_mod.APP_VERSION) + " + Faturas 2.6.34"
        except Exception:
            pass

    def _find_and_patch():
        patched = False
        mods = []
        main_mod = _sys.modules.get("__main__")
        if main_mod is not None:
            mods.append(main_mod)
        mods.extend(list(_sys.modules.values()))
        seen = set()
        for mod in mods:
            if mod is None or id(mod) in seen:
                continue
            seen.add(id(mod))
            try:
                if hasattr(mod, "FaturasPage"):
                    _patch_faturas_class(getattr(mod, "FaturasPage"), mod)
                    patched = True
            except Exception:
                pass
        return patched

    def _worker():
        for _ in range(2400):
            if _find_and_patch():
                return
            _time.sleep(0.05)

    try:
        if not _find_and_patch():
            _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2634").start()
    except Exception:
        pass

_central_cte_hotfix_faturas_2634_start()

# ============================================================================
# HOTFIX XML Dedup 2.6.35
# - Deduplicação robusta para a aba XML/CT-e.
# - Bloqueia/limpa XML repetido por chave fiscal, hash do XML ou metadados.
# - Varre listas internas e tabelas visuais mesmo quando a tela usa classe
#   empacotada no .exe, não somente a classe App da engine.
# ============================================================================
def _central_cte_hotfix_xml_dedup_2635_start():
    import os as _os, re as _re, sys as _sys, time as _time, threading as _threading, hashlib as _hashlib, gc as _gc, inspect as _inspect
    from pathlib import Path as _Path
    import xml.etree.ElementTree as _ET

    _PATCH_TAG = "_hotfix_xml_dedup_2635"

    def _digits(value):
        return _re.sub(r"\D", "", str(value or ""))

    def _norm_path(value):
        try:
            return _os.path.normcase(_os.path.abspath(str(value or "")))
        except Exception:
            return str(value or "").strip().lower()

    def _sha1_file(path):
        try:
            h = _hashlib.sha1()
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""

    def _xml_key_from_file(path):
        p = _Path(str(path or ""))
        if not p.exists():
            return "PATH:" + _norm_path(path)
        if p.suffix.lower() != ".xml":
            return "PATH:" + _norm_path(path)
        try:
            root = _ET.parse(p).getroot()
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("infCte", "infNFe", "infMDFe"):
                    d = _digits(elem.attrib.get("Id", ""))
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("chCTe", "chNFe", "chMDFe", "chave"):
                    d = _digits(elem.text or "")
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
        except Exception:
            pass
        digest = _sha1_file(p)
        if digest:
            return "XMLSHA1:" + digest
        return "PATH:" + _norm_path(path)

    def _get_field(info, *names):
        if isinstance(info, dict):
            lowmap = {str(k).lower(): v for k, v in info.items()}
            for n in names:
                if n in info:
                    return info.get(n)
                if str(n).lower() in lowmap:
                    return lowmap[str(n).lower()]
            return ""
        for n in names:
            try:
                if hasattr(info, n):
                    return getattr(info, n)
            except Exception:
                pass
        return ""

    def _info_path(info):
        return str(_get_field(info, "path", "caminho", "arquivo_path", "file_path", "filename", "filepath") or "")

    def _info_key(info):
        # Chave fiscal em qualquer nome conhecido de campo.
        for field in ("chave", "chCTe", "chcte", "chave_cte", "cte_chave", "chNFe", "chnfe", "chave_nfe", "id", "Id"):
            d = _digits(_get_field(info, field))
            if len(d) >= 44:
                return "CHAVE:" + d[-44:]
        p = _info_path(info)
        if p:
            return _xml_key_from_file(p)
        # Fallback por metadados visíveis da grade.
        tipo = str(_get_field(info, "tipo", "type", "document_type") or "").strip().upper()
        numero = str(_get_field(info, "numero", "nCT", "nct", "number", "num") or "").strip()
        serie = str(_get_field(info, "serie", "série", "series") or "").strip()
        emitente = str(_get_field(info, "emitente", "emitter", "xNome", "partner") or "").strip().upper()
        nf = str(_get_field(info, "nf", "NF", "nfe", "nNF", "nota") or "").strip()
        valor = str(_get_field(info, "valor", "vTPrest", "total", "value") or "").strip()
        if ("CT" in tipo or tipo in ("XML", "NF-E", "NFE")) and (numero or nf) and (serie or emitente):
            return "META:" + "|".join([tipo, numero, serie, emitente, nf, valor])
        return ""

    def _looks_xml_item(item):
        try:
            p = _info_path(item)
            if p.lower().endswith(".xml"):
                return True
            tipo = str(_get_field(item, "tipo", "type") or "").upper()
            if any(x in tipo for x in ("CT-E", "CTE", "NF-E", "NFE", "XML")):
                return True
            if _info_key(item).startswith(("CHAVE:", "XMLSHA1:", "META:")):
                return True
        except Exception:
            pass
        return False

    def _list_is_candidate(attr_name, seq):
        low = str(attr_name or "").lower()
        if any(k in low for k in ("xml", "cte", "dacte", "doc", "file", "arquivo", "loaded", "carregado", "lista")):
            return True
        try:
            for item in list(seq or [])[:12]:
                if _looks_xml_item(item):
                    return True
        except Exception:
            pass
        return False

    def _dedupe_list(seq):
        fixed, seen, removed = [], set(), 0
        for item in list(seq or []):
            key = _info_key(item)
            if not key:
                fixed.append(item)
                continue
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            fixed.append(item)
        return fixed, removed

    def _dedupe_object_lists(obj):
        removed_total = 0
        try:
            data = vars(obj)
        except Exception:
            return 0
        for attr, val in list(data.items()):
            try:
                if not isinstance(val, list) or len(val) < 2:
                    continue
                if not _list_is_candidate(attr, val):
                    continue
                fixed, removed = _dedupe_list(val)
                if removed:
                    setattr(obj, attr, fixed)
                    removed_total += removed
            except Exception:
                pass
        # Limpa seleção baseada em caminhos removidos, se existir.
        try:
            for list_name in ("files", "xmls", "xml_files", "documentos_xml", "loaded_xmls", "loaded_files", "docs", "documents"):
                seq = getattr(obj, list_name, None)
                if isinstance(seq, list):
                    valid = {_info_path(x) for x in seq if _info_path(x)}
                    if valid and hasattr(obj, "selected_paths"):
                        obj.selected_paths = {p for p in getattr(obj, "selected_paths", set()) if p in valid}
        except Exception:
            pass
        return removed_total

    def _dedupe_qtable(table):
        # Remove linhas visualmente repetidas quando a tela é Qt/PySide e a lista interna não é exposta.
        try:
            row_count = int(table.rowCount())
            col_count = int(table.columnCount())
        except Exception:
            return 0
        if row_count < 2 or col_count < 3 or row_count > 5000:
            return 0
        seen = set()
        remove_rows = []
        for r in range(row_count):
            vals = []
            for c in range(min(col_count, 10)):
                txt = ""
                try:
                    it = table.item(r, c)
                    if it is not None:
                        txt = str(it.text() or "").strip()
                except Exception:
                    try:
                        idx = table.model().index(r, c)
                        txt = str(table.model().data(idx) or "").strip()
                    except Exception:
                        txt = ""
                vals.append(txt)
            joined = "|".join(vals).upper()
            # Só atua em linhas com cara de XML/CT-e, evitando mexer em tabelas de cadastro.
            if not ("CT-E" in joined or "CTE" in joined or ".XML" in joined or any(_re.fullmatch(r"\d{5,10}", v or "") for v in vals[:4])):
                continue
            # Preferência: Tipo + Número + Série + NF + Emitente.
            key = "ROW:" + "|".join([vals[0] if len(vals) > 0 else "", vals[1] if len(vals) > 1 else "", vals[2] if len(vals) > 2 else "", vals[3] if len(vals) > 3 else "", vals[5] if len(vals) > 5 else ""]).upper()
            if key in seen:
                remove_rows.append(r)
            else:
                seen.add(key)
        for r in reversed(remove_rows):
            try:
                table.removeRow(r)
            except Exception:
                pass
        return len(remove_rows)

    def _dedupe_object_tables(obj):
        removed = 0
        try:
            data = vars(obj)
        except Exception:
            data = {}
        for attr, val in list(data.items()):
            low = str(attr).lower()
            if not any(k in low for k in ("table", "grid", "tree", "lista", "list")):
                continue
            try:
                removed += _dedupe_qtable(val)
            except Exception:
                pass
        return removed

    def _safe_refresh(obj):
        for name in ("refresh_table", "atualizar_tabela", "update_table", "refresh_xml_table", "update_stats", "update_cards", "refresh_filter_chips", "apply_filters"):
            fn = getattr(obj, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def _dedupe_obj(obj, refresh=False):
        if obj is None or getattr(obj, "_dedup_2635_busy", False):
            return 0
        try:
            setattr(obj, "_dedup_2635_busy", True)
            removed = _dedupe_object_lists(obj)
            removed += _dedupe_object_tables(obj)
            if removed and refresh:
                _safe_refresh(obj)
                try:
                    fn = getattr(obj, "set_status", None) or getattr(obj, "status", None)
                    if callable(fn):
                        fn(f"XML repetido ignorado/removido: {removed}.")
                except Exception:
                    pass
            return removed
        except Exception:
            return 0
        finally:
            try:
                setattr(obj, "_dedup_2635_busy", False)
            except Exception:
                pass

    def _module_is_ours(mod_name):
        s = str(mod_name or "").lower()
        return s == "__main__" or "central" in s or "cte" in s or "dacte" in s or "engine" in s

    def _wrap_class(Cls):
        try:
            if Cls is None or getattr(Cls, _PATCH_TAG, False):
                return False
            if not _module_is_ours(getattr(Cls, "__module__", "")):
                return False
            setattr(Cls, _PATCH_TAG, True)
            patched_any = False
            for name, member in list(getattr(Cls, "__dict__", {}).items()):
                low = str(name).lower()
                if low.startswith("_"):
                    continue
                if not callable(member):
                    continue
                if not any(k in low for k in ("xml", "cte", "dacte", "add", "adicion", "carreg", "load", "open", "select", "selecion", "pasta", "file", "arquivo", "process", "refresh", "atual", "filter", "filtro", "limpar", "clear")):
                    continue
                orig = member
                def make_wrapped(_orig, _name):
                    def wrapped(self, *args, **kwargs):
                        is_refresh = any(k in str(_name).lower() for k in ("refresh", "atual", "update", "filter", "filtro"))
                        if not getattr(self, "_dedup_2635_busy", False):
                            _dedupe_obj(self, refresh=False)
                        result = _orig(self, *args, **kwargs)
                        removed = _dedupe_obj(self, refresh=(not is_refresh))
                        return result
                    try:
                        wrapped.__name__ = getattr(_orig, "__name__", "wrapped")
                    except Exception:
                        pass
                    return wrapped
                try:
                    setattr(Cls, name, make_wrapped(orig, name))
                    patched_any = True
                except Exception:
                    pass
            return patched_any
        except Exception:
            return False

    def _patch_known_app_add_paths():
        # Correção direta para a classe App da engine, quando ela existir.
        try:
            AppCls = globals().get("App")
            if AppCls is None or getattr(AppCls, "_hotfix_add_paths_direct_2635", False):
                return
            orig = getattr(AppCls, "add_paths", None)
            if not callable(orig):
                return
            def add_paths_dedup_2635(self, paths):
                # Reimplementa o carregamento com trava antes de append, não apenas depois.
                known_paths = set()
                known_keys = set()
                for info in getattr(self, "files", []) or []:
                    p0 = _info_path(info)
                    if p0:
                        known_paths.add(_norm_path(p0))
                    k0 = _info_key(info)
                    if k0:
                        known_keys.add(k0)
                added = 0
                skipped = 0
                errors = []
                for raw in list(paths or []):
                    try:
                        p = _Path(raw)
                        if not p.exists():
                            continue
                        npath = _norm_path(p)
                        pre_key = _xml_key_from_file(p) if p.suffix.lower() == ".xml" else "PATH:" + npath
                        if npath in known_paths or pre_key in known_keys:
                            skipped += 1
                            continue
                        if p.suffix.lower() == ".xml":
                            info = parse_xml(p)
                        else:
                            info = {
                                "tipo": p.suffix.upper().replace(".", ""),
                                "numero": "", "serie": "", "emitente": "",
                                "destinatario": "", "valor": "",
                                "arquivo": p.name, "path": str(p)
                            }
                        post_key = _info_key(info) or pre_key
                        if post_key in known_keys:
                            skipped += 1
                            continue
                        if isinstance(info, dict):
                            info["dedup_key"] = post_key
                        self.files.append(info)
                        known_paths.add(npath)
                        known_keys.add(post_key)
                        added += 1
                    except Exception as e:
                        try:
                            errors.append(f"{_Path(raw).name}: {e}")
                        except Exception:
                            errors.append(str(e))
                removed = _dedupe_obj(self, refresh=False)
                _safe_refresh(self)
                try:
                    self.update_stats()
                except Exception:
                    pass
                if errors:
                    try:
                        messagebox.showwarning(APP_TITLE, "Alguns arquivos não foram carregados:\n\n" + "\n".join(errors[:10]))
                    except Exception:
                        pass
                msg = f"{added} arquivo(s) adicionado(s). Total: {len(getattr(self, 'files', []) or [])}."
                if skipped or removed:
                    msg += f" Repetido(s) ignorado(s)/removido(s): {skipped + removed}."
                try:
                    self.set_status(msg)
                except Exception:
                    pass
                if skipped and not added:
                    try:
                        messagebox.showinfo(APP_TITLE, f"Nenhum XML novo adicionado.\n\nXML/documento repetido ignorado: {skipped}.")
                    except Exception:
                        pass
            AppCls.add_paths = add_paths_dedup_2635
            AppCls._hotfix_add_paths_direct_2635 = True
        except Exception:
            pass

    def _scan_and_patch():
        _patch_known_app_add_paths()
        # Patches em classes do app principal empacotado.
        for mod in list(_sys.modules.values()):
            if mod is None or not _module_is_ours(getattr(mod, "__name__", "")):
                continue
            try:
                for obj in list(vars(mod).values()):
                    if _inspect.isclass(obj):
                        _wrap_class(obj)
            except Exception:
                pass
        # Dedupe em instâncias já criadas.
        try:
            for obj in list(_gc.get_objects()):
                try:
                    cls = obj.__class__
                    if not _module_is_ours(getattr(cls, "__module__", "")):
                        continue
                    _dedupe_obj(obj, refresh=False)
                except Exception:
                    pass
        except Exception:
            pass

    def _worker():
        for _ in range(240):
            try:
                _scan_and_patch()
            except Exception:
                pass
            _time.sleep(0.15)

    try:
        _scan_and_patch()
        _threading.Thread(target=_worker, daemon=True).start()
    except Exception:
        pass

