# ============================================================================
# HOTFIX Log de Importacao XML 2.6.36
# - Cria tela de log após adicionar XML/CT-e.
# - Mostra quantos CT-e entraram e quantos foram ignorados/removidos por duplicidade.
# - Deduplica também tabelas visuais Qt/Tk que tenham recebido linha repetida.
# ============================================================================
def _central_cte_hotfix_log_importacao_xml_2636_start():
    import os as _os, re as _re, sys as _sys, time as _time, threading as _threading, hashlib as _hashlib, gc as _gc, inspect as _inspect
    from pathlib import Path as _Path
    import xml.etree.ElementTree as _ET

    _PATCH_TAG = "_hotfix_log_importacao_xml_2636"
    _DIALOGS = []

    def _digits(value):
        return _re.sub(r"\D", "", str(value or ""))

    def _norm_text(value):
        try:
            import unicodedata as _unicodedata
            s = _unicodedata.normalize("NFKD", str(value or ""))
            s = "".join(ch for ch in s if not _unicodedata.combining(ch))
        except Exception:
            s = str(value or "")
        return _re.sub(r"\s+", " ", s.strip().upper())

    def _norm_path(value):
        try:
            return _os.path.normcase(_os.path.abspath(str(value or "")))
        except Exception:
            return str(value or "").strip().lower()

    def _sha1_file(path):
        try:
            h = _hashlib.sha1()
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""

    def _xml_key_from_file(path):
        p = _Path(path)
        if not p.exists():
            return "MISS:" + _norm_path(path)
        if p.suffix.lower() != ".xml":
            return "PATH:" + _norm_path(path)
        try:
            root = _ET.parse(p).getroot()
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("infCte", "infNFe", "infMDFe"):
                    d = _digits(elem.attrib.get("Id", ""))
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
            for elem in root.iter():
                tag = str(elem.tag).split("}")[-1]
                if tag in ("chCTe", "chNFe", "chMDFe", "chave"):
                    d = _digits(elem.text or "")
                    if len(d) >= 44:
                        return "CHAVE:" + d[-44:]
        except Exception:
            pass
        digest = _sha1_file(p)
        if digest:
            return "XMLSHA1:" + digest
        return "PATH:" + _norm_path(path)

    def _info_path(info):
        if isinstance(info, dict):
            return str(info.get("path") or info.get("caminho") or info.get("arquivo_path") or info.get("arquivo") or "")
        for attr in ("path", "caminho", "arquivo_path", "arquivo"):
            try:
                v = getattr(info, attr)
                if v:
                    return str(v)
            except Exception:
                pass
        if isinstance(info, (str, _Path)):
            return str(info)
        return ""

    def _info_key(info):
        if isinstance(info, dict):
            for field in ("dedup_key", "chave", "chCTe", "chave_cte", "chave_nfe", "chNFe", "id", "Id"):
                val = info.get(field, "")
                d = _digits(val)
                if len(d) >= 44:
                    return "CHAVE:" + d[-44:]
                if field == "dedup_key" and str(val or "").strip():
                    s = str(val).strip()
                    if s.startswith("CHAVE:") or s.startswith("XMLSHA1:") or s.startswith("PATH:"):
                        return s
            p = _info_path(info)
            if p and (str(p).lower().endswith(".xml") or _Path(str(p)).exists()):
                return _xml_key_from_file(p)
            tipo = _norm_text(info.get("tipo") or info.get("Tipo") or "")
            numero = _digits(info.get("numero") or info.get("Número") or info.get("nCT") or "")
            serie = _digits(info.get("serie") or info.get("Série") or "")
            nf = _digits(info.get("nf") or info.get("NF") or "")
            emit = _norm_text(info.get("emitente") or info.get("Emitente") or "")
            if numero and ("CT" in tipo or emit or serie or nf):
                return "META:" + "|".join([tipo, numero, serie, nf, emit[:70]])
        p = _info_path(info)
        if p:
            return _xml_key_from_file(p)
        return "OBJ:" + str(id(info))

    def _looks_xml_item(item):
        p = _info_path(item)
        if p and str(p).lower().endswith(".xml"):
            return True
        if isinstance(item, dict):
            tipo = _norm_text(item.get("tipo") or item.get("Tipo") or "")
            return tipo in ("CT-E", "CTE", "NF-E", "NFE", "XML", "XML INVALIDO", "XML INVÁLIDO")
        return False

    def _dedupe_list(seq):
        fixed = []
        seen = set()
        removed = []
        for item in list(seq or []):
            key = _info_key(item)
            if key in seen:
                removed.append({"key": key, "arquivo": _Path(_info_path(item)).name if _info_path(item) else "", "motivo": "CT-e/XML repetido na lista"})
                continue
            seen.add(key)
            fixed.append(item)
        return fixed, removed

    def _dedupe_object_lists(obj):
        removed_records = []
        try:
            data = vars(obj)
        except Exception:
            return removed_records
        for attr, val in list(data.items()):
            low = str(attr).lower()
            if not isinstance(val, list) or not val:
                continue
            if not any(k in low for k in ("xml", "cte", "file", "files", "doc", "document")):
                continue
            if "fatura" in low or "invoice" in low:
                continue
            if not any(_looks_xml_item(x) for x in val[:12]):
                continue
            fixed, removed = _dedupe_list(val)
            if removed:
                try:
                    setattr(obj, attr, fixed)
                    removed_records.extend(removed)
                except Exception:
                    pass
        try:
            if hasattr(obj, "files") and hasattr(obj, "selected_paths"):
                valid = {_info_path(x) for x in getattr(obj, "files", []) if _info_path(x)}
                obj.selected_paths = {p for p in getattr(obj, "selected_paths", set()) if p in valid}
        except Exception:
            pass
        return removed_records

    def _table_cell_text(table, r, c):
        try:
            item = table.item(r, c)
            if item is not None:
                return str(item.text() or "").strip()
        except Exception:
            pass
        try:
            model = table.model()
            idx = model.index(r, c)
            return str(model.data(idx) or "").strip()
        except Exception:
            return ""

    def _row_key(vals):
        vals = [str(v or "").strip() for v in vals]
        joined = " | ".join(vals)
        upper = _norm_text(joined)
        if not upper:
            return ""
        # Se uma chave fiscal de 44 digitos aparecer em qualquer coluna, ela manda.
        d = _digits(joined)
        if len(d) >= 44:
            return "CHAVE:" + d[-44:]
        # Tabelas de XML/CT-e: normalmente Tipo, Número, Série, Emitente, Destinatário, NF.
        looks = ("CT-E" in upper or "CTE" in upper or "NF-E" in upper or "NFE" in upper or ".XML" in upper)
        if not looks:
            # Heurística para a tela atual: primeira coluna tipo e segunda número CT-e.
            if len(vals) >= 3 and _digits(vals[1]) and len(_digits(vals[1])) >= 4:
                looks = True
        if not looks:
            return ""
        # Para linhas idênticas, esta chave remove duplicidade visual mesmo sem path.
        compact = [_norm_text(x) for x in vals[:min(10, len(vals))]]
        return "ROW:" + "|".join(compact)

    def _is_probably_xml_table(table):
        try:
            rc = int(table.rowCount())
            cc = int(table.columnCount())
        except Exception:
            return False
        if rc <= 0 or cc <= 1 or rc > 20000 or cc > 80:
            return False
        sample = []
        for r in range(min(rc, 8)):
            for c in range(min(cc, 8)):
                sample.append(_table_cell_text(table, r, c))
        s = _norm_text(" | ".join(sample))
        return ("CT-E" in s or "CTE" in s or "NF-E" in s or "NFE" in s or ".XML" in s or any(len(_digits(x)) >= 5 for x in sample[:24]))

    def _dedupe_qtable(table):
        removed = []
        if table is None or not _is_probably_xml_table(table):
            return removed
        try:
            rc = int(table.rowCount())
            cc = int(table.columnCount())
        except Exception:
            return removed
        seen = set()
        to_remove = []
        for r in range(rc):
            vals = [_table_cell_text(table, r, c) for c in range(min(cc, 12))]
            key = _row_key(vals)
            if not key:
                continue
            if key in seen:
                to_remove.append((r, key, vals))
            else:
                seen.add(key)
        for r, key, vals in reversed(to_remove):
            try:
                table.removeRow(r)
                removed.append({"key": key, "arquivo": vals[1] if len(vals) > 1 else "", "motivo": "CT-e/XML repetido na tabela visual"})
            except Exception:
                pass
        return removed

    def _dedupe_treeview(tree):
        removed = []
        try:
            children = list(tree.get_children())
        except Exception:
            return removed
        seen = set()
        for iid in children:
            try:
                vals = list(tree.item(iid, "values") or [])
            except Exception:
                continue
            key = _row_key(vals)
            if not key:
                continue
            if key in seen:
                try:
                    tree.delete(iid)
                    removed.append({"key": key, "arquivo": vals[2] if len(vals) > 2 else "", "motivo": "CT-e/XML repetido na tabela visual"})
                except Exception:
                    pass
            else:
                seen.add(key)
        return removed

    def _dedupe_all_visual_tables():
        removed = []
        try:
            for obj in list(_gc.get_objects()):
                try:
                    if hasattr(obj, "rowCount") and hasattr(obj, "columnCount") and hasattr(obj, "removeRow"):
                        removed.extend(_dedupe_qtable(obj))
                    elif hasattr(obj, "get_children") and hasattr(obj, "delete") and hasattr(obj, "item"):
                        removed.extend(_dedupe_treeview(obj))
                except Exception:
                    pass
        except Exception:
            pass
        return removed

    def _dedupe_everywhere():
        removed = []
        try:
            for obj in list(_gc.get_objects()):
                try:
                    cls = obj.__class__
                    mod_name = getattr(cls, "__module__", "")
                    if not _module_is_ours(mod_name):
                        continue
                    removed.extend(_dedupe_object_lists(obj))
                except Exception:
                    pass
        except Exception:
            pass
        removed.extend(_dedupe_all_visual_tables())
        return removed

    def _collect_current_keys():
        keys = set()
        try:
            for obj in list(_gc.get_objects()):
                try:
                    if hasattr(obj, "rowCount") and hasattr(obj, "columnCount"):
                        if not _is_probably_xml_table(obj):
                            continue
                        rc = int(obj.rowCount()); cc = int(obj.columnCount())
                        for r in range(rc):
                            k = _row_key([_table_cell_text(obj, r, c) for c in range(min(cc, 12))])
                            if k:
                                keys.add(k)
                    elif hasattr(obj, "get_children") and hasattr(obj, "item"):
                        for iid in list(obj.get_children()):
                            k = _row_key(list(obj.item(iid, "values") or []))
                            if k:
                                keys.add(k)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            for obj in list(_gc.get_objects()):
                try:
                    if not _module_is_ours(getattr(obj.__class__, "__module__", "")):
                        continue
                    for attr, val in list(vars(obj).items()):
                        if isinstance(val, list) and val and any(_looks_xml_item(x) for x in val[:12]):
                            for item in val:
                                k = _info_key(item)
                                if k:
                                    keys.add(k)
                except Exception:
                    pass
        except Exception:
            pass
        return keys

    def _module_is_ours(mod_name):
        s = str(mod_name or "").lower()
        return s == "__main__" or "central" in s or "cte" in s or "dacte" in s or "engine" in s

    def _refresh_like(obj):
        for name in ("refresh_table", "update_table", "refresh_xml_table", "atualizar_tabela", "update_stats", "update_cards", "refresh_filter_chips", "apply_filters"):
            fn = getattr(obj, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def _format_key_short(key):
        key = str(key or "")
        if key.startswith("CHAVE:"):
            return key.split(":", 1)[1][-12:]
        if key.startswith("ROW:"):
            parts = key.split("|", 4)
            return " | ".join(parts[:4]).replace("ROW:", "")
        if len(key) > 48:
            return key[:45] + "..."
        return key

    def _build_log_text(log):
        lines = []
        lines.append("LOG DE IMPORTACAO DE XML/CT-e")
        lines.append("-" * 52)
        lines.append(f"CT-e adicionados: {log.get('added', 0)}")
        lines.append(f"CT-e repetidos ignorados/removidos: {log.get('skipped', 0)}")
        lines.append(f"Erros: {log.get('errors_count', 0)}")
        lines.append(f"Total real na lista: {log.get('total', 0)}")
        if log.get("duplicates"):
            lines.append("")
            lines.append("Repetidos:")
            for rec in log.get("duplicates", [])[:200]:
                lines.append(f"- {_format_key_short(rec.get('key'))} | {rec.get('arquivo') or '-'} | {rec.get('motivo') or 'repetido'}")
        if log.get("errors"):
            lines.append("")
            lines.append("Erros:")
            for err in log.get("errors", [])[:50]:
                lines.append(f"- {err}")
        return "\n".join(lines)

