def _fix2647_controle_html_from_info(info):
    try:
        result = info.get("validacao") or {}
        bloco = str(result.get("controle_dacte_compacto") or "").strip()
        if not bloco:
            return ""
        regra = escape(str(result.get("controle_dacte_regra") or "CONTROLE"))
        linha1 = escape(str(result.get("controle_dacte_linha1") or ""))
        linha2 = escape(str(result.get("controle_dacte_linha2") or ""))
        status = _fix2643_norm(result.get("controle_dacte_status") or result.get("status") or "")
        cls = "ok" if "OK" in status and "DIVERG" not in status else "bad"
        return f'<div class="controle-rodotec {cls}"><b>CONTROLE INTERNO - {regra}</b><br>{linha1}<br>{linha2}</div>'
    except Exception:
        return ""

try:
    _fix2647_base_render_dacte_page = globals().get("_fix2641_orig_render_dacte_page") or render_dacte_page
    def render_dacte_page(info):
        html = _fix2647_base_render_dacte_page(info)
        try:
            import re as _re
            # Segurança: remove qualquer bloco antigo que tenha vindo de renderizadores anteriores.
            html = _re.sub(r'\s*<div class="controle-rodotec[^"\\]*(?: [^"\\]*)?">.*?</div>\s*', '\n', html, flags=_re.S)
            bloco = _fix2647_controle_html_from_info(info)
            if bloco:
                marker = '    <div class="section-title">INFORMAÇÕES RELATIVAS AO IMPOSTO</div>'
                if marker in html:
                    html = html.replace(marker, f"    {bloco}\n\n{marker}", 1)
                else:
                    html += "\n" + bloco
        except Exception:
            pass
        return html
except Exception:
    pass

