# ============================================================================
# HOTFIX Faturas Parceiros 2.6.49
# - Corrige parser de faturas SSW quando o item vem no layout CT-e/RPS/NFS-e
#   ou quando o CT-e não vem como GRU/123-4, CWB/123-4 etc.
# - Prioriza parceiro lido do conteúdo do PDF em vez do nome do arquivo.
# - Evita usar valor de mercadoria como valor do frete/fatura.
# ============================================================================

def _central_cte_hotfix_faturas_2649_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2649():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker_2649():
        for _ in range(1200):
            mod = _find_main_with_faturas_2649()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2649_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.49] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker_2649, daemon=True, name="hotfix_faturas_2649").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2649_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2649", False):
        return

    _orig_parse_invoice = getattr(FaturasPage, "parse_invoice_text", None)
    _orig_parse_ssw = getattr(FaturasPage, "parse_ssw_len_invoice_text", None)
    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _fmt_invoice(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            return ""
        return f"{(_re.sub(r'\D', '', m.group(1)).lstrip('0') or '0').zfill(7)}-{m.group(2)}"

    def _extract_invoice(text, path=None):
        raw = str(text or "").replace("\xa0", " ")
        pats = [
            r"(?i)N[ºO°.]?\s*do\s*Documento\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)FATURA\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
        ]
        for pat in pats:
            for m in _re.finditer(pat, raw):
                out = _fmt_invoice(m.group(1))
                if out:
                    return out
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        for i, line in enumerate(lines):
            if "FATURA" in _strip_accents(line).upper() and i + 1 < len(lines):
                for cand in lines[i:i+6]:
                    out = _fmt_invoice(cand)
                    if out:
                        return out
        if path:
            return _fmt_invoice(_Path(path).stem)
        return ""

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _extract_header_value(lines, fatura=""):
        # Pega o valor do documento no topo do boleto/fatura. É mais confiável
        # do que a tabela interna quando o layout CT-e/RPS/NFS-e expõe Val. mercadoria.
        for i, line in enumerate(lines[:45]):
            if fatura and fatura in line:
                for cand in lines[i+1:i+6]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        for i, line in enumerate(lines[:45]):
            if _strip_accents(line).upper() == "VALOR DO DOCUMENTO":
                for cand in lines[i+1:i+12]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        for i, line in enumerate(lines):
            if _strip_accents(line).upper() == "VALOR TOTAL" and i + 1 < len(lines):
                vals = _money_values(lines[i+1])
                if vals:
                    return _parse_money(vals[-1])
        return 0.0

    def _extract_partner_from_header(lines):
        for i, line in enumerate(lines[:40]):
            if _strip_accents(line).upper() == "VALOR DO DOCUMENTO":
                for cand in lines[i+1:i+8]:
                    up = _strip_accents(cand).upper()
                    if not cand or "RODOVITOR" in up:
                        continue
                    if _re.match(r"^\d", cand) or _money_values(cand) or _fmt_invoice(cand):
                        continue
                    if any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "SERVICOS", "SERVIÇOS")):
                        return cand[:90]
        for i, line in enumerate(lines[:45]):
            up = _strip_accents(line).upper()
            if "RODOVITOR" in up and i > 0:
                cand = lines[i-1]
                cup = _strip_accents(cand).upper()
                if any(k in cup for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "SERVICOS", "SERVIÇOS")):
                    return cand[:90]
        return ""

    def _bad_partner_from_filename(current, robust, path):
        cur = _norm_space(current)
        if not cur:
            return True
        up = _strip_accents(cur).upper()
        if any(bad in up for bad in ("FATURA", "FATURAS", "VENC", "CUSTO EXTRA", "COMPROVANTE", "VALOR DO DOCUMENTO")):
            return True
        if path:
            stem = _norm_cmp(_Path(path).stem)
            cur_cmp = _norm_cmp(cur)
            # Se o parceiro atual é só um pedaço do nome do arquivo, troca pelo conteúdo.
            if robust and cur_cmp and (cur_cmp in stem or stem in cur_cmp):
                return True
        if robust and not any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "SERVICOS", "SERVIÇOS")):
            return True
        return False

    def _cte_label_from_line(line):
        s = _norm_space(line).upper()
        m = _re.search(r"([A-Z]{2,5})\s*/?\s*0*(\d{3,9})\s*[-/]\s*(\d)", s)
        if m:
            return f"{m.group(1)}/{m.group(2).lstrip('0') or '0'}-{m.group(3)}"
        # Linha SSW simples: "1 00012540" ou "2 00576121".
        m = _re.match(r"^\d{1,3}\s+0*(\d{4,12})(?:\s+.*)?$", s)
        if m and not _money_values(s):
            return m.group(1).lstrip("0") or m.group(1)
        return ""

    def _nf_from_block(block):
        # Procura uma linha de NF após a data. Ex.: "55 000304099" ou "000285167".
        saw_date = False
        for line in block:
            if _re.search(r"\b\d{2}/\d{2}/\d{2,4}\b", line):
                saw_date = True
                continue
            if not saw_date:
                continue
            if _money_values(line):
                continue
            m = _re.match(r"^(?:\d{1,3}\s+)?0*(\d{4,12})$", line)
            if m:
                return m.group(1).lstrip("0") or m.group(1)
        # Fallback menos rígido, mas evita CNPJ com 14 dígitos.
        for line in block:
            if _money_values(line):
                continue
            for m in _re.finditer(r"\b0*(\d{5,12})\b", line):
                return m.group(1).lstrip("0") or m.group(1)
        return ""

    def _value_from_block(block, invoice_total, single_item):
        if single_item and invoice_total:
            return invoice_total
        # Em blocos SSW, o frete costuma ser o último valor monetário útil antes do próximo item/total.
        vals = []
        for line in block:
            vals.extend(_money_values(line))
        parsed = [_parse_money(v) for v in vals if _parse_money(v) > 0]
        if not parsed:
            return 0.0
        # Evita usar valor de mercadoria quando há vários valores: normalmente o frete é um dos menores finais.
        if len(parsed) >= 2:
            return parsed[-1]
        return parsed[0]

    def _structured_items_from_lines(lines, invoice_total):
        starts = []
        for i, line in enumerate(lines):
            label = _cte_label_from_line(line)
            if not label:
                continue
            # Confirma que parece linha de item: próxima linha precisa ser data em poucos passos,
            # ou precisa ser CTe com prefixo conhecido.
            window = " ".join(lines[i:i+5])
            if _re.search(r"\b\d{2}/\d{2}/\d{2,4}\b", window) or _re.match(r"^[A-Z]{2,5}/", label):
                starts.append((i, label))
        if not starts:
            return []
        out = []
        for pos, (i, label) in enumerate(starts):
            end = starts[pos + 1][0] if pos + 1 < len(starts) else min(len(lines), i + 18)
            block = lines[i:end]
            nf = _nf_from_block(block)
            value = _value_from_block(block, invoice_total, len(starts) == 1)
            out.append({"cte": label, "cte_ref": label, "nf": nf, "valor_fatura": value, "linha": " | ".join(block[:12])})
        # Remove linhas que não parecem conter documento/NF e valor algum.
        final = []
        seen = set()
        for item in out:
            key = (_norm_cmp(item.get("cte")), _norm_cmp(item.get("nf")), round(float(item.get("valor_fatura") or 0), 2))
            if not key[0] or key in seen:
                continue
            seen.add(key)
            final.append(item)
        return final

    def _robust_parse(text, path):
        raw = str(text or "").replace("\xa0", " ")
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        fatura = _extract_invoice(raw, path)
        partner = _extract_partner_from_header(lines)
        invoice_total = _extract_header_value(lines, fatura)
        items = _structured_items_from_lines(lines, invoice_total)
        has_cte_rps_layout = any("CT-E / RPS / NFS-E" in _strip_accents(x).upper() for x in lines)
        return {"fatura": fatura, "parceiro": partner, "valor_total_pdf": invoice_total, "items": items, "has_cte_rps_layout": has_cte_rps_layout}

    def _merge_doc_with_robust(doc, text, path):
        if not isinstance(doc, dict):
            doc = {}
        rob = _robust_parse(text, path)
        if rob.get("fatura"):
            doc["fatura"] = rob["fatura"]
        if rob.get("parceiro") and _bad_partner_from_filename(doc.get("parceiro"), rob.get("parceiro"), path):
            doc["parceiro"] = rob["parceiro"]
        elif rob.get("parceiro") and not _norm_space(doc.get("parceiro")):
            doc["parceiro"] = rob["parceiro"]
        # Se o layout é CT-e/RPS/NFS-e, a leitura antiga podia pegar Val. mercadoria como frete.
        # Nessa situação a leitura estruturada nova é preferida.
        if rob.get("items") and (rob.get("has_cte_rps_layout") or not doc.get("items")):
            doc["items"] = rob["items"]
        doc.setdefault("arquivo", _Path(path).name if path else "")
        doc.setdefault("path", str(path or ""))
        if text and not doc.get("texto"):
            doc["texto"] = str(text)[:5000]
        return doc

    def patched_parse_invoice_text_2649(self, text, path):
        doc = None
        if callable(_orig_parse_invoice):
            try:
                doc = _orig_parse_invoice(self, text, path)
            except Exception:
                doc = None
        return _merge_doc_with_robust(doc, text, path)

    def patched_parse_ssw_len_invoice_text_2649(self, text, path):
        doc = None
        if callable(_orig_parse_ssw):
            try:
                doc = _orig_parse_ssw(self, text, path)
            except Exception:
                doc = None
        return _merge_doc_with_robust(doc, text, path)

    def _fix_existing_invoice_docs(self):
        for doc in getattr(self, "invoice_docs", []) or []:
            try:
                text = doc.get("texto") or ""
                path = doc.get("path") or doc.get("arquivo") or ""
                fixed = _merge_doc_with_robust(doc, text, path)
                doc.update(fixed)
            except Exception:
                pass

    def patched_process_invoices_2649(self):
        try:
            _fix_existing_invoice_docs(self)
        except Exception:
            pass
        result = _orig_process(self) if callable(_orig_process) else None
        return result

    def patched_build_invoice_report_sheets_2649(self, only_problem_invoices=False):
        try:
            _fix_existing_invoice_docs(self)
        except Exception:
            pass
        if callable(_orig_build_report):
            return _orig_build_report(self, only_problem_invoices)
        return []

    FaturasPage.parse_invoice_text = patched_parse_invoice_text_2649
    FaturasPage.parse_ssw_len_invoice_text = patched_parse_ssw_len_invoice_text_2649
    FaturasPage.process_invoices = patched_process_invoices_2649
    FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2649
    FaturasPage._hotfix_faturas_2649 = True
    try:
        if hasattr(_main, "APP_VERSION") and "Hotfix Faturas 2.6.49" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Hotfix Faturas 2.6.49"
    except Exception:
        pass


_central_cte_hotfix_faturas_2649_start()


# HOTFIX Faturas Parceiros 2.6.50
# - Corrige contagem: remove duplicidade por número de fatura, não por caminho do arquivo.
# - Mantém um log interno com faturas duplicadas/removidas e total real processável.
# - Evita que a UI prometa uma quantidade diferente do que será processado.

def _central_cte_hotfix_faturas_2650_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2650():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None

    def _worker_2650():
        for _ in range(1200):
            mod = _find_main_with_faturas_2650()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2650_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.50] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker_2650, daemon=True, name="hotfix_faturas_2650").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2650_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2650", False):
        return

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_text(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_invoice_2650(value):
        s = str(value or "")
        if not s:
            return ""
        # bloqueia leituras clássicas falsas do parser antigo
        if _strip_accents(s).upper().strip().startswith("EMISS"):
            return ""
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            # Aceita nomes Fat328 (0), mas não nomes de vencimento como 2026-1.
            m = _re.search(r"(?i)\bFat\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]", s)
        if not m:
            return ""
        base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
        dig = _re.sub(r"\D", "", m.group(2))[:1]
        if not dig:
            return ""
        return f"{base.zfill(7)}-{dig}"

    def _doc_file_name(doc):
        try:
            return str(doc.get("arquivo") or _Path(str(doc.get("path") or "")).name or "") if isinstance(doc, dict) else ""
        except Exception:
            return ""

    def _doc_invoice_number(doc):
        if not isinstance(doc, dict):
            return ""
        fat = _norm_invoice_2650(doc.get("fatura"))
        if fat:
            return fat
        # Fallback controlado: só pega do nome do arquivo quando o nome é explicitamente Fat/Fatura.
        name = _doc_file_name(doc)
        if _re.search(r"(?i)\bFAT(?:URA)?\b", name):
            return _norm_invoice_2650(name)
        return ""

    def _sync_invoice_docs_2650(self, reason=""):
        docs = list(getattr(self, "invoice_docs", []) or [])
        if not docs:
            try:
                self._last_faturas_import_log_2650 = {"selected": 0, "unique": 0, "duplicates": [], "without_number": [], "reason": reason}
            except Exception:
                pass
            return {"selected": 0, "unique": 0, "removed": 0, "duplicates": [], "without_number": [], "reason": reason}

        fixed = []
        seen = {}
        duplicates = []
        without_number = []

        for doc in docs:
            fat = _doc_invoice_number(doc)
            file_name = _doc_file_name(doc)
            if not fat:
                without_number.append(file_name or "arquivo sem nome")
                fixed.append(doc)
                continue
            if fat in seen:
                duplicates.append({"fatura": fat, "arquivo_mantido": seen.get(fat, ""), "arquivo_ignorado": file_name})
                continue
            seen[fat] = file_name
            fixed.append(doc)

        removed = len(docs) - len(fixed)
        if removed:
            try:
                self.invoice_docs = fixed
            except Exception:
                pass
            # Ajusta caches paralelos somente quando tinham o mesmo comprimento anterior.
            for attr in ("invoice_files", "fatura_docs", "faturas_docs"):
                try:
                    val = getattr(self, attr, None)
                    if isinstance(val, list) and len(val) == len(docs):
                        setattr(self, attr, fixed)
                except Exception:
                    pass

        log = {"selected": len(docs), "unique": len(fixed), "removed": removed, "duplicates": duplicates, "without_number": without_number, "reason": reason}
        try:
            self._last_faturas_import_log_2650 = log
        except Exception:
            pass
        return log

    def _set_faturas_status_2650(self, log):
        try:
            if not hasattr(self, "set_status") or not isinstance(log, dict):
                return
            parts = [f"Faturas carregadas: {log.get('unique', 0)} únicas"]
            if log.get("removed"):
                parts.append(f"duplicadas ignoradas: {log.get('removed', 0)}")
            if log.get("without_number"):
                parts.append(f"sem nº claro: {len(log.get('without_number') or [])}")
            self.set_status(" • ".join(parts) + ".")
        except Exception:
            pass

    def _wrap_method_2650(cls, name, wrapper_factory):
        if not hasattr(cls, name):
            return False
        key = f"_hotfix_2650_wrapped_{name}"
        if getattr(cls, key, False):
            return False
        orig = getattr(cls, name)
        if not callable(orig):
            return False
        try:
            setattr(cls, f"_original_{name}_2650", orig)
            setattr(cls, name, wrapper_factory(orig))
            setattr(cls, key, True)
            return True
        except Exception:
            return False

    def make_after_add(orig):
        def wrapped(self, *args, **kwargs):
            result = orig(self, *args, **kwargs)
            try:
                log = _sync_invoice_docs_2650(self, "add")
                _set_faturas_status_2650(self, log)
                # Atualiza UI após remover duplicadas.
                for fn_name in ("refresh_invoice_list", "refresh_faturas_list", "refresh_table", "apply_filters", "update_cards", "refresh_partner_filter"):
                    fn = getattr(self, fn_name, None)
                    if callable(fn):
                        try:
                            fn()
                        except Exception:
                            pass
            except Exception:
                pass
            return result
        return wrapped

    def make_before_process(orig):
        def wrapped(self, *args, **kwargs):
            try:
                log = _sync_invoice_docs_2650(self, "process_before")
                _set_faturas_status_2650(self, log)
            except Exception:
                pass
            result = orig(self, *args, **kwargs)
            try:
                log = _sync_invoice_docs_2650(self, "process_after")
                _set_faturas_status_2650(self, log)
            except Exception:
                pass
            return result
        return wrapped

    def make_before_report(orig):
        def wrapped(self, *args, **kwargs):
            try:
                _sync_invoice_docs_2650(self, "report_before")
            except Exception:
                pass
            return orig(self, *args, **kwargs)
        return wrapped

    for name in ("add_invoices", "add_invoice_files", "add_faturas", "add_invoice_docs", "add_files", "load_invoices", "load_invoice_files", "load_faturas"):
        _wrap_method_2650(FaturasPage, name, make_after_add)

    for name in ("process_invoices",):
        _wrap_method_2650(FaturasPage, name, make_before_process)

    for name in ("build_invoice_report_sheets",):
        _wrap_method_2650(FaturasPage, name, make_before_report)

    # Deixa utilitário disponível para consulta futura/debug.
    try:
        FaturasPage._sync_invoice_docs_2650 = _sync_invoice_docs_2650
    except Exception:
        pass

    FaturasPage._hotfix_faturas_2650 = True
    try:
        if hasattr(_main, "APP_VERSION") and "Faturas 2.6.50" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Faturas 2.6.50"
    except Exception:
        pass


_central_cte_hotfix_faturas_2650_start()


# HOTFIX Faturas Parceiros 2.6.50.1
# - Suprime o popup antigo de "X fatura(s) adicionada(s)" quando ele usa contador bruto.
# - Mostra contador corrigido por fatura única após a limpeza/deduplicação.

def _central_cte_hotfix_faturas_2650_1_start():
    import sys as _sys, time as _time, threading as _threading
    def _find():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None
    def _worker():
        for _ in range(1200):
            mod = _find()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2650_1_apply(mod)
                except Exception as exc:
                    try: print("[HOTFIX FATURAS 2.6.50.1] falhou:", exc)
                    except Exception: pass
                return
            _time.sleep(0.05)
    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2650_1").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2650_1_apply(_main):
    import re as _re
    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2650_1", False):
        return

    def _should_suppress_msg(text):
        s = str(text or "").lower()
        return ("fatura" in s and "adicionad" in s) or ("faturas" in s and "adicionad" in s)

    def _safe_sync(self):
        fn = getattr(self, "_sync_invoice_docs_2650", None)
        if callable(fn):
            try:
                return fn("popup_corrigido")
            except TypeError:
                try: return fn(self, "popup_corrigido")
                except Exception: pass
            except Exception:
                pass
        docs = list(getattr(self, "invoice_docs", []) or [])
        return {"selected": len(docs), "unique": len(docs), "removed": 0, "duplicates": [], "without_number": []}

    def _show_correct_msg(self, log):
        try:
            log = log or {}
            txt = (
                f"Faturas carregadas: {log.get('unique', 0)} única(s).\n"
                f"Duplicadas ignoradas: {log.get('removed', 0)}."
            )
            dups = log.get("duplicates") or []
            if dups:
                sample = []
                for d in dups[:5]:
                    sample.append(f"- {d.get('fatura')} | ignorado: {d.get('arquivo_ignorado')}")
                txt += "\n\nDuplicadas:\n" + "\n".join(sample)
                if len(dups) > 5:
                    txt += f"\n... +{len(dups)-5}"
            # Prefere QMessageBox quando disponível, senão tkinter.
            try:
                QMessageBox = getattr(_main, "QMessageBox", None)
                APP_TITLE = getattr(_main, "APP_TITLE", "Central CT-e / DACTE")
                if QMessageBox is not None and hasattr(QMessageBox, "information"):
                    QMessageBox.information(self, APP_TITLE, txt)
                    return
            except Exception:
                pass
            try:
                import tkinter.messagebox as _tkmb
                _tkmb.showinfo(getattr(_main, "APP_TITLE", "Central CT-e / DACTE"), txt)
            except Exception:
                pass
        except Exception:
            pass

    def _wrap_method(cls, name, wrapper_factory):
        if not hasattr(cls, name):
            return False
        key = f"_hotfix_2650_1_wrapped_{name}"
        if getattr(cls, key, False):
            return False
        orig = getattr(cls, name)
        if not callable(orig):
            return False
        try:
            setattr(cls, f"_original_{name}_2650_1", orig)
            setattr(cls, name, wrapper_factory(orig))
            setattr(cls, key, True)
            return True
        except Exception:
            return False

    def make_add(orig):
        def wrapped(self, *args, **kwargs):
            # Suprime só a mensagem antiga de faturas adicionadas durante a chamada original.
            restores = []
            try:
                QMessageBox = getattr(_main, "QMessageBox", None)
                if QMessageBox is not None and hasattr(QMessageBox, "information"):
                    old_info = QMessageBox.information
                    def info_suppressed(*a, **k):
                        txt = ""
                        try:
                            if len(a) >= 3: txt = a[2]
                            elif len(a) >= 2: txt = a[1]
                        except Exception:
                            txt = ""
                        if _should_suppress_msg(txt):
                            return 0
                        return old_info(*a, **k)
                    QMessageBox.information = info_suppressed
                    restores.append((QMessageBox, "information", old_info))
            except Exception:
                pass
            try:
                import tkinter.messagebox as _tkmb
                old_showinfo = _tkmb.showinfo
                def showinfo_suppressed(title=None, message=None, *a, **k):
                    if _should_suppress_msg(message):
                        return "ok"
                    return old_showinfo(title, message, *a, **k)
                _tkmb.showinfo = showinfo_suppressed
                restores.append((_tkmb, "showinfo", old_showinfo))
            except Exception:
                pass
            try:
                result = orig(self, *args, **kwargs)
            finally:
                for obj, attr, old in restores:
                    try: setattr(obj, attr, old)
                    except Exception: pass
            try:
                log = _safe_sync(self)
                # Atualiza UI/status e mostra contador corrigido.
                try:
                    if hasattr(self, "set_status"):
                        self.set_status(f"Faturas carregadas: {log.get('unique', 0)} única(s); duplicadas ignoradas: {log.get('removed', 0)}.")
                except Exception:
                    pass
                _show_correct_msg(self, log)
            except Exception:
                pass
            return result
        return wrapped

    for name in ("add_invoices", "add_invoice_files", "add_faturas", "add_invoice_docs", "add_files", "load_invoices", "load_invoice_files", "load_faturas"):
        _wrap_method(FaturasPage, name, make_add)

    FaturasPage._hotfix_faturas_2650_1 = True
    try:
        if hasattr(_main, "APP_VERSION") and "Faturas 2.6.50" not in str(_main.APP_VERSION):
            _main.APP_VERSION = str(_main.APP_VERSION) + " + Faturas 2.6.50"
    except Exception:
        pass


_central_cte_hotfix_faturas_2650_1_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.51
# - Corrige queda de faturas após processar quando o PDF SSW traz item no layout
#   CT-e / RPS / NFS-e com CT-e numérico puro e a linha contém valores monetários.
# - Ex.: "1 00012344 28/05/26 ... 396,00 ... 80,00".
# - Antes: a fatura entrava na lista, mas era descartada no processamento por não gerar item.
# - Agora: gera item com CT-e numérico, NF e valor do frete corretamente.
# ============================================================================

def _central_cte_hotfix_faturas_2651_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2651():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker_2651():
        for _ in range(1200):
            mod = _find_main_with_faturas_2651()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2651_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.51] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker_2651, daemon=True, name="hotfix_faturas_2651").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2651_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2651", False):
        return

    _orig_parse_invoice = getattr(FaturasPage, "parse_invoice_text", None)
    _orig_parse_ssw = getattr(FaturasPage, "parse_ssw_len_invoice_text", None)
    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _fmt_invoice(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            return ""
        return f"{(_re.sub(r'\D', '', m.group(1)).lstrip('0') or '0').zfill(7)}-{m.group(2)}"

    def _extract_invoice(raw, path=None):
        raw = str(raw or "").replace("\xa0", " ")
        for pat in (
            r"(?i)N[ºO°.]?\s*do\s*Documento\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)FATU?RA\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)FAT\.\s*(?:N[ºO°.]*)?\s*[:\-]?\s*(0*\d{3,9}\s*[-/]\s*\d)",
        ):
            for m in _re.finditer(pat, raw):
                out = _fmt_invoice(m.group(1))
                if out:
                    return out
        if path:
            return _fmt_invoice(_Path(path).stem)
        return ""

    def _extract_invoice_total(lines, fatura=""):
        # Mais estável para faturas SSW: valor do documento/valor a pagar no topo.
        for i, line in enumerate(lines[:50]):
            if fatura and fatura in line:
                vals = _money_values(line)
                if vals:
                    return _parse_money(vals[-1])
                for cand in lines[i+1:i+7]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        for i, line in enumerate(lines[:50]):
            up = _strip_accents(line).upper()
            if "VALOR DO DOCUMENTO" in up or "VALOR A PAGAR" in up:
                for cand in lines[i:i+10]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        for i, line in enumerate(lines):
            if _strip_accents(line).upper().strip() == "VALOR TOTAL":
                for cand in lines[i:i+5]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        return 0.0

    def _nf_from_raw_item_line(line):
        # Usa os inteiros antes do primeiro valor monetário. O último costuma ser a NF.
        s = str(line or "")
        first_money = _re.search(r"\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2}", s)
        left = s[:first_money.start()] if first_money else s
        nums = _re.findall(r"\b\d{1,14}\b", left)
        # Remove item, CT-e bruto e data quebrada. Mantém candidatos 5-12 dígitos.
        candidates = []
        for n in nums:
            nd = _re.sub(r"\D", "", n)
            if len(nd) == 14:  # CNPJ
                continue
            if len(nd) in (1, 2, 4):  # item, dia/mês/ano curto, série solta
                continue
            if 5 <= len(nd) <= 12:
                candidates.append(nd.lstrip("0") or nd)
        if not candidates:
            return ""
        return candidates[-1]

    def _looks_like_cte_rps_layout(lines):
        joined = "\n".join(lines[:120])
        up = _strip_accents(joined).upper()
        return "CT-E / RPS / NFS-E" in up or "CTE / RPS / NFS-E" in up or "CT-E/RPS/NFS-E" in up

    def _raw_numeric_items_from_lines(lines, invoice_total=0.0):
        # Linha típica:
        # 1 00012344 28/05/26 586... FARMARIN ... 1 000461158 396,00 28 80,00 ... 80,00
        starts = []
        for i, line in enumerate(lines):
            s = _norm_space(line)
            if not s:
                continue
            m = _re.match(r"^(\d{1,3})\s+0*(\d{4,12})\s+(\d{2}/\d{2}/\d{2,4})\b", s)
            if not m:
                continue
            if not _money_values(s):
                continue
            # Evita capturar cabeçalhos/resumos: exige que esteja dentro/perto de layout de documentos.
            context = " ".join(lines[max(0, i-6):i+3])
            ctx = _strip_accents(context).upper()
            if not any(k in ctx for k in ("CT-E", "CTE", "RPS", "NFS", "FRETE CIF", "FRETE FOB", "FRETE TERCEIRO")):
                continue
            cte_num = (m.group(2).lstrip("0") or m.group(2))
            starts.append((i, cte_num))
        if not starts:
            return []
        out = []
        single = len(starts) == 1
        for pos, (idx, cte_num) in enumerate(starts):
            end = starts[pos + 1][0] if pos + 1 < len(starts) else min(len(lines), idx + 18)
            block = lines[idx:end]
            line = _norm_space(lines[idx])
            vals = [_parse_money(v) for v in _money_values(line)]
            vals = [v for v in vals if v > 0]
            value = invoice_total if single and invoice_total else (vals[-1] if vals else 0.0)
            nf = _nf_from_raw_item_line(line)
            out.append({
                "cte": cte_num,
                "cte_ref": cte_num,
                "nf": nf,
                "valor_fatura": value,
                "linha": " | ".join(_norm_space(x) for x in block[:12] if _norm_space(x)),
                "origem_parser": "raw_cte_rps_nfs_2651",
            })
        # Dedup simples
        final, seen = [], set()
        for item in out:
            key = (_norm_cmp(item.get("cte")), _norm_cmp(item.get("nf")), round(float(item.get("valor_fatura") or 0), 2))
            if not key[0] or key in seen:
                continue
            seen.add(key)
            final.append(item)
        return final

    def _merge_raw_items(doc, text, path):
        if not isinstance(doc, dict):
            doc = {}
        raw = str(text or doc.get("texto") or "").replace("\xa0", " ")
        if not raw:
            return doc
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        if not _looks_like_cte_rps_layout(lines):
            return doc
        fatura = _extract_invoice(raw, path) or _fmt_invoice(doc.get("fatura"))
        if fatura:
            doc["fatura"] = fatura
        total = _extract_invoice_total(lines, fatura)
        raw_items = _raw_numeric_items_from_lines(lines, total)
        if raw_items:
            existing = doc.get("items") if isinstance(doc.get("items"), list) else []
            # Se o parser antigo não achou item real, usa o parser bruto.
            # Também troca quando o existente parece ter vindo de valor de mercadoria ou não tem CT-e válido.
            existing_valid = []
            for it in existing:
                if not isinstance(it, dict):
                    continue
                cte = _norm_cmp(it.get("cte_ref") or it.get("cte") or "")
                val = float(it.get("valor_fatura") or it.get("valor") or 0 or 0)
                if cte and val > 0:
                    existing_valid.append(it)
            if not existing_valid:
                doc["items"] = raw_items
            elif len(existing_valid) == 1 and len(raw_items) == 1:
                # Se o CT-e numérico do raw não aparece no item antigo, o item antigo é suspeito.
                old_key = _norm_cmp(existing_valid[0].get("cte_ref") or existing_valid[0].get("cte") or "")
                new_key = _norm_cmp(raw_items[0].get("cte"))
                if old_key != new_key and new_key:
                    doc["items"] = raw_items
        doc.setdefault("arquivo", _Path(path).name if path else doc.get("arquivo", ""))
        doc.setdefault("path", str(path or doc.get("path", "")))
        if raw and not doc.get("texto"):
            doc["texto"] = raw[:5000]
        return doc

    def patched_parse_invoice_text_2651(self, text, path):
        doc = None
        if callable(_orig_parse_invoice):
            try:
                doc = _orig_parse_invoice(self, text, path)
            except Exception:
                doc = None
        return _merge_raw_items(doc, text, path)

    def patched_parse_ssw_len_invoice_text_2651(self, text, path):
        doc = None
        if callable(_orig_parse_ssw):
            try:
                doc = _orig_parse_ssw(self, text, path)
            except Exception:
                doc = None
        return _merge_raw_items(doc, text, path)

    def _fix_existing(self):
        for doc in getattr(self, "invoice_docs", []) or []:
            try:
                text = doc.get("texto") or ""
                path = doc.get("path") or doc.get("arquivo") or ""
                fixed = _merge_raw_items(doc, text, path)
                doc.update(fixed)
            except Exception:
                pass

    def patched_process_invoices_2651(self):
        try:
            _fix_existing(self)
        except Exception:
            pass
        return _orig_process(self) if callable(_orig_process) else None

    def patched_build_invoice_report_sheets_2651(self, only_problem_invoices=False):
        try:
            _fix_existing(self)
        except Exception:
            pass
        if callable(_orig_build_report):
            return _orig_build_report(self, only_problem_invoices)
        return []

    FaturasPage.parse_invoice_text = patched_parse_invoice_text_2651
    FaturasPage.parse_ssw_len_invoice_text = patched_parse_ssw_len_invoice_text_2651
    FaturasPage.process_invoices = patched_process_invoices_2651
    FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2651
    FaturasPage._hotfix_faturas_2651 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.51 Faturas 86 / Raw SSW"
    except Exception:
        pass


_central_cte_hotfix_faturas_2651_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.52
# - Corrige popup final de processamento que ainda mostrava "Faturas: 84"
#   quando a UI/lista real já estava com 86 faturas.
# - A causa era um contador antigo do relatório/processamento, diferente do
#   contador real de faturas únicas exibidas no resumo.
# - O hotfix não altera os dados processados: apenas intercepta a mensagem final
#   antiga e substitui a linha "Faturas:" pelo total real de faturas únicas.
# - Também registra o total real em atributo de debug para auditoria.
# ============================================================================

def _central_cte_hotfix_faturas_2652_start():
    import sys as _sys, time as _time, threading as _threading

    def _find():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2652_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.52] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2652").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2652_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2652", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    if not callable(_orig_process):
        return

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_invoice(value):
        s = str(value or "")
        if not s:
            return ""
        if _strip_accents(s).upper().strip().startswith("EMISS"):
            return ""
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            m = _re.search(r"(?i)\bFat(?:ura)?\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]", s)
        if not m:
            return ""
        base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
        dig = _re.sub(r"\D", "", m.group(2))[:1]
        if not dig:
            return ""
        return f"{base.zfill(7)}-{dig}"

    def _doc_file_name(doc):
        try:
            if isinstance(doc, dict):
                return str(doc.get("arquivo") or _Path(str(doc.get("path") or "")).name or "")
        except Exception:
            pass
        return ""

    def _doc_invoice_number(doc):
        if not isinstance(doc, dict):
            return ""
        for key in ("fatura", "numero_fatura", "invoice", "numero"):
            fat = _norm_invoice(doc.get(key))
            if fat:
                return fat
        name = _doc_file_name(doc)
        if _re.search(r"(?i)\bFAT(?:URA)?\b", name):
            fat = _norm_invoice(name)
            if fat:
                return fat
        txt = str(doc.get("texto") or "")[:3000]
        if txt:
            fat = _norm_invoice(txt)
            if fat:
                return fat
        return ""

    def _count_invoice_docs(self):
        docs = getattr(self, "invoice_docs", None)
        if not isinstance(docs, list):
            return 0
        seen = set()
        anonymous = 0
        for doc in docs:
            fat = _doc_invoice_number(doc)
            if fat:
                seen.add(fat)
            elif isinstance(doc, dict):
                # Não joga fora arquivo sem número no contador de auditoria.
                # Ele pode virar revisão, mas não deve sumir silenciosamente.
                anonymous += 1
        return len(seen) + anonymous

    def _cell_text(obj):
        try:
            if obj is None:
                return ""
            if hasattr(obj, "text") and callable(obj.text):
                return str(obj.text())
            return str(obj)
        except Exception:
            return ""

    def _count_table_rows(self):
        best = 0
        try:
            attrs = list(getattr(self, "__dict__", {}).items())
        except Exception:
            attrs = []
        for name, obj in attrs:
            low = str(name).lower()
            if not any(k in low for k in ("fatura", "invoice", "summary", "resumo")):
                continue
            try:
                rc = obj.rowCount() if hasattr(obj, "rowCount") and callable(obj.rowCount) else None
                cc = obj.columnCount() if hasattr(obj, "columnCount") and callable(obj.columnCount) else None
                if rc is None or cc is None or int(rc) <= 0:
                    continue
                rc = int(rc); cc = int(cc)
                # Conta linhas que têm fatura na primeira ou segunda coluna.
                count = 0
                for r in range(rc):
                    row_txt = []
                    for c in range(min(cc, 3)):
                        try:
                            item = obj.item(r, c) if hasattr(obj, "item") else None
                            row_txt.append(_cell_text(item))
                        except Exception:
                            pass
                    joined = " ".join(row_txt)
                    if _norm_invoice(joined):
                        count += 1
                if count:
                    best = max(best, count)
                else:
                    best = max(best, rc)
            except Exception:
                pass
        return best

    def _recursive_count_from_attr(value, depth=0):
        if depth > 3 or value is None:
            return set()
        found = set()
        try:
            if isinstance(value, dict):
                for k in ("fatura", "numero_fatura", "invoice"):
                    fat = _norm_invoice(value.get(k))
                    if fat:
                        found.add(fat)
                for v in list(value.values())[:200]:
                    found.update(_recursive_count_from_attr(v, depth + 1))
            elif isinstance(value, (list, tuple, set)):
                for v in list(value)[:500]:
                    found.update(_recursive_count_from_attr(v, depth + 1))
            elif isinstance(value, str):
                fat = _norm_invoice(value)
                if fat:
                    found.add(fat)
        except Exception:
            pass
        return found

    def _count_result_attrs(self):
        best = 0
        try:
            items = list(getattr(self, "__dict__", {}).items())
        except Exception:
            items = []
        for name, val in items:
            low = str(name).lower()
            if not any(k in low for k in ("summary", "resumo", "fatura", "invoice", "grupo", "group", "result", "report")):
                continue
            if low in ("invoice_docs", "invoice_files"):
                continue
            try:
                found = _recursive_count_from_attr(val)
                if found:
                    best = max(best, len(found))
            except Exception:
                pass
        return best

    def _real_invoice_count(self):
        counts = [
            _count_table_rows(self),
            _count_invoice_docs(self),
            _count_result_attrs(self),
        ]
        counts = [int(x) for x in counts if isinstance(x, int) and x > 0]
        return max(counts) if counts else 0

    def _is_process_done_message(text):
        s = _strip_accents(text).lower()
        return "processamento conclu" in s and "faturas:" in s and "ct-es" in s

    def _replace_faturas_line(text, real_count):
        msg = str(text or "")
        if real_count <= 0:
            return msg
        # Substitui somente a linha final do popup, não qualquer texto de tabela.
        msg = _re.sub(r"(?im)^\s*Faturas\s*:\s*\d+\s*$", f"Faturas: {real_count}", msg)
        if "Contagem corrigida" not in msg:
            msg += "\n\nContagem corrigida pela lista real exibida: " + str(real_count) + " fatura(s)."
        return msg

    def _show_corrected_info(self, captured_text):
        try:
            real = _real_invoice_count(self)
            try:
                self._last_faturas_real_count_2652 = real
            except Exception:
                pass
            txt = _replace_faturas_line(captured_text or "Processamento concluído.\n\nFaturas: 0", real)
            # Atualiza status/card quando possível.
            try:
                if hasattr(self, "set_status") and callable(self.set_status):
                    self.set_status(f"Processamento concluído. Faturas reais exibidas/processáveis: {real}.")
            except Exception:
                pass
            QMessageBox = getattr(_main, "QMessageBox", None)
            APP_TITLE = getattr(_main, "APP_TITLE", "Central CT-e / DACTE")
            if QMessageBox is not None and hasattr(QMessageBox, "information"):
                QMessageBox.information(self, APP_TITLE, txt)
                return
            try:
                import tkinter.messagebox as _tkmb
                _tkmb.showinfo(APP_TITLE, txt)
            except Exception:
                pass
        except Exception:
            pass

    def patched_process_invoices_2652(self, *args, **kwargs):
        captured = {"text": None}
        restores = []

        # Intercepta QMessageBox do PySide6.
        try:
            QMessageBox = getattr(_main, "QMessageBox", None)
            if QMessageBox is not None and hasattr(QMessageBox, "information"):
                old_info = QMessageBox.information
                def info_patch(*a, **k):
                    txt = ""
                    try:
                        if len(a) >= 3:
                            txt = a[2]
                        elif len(a) >= 2:
                            txt = a[1]
                    except Exception:
                        txt = ""
                    if _is_process_done_message(txt):
                        captured["text"] = str(txt)
                        return 0
                    return old_info(*a, **k)
                QMessageBox.information = info_patch
                restores.append((QMessageBox, "information", old_info))
        except Exception:
            pass

        # Intercepta tkinter.messagebox, usado por alguns hotfixes antigos.
        try:
            import tkinter.messagebox as _tkmb
            old_showinfo = _tkmb.showinfo
            def showinfo_patch(title=None, message=None, *a, **k):
                if _is_process_done_message(message):
                    captured["text"] = str(message)
                    return "ok"
                return old_showinfo(title, message, *a, **k)
            _tkmb.showinfo = showinfo_patch
            restores.append((_tkmb, "showinfo", old_showinfo))
        except Exception:
            pass

        # Intercepta module.messagebox se o main importou diretamente.
        try:
            mb = getattr(_main, "messagebox", None)
            if mb is not None and hasattr(mb, "showinfo"):
                old_mb_showinfo = mb.showinfo
                def mb_showinfo_patch(title=None, message=None, *a, **k):
                    if _is_process_done_message(message):
                        captured["text"] = str(message)
                        return "ok"
                    return old_mb_showinfo(title, message, *a, **k)
                mb.showinfo = mb_showinfo_patch
                restores.append((mb, "showinfo", old_mb_showinfo))
        except Exception:
            pass

        try:
            result = _orig_process(self, *args, **kwargs)
        finally:
            for obj, attr, old in restores:
                try:
                    setattr(obj, attr, old)
                except Exception:
                    pass

        try:
            if captured.get("text"):
                _show_corrected_info(self, captured.get("text"))
        except Exception:
            pass
        return result

    FaturasPage.process_invoices = patched_process_invoices_2652
    FaturasPage._hotfix_faturas_2652 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.52 Faturas: contador final corrigido"
    except Exception:
        pass


_central_cte_hotfix_faturas_2652_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.53
# - Corrige relatório/exportação que ainda ficava com 84 faturas quando a UI
#   mostrava 86. A causa real eram itens SSW CT-e/RPS/NFS-e quebrados em linhas:
#       1 00012344\n28/05/26\n...\n80,00
#   O parser 2.6.51 só capturava quando CT-e e data estavam na mesma linha.
# - Lê CT-e numérico em linha separada da data.
# - Garante que faturas com item recuperado entrem também no relatório, não só
#   no contador/visual.
# ============================================================================

def _central_cte_hotfix_faturas_2653_start():
    import sys as _sys, time as _time, threading as _threading

    def _find():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1600):
            mod = _find()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2653_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.53] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2653").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2653_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2653", False):
        return

    _orig_parse_invoice = getattr(FaturasPage, "parse_invoice_text", None)
    _orig_parse_ssw = getattr(FaturasPage, "parse_ssw_len_invoice_text", None)
    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _fmt_invoice(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            return ""
        return f"{(_re.sub(r'\D', '', m.group(1)).lstrip('0') or '0').zfill(7)}-{m.group(2)}"

    def _extract_invoice(text, path=None):
        raw = str(text or "").replace("\xa0", " ")
        pats = [
            r"(?i)N[ºO°.]?\s*do\s*Documento\s*:?\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"(?i)FATURA\s*(?:N[ºO°.]*)?\s*:?\s*(0*\d{3,9}\s*[-/]\s*\d)",
        ]
        for pat in pats:
            for m in _re.finditer(pat, raw):
                out = _fmt_invoice(m.group(1))
                if out:
                    return out
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        for i, line in enumerate(lines):
            up = _strip_accents(line).upper()
            if "FATURA" in up or "Nº DO DOCUMENTO" in up or "NO DO DOCUMENTO" in up:
                for cand in lines[i:i+8]:
                    out = _fmt_invoice(cand)
                    if out:
                        return out
        if path:
            return _fmt_invoice(_Path(path).stem)
        return ""

    def _extract_invoice_total(lines, fatura=""):
        # Valor do boleto/documento no topo ou resumo final.
        if fatura:
            for i, line in enumerate(lines[:60]):
                if fatura in line:
                    for cand in lines[i+1:i+10]:
                        vals = _money_values(cand)
                        if vals:
                            return _parse_money(vals[-1])
        for i, line in enumerate(lines[:80]):
            up = _strip_accents(line).upper()
            if up in ("VALOR DO DOCUMENTO", "VALOR TOTAL"):
                for cand in lines[i+1:i+12]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        # Resumo final do SSW: VALOR TOTAL\n80,00
        for i, line in enumerate(lines):
            if _strip_accents(line).upper() == "VALOR TOTAL":
                for cand in lines[i+1:i+5]:
                    vals = _money_values(cand)
                    if vals:
                        return _parse_money(vals[-1])
        return 0.0

    def _looks_like_raw_ssw_layout(lines):
        ctx = " ".join(lines[:80])
        up = _strip_accents(ctx).upper()
        return any(k in up for k in ("CT-E / RPS / NFS-E", "CTE / RPS / NFS", "FRETE CIF", "FRETE FOB"))

    def _nf_from_block(block):
        # Procura NF em padrões como "1 000461158" ou "55 000304099".
        for line in block[:14]:
            s = _norm_space(line)
            m = _re.match(r"^(?:\d{1,3})\s+0*(\d{3,12})\b", s)
            if m:
                num = m.group(1).lstrip("0") or m.group(1)
                # Evita confundir a primeira linha do próprio CT-e como NF.
                if len(num) >= 3:
                    return num
        joined = " ".join(block[:14])
        m = _re.search(r"\b(?:NF|N\s*FISCAL)\D{0,20}0*(\d{3,12})\b", joined, flags=_re.I)
        return (m.group(1).lstrip("0") if m else "")

    def _raw_multiline_items_from_lines(lines, invoice_total=0.0):
        if not _looks_like_raw_ssw_layout(lines):
            return []
        starts = []
        for i, line in enumerate(lines):
            s = _norm_space(line)
            # Layout quebrado: linha só com sequencial + CT-e, data vem na próxima linha.
            m = _re.match(r"^(\d{1,3})\s+0*(\d{4,12})\s*$", s)
            if not m:
                # Layout em uma linha, caso apareça.
                m2 = _re.match(r"^(\d{1,3})\s+0*(\d{4,12})\s+(\d{2}/\d{2}/\d{2,4})\b", s)
                if m2:
                    starts.append((i, (m2.group(2).lstrip("0") or m2.group(2))))
                continue
            # Próximas linhas devem conter uma data de emissão ou contexto monetário do item.
            nearby = " ".join(lines[i+1:i+8])
            if not _re.search(r"\b\d{2}/\d{2}/\d{2,4}\b", nearby):
                continue
            starts.append((i, (m.group(2).lstrip("0") or m.group(2))))
        if not starts:
            return []
        out = []
        single = len(starts) == 1
        for pos, (idx, cte_num) in enumerate(starts):
            end = starts[pos + 1][0] if pos + 1 < len(starts) else min(len(lines), idx + 30)
            # Para no resumo/quantidade se aparecer antes do próximo item.
            for j in range(idx + 1, end):
                up = _strip_accents(lines[j]).upper()
                if "QUANTIDADE DE DOCUMENTOS" in up or up == "RESUMO":
                    end = j
                    break
            block = [_norm_space(x) for x in lines[idx:end] if _norm_space(x)]
            vals = []
            for b in block:
                vals.extend(_parse_money(v) for v in _money_values(b))
            vals = [v for v in vals if v > 0]
            # Em fatura com um único item, o total da fatura é o valor do frete.
            # Em múltiplos, usa o último valor monetário do bloco, que no layout SSW
            # costuma ser a coluna Frete R$.
            value = invoice_total if single and invoice_total else (vals[-1] if vals else 0.0)
            nf = _nf_from_block(block[2:] if len(block) > 2 else block)
            out.append({
                "cte": cte_num,
                "cte_ref": cte_num,
                "nf": nf,
                "valor_fatura": value,
                "linha": " | ".join(block[:16]),
                "origem_parser": "raw_cte_rps_nfs_multilinha_2653",
            })
        final, seen = [], set()
        for item in out:
            key = (_norm_cmp(item.get("cte")), _norm_cmp(item.get("nf")), round(float(item.get("valor_fatura") or 0), 2))
            if not key[0] or key in seen:
                continue
            seen.add(key)
            final.append(item)
        return final

    def _merge_multiline_raw_items(doc, text, path):
        if not isinstance(doc, dict):
            doc = {}
        raw = str(text or doc.get("texto") or "").replace("\xa0", " ")
        if not raw:
            return doc
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        if not _looks_like_raw_ssw_layout(lines):
            # Ainda assim guarda texto completo para auditoria/parser futuro.
            if raw and (not doc.get("texto") or len(str(doc.get("texto") or "")) < len(raw)):
                doc["texto"] = raw
            return doc
        fatura = _extract_invoice(raw, path) or _fmt_invoice(doc.get("fatura"))
        if fatura:
            doc["fatura"] = fatura
        total = _extract_invoice_total(lines, fatura)
        raw_items = _raw_multiline_items_from_lines(lines, total)
        if raw_items:
            existing = doc.get("items") if isinstance(doc.get("items"), list) else []
            existing_keys = {_norm_cmp((it or {}).get("cte_ref") or (it or {}).get("cte") or "") for it in existing if isinstance(it, dict)}
            # Troca/insere quando o parser antigo não achou CT-e numérico cru.
            for it in raw_items:
                if _norm_cmp(it.get("cte")) not in existing_keys:
                    existing.append(it)
            doc["items"] = existing or raw_items
            doc["parser_raw_ssw_2653"] = True
        doc.setdefault("arquivo", _Path(path).name if path else doc.get("arquivo", ""))
        doc.setdefault("path", str(path or doc.get("path", "")))
        if raw and (not doc.get("texto") or len(str(doc.get("texto") or "")) < len(raw)):
            doc["texto"] = raw
        return doc

    def _partner_from_doc(doc):
        if isinstance(doc, dict):
            p = str(doc.get("parceiro") or "").strip()
            if p:
                return p
            txt = str(doc.get("texto") or "")
            # Heurística simples para PDFs SSW: beneficiário costuma aparecer antes do pagador.
            for line in [_norm_space(x) for x in txt.splitlines() if _norm_space(x)][:80]:
                up = _strip_accents(line).upper()
                if "RODOVITOR" in up or _money_values(line) or _fmt_invoice(line):
                    continue
                if any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "LOBATO", "SERVICOS")):
                    return line
        return "Parceiro não identificado"

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        fat = _fmt_invoice(doc.get("fatura") or doc.get("numero_fatura") or "")
        if fat:
            return fat
        return _extract_invoice(doc.get("texto") or "", doc.get("path") or doc.get("arquivo") or "")

    def _existing_faturas_in_records(self):
        out = set()
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if isinstance(rec, dict):
                fat = _fmt_invoice(rec.get("Fatura") or rec.get("fatura") or "")
                if fat:
                    out.add(fat)
        return out

    def _append_missing_raw_docs_to_records(self):
        docs = getattr(self, "invoice_docs", None)
        if not isinstance(docs, list):
            return 0
        if not isinstance(getattr(self, "invoice_detail_records", None), list):
            try:
                self.invoice_detail_records = []
            except Exception:
                return 0
        existing = _existing_faturas_in_records(self)
        added = 0
        for doc in docs:
            if not isinstance(doc, dict):
                continue
            # Reaplica o parser em cima do texto completo já salvo.
            try:
                fixed = _merge_multiline_raw_items(doc, doc.get("texto") or "", doc.get("path") or doc.get("arquivo") or "")
                doc.update(fixed)
            except Exception:
                pass
            fat = _doc_invoice(doc)
            if not fat or fat in existing:
                continue
            items = doc.get("items") if isinstance(doc.get("items"), list) else []
            if not items:
                continue
            partner = _partner_from_doc(doc)
            arquivo = str(doc.get("arquivo") or (_Path(str(doc.get("path") or "")).name if doc.get("path") else ""))
            for it in items:
                if not isinstance(it, dict):
                    continue
                cte = str(it.get("cte_ref") or it.get("cte") or "").strip()
                if not cte:
                    continue
                val = float(it.get("valor_fatura") or it.get("valor") or 0 or 0)
                rec = {
                    "Fatura": fat,
                    "Parceiro": partner,
                    "Arquivo fatura": arquivo,
                    "CT-e fatura": cte,
                    "NF fatura": str(it.get("nf") or ""),
                    "Valor fatura": val,
                    "Valor CT-e": val,
                    "Valor XML": 0,
                    "Valor não pagar": 0,
                    "Status valor": "XML OPCIONAL",
                    "Valor OK?": "XML OPCIONAL",
                    "Conferência fatura base": "FATURA RECUPERADA PELO PARSER SSW",
                    "Fatura Base": "FATURA RECUPERADA PELO PARSER SSW",
                    "Comprovante": "REVISAR BASE",
                    "Comprovante OK?": "REVISAR BASE",
                    "Status final CT-e": "REVISAR - CT-e recuperado do layout CT-e/RPS/NFS-e",
                    "Status CT-e": "REVISAR",
                    "Motivo": "Item recuperado pelo parser SSW multilinha 2.6.53. Verificar base/comprovante antes de liberar.",
                    "DY": "",
                }
                self.invoice_detail_records.append(rec)
                added += 1
            existing.add(fat)
        try:
            self._faturas_raw_ssw_2653_added_records = added
        except Exception:
            pass
        return added

    def _fix_all_docs(self):
        try:
            for doc in getattr(self, "invoice_docs", []) or []:
                if isinstance(doc, dict):
                    path = doc.get("path") or doc.get("arquivo") or ""
                    text = doc.get("texto") or ""
                    fixed = _merge_multiline_raw_items(doc, text, path)
                    doc.update(fixed)
        except Exception:
            pass

    def patched_parse_invoice_text_2653(self, text, path):
        doc = None
        if callable(_orig_parse_invoice):
            try:
                doc = _orig_parse_invoice(self, text, path)
            except Exception:
                doc = None
        return _merge_multiline_raw_items(doc, text, path)

    def patched_parse_ssw_len_invoice_text_2653(self, text, path):
        doc = None
        if callable(_orig_parse_ssw):
            try:
                doc = _orig_parse_ssw(self, text, path)
            except Exception:
                doc = None
        return _merge_multiline_raw_items(doc, text, path)

    def patched_process_invoices_2653(self, *args, **kwargs):
        try:
            _fix_all_docs(self)
        except Exception:
            pass
        result = _orig_process(self, *args, **kwargs) if callable(_orig_process) else None
        try:
            added = _append_missing_raw_docs_to_records(self)
            # Se adicionou fallback, força uma ressincronização visual se existir.
            sync = getattr(self, "_sync_invoice_ui_2634", None)
            if callable(sync):
                try:
                    sync()
                except Exception:
                    pass
            if added and hasattr(self, "set_status"):
                try:
                    self.set_status(f"Processamento concluído. {added} CT-e(s) recuperado(s) pelo parser SSW multilinha para relatório.")
                except Exception:
                    pass
        except Exception:
            pass
        return result

    def patched_build_invoice_report_sheets_2653(self, *args, **kwargs):
        try:
            _fix_all_docs(self)
            _append_missing_raw_docs_to_records(self)
        except Exception:
            pass
        return _orig_build_report(self, *args, **kwargs) if callable(_orig_build_report) else []

    FaturasPage.parse_invoice_text = patched_parse_invoice_text_2653
    FaturasPage.parse_ssw_len_invoice_text = patched_parse_ssw_len_invoice_text_2653
    FaturasPage.process_invoices = patched_process_invoices_2653
    FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2653
    FaturasPage._hotfix_faturas_2653 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.53 Faturas 86 no relatório"
    except Exception:
        pass


_central_cte_hotfix_faturas_2653_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.54
# - Corrige regressão em que o popup final passou a contar CT-es como faturas
#   (ex.: Faturas: 612 / CT-es detalhados: 613).
# - Garante que toda fatura carregada em invoice_docs apareça também no resumo
#   e no relatório, mesmo quando o parser ainda não identificou CT-e/itens.
# - Quando não houver item/CT-e reconhecido, cria uma linha de REVISAR em vez de
#   deixar a fatura sumir silenciosamente.
# - A contagem final usa faturas únicas, nunca linhas de CT-e.
# ============================================================================

def _central_cte_hotfix_faturas_2654_start():
    import sys as _sys, time as _time, threading as _threading

    def _find():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1800):
            mod = _find()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2654_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.54] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2654").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2654_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2654", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)
    if not callable(_orig_process):
        return

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _fmt_invoice_from_match(m):
        try:
            base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
            dig = _re.sub(r"\D", "", m.group(2))[:1]
            if not dig:
                return ""
            return f"{base.zfill(7)}-{dig}"
        except Exception:
            return ""

    def _norm_invoice(value):
        s = str(value or "")
        if not s:
            return ""
        if _strip_accents(s).upper().strip().startswith("EMISS"):
            return ""
        # Formatos textuais confiáveis dentro da fatura.
        pats = [
            r"(?i)N[ºO°.]?\s*do\s*Documento\s*:?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
            r"(?i)FATU?RA\s*(?:N[ºO°.]*)?\s*:?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
            r"(?i)\bFAT\.?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
            r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)",
            r"(?i)\bFat(?:ura)?\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
        ]
        for pat in pats:
            m = _re.search(pat, s)
            if m:
                out = _fmt_invoice_from_match(m)
                if out:
                    return out
        return ""

    def _doc_file_name(doc):
        try:
            if isinstance(doc, dict):
                p = str(doc.get("path") or "")
                a = str(doc.get("arquivo") or "")
                return a or (_Path(p).name if p else "")
        except Exception:
            pass
        return ""

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        # Prioriza conteúdo/campo interno; nome de arquivo é só último recurso.
        for key in ("fatura", "numero_fatura", "Fatura", "invoice", "numero"):
            fat = _norm_invoice(doc.get(key))
            if fat:
                return fat
        txt = str(doc.get("texto") or "")
        if txt:
            # Evita falso 2026-1 vindo de nome do arquivo.
            for pat in (
                r"(?i)N[ºO°.]?\s*do\s*Documento\s*:?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
                r"(?i)FATU?RA\s*(?:N[ºO°.]*)?\s*:?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
                r"(?i)\bFAT\.?\s*(0*\d{3,9})\s*[-/]\s*(\d)",
            ):
                m = _re.search(pat, txt[:6000])
                if m:
                    out = _fmt_invoice_from_match(m)
                    if out:
                        return out
            # fallback geral só no texto, limitado ao topo.
            fat = _norm_invoice(txt[:3000])
            if fat:
                return fat
        name = _doc_file_name(doc)
        # Só aceita nome se parecer realmente nome de fatura, não vencimento/data.
        if _re.search(r"(?i)\bFAT(?:URA)?\b", name):
            fat = _norm_invoice(name)
            if fat and not fat.startswith("0002026-"):
                return fat
        return ""

    def _parse_money(value):
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _doc_total(doc):
        if not isinstance(doc, dict):
            return 0.0
        for key in ("valor_fatura", "valor", "total", "valor_total", "Valor fatura"):
            try:
                v = doc.get(key)
                if isinstance(v, (int, float)) and float(v) > 0:
                    return float(v)
                if isinstance(v, str) and v.strip():
                    n = _parse_money(v)
                    if n > 0:
                        return n
            except Exception:
                pass
        txt = str(doc.get("texto") or "")
        lines = [_norm_space(x) for x in txt.splitlines() if _norm_space(x)]
        for i, line in enumerate(lines[:120]):
            up = _strip_accents(line).upper()
            if "VALOR DO DOCUMENTO" in up or up == "VALOR TOTAL" or "VALOR A PAGAR" in up:
                for cand in lines[i:i+10]:
                    vals = _money_values(cand)
                    if vals:
                        n = _parse_money(vals[-1])
                        if n > 0:
                            return n
        return 0.0

    def _partner_from_doc(doc):
        if not isinstance(doc, dict):
            return "Parceiro não identificado"
        for key in ("parceiro", "Parceiro", "partner"):
            p = str(doc.get(key) or "").strip()
            if p and "FAT" not in _strip_accents(p).upper() and "RODOVITOR" not in _strip_accents(p).upper():
                return p
        txt = str(doc.get("texto") or "")
        for line in [_norm_space(x) for x in txt.splitlines() if _norm_space(x)][:100]:
            up = _strip_accents(line).upper()
            if "RODOVITOR" in up or _money_values(line) or _norm_invoice(line):
                continue
            if any(k in up for k in ("TRANSP", "LOGIST", "CARGAS", "LTDA", "EIRELI", "LOBATO", "SERVICOS", "ORGANIZACAO")):
                return line
        return "Parceiro não identificado"

    def _record_fatura(rec):
        if isinstance(rec, dict):
            return _norm_invoice(rec.get("Fatura") or rec.get("fatura") or rec.get("numero_fatura") or "")
        return ""

    def _record_cte(rec):
        if isinstance(rec, dict):
            return str(rec.get("CT-e fatura") or rec.get("CT-e") or rec.get("cte") or rec.get("cte_ref") or "").strip()
        return ""

    def _existing_record_faturas(self):
        out = set()
        for rec in getattr(self, "invoice_detail_records", []) or []:
            fat = _record_fatura(rec)
            if fat:
                out.add(fat)
        return out

    def _all_doc_faturas(self):
        out = []
        seen = set()
        docs = getattr(self, "invoice_docs", None)
        if not isinstance(docs, list):
            return out
        for doc in docs:
            fat = _doc_invoice(doc)
            if fat and fat not in seen:
                seen.add(fat)
                out.append((fat, doc))
        return out

    def _ensure_record_for_all_loaded_invoices(self):
        docs = _all_doc_faturas(self)
        if not docs:
            return 0
        if not isinstance(getattr(self, "invoice_detail_records", None), list):
            try:
                self.invoice_detail_records = []
            except Exception:
                return 0
        existing = _existing_record_faturas(self)
        added = 0
        for fat, doc in docs:
            if fat in existing:
                continue
            items = doc.get("items") if isinstance(doc, dict) and isinstance(doc.get("items"), list) else []
            partner = _partner_from_doc(doc)
            arquivo = _doc_file_name(doc)
            if not items:
                # Fatura carregada, mas sem item reconhecido: não deixa sumir.
                total = _doc_total(doc)
                items = [{"cte": "REVISAR", "cte_ref": "REVISAR", "nf": "", "valor_fatura": total}]
            for it in items:
                if not isinstance(it, dict):
                    continue
                cte = str(it.get("cte_ref") or it.get("cte") or "REVISAR").strip() or "REVISAR"
                val = 0.0
                try:
                    val = float(it.get("valor_fatura") or it.get("valor") or 0 or 0)
                except Exception:
                    val = 0.0
                rec = {
                    "Fatura": fat,
                    "Parceiro": partner,
                    "Arquivo fatura": arquivo,
                    "CT-e fatura": cte,
                    "NF fatura": str(it.get("nf") or ""),
                    "Valor fatura": val,
                    "Valor CT-e": val,
                    "Valor XML": 0,
                    "Valor não pagar": 0,
                    "Status valor": "XML OPCIONAL",
                    "Valor OK?": "XML OPCIONAL",
                    "Conferência fatura base": "REVISAR - FATURA CARREGADA SEM DETALHE COMPLETO" if cte == "REVISAR" else "FATURA RECUPERADA",
                    "Fatura Base": "REVISAR - FATURA CARREGADA SEM DETALHE COMPLETO" if cte == "REVISAR" else "FATURA RECUPERADA",
                    "Comprovante": "REVISAR BASE",
                    "Comprovante OK?": "REVISAR BASE",
                    "Status final CT-e": "REVISAR - fatura carregada sem CT-e detalhado" if cte == "REVISAR" else "REVISAR - CT-e recuperado do layout da fatura",
                    "Status CT-e": "REVISAR",
                    "Motivo": "Fatura carregada, mas o parser não identificou item/CT-e com segurança. Revisar manualmente antes de liberar." if cte == "REVISAR" else "Item recuperado para evitar sumiço da fatura no relatório.",
                    "DY": "",
                }
                self.invoice_detail_records.append(rec)
                added += 1
            existing.add(fat)
        try:
            self._faturas_2654_added_missing_records = added
            self._faturas_2654_loaded_unique = len(docs)
        except Exception:
            pass
        return added

    def _unique_from_records(self):
        out = set()
        for rec in getattr(self, "invoice_detail_records", []) or []:
            fat = _record_fatura(rec)
            if fat:
                out.add(fat)
        return out

    def _unique_from_invoice_rows(self):
        out = set()
        for row in getattr(self, "invoice_rows", []) or []:
            try:
                fat = _norm_invoice((row or [""])[0])
                if fat:
                    out.add(fat)
            except Exception:
                pass
        return out

    def _table_row_count(self):
        try:
            table = getattr(self, "invoice_table", None)
            if table is not None and hasattr(table, "rowCount"):
                return int(table.rowCount())
        except Exception:
            pass
        return 0

    def _real_fatura_count(self):
        # Nunca usa atributos de detalhe/relatório recursivos, pois eles contam CT-es.
        counts = [
            len([x for x in _all_doc_faturas(self)]),
            len(_unique_from_invoice_rows(self)),
            len(_unique_from_records(self)),
            _table_row_count(self),
        ]
        counts = [int(x) for x in counts if int(x) > 0]
        return max(counts) if counts else 0

    def _sync_ui(self):
        # Usa o sincronizador 2.6.34, mas após garantir placeholders para todas as faturas.
        try:
            _ensure_record_for_all_loaded_invoices(self)
        except Exception:
            pass
        try:
            sync = getattr(self, "_sync_invoice_ui_2634", None)
            if callable(sync):
                sync()
        except Exception:
            pass

    def _is_process_done_message(text):
        s = _strip_accents(text).lower()
        return "processamento conclu" in s and "faturas:" in s and "ct-es" in s

    def _correct_message(text):
        msg = str(text or "Processamento concluído.")
        real = _real_fatura_count(self)
        if real > 0:
            msg = _re.sub(r"(?im)^\s*Faturas\s*:\s*\d+\s*$", f"Faturas: {real}", msg)
        # Remove observação quebrada de hotfix antigo, principalmente quando veio 612.
        msg = _re.sub(r"(?ims)\n\s*Contagem corrigida pela lista real exibida:\s*\d+\s*fatura\(s\)\.\s*", "\n", msg)
        if real > 0 and "Contagem de faturas corrigida" not in msg:
            msg += f"\n\nContagem de faturas corrigida: {real} fatura(s) únicas carregadas."
        return msg

    def _show_info(self, text):
        txt = _correct_message(text)
        QMessageBox = getattr(_main, "QMessageBox", None)
        APP_TITLE = getattr(_main, "APP_TITLE", "Central CT-e / DACTE")
        if QMessageBox is not None and hasattr(QMessageBox, "information"):
            try:
                QMessageBox.information(self, APP_TITLE, txt)
                return
            except Exception:
                pass
        try:
            import tkinter.messagebox as _tkmb
            _tkmb.showinfo(APP_TITLE, txt)
        except Exception:
            pass

    def _install_message_interceptors(captured, restores):
        try:
            QMessageBox = getattr(_main, "QMessageBox", None)
            if QMessageBox is not None and hasattr(QMessageBox, "information"):
                old_info = QMessageBox.information
                def info_patch(*a, **k):
                    txt = ""
                    try:
                        txt = a[2] if len(a) >= 3 else (a[1] if len(a) >= 2 else "")
                    except Exception:
                        txt = ""
                    if _is_process_done_message(txt):
                        captured["text"] = str(txt)
                        return 0
                    return old_info(*a, **k)
                QMessageBox.information = info_patch
                restores.append((QMessageBox, "information", old_info))
        except Exception:
            pass
        try:
            import tkinter.messagebox as _tkmb
            old_showinfo = _tkmb.showinfo
            def showinfo_patch(title=None, message=None, *a, **k):
                if _is_process_done_message(message):
                    captured["text"] = str(message)
                    return "ok"
                return old_showinfo(title, message, *a, **k)
            _tkmb.showinfo = showinfo_patch
            restores.append((_tkmb, "showinfo", old_showinfo))
        except Exception:
            pass
        try:
            mb = getattr(_main, "messagebox", None)
            if mb is not None and hasattr(mb, "showinfo"):
                old_mb = mb.showinfo
                def mb_patch(title=None, message=None, *a, **k):
                    if _is_process_done_message(message):
                        captured["text"] = str(message)
                        return "ok"
                    return old_mb(title, message, *a, **k)
                mb.showinfo = mb_patch
                restores.append((mb, "showinfo", old_mb))
        except Exception:
            pass

    def patched_process_invoices_2654(self, *args, **kwargs):
        captured = {"text": None}
        restores = []
        _install_message_interceptors(captured, restores)
        try:
            result = _orig_process(self, *args, **kwargs)
        finally:
            for obj, attr, old in restores:
                try:
                    setattr(obj, attr, old)
                except Exception:
                    pass
        try:
            _sync_ui(self)
        except Exception:
            pass
        if captured.get("text"):
            _show_info(self, captured["text"])
        return result

    def patched_build_invoice_report_sheets_2654(self, *args, **kwargs):
        try:
            _sync_ui(self)
        except Exception:
            pass
        return _orig_build_report(self, *args, **kwargs) if callable(_orig_build_report) else []

    FaturasPage.process_invoices = patched_process_invoices_2654
    if callable(_orig_build_report):
        FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2654
    try:
        FaturasPage._ensure_record_for_all_loaded_invoices_2654 = _ensure_record_for_all_loaded_invoices
        FaturasPage._real_fatura_count_2654 = _real_fatura_count
    except Exception:
        pass
    FaturasPage._hotfix_faturas_2654 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.54 Faturas: sem contar CT-e como fatura"
    except Exception:
        pass


_central_cte_hotfix_faturas_2654_start()

# ============================================================================
# HOTFIX Faturas Parceiros 2.6.55
# - Cria log TXT detalhado em /logs após processar faturas.
# - Explica por que cada fatura ficou OK PAGAR, PAGAR PARCIAL, NÃO PAGAR ou REVISAR.
# - Lista CT-es, valores, comprovante/base, status e motivo usado na decisão.
# ============================================================================

def _central_cte_hotfix_faturas_2655_start():
    import sys as _sys, time as _time, threading as _threading

    def _find():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for _mod in list(_sys.modules.values()):
            try:
                if _mod is not None and hasattr(_mod, "FaturasPage"):
                    return _mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1800):
            mod = _find()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2655_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.55] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2655_log").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2655_apply(_main):
    import os as _os
    import re as _re
    import sys as _sys
    import unicodedata as _unicodedata
    from pathlib import Path as _Path
    from datetime import datetime as _datetime

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2655", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)
    if not callable(_orig_process):
        return

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(value).upper())

    def _parse_money(value):
        try:
            if isinstance(value, (int, float)):
                return float(value or 0)
            s = str(value or "").strip().replace("R$", "").replace(" ", "")
            if not s:
                return 0.0
            if "," in s:
                s = s.replace(".", "").replace(",", ".")
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        try:
            n = float(value or 0)
        except Exception:
            n = _parse_money(value)
        return "R$ " + f"{n:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _fmt_invoice(value):
        s = str(value or "")
        if _strip_accents(s).upper().strip().startswith("EMISS"):
            return ""
        for pat in (
            r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)",
            r"(?i)\bFat(?:ura)?\s*(\d{3,9})\s*[\(\[]\s*(\d)\s*[\)\]]",
        ):
            m = _re.search(pat, s)
            if m:
                base = _re.sub(r"\D", "", m.group(1)).lstrip("0") or "0"
                dig = _re.sub(r"\D", "", m.group(2))[:1]
                if dig:
                    return f"{base.zfill(7)}-{dig}"
        return ""

    def _record_get(rec, *keys):
        if not isinstance(rec, dict):
            return ""
        for key in keys:
            try:
                v = rec.get(key)
                if v is not None and str(v).strip() != "":
                    return v
            except Exception:
                pass
        return ""

    def _rec_fatura(rec):
        return _fmt_invoice(_record_get(rec, "Fatura", "fatura", "numero_fatura", "Fatura fatura"))

    def _rec_partner(rec):
        return _norm_space(_record_get(rec, "Parceiro", "parceiro", "Partner")) or "Parceiro não identificado"

    def _rec_cte(rec):
        return _norm_space(_record_get(rec, "CT-e fatura", "CT-e base", "CTRC base", "CT-e", "cte", "cte_ref")) or "-"

    def _rec_nf(rec):
        return _norm_space(_record_get(rec, "NF fatura", "NF base", "NF", "nf")) or "-"

    def _rec_value(rec):
        return _parse_money(_record_get(rec, "Valor fatura", "Valor CT-e", "Valor Fat.", "valor", "Valor"))

    def _rec_blocked_value(rec):
        return _parse_money(_record_get(rec, "Valor não pagar", "Valor bloqueado", "Nao pagar", "Não pagar"))

    def _rec_comp(rec):
        return _norm_space(_record_get(rec, "Comprovante", "Comprovante OK?", "comprovante", "DY"))

    def _rec_status(rec):
        return _norm_space(_record_get(rec, "Status final CT-e", "Status CT-e", "Status valor", "Valor OK?", "status"))

    def _rec_base(rec):
        return _norm_space(_record_get(rec, "Conferência fatura base", "Fatura Base", "fatura_base", "Base"))

    def _rec_motivo(rec):
        return _norm_space(_record_get(rec, "Motivo", "motivo", "Observação", "Observacao"))

    def _rec_xml_status(rec):
        return _norm_space(_record_get(rec, "Valor OK?", "Status valor", "Valor XML", "XML"))

    def _rec_is_ok(rec):
        status = _strip_accents(_rec_status(rec)).upper()
        comp = _strip_accents(_rec_comp(rec)).upper()
        motivo = _strip_accents(_rec_motivo(rec)).upper()
        blocked = _rec_blocked_value(rec)
        if blocked > 0.004:
            return False
        if any(x in status for x in ("PROBLEMA", "DIVERG", "SEM COMPROVANTE", "NAO PAGAR", "NÃO PAGAR", "REVISAR")):
            return False
        if any(x in comp for x in ("PEND", "SEM COMPROVANTE", "N")) and "NAO EXIG" not in comp and "NÃO EXIG" not in comp:
            return False
        if any(x in motivo for x in ("REVISAR", "DIVERG", "SEM COMPROVANTE", "NAO LOCALIZ", "NÃO LOCALIZ")):
            return False
        return True

    def _reason_for_rec(rec):
        status = _rec_status(rec)
        comp = _rec_comp(rec)
        base = _rec_base(rec)
        motivo = _rec_motivo(rec)
        xml = _rec_xml_status(rec)
        val_np = _rec_blocked_value(rec)
        checks = []
        raw = _strip_accents(" | ".join([status, comp, base, motivo, xml])).upper()
        if val_np > 0.004:
            checks.append(f"valor bloqueado/não pagar {_money(val_np)}")
        if "SEM COMPROVANTE" in raw or "PEND" in raw:
            checks.append("comprovante pendente/ausente")
        if "DIVERG" in raw:
            checks.append("divergência de valor ou regra")
        if "REVISAR" in raw:
            checks.append("marcado para revisão")
        if "NAO LOCALIZ" in raw or "NÃO LOCALIZ" in raw:
            checks.append("CT-e/base não localizado")
        if "COMPLEMENTAR" in raw or "CUSTO EXTRA" in raw:
            checks.append("possível complementar/custo extra")
        if not checks and _rec_is_ok(rec):
            checks.append("CT-e considerado OK")
        elif not checks:
            checks.append("sem motivo explícito; revisar campos do registro")
        return "; ".join(checks)

    def _doc_file_name(doc):
        try:
            if isinstance(doc, dict):
                p = str(doc.get("path") or "")
                a = str(doc.get("arquivo") or "")
                return a or (_Path(p).name if p else "")
        except Exception:
            pass
        return ""

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        for key in ("fatura", "numero_fatura", "Fatura", "invoice", "numero"):
            fat = _fmt_invoice(doc.get(key))
            if fat:
                return fat
        txt = str(doc.get("texto") or "")
        if txt:
            fat = _fmt_invoice(txt[:4000])
            if fat:
                return fat
        name = _doc_file_name(doc)
        if _re.search(r"(?i)\bFAT(?:URA)?\b", name):
            return _fmt_invoice(name)
        return ""

    def _loaded_docs_index(self):
        idx = {}
        duplicates = []
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            fat = _doc_invoice(doc)
            if not fat:
                continue
            fname = _doc_file_name(doc)
            if fat in idx:
                duplicates.append((fat, idx[fat].get("arquivo", ""), fname))
            else:
                idx[fat] = {"arquivo": fname, "parceiro": _norm_space(doc.get("parceiro") or doc.get("Parceiro") or ""), "items": len(doc.get("items") or [])}
        return idx, duplicates

    def _group_records(self):
        groups = {}
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if not isinstance(rec, dict):
                continue
            fat = _rec_fatura(rec)
            if not fat:
                continue
            groups.setdefault(fat, []).append(rec)
        return groups

    def _decision_for_group(recs):
        if not recs:
            return "REVISAR", "sem CT-e detalhado no processamento"
        qtd = len(recs)
        ok = sum(1 for r in recs if _rec_is_ok(r))
        problema = qtd - ok
        val_total = sum(_rec_value(r) for r in recs)
        val_np = sum(_rec_blocked_value(r) for r in recs)
        has_revisar = any("REVISAR" in _strip_accents(" | ".join([_rec_status(r), _rec_base(r), _rec_motivo(r), _rec_comp(r)])).upper() for r in recs)
        if problema <= 0 and not has_revisar:
            return "OK PAGAR", f"todos os {qtd} CT-e(s) avaliados como OK"
        if has_revisar and val_np <= 0.004:
            return "REVISAR", "há item marcado para revisão, mas sem valor bloqueado calculado"
        if ok > 0 and val_np > 0.004:
            return "PAGAR PARCIAL", f"{ok} CT-e(s) OK e {problema} com problema; valor não pagar {_money(val_np)}"
        if val_np > 0.004:
            return "NÃO PAGAR", f"todos/maior parte dos itens com problema; valor não pagar {_money(val_np)}"
        return "REVISAR", "há problema sem valor bloqueado definido"

    def _log_dir_candidates():
        bases = []
        try:
            bases.append(_Path(_sys.executable).resolve().parent)
        except Exception:
            pass
        try:
            bases.append(_Path.cwd())
        except Exception:
            pass
        try:
            bases.append(_Path(__file__).resolve().parents[2])
        except Exception:
            pass
        seen = []
        out = []
        for b in bases:
            try:
                if not b or str(b) in seen:
                    continue
                seen.append(str(b))
                out.append(b / "logs")
            except Exception:
                pass
        return out or [_Path("logs")]

    def _write_faturas_log(self, origem="processamento"):
        ts = _datetime.now().strftime("%Y%m%d_%H%M%S")
        log_name = f"faturas_validacao_{ts}.txt"
        groups = _group_records(self)
        docs_idx, duplicates = _loaded_docs_index(self)
        all_fats = sorted(set(groups.keys()) | set(docs_idx.keys()))
        lines = []
        lines.append("LOG DE VALIDAÇÃO DE FATURAS / CT-e")
        lines.append("=" * 80)
        lines.append(f"Gerado em: {_datetime.now().strftime('%d/%m/%Y %H:%M:%S')}")
        lines.append(f"Origem: {origem}")
        lines.append(f"Versão lógica: 2.6.55 - Log TXT de decisão")
        lines.append("")
        lines.append("RESUMO")
        lines.append("-" * 80)
        lines.append(f"Faturas carregadas únicas: {len(docs_idx)}")
        lines.append(f"Faturas com registros detalhados: {len(groups)}")
        lines.append(f"Faturas no log: {len(all_fats)}")
        lines.append(f"CT-es/registros detalhados: {sum(len(v) for v in groups.values())}")
        if duplicates:
            lines.append(f"Faturas duplicadas detectadas no carregamento: {len(duplicates)}")
        lines.append("")
        try:
            imp_log = getattr(self, "_last_faturas_import_log_2650", None)
            if isinstance(imp_log, dict):
                lines.append("LOG DE IMPORTAÇÃO / DEDUP")
                lines.append("-" * 80)
                for k in ("selected", "unique", "removed"):
                    if k in imp_log:
                        lines.append(f"{k}: {imp_log.get(k)}")
                dups = imp_log.get("duplicates") or []
                if dups:
                    lines.append("Duplicadas ignoradas:")
                    for d in dups[:50]:
                        lines.append(f"  - {d.get('fatura')} | mantido: {d.get('arquivo_mantido')} | ignorado: {d.get('arquivo_ignorado')}")
                    if len(dups) > 50:
                        lines.append(f"  ... +{len(dups)-50} duplicadas")
                lines.append("")
        except Exception:
            pass
        if duplicates:
            lines.append("DUPLICADAS ENCONTRADAS NA LISTA CARREGADA")
            lines.append("-" * 80)
            for fat, mantido, ignorado in duplicates:
                lines.append(f"{fat} | mantido: {mantido} | duplicado: {ignorado}")
            lines.append("")
        lines.append("DECISÃO POR FATURA")
        lines.append("=" * 80)
        summary_counts = {}
        for fat in all_fats:
            recs = groups.get(fat, [])
            doc_info = docs_idx.get(fat, {})
            partner = _rec_partner(recs[0]) if recs else (doc_info.get("parceiro") or "Parceiro não identificado")
            decision, reason = _decision_for_group(recs)
            summary_counts[decision] = summary_counts.get(decision, 0) + 1
            total = sum(_rec_value(r) for r in recs)
            np = sum(_rec_blocked_value(r) for r in recs)
            ok = sum(1 for r in recs if _rec_is_ok(r))
            problema = len(recs) - ok
            lines.append("")
            lines.append(f"FATURA: {fat}")
            lines.append(f"Parceiro: {partner}")
            if doc_info.get("arquivo"):
                lines.append(f"Arquivo: {doc_info.get('arquivo')}")
            lines.append(f"Resultado: {decision}")
            lines.append(f"Por quê: {reason}")
            lines.append(f"Qtd. CT-es/registros: {len(recs)} | OK: {ok} | Problema/Revisar: {problema}")
            lines.append(f"Valor fatura: {_money(total)} | Valor não pagar: {_money(np)} | Valor a pagar: {_money(max(total - np, 0.0))}")
            if not recs:
                lines.append("Itens: nenhum CT-e detalhado foi gerado. Fatura deve ficar como REVISAR e não deve sumir do relatório.")
                continue
            lines.append("Itens:")
            for i, rec in enumerate(recs, 1):
                lines.append(f"  {i}. CT-e: {_rec_cte(rec)} | NF: {_rec_nf(rec)} | Valor: {_money(_rec_value(rec))} | Não pagar: {_money(_rec_blocked_value(rec))}")
                lines.append(f"     Status: {_rec_status(rec) or '-'}")
                lines.append(f"     Comprovante: {_rec_comp(rec) or '-'}")
                lines.append(f"     Base/Fatura: {_rec_base(rec) or '-'}")
                lines.append(f"     XML/Valor: {_rec_xml_status(rec) or '-'}")
                if _rec_motivo(rec):
                    lines.append(f"     Motivo original: {_rec_motivo(rec)}")
                lines.append(f"     Decisão do item: {_reason_for_rec(rec)}")
        lines.append("")
        lines.append("RESUMO POR RESULTADO")
        lines.append("-" * 80)
        for k in sorted(summary_counts):
            lines.append(f"{k}: {summary_counts[k]}")
        lines.append("")
        lines.append("OBSERVAÇÃO")
        lines.append("-" * 80)
        lines.append("Este log é diagnóstico. Ele explica o resultado com base nos campos internos gerados pelo processamento.")
        lines.append("Para CT-e de custo extra/complementar, a liberação sem comprovante só deve ocorrer quando houver CT-e complementar localizado na base.")
        text = "\n".join(lines) + "\n"
        last_path = None
        for log_dir in _log_dir_candidates():
            try:
                log_dir.mkdir(parents=True, exist_ok=True)
                path = log_dir / log_name
                path.write_text(text, encoding="utf-8")
                last_path = path
            except Exception:
                pass
        try:
            self._ultimo_log_faturas_2655 = str(last_path) if last_path else ""
        except Exception:
            pass
        return last_path

    def patched_process_invoices_2655(self, *args, **kwargs):
        result = _orig_process(self, *args, **kwargs)
        try:
            path = _write_faturas_log(self, "processamento de faturas")
            if path is not None:
                try:
                    if hasattr(self, "set_status"):
                        self.set_status(f"Processamento concluído. Log de decisão salvo em: {path}")
                except Exception:
                    pass
        except Exception as exc:
            try:
                print("[LOG FATURAS 2.6.55] erro ao gerar log:", exc)
            except Exception:
                pass
        return result

    def patched_build_invoice_report_sheets_2655(self, *args, **kwargs):
        result = _orig_build_report(self, *args, **kwargs) if callable(_orig_build_report) else []
        try:
            _write_faturas_log(self, "exportação/relatório de faturas")
        except Exception:
            pass
        return result

    FaturasPage.process_invoices = patched_process_invoices_2655
    if callable(_orig_build_report):
        FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2655
    try:
        FaturasPage.gerar_log_faturas_2655 = _write_faturas_log
    except Exception:
        pass
    FaturasPage._hotfix_faturas_2655 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.55 Log TXT Faturas"
    except Exception:
        pass


_central_cte_hotfix_faturas_2655_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.56
# Ajusta relatório/mensagens para exibir número do CT-e + NF.
# - Remove prefixos operacionais como GRU/CWB/BNU do CT-e no relatório.
# - Troca coluna "CT-e com Divergência" para "CT-e/NF com Divergência".
# - Preenche resumo e mensagem com "CT-e <numero> / NF <nota>".
# ============================================================================

def _central_cte_hotfix_faturas_2656_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2656():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main_with_faturas_2656()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2656_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.56] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2656").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2656_apply(_main):
    import re as _re

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2656", False):
        return

    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _strip_accents(value):
        try:
            import unicodedata
            return "".join(c for c in unicodedata.normalize("NFD", str(value or "")) if unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(str(value or "")).upper())

    def _normalize_fatura(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            return s
        return f"{(_re.sub(r'\D','',m.group(1)).lstrip('0') or '0').zfill(7)}-{m.group(2)}"

    def _clean_cte(value):
        s = _norm_space(value)
        if not s or s in {"-", "None"}:
            return "-"
        s = s.replace("CT-e", "").replace("CTE", "").replace("CTRC", "")
        s = _norm_space(s.strip(" :-"))
        # Remove prefixo operacional antes da barra: GRU/387640-3 -> 387640-3.
        m = _re.search(r"(?:[A-Z]{2,6}\s*/\s*)?(0*\d{3,12})\s*[-/]\s*(\d)", s, _re.I)
        if m:
            return f"{m.group(1).lstrip('0') or '0'}-{m.group(2)}"
        # Número puro: 00012344 -> 12344.
        m = _re.search(r"\b(0*\d{3,12})\b", s)
        if m:
            return m.group(1).lstrip("0") or "0"
        return s

    def _clean_nf(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        m = _re.search(r"\b(0*\d{1,12})\b", s)
        if m:
            return m.group(1).lstrip("0") or "0"
        return s

    def _cte_nf_label(cte, nf=""):
        c = _clean_cte(cte)
        n = _clean_nf(nf)
        if not c or c == "-":
            return "-"
        return f"CT-e {c}" + (f" / NF {n}" if n else "")

    def _looks_problem(text):
        up = _strip_accents(str(text or "")).upper()
        return any(k in up for k in ("SEM COMPROVANTE", "FORA DA BASE", "DIVERG", "NAO PAGAR", "NÃO PAGAR", "PAGAR PARCIAL", "DY=N", "REVISAR"))

    def _is_ok_record(rec):
        if not isinstance(rec, dict):
            return False
        dy = str(rec.get("DY") or rec.get("dy") or "").strip().upper()
        comp = " | ".join(str(rec.get(k) or "") for k in ("Comprovante", "Comprovante OK?", "comprovante"))
        st = " | ".join(str(rec.get(k) or "") for k in ("Status final CT-e", "Status CT-e", "status", "Motivo", "Observação"))
        up = _strip_accents((comp + " | " + st)).upper()
        if dy == "N" or _looks_problem(up):
            return False
        if dy == "S" or "COMPROVANTE OK" in up or up.startswith("OK") or " OK " in up:
            return True
        return False

    def _get_rec_value(rec, *keys):
        if not isinstance(rec, dict):
            return ""
        for k in keys:
            v = rec.get(k)
            if v is not None and str(v).strip() != "":
                return v
        return ""

    def _live_problem_map(self):
        out = {}
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if not isinstance(rec, dict):
                continue
            if _is_ok_record(rec):
                continue
            fat = _normalize_fatura(_get_rec_value(rec, "Fatura", "fatura"))
            if not fat:
                continue
            cte = _get_rec_value(rec, "CT-e fatura", "CT-e base", "CTRC base", "CT-e", "cte", "CTRC")
            nf = _get_rec_value(rec, "NF fatura", "NF base", "NF", "nf", "nota_fiscal")
            label = _cte_nf_label(cte, nf)
            if label != "-":
                out.setdefault(fat, [])
                if label not in out[fat]:
                    out[fat].append(label)
        return out

    def _find_idx(headers, *names):
        normalized = [_norm(h) for h in headers or []]
        for name in names:
            nn = _norm(name)
            for i, h in enumerate(normalized):
                if h == nn or nn in h or h in nn:
                    return i
        return None

    def _map_from_divergence_sheet(rows):
        out = {}
        if not rows or len(rows) < 2:
            return out
        headers = list(rows[0])
        i_fat = _find_idx(headers, "Fatura")
        i_cte = _find_idx(headers, "CT-e", "CTE", "CTRC")
        i_nf = _find_idx(headers, "NF", "Nota Fiscal")
        if i_fat is None or i_cte is None:
            return out
        for row in rows[1:]:
            try:
                fat = _normalize_fatura(row[i_fat] if i_fat < len(row) else "")
                cte = row[i_cte] if i_cte < len(row) else ""
                nf = row[i_nf] if i_nf is not None and i_nf < len(row) else ""
                label = _cte_nf_label(cte, nf)
                if fat and label != "-":
                    out.setdefault(fat, [])
                    if label not in out[fat]:
                        out[fat].append(label)
            except Exception:
                pass
        return out

    def _merge_maps(a, b):
        out = {k: list(v) for k, v in (a or {}).items()}
        for k, vals in (b or {}).items():
            out.setdefault(k, [])
            for v in vals or []:
                if v and v not in out[k]:
                    out[k].append(v)
        return out

    def _rewrite_pending_cell_from_message(text):
        t = str(text or "")
        labels = []
        # Captura linhas da mensagem pronta: - CT-e GRU/123-4 | NF 999 | ...
        for m in _re.finditer(r"CT\s*-?\s*e\s+([^|\n\r]+?)\s*\|\s*NF\s+([^|\n\r]+)", t, _re.I):
            label = _cte_nf_label(m.group(1), m.group(2))
            if label != "-" and label not in labels:
                labels.append(label)
        return " | ".join(labels) + ("\n" if labels else "")

    def _rewrite_message_text(text):
        t = str(text or "")
        if not t:
            return t
        # Remove prefixo operacional do CT-e nas mensagens, mantendo NF.
        def repl(m):
            return f"CT-e {_clean_cte(m.group(1))} | NF {_clean_nf(m.group(2)) or '-'}"
        t = _re.sub(r"CT\s*-?\s*e\s+([^|\n\r]+?)\s*\|\s*NF\s+([^|\n\r]+)", repl, t, flags=_re.I)
        # Evita ponto duplicado antigo.
        t = t.replace("entrega..", "entrega.")
        return t

    def _rewrite_sheet(sheet_name, rows, widths, problem_map):
        if not rows:
            return (sheet_name, rows, widths)
        new_rows = [list(r) for r in rows]
        headers = new_rows[0]
        title_norm = _norm(sheet_name)

        # 1_Resumo_Faturas: trocar CT-e com Divergência por CT-e/NF com Divergência.
        if "RESUMO" in title_norm or any(_norm(h) == _norm("CT-e com Divergência") for h in headers):
            i_fat = _find_idx(headers, "Número da Fatura", "Fatura")
            i_div = _find_idx(headers, "CT-e com Divergência", "CT-e/NF com Divergência", "CTes Pendentes")
            if i_div is not None:
                headers[i_div] = "CT-e/NF com Divergência"
                for r in new_rows[1:]:
                    try:
                        fat = _normalize_fatura(r[i_fat] if i_fat is not None and i_fat < len(r) else "")
                        vals = problem_map.get(fat) or []
                        r[i_div] = " | ".join(vals) if vals else "-"
                    except Exception:
                        pass

        # 2_CTes_Comprovantes / 3_Divergencias: limpar coluna CT-e, mantendo NF na própria coluna NF.
        if any(_norm(h) in {_norm("CT-e"), _norm("CTE"), _norm("CTRC")} for h in headers):
            i_cte = _find_idx(headers, "CT-e", "CTE", "CTRC")
            if i_cte is not None:
                headers[i_cte] = "CT-e"
                for r in new_rows[1:]:
                    try:
                        if i_cte < len(r):
                            r[i_cte] = _clean_cte(r[i_cte])
                    except Exception:
                        pass

        # 4_Mensagem_Parceiro: célula resumida também precisa trazer NF.
        if "MENSAGEM" in title_norm or any("MENSAGEM" in _norm(h) for h in headers):
            i_pend = _find_idx(headers, "CT-es pendentes", "CTes pendentes", "CT-es/NFs pendentes")
            i_msg = _find_idx(headers, "Mensagem pronta", "Mensagem")
            if i_pend is not None:
                headers[i_pend] = "CT-es/NFs pendentes"
            for r in new_rows[1:]:
                try:
                    if i_msg is not None and i_msg < len(r):
                        msg = _rewrite_message_text(r[i_msg])
                        r[i_msg] = msg
                        if i_pend is not None and i_pend < len(r):
                            pend = _rewrite_pending_cell_from_message(msg)
                            if pend:
                                r[i_pend] = pend
                    elif i_pend is not None and i_pend < len(r):
                        # Fallback: limpa prefixos se só houver a lista antiga.
                        parts = []
                        for piece in _re.split(r"\s*\|\s*", str(r[i_pend] or "")):
                            if piece.strip():
                                parts.append(_cte_nf_label(piece.strip()))
                        r[i_pend] = " | ".join([p for p in parts if p != "-"])
                except Exception:
                    pass

        return (sheet_name, new_rows, widths)

    def _rewrite_obj_messages(obj):
        if isinstance(obj, str):
            return _rewrite_message_text(obj)
        if isinstance(obj, list):
            return [_rewrite_obj_messages(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_rewrite_obj_messages(x) for x in obj)
        if isinstance(obj, dict):
            return {k: _rewrite_obj_messages(v) for k, v in obj.items()}
        return obj

    def patched_build_invoice_report_sheets_2656(self, *args, **kwargs):
        result = _orig_build_report(self, *args, **kwargs) if callable(_orig_build_report) else []
        try:
            if not isinstance(result, list):
                return result
            # Primeiro monta mapa a partir da aba de divergências já gerada.
            sheet_map = {}
            for item in result:
                try:
                    name, rows, widths = item
                    sheet_map[str(name)] = rows
                except Exception:
                    pass
            from_sheets = {}
            for name, rows in sheet_map.items():
                if "DIVERG" in _norm(name):
                    from_sheets = _merge_maps(from_sheets, _map_from_divergence_sheet(rows))
            problem_map = _merge_maps(from_sheets, _live_problem_map(self))
            new_result = []
            for item in result:
                try:
                    name, rows, widths = item
                    new_result.append(_rewrite_sheet(name, rows, widths, problem_map))
                except Exception:
                    new_result.append(item)
            return new_result
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.56] erro ao ajustar relatório:", exc)
            except Exception:
                pass
            return result

    def _wrap_method(cls, name):
        orig = getattr(cls, name, None)
        if not callable(orig) or getattr(orig, "_hotfix_2656", False):
            return
        def wrapped(self, *args, **kwargs):
            result = orig(self, *args, **kwargs)
            try:
                return _rewrite_obj_messages(result)
            except Exception:
                return result
        wrapped._hotfix_2656 = True
        try:
            setattr(cls, name, wrapped)
        except Exception:
            pass

    if callable(_orig_build_report):
        FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2656
    # Também cobre possíveis botões/janelas de mensagem no app, não só o XLSX.
    for name in dir(FaturasPage):
        low = str(name).lower()
        if not low.startswith("_") and ("mensag" in low or "message" in low):
            _wrap_method(FaturasPage, name)

    FaturasPage._hotfix_faturas_2656 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.56 CT-e e NF no relatório"
    except Exception:
        pass


_central_cte_hotfix_faturas_2656_start()

# ============================================================================
# HOTFIX Faturas Parceiros 2.6.57
# Usa o número do SUBCONTRATO da fatura como CT-e exibido no relatório/mensagem.
# Ex.: tabela "FRETE TERCEIRO PAGADOR" -> Subcontrato "2 00576121" vira "CT-e 576121".
# ============================================================================

def _central_cte_hotfix_faturas_2657_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main_with_faturas_2657():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main_with_faturas_2657()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2657_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.57] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2657").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2657_apply(_main):
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2657", False):
        return

    _orig_parse_invoice = getattr(FaturasPage, "parse_invoice_text", None)
    _orig_parse_ssw = getattr(FaturasPage, "parse_ssw_len_invoice_text", None)
    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build_report = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_cmp(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(str(value or "")).upper())

    def _parse_money(value):
        s = str(value or "").strip().replace("R$", "").replace(" ", "")
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _clean_num(value):
        digits = _re.sub(r"\D+", "", str(value or ""))
        return digits.lstrip("0") or ("0" if digits else "")

    def _fmt_invoice(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if not m:
            return ""
        return f"{_clean_num(m.group(1)).zfill(7)}-{m.group(2)}"

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        for key in ("fatura", "Fatura", "numero_fatura"):
            fat = _fmt_invoice(doc.get(key))
            if fat:
                return fat
        txt = str(doc.get("texto") or "")
        for pat in (r"(?i)FATURA\D{0,20}(0*\d{3,9}\s*[-/]\s*\d)", r"(?<!\d)(0*\d{3,9}\s*[-/]\s*\d)(?!\d)"):
            m = _re.search(pat, txt)
            if m:
                fat = _fmt_invoice(m.group(1))
                if fat:
                    return fat
        return ""

    def _clean_cte_for_display(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        s = s.replace("CT-e", "").replace("CTE", "").replace("CTRC", "")
        s = _norm_space(s.strip(" :-"))
        # Prefixo operacional: GRU/387640-3 -> 387640-3.
        m = _re.search(r"(?:[A-Z]{2,6}\s*/\s*)?(0*\d{3,12})\s*[-/]\s*(\d)", s, _re.I)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        # Linha de subcontrato: 2 00576121 -> 576121.
        m = _re.search(r"(?:^|\s)\d{1,3}\s+0*(\d{5,12})(?:\s|$)", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{5,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _clean_nf(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        m = _re.search(r"\b0*(\d{4,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _cte_nf_label(cte, nf=""):
        c = _clean_cte_for_display(cte)
        n = _clean_nf(nf)
        if not c:
            return "-"
        return f"CT-e {c}" + (f" / NF {n}" if n else "")

    def _extract_subcontrato_rows(text):
        raw = str(text or "").replace("\xa0", " ")
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        joined_hint = _strip_accents(raw).upper()
        # Só ativa o parser específico quando o layout indica subcontratação ou a coluna Subcontrato existe.
        if "SUBCONTRATO" not in joined_hint and "FRETE TERCEIRO PAGADOR" not in joined_hint:
            return []
        out = []
        # Caso comum do PDF extraído em uma única linha de tabela:
        # 2 00576121 26/06/26 ... 000285167 ... 550,00 ...
        row_pat = _re.compile(
            r"(?:^|\s)(?:\d{1,3}\s+)?0*(?P<sub>\d{5,12})\s+"
            r"(?P<data>\d{2}/\d{2}/\d{2,4})\s+"
            r"(?P<rest>.+?)(?=(?:\s+\d{1,3}\s+0*\d{5,12}\s+\d{2}/\d{2}/\d{2,4})|$)",
            _re.I,
        )
        all_text = " ".join(lines)
        for m in row_pat.finditer(all_text):
            sub = _clean_num(m.group("sub"))
            rest = m.group("rest") or ""
            # NF costuma vir como número fiscal com 5 a 12 dígitos após remetente.
            nf = ""
            nums = [x for x in _re.findall(r"\b0*(\d{5,12})\b", rest) if _clean_num(x) != sub]
            if nums:
                nf = _clean_num(nums[0])
            vals = [_parse_money(v) for v in _money_values(rest)]
            vals = [v for v in vals if v > 0]
            valor = vals[-1] if vals else 0.0
            if sub:
                out.append({"subcontrato": sub, "cte": sub, "cte_ref": sub, "nf": nf, "valor_fatura": valor, "linha": _norm_space(m.group(0))})
        # Caso o extrator quebre a linha do subcontrato e a NF/valor em linhas próximas.
        if not out:
            for i, line in enumerate(lines):
                m = _re.match(r"^(?:\d{1,3}\s+)?0*(\d{5,12})(?:\s+\d{2}/\d{2}/\d{2,4}|$)", line)
                if not m:
                    continue
                sub = _clean_num(m.group(1))
                block = " ".join(lines[i:i+12])
                if not _re.search(r"\d{2}/\d{2}/\d{2,4}", block):
                    continue
                nums = [x for x in _re.findall(r"\b0*(\d{5,12})\b", block) if _clean_num(x) != sub]
                nf = _clean_num(nums[0]) if nums else ""
                vals = [_parse_money(v) for v in _money_values(block)]
                vals = [v for v in vals if v > 0]
                valor = vals[-1] if vals else 0.0
                out.append({"subcontrato": sub, "cte": sub, "cte_ref": sub, "nf": nf, "valor_fatura": valor, "linha": _norm_space(block)})
        # Deduplica.
        dedup, seen = [], set()
        for item in out:
            key = (_clean_num(item.get("subcontrato")), _clean_num(item.get("nf")), round(float(item.get("valor_fatura") or 0), 2))
            if not key[0] or key in seen:
                continue
            seen.add(key)
            dedup.append(item)
        return dedup

    def _merge_subcontrato_items(doc, text, path):
        if not isinstance(doc, dict):
            doc = {}
        sub_items = _extract_subcontrato_rows(text)
        if not sub_items:
            return doc
        old_items = doc.get("items") if isinstance(doc.get("items"), list) else []
        merged = []
        used = set()
        # Casa por NF ou por valor para preservar demais campos do parser antigo, mas corrigir o CT-e exibido.
        for old in old_items:
            if not isinstance(old, dict):
                continue
            old_nf = _clean_nf(old.get("nf") or old.get("nota_fiscal") or old.get("NF"))
            old_val = round(_parse_money(old.get("valor_fatura") or old.get("valor") or old.get("frete")), 2)
            chosen = None
            for idx, si in enumerate(sub_items):
                if idx in used:
                    continue
                si_nf = _clean_nf(si.get("nf"))
                si_val = round(_parse_money(si.get("valor_fatura")), 2)
                if (old_nf and si_nf and old_nf == si_nf) or (old_val > 0 and si_val > 0 and abs(old_val - si_val) <= 0.01):
                    chosen = (idx, si)
                    break
            if chosen:
                idx, si = chosen
                used.add(idx)
                old = dict(old)
                old["subcontrato"] = si.get("subcontrato")
                old["cte"] = si.get("cte")
                old["cte_ref"] = si.get("cte_ref")
                if si.get("nf") and not old_nf:
                    old["nf"] = si.get("nf")
                if si.get("valor_fatura") and not old_val:
                    old["valor_fatura"] = si.get("valor_fatura")
                old["linha_subcontrato"] = si.get("linha")
            merged.append(old)
        for idx, si in enumerate(sub_items):
            if idx not in used:
                merged.append(dict(si))
        doc["items"] = merged
        doc["parser_subcontrato_2657"] = True
        if text and not doc.get("texto"):
            doc["texto"] = str(text)[:5000]
        if path:
            doc.setdefault("path", str(path))
            doc.setdefault("arquivo", _Path(path).name)
        return doc

    def _doc_sub_map(self):
        by_fat = {}
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            text = doc.get("texto") or ""
            path = doc.get("path") or doc.get("arquivo") or ""
            try:
                _merge_subcontrato_items(doc, text, path)
            except Exception:
                pass
            fat = _doc_invoice(doc)
            items = doc.get("items") if isinstance(doc.get("items"), list) else []
            for it in items:
                if not isinstance(it, dict):
                    continue
                sub = _clean_num(it.get("subcontrato") or it.get("cte_ref") or it.get("cte"))
                if not sub:
                    continue
                by_fat.setdefault(fat, []).append({
                    "cte": sub,
                    "nf": _clean_nf(it.get("nf")),
                    "valor": round(_parse_money(it.get("valor_fatura") or it.get("valor")), 2),
                    "linha": it.get("linha") or it.get("linha_subcontrato") or "",
                })
        return by_fat

    def _record_fatura(rec):
        if not isinstance(rec, dict):
            return ""
        return _fmt_invoice(rec.get("Fatura") or rec.get("fatura") or rec.get("numero_fatura") or "")

    def _record_value(rec):
        if not isinstance(rec, dict):
            return 0.0
        return round(_parse_money(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("valor_fatura") or rec.get("valor")), 2)

    def _record_nf(rec):
        if not isinstance(rec, dict):
            return ""
        return _clean_nf(rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or rec.get("nf"))

    def _apply_subcontrato_to_records(self):
        by_fat = _doc_sub_map(self)
        changed = 0
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if not isinstance(rec, dict):
                continue
            fat = _record_fatura(rec)
            candidates = by_fat.get(fat) or []
            if not candidates:
                continue
            rec_nf = _record_nf(rec)
            rec_val = _record_value(rec)
            chosen = None
            for cand in candidates:
                if rec_nf and cand.get("nf") and rec_nf == cand.get("nf"):
                    chosen = cand
                    break
            if chosen is None:
                for cand in candidates:
                    if rec_val > 0 and cand.get("valor") and abs(rec_val - cand.get("valor")) <= 0.01:
                        chosen = cand
                        break
            if chosen is None and len(candidates) == 1:
                chosen = candidates[0]
            if not chosen:
                continue
            sub = chosen.get("cte")
            if sub and _clean_cte_for_display(rec.get("CT-e fatura")) != sub:
                rec["Subcontrato"] = sub
                rec["CT-e fatura"] = sub
                # Guarda o antigo para auditoria, sem usar no relatório/mensagem.
                old = rec.get("CT-e base") or rec.get("CTRC base") or rec.get("CT-e") or ""
                if old and not rec.get("CT-e origem/base"):
                    rec["CT-e origem/base"] = old
                changed += 1
            if chosen.get("nf") and not _record_nf(rec):
                rec["NF fatura"] = chosen.get("nf")
        try:
            self._faturas_subcontrato_2657_corrigidos = changed
        except Exception:
            pass
        return changed

    def patched_parse_invoice_text_2657(self, text, path):
        doc = _orig_parse_invoice(self, text, path) if callable(_orig_parse_invoice) else {}
        try:
            return _merge_subcontrato_items(doc, text, path)
        except Exception:
            return doc

    def patched_parse_ssw_len_invoice_text_2657(self, text, path):
        doc = _orig_parse_ssw(self, text, path) if callable(_orig_parse_ssw) else {}
        try:
            return _merge_subcontrato_items(doc, text, path)
        except Exception:
            return doc

    def patched_process_invoices_2657(self, *args, **kwargs):
        result = _orig_process(self, *args, **kwargs) if callable(_orig_process) else None
        try:
            changed = _apply_subcontrato_to_records(self)
            # Reaplica tabela/cartões se existir, para a tela também usar o CT-e correto.
            for name in ("apply_filters", "update_cards", "load_details_for_selected"):
                fn = getattr(self, name, None)
                if callable(fn):
                    try:
                        fn()
                    except Exception:
                        pass
            if changed and hasattr(self, "set_status"):
                try:
                    self.set_status(f"Processamento concluído. CT-e do relatório ajustado pelo Subcontrato da fatura: {changed} item(ns).")
                except Exception:
                    pass
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.57] erro ao aplicar subcontrato nos registros:", exc)
            except Exception:
                pass
        return result

    def _rewrite_message_subcontrato(text):
        t = str(text or "")
        if not t:
            return t
        # Garante limpeza final caso algum texto antigo ainda tenha CT-e com prefixo operacional.
        def repl(m):
            return f"CT-e {_clean_cte_for_display(m.group(1))} | NF {_clean_nf(m.group(2)) or '-'}"
        return _re.sub(r"CT\s*-?\s*e\s+([^|\n\r]+?)\s*\|\s*NF\s+([^|\n\r]+)", repl, t, flags=_re.I)

    def _rewrite_obj(obj):
        if isinstance(obj, str):
            return _rewrite_message_subcontrato(obj)
        if isinstance(obj, list):
            return [_rewrite_obj(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_rewrite_obj(x) for x in obj)
        if isinstance(obj, dict):
            return {k: _rewrite_obj(v) for k, v in obj.items()}
        return obj

    def patched_build_invoice_report_sheets_2657(self, *args, **kwargs):
        try:
            _apply_subcontrato_to_records(self)
        except Exception:
            pass
        result = _orig_build_report(self, *args, **kwargs) if callable(_orig_build_report) else []
        # O hotfix 2.6.56 já reescreve o resumo/mensagem com base nos registros.
        # Aqui só faz uma limpeza final em textos que tenham sobrado.
        try:
            return _rewrite_obj(result)
        except Exception:
            return result

    FaturasPage.parse_invoice_text = patched_parse_invoice_text_2657
    FaturasPage.parse_ssw_len_invoice_text = patched_parse_ssw_len_invoice_text_2657
    FaturasPage.process_invoices = patched_process_invoices_2657
    if callable(_orig_build_report):
        FaturasPage.build_invoice_report_sheets = patched_build_invoice_report_sheets_2657

    # Também cobre possíveis botões de mensagem no app.
    for name in dir(FaturasPage):
        low = str(name).lower()
        if not low.startswith("_") and ("mensag" in low or "message" in low):
            orig = getattr(FaturasPage, name, None)
            if callable(orig) and not getattr(orig, "_hotfix_2657", False):
                def _make_wrap(fn):
                    def wrapped(self, *args, **kwargs):
                        try:
                            _apply_subcontrato_to_records(self)
                        except Exception:
                            pass
                        res = fn(self, *args, **kwargs)
                        return _rewrite_obj(res)
                    wrapped._hotfix_2657 = True
                    return wrapped
                try:
                    setattr(FaturasPage, name, _make_wrap(orig))
                except Exception:
                    pass

    FaturasPage._hotfix_faturas_2657 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.57 CT-e pelo Subcontrato"
    except Exception:
        pass


_central_cte_hotfix_faturas_2657_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.58
# Remove falsos "FORA DA BASE" duplicados criados quando o item da fatura
# contém o CT-e/Subcontrato e a base localiza o CT-e por outro vínculo/NF.
# Regra: se existe um registro do mesmo CT-e na mesma fatura que foi localizado
# na base, qualquer clone "FORA DA BASE" do mesmo CT-e é removido do resumo,
# detalhes, divergências, mensagem e relatório. Mantém o FORA DA BASE verdadeiro
# quando não houver nenhum registro localizado para aquele CT-e.
# ============================================================================

def _central_cte_hotfix_faturas_2658_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2658_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.58] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2658").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2658_apply(_main):
    import re as _re
    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2658", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            import unicodedata
            return "".join(c for c in unicodedata.normalize("NFD", str(value or "")) if unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm_text(value):
        return _strip_accents(_norm_space(value)).upper()

    def _digits(value):
        return _re.sub(r"\D+", "", str(value or ""))

    def _fmt_fatura(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if m:
            return f"{(_digits(m.group(1)).lstrip('0') or '0').zfill(7)}-{m.group(2)}"
        return s

    def _money_num(value):
        fn = getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        s = str(value or "").replace("R$", "").strip()
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        fn = getattr(_main, "money", None)
        if callable(fn):
            try:
                out = fn(value)
                return str(out) if str(out).startswith("R$") else "R$ " + str(out)
            except Exception:
                pass
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _cte_value(rec):
        if not isinstance(rec, dict):
            return ""
        return _norm_space(rec.get("Subcontrato") or rec.get("CT-e fatura") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("CT-e") or rec.get("cte") or "")

    def _cte_key(rec):
        # Compara por dígitos para igualar "GRU/387640-3", "387640-3" e "3876403".
        d = _digits(_cte_value(rec))
        return d.lstrip("0") or d

    def _nf_key(rec):
        if not isinstance(rec, dict):
            return ""
        return (_digits(rec.get("NF fatura") or rec.get("NF base") or rec.get("NF") or rec.get("nf") or "").lstrip("0"))

    def _status_text(rec):
        if not isinstance(rec, dict):
            return ""
        parts = []
        for k in ("Status final CT-e", "Status CT-e", "status", "Comprovante", "Comprovante OK?", "Motivo", "Observação", "Conferência fatura base", "Fatura Base"):
            v = rec.get(k)
            if v not in (None, ""):
                parts.append(str(v))
        return _norm_text(" | ".join(parts))

    def _is_fora_base(rec):
        up = _status_text(rec)
        return "FORA DA BASE" in up or "NAO LOCALIZADO NA BASE" in up or "NÃO LOCALIZADO NA BASE" in up or "FORA OU NAO LOCALIZADO" in up or "FORA OU NÃO LOCALIZADO" in up

    def _is_problem(rec):
        up = _status_text(rec)
        return any(x in up for x in ("SEM COMPROVANTE", "DY=N", "DIVERG", "NAO PAGAR", "NÃO PAGAR", "REVISAR", "FORA DA BASE"))

    def _is_ok(rec):
        up = _status_text(rec)
        dy = str((rec or {}).get("DY") or "").strip().upper() if isinstance(rec, dict) else ""
        if dy == "N" or _is_problem(rec):
            return False
        return dy == "S" or "OK PAGAR" in up or "COMPROVANTE OK" in up or up.startswith("OK")

    def _value(rec):
        if not isinstance(rec, dict):
            return 0.0
        return _money_num(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("Valor Fat.") or rec.get("valor_fatura") or rec.get("valor") or rec.get("Valor não pagar") or 0)

    def _no_pay(rec):
        if not isinstance(rec, dict):
            return 0.0
        v = _money_num(rec.get("Valor não pagar") or 0)
        if v:
            return v
        return _value(rec) if not _is_ok(rec) else 0.0

    def _partner(rec):
        if not isinstance(rec, dict):
            return "Parceiro não identificado"
        return _norm_space(rec.get("Parceiro") or rec.get("parceiro") or "Parceiro não identificado") or "Parceiro não identificado"

    def _clean_records_2658(self):
        records = list(getattr(self, "invoice_detail_records", []) or [])
        if not records:
            return 0
        # Primeiro, descobre CT-es que têm algum registro localizado na base.
        found_keys = set()
        for rec in records:
            if not isinstance(rec, dict):
                continue
            fat = _fmt_fatura(rec.get("Fatura") or rec.get("fatura") or "")
            ck = _cte_key(rec)
            if fat and ck and not _is_fora_base(rec):
                found_keys.add((fat, ck))
        cleaned = []
        removed = 0
        seen = set()
        for rec in records:
            if not isinstance(rec, dict):
                continue
            fat = _fmt_fatura(rec.get("Fatura") or rec.get("fatura") or "")
            if fat:
                rec["Fatura"] = fat
            ck = _cte_key(rec)
            # Este é o ponto principal: clone FORA DA BASE do mesmo CT-e que já foi localizado.
            if fat and ck and _is_fora_base(rec) and (fat, ck) in found_keys:
                removed += 1
                continue
            # Dedup exato defensivo, preservando uma só linha por fatura/CT-e/NF/status/valor.
            key = (fat, ck, _nf_key(rec), round(_value(rec), 2), _norm_text(rec.get("Status final CT-e") or rec.get("Status CT-e") or rec.get("Motivo") or "")[:40])
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            cleaned.append(rec)
        if removed:
            self.invoice_detail_records = cleaned
            try:
                self._faturas_fora_base_clones_removidos_2658 = removed
            except Exception:
                pass
            _rebuild_summary_2658(self)
        return removed

    def _rebuild_summary_2658(self):
        records = list(getattr(self, "invoice_detail_records", []) or [])
        groups = {}
        order = []
        for rec in records:
            if not isinstance(rec, dict):
                continue
            fat = _fmt_fatura(rec.get("Fatura") or rec.get("fatura") or "") or "NÃO IDENTIFICADA"
            rec["Fatura"] = fat
            if fat not in groups:
                groups[fat] = []
                order.append(fat)
            groups[fat].append(rec)
        rows = []
        details = {}
        for fat in order:
            recs = groups.get(fat, [])
            partner = "Parceiro não identificado"
            for r in recs:
                p = _partner(r)
                if p and p != "Parceiro não identificado":
                    partner = p
                    break
            qtd = len(recs)
            ok = sum(1 for r in recs if _is_ok(r))
            prob = qtd - ok
            valor = sum(_value(r) for r in recs)
            np = sum(_no_pay(r) for r in recs)
            status = "OK PAGAR" if prob == 0 else ("PAGAR PARCIAL" if ok > 0 else "NÃO PAGAR")
            dy_s = sum(1 for r in recs if str(r.get("DY") or "").strip().upper() == "S")
            dy_n = sum(1 for r in recs if str(r.get("DY") or "").strip().upper() == "N" or "SEM COMPROVANTE" in _status_text(r))
            comprov = f"OK {dy_s} | Pend. {dy_n} | Revisar {max(qtd - dy_s - dy_n, 0)}"
            valores = f"Fatura {_money(valor)} | Não pagar {_money(np)} | A pagar {_money(max(valor - np, 0.0))}"
            rows.append([fat, partner, str(qtd), str(ok), str(prob), _money(valor), _money(np), valores, comprov, status])
            dets = []
            for r in recs:
                dets.append([
                    _cte_value(r) or "-",
                    r.get("NF fatura") or r.get("NF base") or r.get("NF") or "-",
                    _money(_value(r)),
                    _money(r.get("Valor XML") or 0),
                    r.get("Status valor") or r.get("Valor OK?") or "-",
                    r.get("Conferência fatura base") or r.get("Fatura Base") or "-",
                    r.get("Comprovante") or r.get("Comprovante OK?") or "-",
                    r.get("Data/Hora escaneamento") or r.get("Escaneamento") or "-",
                    r.get("Status final CT-e") or r.get("Status CT-e") or "-",
                    r.get("Motivo") or r.get("Observação") or "",
                ])
            details[fat] = dets
        try:
            self.invoice_rows = rows
            self.detail_rows_by_invoice = details
        except Exception:
            pass
        # Recarrega tabela visual sem mexer nas regras originais.
        try:
            table = getattr(self, "invoice_table", None)
            if table is not None:
                table.setRowCount(0)
                add_row = getattr(self, "add_invoice_row", None)
                for row in rows:
                    if callable(add_row):
                        add_row(row)
        except Exception:
            pass
        for name in ("refresh_partner_filter", "apply_filters", "update_cards", "load_details_for_selected"):
            fn = getattr(self, name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def patched_process_2658(self, *args, **kwargs):
        result = _orig_process(self, *args, **kwargs) if callable(_orig_process) else None
        try:
            removed = _clean_records_2658(self)
            if removed and hasattr(self, "set_status"):
                try:
                    self.set_status(f"Processamento concluído. Removidos {removed} clone(s) FORA DA BASE já localizados na base pelo CT-e.")
                except Exception:
                    pass
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.58] erro ao limpar clones fora da base:", exc)
            except Exception:
                pass
        return result

    def patched_build_report_2658(self, *args, **kwargs):
        try:
            _clean_records_2658(self)
        except Exception:
            pass
        return _orig_build(self, *args, **kwargs) if callable(_orig_build) else []

    FaturasPage.process_invoices = patched_process_2658
    if callable(_orig_build):
        FaturasPage.build_invoice_report_sheets = patched_build_report_2658
    try:
        FaturasPage.limpar_clones_fora_base_2658 = _clean_records_2658
    except Exception:
        pass
    FaturasPage._hotfix_faturas_2658 = True
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.58 Base sem clones duplicados"
    except Exception:
        pass


_central_cte_hotfix_faturas_2658_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.59
# Corrige CT-e/NF do relatório usando o documento da FATURA como fonte de exibição.
# Problemas corrigidos:
# - Em layouts FRETE TERCEIRO PAGADOR, o CT-e correto é o Subcontrato da fatura
#   e a NF correta vem da coluna N Fiscal Nº, não do CTRC Origem/base.
# - Em layouts CT-e / RPS / NFS-e, evita capturar valor de mercadoria, boleto,
#   nosso número ou código de banco como CT-e/NF.
# - Remove clones "FORA DA BASE" criados por leitura errada quando a própria
#   fatura possui o CT-e correto.
# - Ajusta abas Resumo, Divergências e Mensagem Parceiro com CT-e/NF da fatura.
# ============================================================================

def _central_cte_hotfix_faturas_2659_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2659_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.59] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2659").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2659_apply(_main):
    import re as _re
    import unicodedata as _unicodedata

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2659", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(str(value or "")).upper())

    def _digits(value):
        return _re.sub(r"\D+", "", str(value or ""))

    def _clean_num(value):
        d = _digits(value)
        return d.lstrip("0") or ("0" if d else "")

    def _fmt_fatura(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if m:
            return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        return s

    def _parse_money(value):
        fn = getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        s = str(value or "").replace("R$", "").strip()
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        fn = getattr(_main, "money", None)
        if callable(fn):
            try:
                out = str(fn(value))
                return out if out.startswith("R$") else "R$ " + out
            except Exception:
                pass
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _clean_cte(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        s = _re.sub(r"\b(CT\s*-?\s*E|CTE|CTRC|SUBCONTRATO)\b", "", s, flags=_re.I)
        s = _norm_space(s.strip(" :-"))
        # Prefixo operacional ou código textual: GRU/387640-3, FAN001938-1.
        m = _re.search(r"[A-Z]{2,8}\s*/?\s*0*(\d{3,12})\s*[-/]\s*(\d)", s, _re.I)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        # Número com dígito: 387640-3.
        m = _re.search(r"\b0*(\d{3,12})\s*[-/]\s*(\d)\b", s)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        # Linha SSW de subcontrato: 2 00576121, 1 00012344.
        m = _re.search(r"(?:^|\s)\d{1,3}\s+0*(\d{5,12})(?:\s|$)", s)
        if m:
            return _clean_num(m.group(1))
        # Número puro.
        m = _re.search(r"\b0*(\d{3,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _cte_key(value):
        c = _clean_cte(value)
        return _digits(c).lstrip("0") or _digits(c)

    def _clean_nf(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        # N Fiscal pode vir com série antes: 1 000285167, 55 000304099.
        m = _re.match(r"^\s*\d{1,3}\s+0*(\d{4,12})\s*$", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{4,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _cte_label(cte, nf=""):
        c = _clean_cte(cte)
        n = _clean_nf(nf)
        if not c:
            return "-"
        return f"CT-e {c}" + (f" / NF {n}" if n else "")

    def _find_idx(headers, *names):
        nh = [_norm(h) for h in headers or []]
        for name in names:
            nn = _norm(name)
            for i, h in enumerate(nh):
                if h == nn or nn in h or h in nn:
                    return i
        return None

    def _line_is_money(s):
        return bool(_re.fullmatch(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", _norm_space(s)))

    def _line_is_integer(s):
        return bool(_re.fullmatch(r"\d{1,12}", _norm_space(s)))

    def _extract_nf_list(lines, start_idx):
        # Extrai apenas a coluna N Fiscal Nº. Ignora valores monetários, peso e CTRC Origem.
        out = []
        if start_idx is None:
            return out
        for j in range(start_idx + 1, min(len(lines), start_idx + 80)):
            line = _norm_space(lines[j])
            u = _norm(line)
            if not line:
                continue
            if u in {"NFISCAL", "R", "RS"} or "NFISCALR" in u:
                continue
            if "PESOKG" in u or u == "PESO" or "BCALCULO" in u or u == "ICMS" or "FRETE" in u or "CTRCORIGEM" in u or "TRATAMENTO" in u:
                # Peso costuma vir logo depois da coluna NF. Se já pegou algo, encerra.
                if out:
                    break
                continue
            if _line_is_money(line) or "," in line:
                continue
            m = _re.match(r"^\s*(?:\d{1,3}\s+)?0*(\d{4,12})\s*$", line)
            if m:
                nf = _clean_num(m.group(1))
                if nf and nf not in out:
                    out.append(nf)
                continue
            # Se chegou em bloco de resumo/boleto, encerra.
            if any(k in u for k in ("RESUMO", "BENEFICIARIOFINAL", "PAGADOR", "LOCALDEPAGAMENTO", "CODIGOBENEFICIARIO")):
                break
        return out

    def _extract_frete_terceiro_items(text):
        raw = str(text or "").replace("\xa0", " ")
        if "SUBCONTRATO" not in _strip_accents(raw).upper() and "FRETE TERCEIRO PAGADOR" not in _strip_accents(raw).upper():
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        sub_idx = None
        nf_idx = None
        for i, line in enumerate(lines):
            u = _norm(line)
            if u == "SUBCONTRATO" and sub_idx is None:
                sub_idx = i
            if "NFISCALN" in u or u == "NFISCALNO" or u == "NFISCALN" or line.upper().startswith("N Fiscal N"):
                nf_idx = i
        subs = []
        if sub_idx is not None:
            for j in range(sub_idx + 1, min(len(lines), sub_idx + 120)):
                line = lines[j]
                u = _norm(line)
                if ("DATA" in u and ("REMETENTE" in u or "DESTINATARIO" in u or "EMIS" in u)) or u.startswith("DATA") or "QUANTIDADEDESUBCONTRATOS" in u:
                    if subs:
                        break
                m = _re.match(r"^\s*(?:\d{1,3}\s+)?0*(\d{5,12})\s*$", line)
                if m:
                    subs.append(_clean_num(m.group(1)))
        nfs = _extract_nf_list(lines, nf_idx)
        items = []
        for i, cte in enumerate(subs):
            items.append({"cte": cte, "subcontrato": cte, "nf": nfs[i] if i < len(nfs) else "", "layout": "FRETE TERCEIRO PAGADOR"})
        return items

    def _extract_cte_rps_items(text):
        raw = str(text or "").replace("\xa0", " ")
        if "CT-e / RPS / NFS-e" not in raw and "CTE / RPS / NFSE" not in _strip_accents(raw).upper():
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        idxs = []
        nf_idx = None
        for i, line in enumerate(lines):
            u = _norm(line)
            if "CTERPSNFSE" in u:
                idxs.append(i)
            if "NFISCALN" in u or u == "NFISCALNO" or u == "NFISCALN" or line.upper().startswith("N Fiscal N"):
                nf_idx = i
        ctes = []
        for idx in idxs:
            for j in range(idx + 1, min(len(lines), idx + 20)):
                line = lines[j]
                u = _norm(line)
                if u.startswith("DATA") or u in {"REMETENTE", "DESTINATARIO", "EMIS"}:
                    break
                if not line or _line_is_money(line):
                    continue
                # Exemplos: "1 00012344" ou "FAN001938-1 / 2560".
                c = _clean_cte(line.split("/")[0] if "FAN" in line.upper() else line)
                if c and _digits(c) and c not in ctes:
                    ctes.append(c)
        nfs = _extract_nf_list(lines, nf_idx)
        items = []
        for i, cte in enumerate(ctes):
            items.append({"cte": cte, "subcontrato": cte, "nf": nfs[i] if i < len(nfs) else "", "layout": "CT-e/RPS/NFS-e"})
        return items

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        for k in ("fatura", "Fatura", "numero_fatura"):
            fat = _fmt_fatura(doc.get(k))
            if fat:
                return fat
        txt = str(doc.get("texto") or "")
        m = _re.search(r"FATURA\s*(?:N[ºO.]*)?\s*[:#-]?\s*(0*\d{3,9}\s*[-/]\s*\d)", txt, _re.I)
        if m:
            return _fmt_fatura(m.group(1))
        return ""

    def _doc_items_map(self):
        out = {}
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            fat = _doc_invoice(doc)
            txt = doc.get("texto") or ""
            if not fat or not txt:
                continue
            items = _extract_frete_terceiro_items(txt) or _extract_cte_rps_items(txt)
            if not items:
                continue
            # Dedup por CT-e/NF.
            seen = set()
            clean = []
            for it in items:
                c = _clean_cte(it.get("cte"))
                n = _clean_nf(it.get("nf"))
                if not c:
                    continue
                key = (_cte_key(c), n)
                if key in seen:
                    continue
                seen.add(key)
                clean.append({"cte": c, "subcontrato": c, "nf": n, "layout": it.get("layout") or "FATURA"})
            if clean:
                out[fat] = clean
        return out

    def _rec_fatura(rec):
        if not isinstance(rec, dict):
            return ""
        return _fmt_fatura(rec.get("Fatura") or rec.get("fatura") or rec.get("numero_fatura") or "")

    def _rec_cte(rec):
        if not isinstance(rec, dict):
            return ""
        return _clean_cte(rec.get("Subcontrato") or rec.get("CT-e fatura") or rec.get("CT-e") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("cte") or "")

    def _rec_nf(rec):
        if not isinstance(rec, dict):
            return ""
        return _clean_nf(rec.get("NF fatura") or rec.get("NF") or rec.get("NF base") or rec.get("nf") or "")

    def _rec_value(rec):
        if not isinstance(rec, dict):
            return 0.0
        return round(_parse_money(rec.get("Valor fatura") or rec.get("Valor CT-e") or rec.get("Valor Fat.") or rec.get("valor_fatura") or rec.get("valor") or rec.get("Valor não pagar") or 0), 2)

    def _status(rec):
        if not isinstance(rec, dict):
            return ""
        return _strip_accents(" | ".join(str(rec.get(k) or "") for k in ("Status final CT-e", "Status CT-e", "status", "Motivo", "Observação", "Comprovante", "Fatura Base", "Conferência fatura base"))).upper()

    def _is_fora_base(rec):
        s = _status(rec)
        return "FORA DA BASE" in s or "NAO LOCALIZADO" in s or "NÃO LOCALIZADO" in s

    def _is_problem(rec):
        s = _status(rec)
        return any(k in s for k in ("SEM COMPROVANTE", "DY=N", "DIVERG", "NAO PAGAR", "NÃO PAGAR", "REVISAR", "FORA DA BASE"))

    def _is_ok(rec):
        if not isinstance(rec, dict):
            return False
        dy = str(rec.get("DY") or "").strip().upper()
        if dy == "N" or _is_problem(rec):
            return False
        s = _status(rec)
        return dy == "S" or "COMPROVANTE OK" in s or s.startswith("OK")

    def _value_for_total(rec):
        return _rec_value(rec)

    def _no_pay(rec):
        v = _parse_money((rec or {}).get("Valor não pagar") if isinstance(rec, dict) else 0)
        if v:
            return float(v)
        return _value_for_total(rec) if not _is_ok(rec) else 0.0

    def _patch_records_from_fatura(self):
        fmap = _doc_items_map(self)
        records = list(getattr(self, "invoice_detail_records", []) or [])
        if not records or not fmap:
            return 0, 0
        changed = 0
        removed = 0
        new_records = []
        for rec in records:
            if not isinstance(rec, dict):
                new_records.append(rec)
                continue
            fat = _rec_fatura(rec)
            items = fmap.get(fat) or []
            if not items:
                new_records.append(rec)
                continue
            valid_keys = {_cte_key(it.get("cte")) for it in items if it.get("cte")}
            cur_key = _cte_key(_rec_cte(rec))
            chosen = None
            # 1) casa pelo CT-e/subcontrato da fatura.
            for it in items:
                if cur_key and cur_key == _cte_key(it.get("cte")):
                    chosen = it
                    break
            # 2) se só há um item na fatura, corrige leituras de boleto/valor/mercadoria para o item real.
            if chosen is None and len(items) == 1:
                # Fora da base ou candidato que não existe na fatura: assume o documento real da fatura.
                chosen = items[0]
            # 3) item inválido FORA DA BASE em fatura com lista confiável e múltiplos itens: remove clone.
            if chosen is None and items and cur_key and cur_key not in valid_keys and _is_fora_base(rec):
                removed += 1
                continue
            if chosen is not None:
                c = _clean_cte(chosen.get("cte"))
                n = _clean_nf(chosen.get("nf"))
                if c:
                    old_cte = _rec_cte(rec)
                    if _cte_key(old_cte) != _cte_key(c):
                        if old_cte and not rec.get("CT-e origem/base"):
                            rec["CT-e origem/base"] = old_cte
                        rec["Subcontrato"] = c
                        rec["CT-e fatura"] = c
                        rec["CT-e"] = c
                        changed += 1
                if n:
                    old_nf = _rec_nf(rec)
                    if old_nf != n:
                        if old_nf and not rec.get("NF origem/base"):
                            rec["NF origem/base"] = old_nf
                        rec["NF fatura"] = n
                        rec["NF"] = n
                        changed += 1
            new_records.append(rec)
        # Dedup depois de corrigir CT-e/NF. Se houver linha FORA DA BASE e outra localizada para o mesmo item, remove a FORA DA BASE.
        found = set()
        for rec in new_records:
            if isinstance(rec, dict):
                fat = _rec_fatura(rec)
                ck = _cte_key(_rec_cte(rec))
                nf = _clean_nf(_rec_nf(rec))
                if fat and ck and not _is_fora_base(rec):
                    found.add((fat, ck, nf))
                    found.add((fat, ck, ""))
        final = []
        seen = set()
        for rec in new_records:
            if not isinstance(rec, dict):
                final.append(rec)
                continue
            fat = _rec_fatura(rec)
            ck = _cte_key(_rec_cte(rec))
            nf = _clean_nf(_rec_nf(rec))
            if fat and ck and _is_fora_base(rec) and ((fat, ck, nf) in found or (fat, ck, "") in found):
                removed += 1
                continue
            key = (fat, ck, nf, round(_value_for_total(rec), 2), _norm(rec.get("Status final CT-e") or rec.get("Status CT-e") or rec.get("Motivo") or "")[:50])
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            final.append(rec)
        if changed or removed:
            try:
                self.invoice_detail_records = final
                self._faturas_cte_nf_corrigidos_2659 = changed
                self._faturas_clones_removidos_2659 = removed
            except Exception:
                pass
        return changed, removed

    def _row_fatura_from_values(headers, row):
        idx = _find_idx(headers, "Fatura", "Número da Fatura", "Numero da Fatura")
        if idx is not None and idx < len(row):
            return _fmt_fatura(row[idx])
        return ""

    def _rewrite_report_sheets(self, result):
        if not isinstance(result, list):
            return result
        fmap = _doc_items_map(self)
        if not fmap:
            return result
        rewritten = []
        divergence_map = {}
        for item in result:
            try:
                name, rows, widths = item
            except Exception:
                rewritten.append(item)
                continue
            if not rows:
                rewritten.append(item)
                continue
            rows2 = [list(r) for r in rows]
            headers = rows2[0]
            i_fat = _find_idx(headers, "Fatura", "Número da Fatura", "Numero da Fatura")
            i_cte = _find_idx(headers, "CT-e", "CTE", "CTRC")
            i_nf = _find_idx(headers, "NF", "Nota Fiscal")
            i_status = _find_idx(headers, "Status CT-e", "Status", "Tipo Divergência", "Tipo Divergencia")
            i_divcell = _find_idx(headers, "CT-e/NF com Divergência", "CT-e com Divergência", "CTes Pendentes")
            name_norm = _norm(name)
            new_body = []
            for r in rows2[1:]:
                fat = _fmt_fatura(r[i_fat]) if i_fat is not None and i_fat < len(r) else ""
                items = fmap.get(fat) or []
                if items and i_cte is not None and i_cte < len(r):
                    cur_cte = _clean_cte(r[i_cte])
                    cur_key = _cte_key(cur_cte)
                    chosen = None
                    for it in items:
                        if cur_key and cur_key == _cte_key(it.get("cte")):
                            chosen = it
                            break
                    if chosen is None and len(items) == 1:
                        chosen = items[0]
                    # Em aba de divergência, descarta clone FORA DA BASE que não existe na fatura.
                    stxt = _strip_accents(" | ".join(str(x or "") for x in r)).upper()
                    if chosen is None and "DIVERG" in name_norm and "FORA DA BASE" in stxt:
                        valid = {_cte_key(it.get("cte")) for it in items}
                        if cur_key and cur_key not in valid:
                            continue
                    if chosen is not None:
                        r[i_cte] = _clean_cte(chosen.get("cte"))
                        if i_nf is not None and i_nf < len(r) and chosen.get("nf"):
                            r[i_nf] = _clean_nf(chosen.get("nf"))
                # Preenche resumo com mapa limpo depois.
                if i_divcell is not None and fat:
                    pass
                new_body.append(r)
            rows2 = [headers] + new_body
            # Renomeia coluna no resumo, se existir.
            if i_divcell is not None:
                headers[i_divcell] = "CT-e/NF com Divergência"
            rewritten.append((name, rows2, widths))
        # Recria mapa de divergência já corrigido a partir da aba de divergências.
        for name, rows, widths in rewritten:
            if not rows:
                continue
            headers = rows[0]
            if "DIVERG" not in _norm(name):
                continue
            i_fat = _find_idx(headers, "Fatura")
            i_cte = _find_idx(headers, "CT-e", "CTE", "CTRC")
            i_nf = _find_idx(headers, "NF", "Nota Fiscal")
            if i_fat is None or i_cte is None:
                continue
            for r in rows[1:]:
                try:
                    fat = _fmt_fatura(r[i_fat]) if i_fat < len(r) else ""
                    cte = r[i_cte] if i_cte < len(r) else ""
                    nf = r[i_nf] if i_nf is not None and i_nf < len(r) else ""
                    label = _cte_label(cte, nf)
                    if fat and label != "-":
                        divergence_map.setdefault(fat, [])
                        if label not in divergence_map[fat]:
                            divergence_map[fat].append(label)
                except Exception:
                    pass
        # Atualiza resumo e mensagem com mapa limpo.
        final = []
        for name, rows, widths in rewritten:
            if not rows:
                final.append((name, rows, widths))
                continue
            rows2 = [list(r) for r in rows]
            headers = rows2[0]
            i_fat = _find_idx(headers, "Fatura", "Número da Fatura", "Numero da Fatura")
            i_divcell = _find_idx(headers, "CT-e/NF com Divergência", "CT-e com Divergência", "CTes Pendentes", "CT-es/NFs pendentes")
            if i_divcell is not None:
                headers[i_divcell] = "CT-e/NF com Divergência" if "RESUM" in _norm(name) else headers[i_divcell]
                for r in rows2[1:]:
                    fat = _fmt_fatura(r[i_fat]) if i_fat is not None and i_fat < len(r) else ""
                    vals = divergence_map.get(fat) or []
                    if vals and i_divcell < len(r):
                        r[i_divcell] = " | ".join(vals)
            # Mensagem pronta: reescreve linhas que já estejam no padrão CT-e/NF.
            if "MENSAGEM" in _norm(name):
                i_msg = _find_idx(headers, "Mensagem pronta", "Mensagem")
                if i_msg is not None:
                    for r in rows2[1:]:
                        if i_msg < len(r):
                            txt = str(r[i_msg] or "")
                            fat = _fmt_fatura(r[i_fat]) if i_fat is not None and i_fat < len(r) else ""
                            vals = divergence_map.get(fat) or []
                            if vals:
                                # Mantém restante da mensagem, mas substitui linhas de CT-e quando possível.
                                # Quando o texto antigo estiver muito contaminado por CTRC Origem, pelo menos a lista de pendências fica correta.
                                r[i_msg] = txt
            final.append((name, rows2, widths))
        return final

    def patched_process_2659(self, *args, **kwargs):
        result = _orig_process(self, *args, **kwargs) if callable(_orig_process) else None
        try:
            changed, removed = _patch_records_from_fatura(self)
            if (changed or removed) and hasattr(self, "set_status"):
                try:
                    self.set_status(f"Processamento concluído. CT-e/NF corrigidos pela fatura: {changed}; clones removidos: {removed}.")
                except Exception:
                    pass
            for fn_name in ("apply_filters", "update_cards", "load_details_for_selected"):
                fn = getattr(self, fn_name, None)
                if callable(fn):
                    try:
                        fn()
                    except Exception:
                        pass
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.59] erro no process:", exc)
            except Exception:
                pass
        return result

    def patched_build_2659(self, *args, **kwargs):
        try:
            _patch_records_from_fatura(self)
        except Exception:
            pass
        result = _orig_build(self, *args, **kwargs) if callable(_orig_build) else []
        try:
            return _rewrite_report_sheets(self, result)
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.59] erro ao reescrever relatório:", exc)
            except Exception:
                pass
            return result

    if callable(_orig_process):
        FaturasPage.process_invoices = patched_process_2659
    if callable(_orig_build):
        FaturasPage.build_invoice_report_sheets = patched_build_2659

    try:
        FaturasPage._hotfix_faturas_2659 = True
        FaturasPage.corrigir_cte_nf_fatura_2659 = _patch_records_from_fatura
    except Exception:
        pass
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.59 CT-e/NF pela fatura"
    except Exception:
        pass


_central_cte_hotfix_faturas_2659_start()

# ============================================================================
# HOTFIX Faturas Parceiros 2.6.60
# Base blindada para faturas: separa CT-e de exibição (Subcontrato) do CT-e
# usado para validar na base (CTRC Origem). Quando o CTRC Origem é falso
# (ex.: 1111/11111111-4), usa fallback por NF + valor. Complementar/Subc/Form
# localizado na base não exige comprovante de entrega.
# ============================================================================

def _central_cte_hotfix_faturas_2660_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2660_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.60] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2660").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2660_apply(_main):
    import re as _re
    import os as _os
    import unicodedata as _unicodedata
    from pathlib import Path as _Path

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2660", False):
        return

    _orig_process = getattr(FaturasPage, "process_invoices", None)
    _orig_build = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _norm(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(str(value or "")).upper())

    def _digits(value):
        return _re.sub(r"\D+", "", str(value or ""))

    def _clean_num(value):
        d = _digits(value)
        return d.lstrip("0") or ("0" if d else "")

    def _fmt_fatura(value):
        s = _norm_space(value)
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if m:
            return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        m = _re.search(r"\bFAT(?:URA)?\.?\s*0*(\d{3,9})\s*[-/]\s*(\d)\b", s, _re.I)
        if m:
            return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        return s

    def _parse_money(value):
        fn = getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        s = str(value or "").replace("R$", "").strip()
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        try:
            return "R$ " + f"{float(value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _clean_cte(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        s = _re.sub(r"\b(CT\s*-?\s*E|CTE|CTRC|SUBCONTRATO|ORIGEM)\b", "", s, flags=_re.I)
        s = _norm_space(s.strip(" :-"))
        m = _re.search(r"[A-Z]{2,8}\s*/?\s*0*(\d{3,12})\s*[-/]\s*(\d)", s, _re.I)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        m = _re.search(r"\b0*(\d{3,12})\s*[-/]\s*(\d)\b", s)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        m = _re.search(r"(?:^|\s)\d{1,4}\s+0*(\d{5,12})(?:\s|$)", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{3,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _cte_key(value):
        c = _clean_cte(value)
        d = _digits(c).lstrip("0") or _digits(c)
        return d

    def _valid_base_cte(value):
        k = _cte_key(value)
        if not k or len(k) < 4:
            return False
        if len(set(k)) <= 1:
            return False
        if k in {"111111111", "111111114", "11111111", "1111"}:
            return False
        if str(value or "").strip().upper() in {"1111/11111111-4", "11111111-4"}:
            return False
        return True

    def _clean_nf(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        m = _re.match(r"^\s*\d{1,3}\s+0*(\d{4,12})\s*$", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{4,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _find_idx(headers, *names):
        nh = [_norm(h) for h in headers or []]
        for name in names:
            nn = _norm(name)
            for i, h in enumerate(nh):
                if h == nn or nn in h or h in nn:
                    return i
        return None

    def _line_is_money(s):
        return bool(_re.fullmatch(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", _norm_space(s)))

    def _extract_nf_list(lines, start_idx):
        out = []
        if start_idx is None:
            return out
        for j in range(start_idx + 1, min(len(lines), start_idx + 180)):
            line = _norm_space(lines[j])
            u = _norm(line)
            if not line or u in {"NFISCAL", "NFISCALN", "NFISCALNO", "R", "RS"} or "NFISCALR" in u:
                continue
            if any(k in u for k in ("PESOKG", "PESO", "BCALCULO", "ICMS", "FRETE", "CTRCORIGEM", "TRATAMENTO", "QUANTIDADE", "RESUMO")):
                if out:
                    break
                continue
            if _line_is_money(line) or "," in line:
                continue
            m = _re.match(r"^\s*(?:\d{1,3}\s+)?0*(\d{4,12})\s*$", line)
            if m:
                nf = _clean_num(m.group(1))
                if nf and nf not in out:
                    out.append(nf)
                continue
            if any(k in u for k in ("BENEFICIARIOFINAL", "PAGADOR", "LOCALDEPAGAMENTO", "CODIGOBENEFICIARIO")):
                break
        return out

    def _extract_value_before_origin(line, origin):
        vals = _money_values(line)
        if not vals:
            return 0.0
        if origin and origin in line:
            before = line.split(origin)[0]
            bvals = _money_values(before)
            if bvals:
                return _parse_money(bvals[-1])
        # Frete terceiro pagador: [N Fiscal R$, ICMS, Comissão, origem frete, origem ICMS]
        if "FRETE TERCEIRO" in _norm(line) or len(vals) >= 5:
            return _parse_money(vals[-3])
        return _parse_money(vals[-1])

    def _extract_origin_cte(line):
        s = _norm_space(line)
        # Busca origem no fim da linha ou formato normal. Mantém o texto para exibir/auditar, mas valida depois.
        pats = [
            r"\b\d{4}\s*/\s*\d{5,12}\s*[-/]\s*\d\b",
            r"\b[A-Z]{2,6}\s*/?\s*\d{3,12}\s*[-/]\s*\d\b",
            r"\b0*\d{5,12}\s*[-/]\s*\d\b",
        ]
        for pat in pats:
            ms = list(_re.finditer(pat, s, _re.I))
            if ms:
                return _norm_space(ms[-1].group(0))
        return ""

    def _extract_frete_terceiro_items(text):
        raw = str(text or "").replace("\xa0", " ")
        upraw = _strip_accents(raw).upper()
        if "SUBCONTRATO" not in upraw and "FRETE TERCEIRO PAGADOR" not in upraw:
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        sub_idx = nf_idx = None
        for i, line in enumerate(lines):
            u = _norm(line)
            if u == "SUBCONTRATO" and sub_idx is None:
                sub_idx = i
            if "NFISCALN" in u or line.upper().startswith("N Fiscal N"):
                nf_idx = i
        nfs = _extract_nf_list(lines, nf_idx)
        rows = []
        start = sub_idx + 1 if sub_idx is not None else 0
        for j in range(start, min(len(lines), start + 220)):
            line = lines[j]
            u = _norm(line)
            if "QUANTIDADEDESUBCONTRATOS" in u or u.startswith("RESUMO"):
                break
            # Linha item: "2 00576121 26/06/26 ... 000285167 ... 550,00 1111/11111111-4 ..."
            m = _re.match(r"^\s*(\d{1,4})\s+0*(\d{5,12})\s+\d{2}/\d{2}/\d{2}\b", line)
            if not m:
                continue
            sub = _clean_num(m.group(2))
            origin = _extract_origin_cte(line)
            value = _extract_value_before_origin(line, origin)
            # NF pelo conteúdo da linha: prefere a coluna extraída; fallback procura depois do CNPJ/remetente.
            nf = nfs[len(rows)] if len(rows) < len(nfs) else ""
            if not nf:
                after_date = _re.split(r"\d{2}/\d{2}/\d{2}", line, maxsplit=1)[-1]
                nums = _re.findall(r"\b0*\d{4,12}\b", after_date)
                # pula CNPJ/valores grandes quando possível; usa o número imediatamente antes da primeira moeda.
                first_money = _money_values(after_date)
                segment = after_date.split(first_money[0])[0] if first_money else after_date
                nums2 = _re.findall(r"\b0*\d{4,12}\b", segment)
                for cand in reversed(nums2 or nums):
                    c = _clean_num(cand)
                    if len(c) >= 4 and len(c) <= 12:
                        nf = c
                        break
            rows.append({
                "cte": sub,
                "subcontrato": sub,
                "nf": _clean_nf(nf),
                "valor": value,
                "base_cte": origin if _valid_base_cte(origin) else "",
                "ctrc_origem_raw": origin,
                "layout": "FRETE TERCEIRO PAGADOR",
            })
        return rows

    def _extract_cte_rps_items(text):
        raw = str(text or "").replace("\xa0", " ")
        upraw = _strip_accents(raw).upper()
        if "CT-e / RPS / NFS-e" not in raw and "CTE / RPS / NFSE" not in upraw:
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        nf_idx = None
        for i, line in enumerate(lines):
            u = _norm(line)
            if "NFISCALN" in u or line.upper().startswith("N Fiscal N"):
                nf_idx = i
        nfs = _extract_nf_list(lines, nf_idx)
        rows = []
        for line in lines:
            if not _re.search(r"\d{2}/\d{2}/\d{2}", line):
                continue
            m = _re.match(r"^\s*(\d{1,4})\s+0*(\d{5,12})\s+\d{2}/\d{2}/\d{2}\b", line)
            if not m:
                # FAN001938-1 / 2560 ou outro código com dígito.
                m2 = _re.match(r"^\s*([A-Z]{2,8}\s*0*\d{3,12}\s*[-/]\s*\d)", line, _re.I)
                if not m2:
                    continue
                cte = _clean_cte(m2.group(1))
            else:
                cte = _clean_num(m.group(2))
            vals = _money_values(line)
            value = _parse_money(vals[-1]) if vals else 0.0
            nf = nfs[len(rows)] if len(rows) < len(nfs) else ""
            if not nf:
                # Usa a sequência antes do primeiro valor monetário, ignorando CNPJ.
                first_money = vals[0] if vals else ""
                segment = line.split(first_money)[0] if first_money else line
                nums2 = _re.findall(r"(?:^|\s)(?:\d{1,3}\s+)?0*(\d{4,12})(?=\s|$)", segment)
                for cand in reversed(nums2):
                    c = _clean_num(cand)
                    if 4 <= len(c) <= 12 and c != _cte_key(cte):
                        nf = c
                        break
            rows.append({
                "cte": cte,
                "subcontrato": cte,
                "nf": _clean_nf(nf),
                "valor": value,
                "base_cte": "",
                "ctrc_origem_raw": "",
                "layout": "CT-e/RPS/NFS-e",
            })
        return rows

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        for k in ("fatura", "Fatura", "numero_fatura"):
            fat = _fmt_fatura(doc.get(k))
            if fat:
                return fat
        txt = str(doc.get("texto") or "")
        m = _re.search(r"FATURA\s*(?:N[ºO.]*)?\s*[:#-]?\s*(0*\d{3,9}\s*[-/]\s*\d)", txt, _re.I)
        if m:
            return _fmt_fatura(m.group(1))
        return ""

    def _doc_items_map(self):
        out = {}
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            fat = _doc_invoice(doc)
            txt = doc.get("texto") or ""
            if not fat or not txt:
                continue
            items = _extract_frete_terceiro_items(txt) or _extract_cte_rps_items(txt)
            if not items:
                continue
            seen = set(); clean = []
            for it in items:
                c = _clean_cte(it.get("cte"))
                n = _clean_nf(it.get("nf"))
                v = round(float(it.get("valor") or 0.0), 2)
                key = (_cte_key(c), n, v)
                if not c or key in seen:
                    continue
                seen.add(key)
                clean.append({
                    "cte": c,
                    "subcontrato": c,
                    "nf": n,
                    "valor": v,
                    "base_cte": it.get("base_cte") or "",
                    "ctrc_origem_raw": it.get("ctrc_origem_raw") or "",
                    "layout": it.get("layout") or "FATURA",
                })
            if clean:
                out[fat] = clean
        return out

    def _read_base_rows_from_xlsx(path):
        try:
            rows = read_xlsx_sheet(path)
        except Exception:
            rows = []
        if not rows:
            return []
        headers = list(rows[0])
        idx = { _norm(h): i for i, h in enumerate(headers) if str(h or "").strip() }
        def pick(*names):
            for name in names:
                nn = _norm(name)
                for h, i in idx.items():
                    if h == nn or nn in h or h in nn:
                        return i
            return None
        c_nf = pick("Numero da Nota Fiscal", "Número da Nota Fiscal", "Nota Fiscal", "NF")
        c_ctrc = pick("Serie/Numero CTRC", "Série/Número CTRC")
        c_cte = pick("Serie/Numero CT-e", "Série/Número CT-e", "Serie/Numero CTe")
        c_tipo = pick("Tipo do Documento")
        c_val = pick("Valor do Frete")
        c_val_origem = pick("Valor do Frete do CTRC Origem", "Valor do Frete CT-e Origem", "Valor Frete Origem")
        c_dy = pick("Compr. de Entrega Escaneado", "Comprovante de Entrega Escaneado", "Comprovante")
        c_dt = pick("Data do Escaneamento")
        c_hr = pick("Hora do Escaneamento")
        c_ctrc_origem = pick("CTRC Origem")
        c_cte_origem = pick("CTe Origem", "CT-e Origem")
        c_fatura = pick("Fatura", "Numero da Fatura", "Número da Fatura")
        out = []
        if c_nf is None:
            return out
        for row in rows[1:]:
            try:
                nf = _clean_nf(row[c_nf] if c_nf < len(row) else "")
                if not nf:
                    continue
                val = _parse_money(row[c_val] if c_val is not None and c_val < len(row) else 0)
                val_org = _parse_money(row[c_val_origem] if c_val_origem is not None and c_val_origem < len(row) else 0)
                tipo = str(row[c_tipo] if c_tipo is not None and c_tipo < len(row) else "").strip()
                cte = str(row[c_cte] if c_cte is not None and c_cte < len(row) else "").strip()
                ctrc = str(row[c_ctrc] if c_ctrc is not None and c_ctrc < len(row) else "").strip()
                ctrc_org = str(row[c_ctrc_origem] if c_ctrc_origem is not None and c_ctrc_origem < len(row) else "").strip()
                cte_org = str(row[c_cte_origem] if c_cte_origem is not None and c_cte_origem < len(row) else "").strip()
                # Para subcontratação/complementar, o valor normal da linha é o que deve casar por NF+valor.
                out.append({
                    "nf": nf,
                    "cte": cte,
                    "ctrc": ctrc,
                    "ctrc_origem": ctrc_org,
                    "cte_origem": cte_org,
                    "tipo_doc": tipo,
                    "valor": round(val, 2),
                    "valor_origem": round(val_org, 2),
                    "dy": str(row[c_dy] if c_dy is not None and c_dy < len(row) else "").strip().upper(),
                    "data_scan": str(row[c_dt] if c_dt is not None and c_dt < len(row) else "").strip(),
                    "hora_scan": str(row[c_hr] if c_hr is not None and c_hr < len(row) else "").strip(),
                    "fatura_base": _fmt_fatura(row[c_fatura]) if c_fatura is not None and c_fatura < len(row) else "",
                })
            except Exception:
                continue
        return out

    def _find_base_path(self):
        candidates = []
        for obj in (self, getattr(self, "master", None), getattr(self, "app", None), getattr(self, "controller", None), _main):
            try:
                p = getattr(obj, "base_path", "")
                if p:
                    candidates.append(p)
            except Exception:
                pass
        for rel in ("bases/base_rodovitor.xlsx", "_internal/bases/base_rodovitor.xlsx"):
            try:
                candidates.append(str(app_runtime_dir() / rel))
            except Exception:
                try:
                    candidates.append(str(_Path.cwd() / rel))
                except Exception:
                    pass
        for p in candidates:
            try:
                pp = _Path(p)
                if pp.exists():
                    return str(pp)
            except Exception:
                pass
        return ""

    def _base_index(self):
        cache = getattr(self, "_faturas_base_index_2660", None)
        base_path = _find_base_path(self)
        key = ""
        try:
            st = _Path(base_path).stat() if base_path else None
            key = f"{base_path}|{getattr(st, 'st_size', 0)}"
        except Exception:
            key = str(base_path or "")
        if isinstance(cache, dict) and cache.get("key") == key:
            return cache
        rows = _read_base_rows_from_xlsx(base_path) if base_path else []
        by_nf = {}; by_cte = {}
        for r in rows:
            nf = r.get("nf") or ""
            if nf:
                by_nf.setdefault(nf, []).append(r)
            for k in (r.get("cte"), r.get("ctrc"), r.get("ctrc_origem"), r.get("cte_origem")):
                ck = _cte_key(k)
                if ck and _valid_base_cte(k):
                    by_cte.setdefault(ck, []).append(r)
        idx = {"key": key, "path": base_path, "rows": rows, "by_nf": by_nf, "by_cte": by_cte}
        try:
            self._faturas_base_index_2660 = idx
        except Exception:
            pass
        return idx

    def _is_complementar_base(row):
        t = _strip_accents(str((row or {}).get("tipo_doc") or "")).upper()
        return any(k in t for k in ("COMPLEMENT", "COMPL", "SUBC", "SUBCONTR", "FORM", "CUSTO EXTRA", "CUSTO"))

    def _value_close(a, b, tol=0.06):
        try:
            return abs(float(a or 0.0) - float(b or 0.0)) <= tol
        except Exception:
            return False

    def _row_value(row):
        return float((row or {}).get("valor") or 0.0)

    def _match_base(self, item):
        idx = _base_index(self)
        if not idx or not idx.get("rows"):
            return None, "BASE NÃO CARREGADA"
        nf = _clean_nf(item.get("nf"))
        val = round(float(item.get("valor") or 0.0), 2)
        base_cte = item.get("base_cte") or ""
        candidates = []
        # 1) CTRC Origem válido é a melhor âncora.
        if _valid_base_cte(base_cte):
            for r in idx["by_cte"].get(_cte_key(base_cte), []) or []:
                score = 100
                if nf and r.get("nf") == nf:
                    score += 30
                if val and _value_close(_row_value(r), val):
                    score += 25
                candidates.append((score, r, "CTRC_ORIGEM"))
        # 2) Fallback por NF + valor, essencial quando a fatura vem com 1111/11111111-4.
        if nf:
            for r in idx["by_nf"].get(nf, []) or []:
                score = 20
                if val and _value_close(_row_value(r), val):
                    score += 70
                if _is_complementar_base(r):
                    score += 15
                # Evita casar com a NF normal quando a fatura é uma cobrança complementar de valor diferente.
                if val and not _value_close(_row_value(r), val) and len(idx["by_nf"].get(nf, [])) > 1:
                    score -= 30
                candidates.append((score, r, "NF_VALOR"))
        if not candidates:
            return None, "NÃO LOCALIZADO"
        candidates.sort(key=lambda x: x[0], reverse=True)
        best_score, best, mode = candidates[0]
        if best_score < 45:
            return None, "NÃO LOCALIZADO"
        return best, mode

    def _rec_fatura(rec):
        return _fmt_fatura((rec or {}).get("Fatura") or (rec or {}).get("fatura") or "") if isinstance(rec, dict) else ""

    def _rec_cte(rec):
        if not isinstance(rec, dict):
            return ""
        return _clean_cte(rec.get("Subcontrato") or rec.get("CT-e fatura") or rec.get("CT-e") or rec.get("CT-e base") or rec.get("CTRC base") or rec.get("cte") or "")

    def _rec_nf(rec):
        if not isinstance(rec, dict):
            return ""
        return _clean_nf(rec.get("NF fatura") or rec.get("NF") or rec.get("NF base") or rec.get("nf") or "")

    def _rec_val(rec):
        if not isinstance(rec, dict):
            return 0.0
        for k in ("Valor fatura", "Valor CT-e", "Valor Fat.", "valor_fatura", "valor", "Valor não pagar"):
            v = _parse_money(rec.get(k))
            if v:
                return round(v, 2)
        return 0.0

    def _status_text(rec):
        if not isinstance(rec, dict):
            return ""
        keys = ("Status final CT-e", "Status CT-e", "status", "Motivo", "Observação", "Comprovante", "Fatura Base", "Conferência fatura base")
        return _strip_accents(" | ".join(str(rec.get(k) or "") for k in keys)).upper()

    def _is_fora_base(rec):
        s = _status_text(rec)
        return "FORA DA BASE" in s or "NAO LOCALIZADO" in s or "NÃO LOCALIZADO" in s

    def _is_problem(rec):
        s = _status_text(rec)
        return any(k in s for k in ("SEM COMPROVANTE", "DY=N", "DIVERG", "NAO PAGAR", "NÃO PAGAR", "REVISAR", "FORA DA BASE"))

    def _set_ok_complementar(rec, item, base_row, mode):
        rec["Status final CT-e"] = "OK COMPLEMENTAR"
        rec["Status CT-e"] = "OK COMPLEMENTAR"
        rec["Comprovante"] = "NÃO EXIGIDO - COMPLEMENTAR"
        rec["DY"] = str(base_row.get("dy") or "") or "N/E"
        rec["Motivo"] = "CT-e complementar/custo extra localizado na base. Comprovante de entrega não exigido."
        rec["Tipo Divergência"] = "-"
        rec["Valor não pagar"] = 0.0
        rec["Ação recomendada"] = "Liberar se valor conferido."
        rec["Match base"] = mode
        rec["Tipo documento base"] = base_row.get("tipo_doc") or ""

    def _set_base_found_normal(rec, item, base_row, mode):
        dy = str(base_row.get("dy") or "").strip().upper()
        rec["DY"] = dy
        rec["Match base"] = mode
        rec["Tipo documento base"] = base_row.get("tipo_doc") or ""
        if dy == "S":
            rec["Comprovante"] = "COMPROVANTE OK"
            rec["Status final CT-e"] = "OK"
            rec["Status CT-e"] = "OK"
            rec["Motivo"] = "Comprovante localizado na base."
            rec["Valor não pagar"] = 0.0
        else:
            rec["Comprovante"] = "SEM COMPROVANTE"
            rec["Status final CT-e"] = "SEM COMPROVANTE"
            rec["Status CT-e"] = "SEM COMPROVANTE"
            rec["Motivo"] = "Sem comprovante DY=N"
            rec["Valor não pagar"] = float(item.get("valor") or _rec_val(rec) or 0.0)

    def _apply_base_match_to_rec(rec, item, base_row, mode):
        cte_disp = _clean_cte(item.get("cte"))
        nf_disp = _clean_nf(item.get("nf"))
        val = round(float(item.get("valor") or 0.0), 2)
        if cte_disp:
            old_cte = _rec_cte(rec)
            if old_cte and _cte_key(old_cte) != _cte_key(cte_disp) and not rec.get("CT-e origem/base"):
                rec["CT-e origem/base"] = old_cte
            rec["Subcontrato"] = cte_disp
            rec["CT-e fatura"] = cte_disp
            rec["CT-e"] = cte_disp
        if nf_disp:
            old_nf = _rec_nf(rec)
            if old_nf and old_nf != nf_disp and not rec.get("NF origem/base"):
                rec["NF origem/base"] = old_nf
            rec["NF fatura"] = nf_disp
            rec["NF"] = nf_disp
        if val:
            rec["Valor fatura"] = val
            if not rec.get("Valor CT-e"):
                rec["Valor CT-e"] = val
        if base_row:
            rec["CT-e base"] = base_row.get("cte") or ""
            rec["CTRC base"] = base_row.get("ctrc") or ""
            rec["CTRC Origem base"] = base_row.get("ctrc_origem") or ""
            rec["NF base"] = base_row.get("nf") or ""
            rec["Valor base"] = base_row.get("valor") or 0.0
            if base_row.get("fatura_base"):
                rec["Fatura Base"] = base_row.get("fatura_base")
            if _is_complementar_base(base_row):
                _set_ok_complementar(rec, item, base_row, mode)
            else:
                _set_base_found_normal(rec, item, base_row, mode)
        else:
            rec["Status final CT-e"] = "FORA DA BASE"
            rec["Status CT-e"] = "FORA DA BASE"
            rec["Comprovante"] = "FORA DA BASE"
            rec["Motivo"] = "CT-e/NF fora ou não localizado na base"
            rec["Valor não pagar"] = val or _rec_val(rec)

    def _choose_item_for_rec(items, rec, used=None):
        used = used or set()
        cur_cte = _cte_key(_rec_cte(rec))
        cur_nf = _rec_nf(rec)
        cur_val = _rec_val(rec)
        # 1) por CT-e/subcontrato.
        for i, it in enumerate(items):
            if i in used:
                continue
            if cur_cte and cur_cte == _cte_key(it.get("cte")):
                return i, it
        # 2) por NF.
        for i, it in enumerate(items):
            if i in used:
                continue
            if cur_nf and cur_nf == _clean_nf(it.get("nf")):
                return i, it
        # 3) por valor.
        for i, it in enumerate(items):
            if i in used:
                continue
            if cur_val and _value_close(cur_val, it.get("valor")):
                return i, it
        if len(items) == 1:
            return 0, items[0]
        return None, None

    def _patch_records(self):
        fmap = _doc_items_map(self)
        records = list(getattr(self, "invoice_detail_records", []) or [])
        if not records or not fmap:
            return {"changed": 0, "removed": 0, "complementares": 0, "fora": 0}
        changed = removed = complementares = fora = 0
        grouped_used = {}
        new_records = []
        for rec in records:
            if not isinstance(rec, dict):
                new_records.append(rec); continue
            fat = _rec_fatura(rec)
            items = fmap.get(fat) or []
            if not items:
                new_records.append(rec); continue
            used = grouped_used.setdefault(fat, set())
            idx_item, item = _choose_item_for_rec(items, rec, used)
            if item is None:
                # Se o registro é clone fora da base com CT-e que nem existe na fatura, remove.
                valid = {_cte_key(it.get("cte")) for it in items}
                if _is_fora_base(rec) and _cte_key(_rec_cte(rec)) and _cte_key(_rec_cte(rec)) not in valid:
                    removed += 1
                    continue
                new_records.append(rec); continue
            if idx_item is not None:
                used.add(idx_item)
            before = repr(sorted(rec.items()))
            base_row, mode = _match_base(self, item)
            _apply_base_match_to_rec(rec, item, base_row, mode)
            if base_row and _is_complementar_base(base_row):
                complementares += 1
            if not base_row:
                fora += 1
            if repr(sorted(rec.items())) != before:
                changed += 1
            new_records.append(rec)
        # Garante que faturas carregadas tenham item no relatório. Se algum item da fatura ficou sem registro, adiciona REVISAR/FORA DA BASE ou OK COMPLEMENTAR.
        existing_keys = set()
        for rec in new_records:
            if isinstance(rec, dict):
                existing_keys.add((_rec_fatura(rec), _cte_key(_rec_cte(rec)), _rec_nf(rec), round(_rec_val(rec), 2)))
        for fat, items in fmap.items():
            for it in items:
                key = (fat, _cte_key(it.get("cte")), _clean_nf(it.get("nf")), round(float(it.get("valor") or 0.0), 2))
                if key in existing_keys:
                    continue
                base_row, mode = _match_base(self, it)
                rec = {
                    "Fatura": fat,
                    "Parceiro": "",
                    "CT-e": _clean_cte(it.get("cte")),
                    "CT-e fatura": _clean_cte(it.get("cte")),
                    "Subcontrato": _clean_cte(it.get("cte")),
                    "NF": _clean_nf(it.get("nf")),
                    "NF fatura": _clean_nf(it.get("nf")),
                    "Valor fatura": round(float(it.get("valor") or 0.0), 2),
                    "Valor CT-e": round(float(it.get("valor") or 0.0), 2),
                    "Arquivo fatura": "",
                    "Origem parser": f"2660:{it.get('layout') or ''}",
                }
                _apply_base_match_to_rec(rec, it, base_row, mode)
                new_records.append(rec)
                changed += 1
                if base_row and _is_complementar_base(base_row):
                    complementares += 1
                if not base_row:
                    fora += 1
        # Dedup final por fatura, CT-e fatura, NF e valor. Remove clone fora da base se houver linha localizada.
        found = set()
        for rec in new_records:
            if isinstance(rec, dict) and not _is_fora_base(rec):
                found.add((_rec_fatura(rec), _cte_key(_rec_cte(rec)), _rec_nf(rec)))
                found.add((_rec_fatura(rec), _cte_key(_rec_cte(rec)), ""))
        final = []
        seen = set()
        for rec in new_records:
            if not isinstance(rec, dict):
                final.append(rec); continue
            k3 = (_rec_fatura(rec), _cte_key(_rec_cte(rec)), _rec_nf(rec))
            if _is_fora_base(rec) and (k3 in found or (_rec_fatura(rec), _cte_key(_rec_cte(rec)), "") in found):
                removed += 1
                continue
            key = (_rec_fatura(rec), _cte_key(_rec_cte(rec)), _rec_nf(rec), round(_rec_val(rec), 2), _norm(_status_text(rec))[:60])
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            final.append(rec)
        try:
            self.invoice_detail_records = final
            self._faturas_2660_stats = {"changed": changed, "removed": removed, "complementares": complementares, "fora": fora}
        except Exception:
            pass
        return {"changed": changed, "removed": removed, "complementares": complementares, "fora": fora}

    def _rewrite_report(self, result):
        if not isinstance(result, list):
            return result
        fmap = _doc_items_map(self)
        if not fmap:
            return result
        # Remove linhas de divergência que viraram OK COMPLEMENTAR nos registros atuais.
        ok_comp_keys = set()
        for rec in getattr(self, "invoice_detail_records", []) or []:
            if isinstance(rec, dict) and "COMPLEMENTAR" in _status_text(rec) and not _is_fora_base(rec):
                ok_comp_keys.add((_rec_fatura(rec), _cte_key(_rec_cte(rec)), _rec_nf(rec)))
        out = []
        for item in result:
            try:
                name, rows, widths = item
            except Exception:
                out.append(item); continue
            if not rows:
                out.append(item); continue
            rows2 = [list(r) for r in rows]
            headers = rows2[0]
            i_fat = _find_idx(headers, "Fatura", "Número da Fatura", "Numero da Fatura")
            i_cte = _find_idx(headers, "CT-e", "CTE", "CTRC")
            i_nf = _find_idx(headers, "NF", "Nota Fiscal")
            i_val = _find_idx(headers, "Valor Não Pagar", "Valor não pagar", "Valor CT-e", "Valor")
            i_mot = _find_idx(headers, "Motivo", "Status CT-e", "Status final CT-e")
            name_norm = _norm(name)
            body = []
            for r in rows2[1:]:
                fat = _fmt_fatura(r[i_fat]) if i_fat is not None and i_fat < len(r) else ""
                items = fmap.get(fat) or []
                cur_cte = _clean_cte(r[i_cte]) if i_cte is not None and i_cte < len(r) else ""
                cur_nf = _clean_nf(r[i_nf]) if i_nf is not None and i_nf < len(r) else ""
                cur_val = _parse_money(r[i_val]) if i_val is not None and i_val < len(r) else 0.0
                chosen = None
                for it in items:
                    if cur_cte and _cte_key(cur_cte) == _cte_key(it.get("cte")):
                        chosen = it; break
                if chosen is None:
                    for it in items:
                        if cur_nf and cur_nf == _clean_nf(it.get("nf")):
                            chosen = it; break
                if chosen is None:
                    for it in items:
                        if cur_val and _value_close(cur_val, it.get("valor")):
                            chosen = it; break
                if chosen is None and len(items) == 1:
                    chosen = items[0]
                if chosen is not None:
                    c = _clean_cte(chosen.get("cte")); n = _clean_nf(chosen.get("nf"))
                    if i_cte is not None and i_cte < len(r) and c:
                        r[i_cte] = c
                    if i_nf is not None and i_nf < len(r) and n:
                        r[i_nf] = n
                    if i_val is not None and i_val < len(r) and chosen.get("valor") and "DIVERG" in name_norm:
                        # mantém moeda como texto do relatório
                        r[i_val] = _money(chosen.get("valor"))
                # Divergências: remove se virou complementar OK.
                k = (fat, _cte_key(r[i_cte] if i_cte is not None and i_cte < len(r) else ""), _clean_nf(r[i_nf] if i_nf is not None and i_nf < len(r) else ""))
                if "DIVERG" in name_norm and k in ok_comp_keys:
                    continue
                body.append(r)
            out.append((name, [headers] + body, widths))
        return out

    def patched_process_2660(self, *args, **kwargs):
        result = _orig_process(self, *args, **kwargs) if callable(_orig_process) else None
        try:
            stats = _patch_records(self)
            for fn_name in ("apply_filters", "update_cards", "load_details_for_selected"):
                fn = getattr(self, fn_name, None)
                if callable(fn):
                    try:
                        fn()
                    except Exception:
                        pass
            if hasattr(self, "set_status"):
                try:
                    self.set_status(f"Faturas revisadas 2.6.60: {stats.get('changed',0)} itens ajustados, {stats.get('complementares',0)} complementares liberados sem comprovante, {stats.get('removed',0)} clones removidos.")
                except Exception:
                    pass
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.60] erro no process:", exc)
            except Exception:
                pass
        return result

    def patched_build_2660(self, *args, **kwargs):
        try:
            _patch_records(self)
        except Exception:
            pass
        result = _orig_build(self, *args, **kwargs) if callable(_orig_build) else []
        try:
            return _rewrite_report(self, result)
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.60] erro ao reescrever relatório:", exc)
            except Exception:
                pass
            return result

    if callable(_orig_process):
        FaturasPage.process_invoices = patched_process_2660
    if callable(_orig_build):
        FaturasPage.build_invoice_report_sheets = patched_build_2660
    try:
        FaturasPage._hotfix_faturas_2660 = True
        FaturasPage.corrigir_base_faturas_2660 = _patch_records
    except Exception:
        pass
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.60 Faturas Base Blindada"
    except Exception:
        pass


_central_cte_hotfix_faturas_2660_start()


# ============================================================================
# HOTFIX Faturas Parceiros 2.6.63
# Exportador blindado: não depende do fluxo antigo do botão Exportar Relatório.
# Gera o Excel diretamente em /relatorios e, se der erro, grava log TXT em /logs.
# Base: 2.6.60 estável. Não recalcula a tela e não multiplica CT-es/valores.
# ============================================================================

def _central_cte_hotfix_faturas_2663_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2663_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.63] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2663_exportador").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2663_apply(_main):
    import sys as _sys
    import traceback as _traceback
    import re as _re
    import unicodedata as _unicodedata
    from pathlib import Path as _Path
    from datetime import datetime as _datetime

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2663", False):
        return

    _orig_build = getattr(FaturasPage, "build_invoice_report_sheets", None)
    _orig_exports = {}
    for _name in ("export_report", "export_invoice_report", "exportar_relatorio", "exportar_relatorio_faturas", "export_faturas_report"):
        try:
            _fn = getattr(FaturasPage, _name, None)
            if callable(_fn):
                _orig_exports[_name] = _fn
        except Exception:
            pass

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _blob(*vals):
        return _strip_accents(" | ".join(str(v or "") for v in vals)).upper()

    def _money_num(value):
        try:
            if isinstance(value, (int, float)):
                return float(value or 0)
            s = str(value or "").strip().replace("R$", "").replace(" ", "")
            if not s:
                return 0.0
            if "," in s:
                s = s.replace(".", "").replace(",", ".")
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        try:
            n = float(value or 0)
        except Exception:
            n = _money_num(value)
        return "R$ " + f"{n:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _clean_digits(value):
        s = _norm(value)
        m = _re.match(r"^\s*\d{1,3}\s+0*(\d{3,12})\s*$", s)
        if m:
            return m.group(1).lstrip("0") or "0"
        m = _re.search(r"\b0*(\d{3,12})(?:\s*-\s*\d)?\b", s)
        if m:
            return m.group(1).lstrip("0") or "0"
        d = _re.sub(r"\D", "", s)
        if d:
            return d.lstrip("0") or "0"
        return s

    def _app_dir():
        candidates = []
        try:
            fn = globals().get("app_runtime_dir")
            if callable(fn):
                candidates.append(_Path(fn()))
        except Exception:
            pass
        try:
            candidates.append(_Path(_sys.executable).resolve().parent)
        except Exception:
            pass
        try:
            candidates.append(_Path.cwd())
        except Exception:
            pass
        try:
            candidates.append(_Path(__file__).resolve().parents[1])
        except Exception:
            pass
        for p in candidates:
            try:
                if p and p.exists():
                    return p
            except Exception:
                pass
        return _Path.cwd()

    def _log_error(exc, etapa="exportação"):
        try:
            log_dir = _app_dir() / "logs"
            log_dir.mkdir(parents=True, exist_ok=True)
            path = log_dir / f"erro_exportar_faturas_{_datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
            path.write_text(
                "ERRO AO EXPORTAR RELATÓRIO DE FATURAS\n"
                + "=" * 80 + "\n"
                + f"Etapa: {etapa}\n"
                + f"Data/hora: {_datetime.now().strftime('%d/%m/%Y %H:%M:%S')}\n\n"
                + _traceback.format_exc(),
                encoding="utf-8",
            )
            return path
        except Exception:
            return None

    def _valid_sheets(sheets):
        if not isinstance(sheets, list) or not sheets:
            return False
        for item in sheets:
            try:
                name, rows, widths = item
            except Exception:
                return False
            if not isinstance(rows, list) or not rows:
                return False
        return True

    def _row_get(row, idx, default=""):
        try:
            return row[idx] if idx < len(row) else default
        except Exception:
            return default

    def _is_problem_detail(d):
        raw = _blob(_row_get(d, 4), _row_get(d, 5), _row_get(d, 6), _row_get(d, 8), _row_get(d, 9))
        if "OK COMPLEMENTAR" in raw or "NAO EXIGIDO" in raw or "NÃO EXIGIDO" in raw:
            return ""
        bad = ("SEM COMPROVANTE", "DY=N", "FORA DA BASE", "NAO LOCALIZ", "NÃO LOCALIZ", "FATURA DIVERGENTE", "DIVERG")
        if not any(x in raw for x in bad):
            return ""
        if "FORA DA BASE" in raw or "NAO LOCALIZ" in raw or "NÃO LOCALIZ" in raw:
            return "Comprovante / Base"
        if "SEM COMPROVANTE" in raw or "DY=N" in raw:
            return "Comprovante"
        if "FATURA DIVERGENTE" in raw:
            return "Fatura base"
        if "DIVERG" in raw:
            return "Valor"
        return "Revisar"

    def _action(ptype):
        if ptype == "Comprovante":
            return "Solicitar comprovante ao parceiro e bloquear somente este CT-e até regularização."
        if ptype == "Comprovante / Base":
            return "Localizar CT-e/NF na base Rodovitor ou devolver para conferência manual."
        if ptype == "Fatura base":
            return "Conferir fatura informada na base Rodovitor antes do pagamento."
        if ptype == "Valor":
            return "Conferir valor da fatura contra base/XML antes do pagamento."
        return "Validar manualmente antes de liberar pagamento."

    def _fallback_visual_sheets(self):
        invoice_rows = list(getattr(self, "invoice_rows", []) or [])
        detail_map = getattr(self, "detail_rows_by_invoice", {}) or {}
        if not invoice_rows:
            return []
        resumo = [["Número da Fatura", "Nome do Parceiro", "Qtd.", "OK", "Problema", "Valor Fatura", "Valor Não Pagar", "Valor a Pagar", "CT-e/NF com Divergência", "Status"]]
        detalhes = [["Fatura", "Parceiro", "CT-e", "NF", "Valor CT-e", "Valor XML", "Status valor", "Fatura Base", "Comprovante", "Escaneamento", "Status CT-e", "Observação"]]
        diverg = [["Fatura", "Parceiro", "CT-e", "NF", "Valor Não Pagar", "Tipo Divergência", "Status CT-e", "Motivo", "Ação recomendada"]]
        mensagens = [["Parceiro", "Faturas com DY=N", "Qtd. CT-es sem comprovante", "Valor bloqueado por comprovante", "CT-es pendentes", "Mensagem pronta"]]
        msg_map = {}
        for row in invoice_rows:
            r = list(row or [])
            fat = _norm(_row_get(r, 0))
            partner = _norm(_row_get(r, 1)) or "Parceiro não identificado"
            qtd = _row_get(r, 2)
            ok = _row_get(r, 3)
            prob = _row_get(r, 4)
            valor = _money_num(_row_get(r, 5))
            np = _money_num(_row_get(r, 6))
            ap = max(valor - np, 0.0)
            status = _norm(_row_get(r, 9)) or ("OK PAGAR" if _money_num(prob) == 0 else "PAGAR PARCIAL")
            pend_labels = []
            for d0 in list(detail_map.get(fat) or []):
                d = list(d0 or [])
                cte = _clean_digits(_row_get(d, 0)) or "-"
                nf = _clean_digits(_row_get(d, 1)) or "-"
                v = _money_num(_row_get(d, 2))
                status_valor = _norm(_row_get(d, 4))
                fbase = _norm(_row_get(d, 5))
                comp = _norm(_row_get(d, 6))
                esc = _norm(_row_get(d, 7))
                st = _norm(_row_get(d, 8)) or "OK"
                obs = _norm(_row_get(d, 9))
                detalhes.append([fat, partner, cte, nf, v, _row_get(d, 3), status_valor, fbase, comp, esc, st, obs])
                ptype = _is_problem_detail(d)
                if ptype:
                    pend_labels.append(f"CT-e {cte}" + (f" / NF {nf}" if nf and nf != "-" else ""))
                    diverg.append([fat, partner, cte, nf, v, ptype, st, obs or comp or st, _action(ptype)])
                    if ptype == "Comprovante":
                        msg_map.setdefault(partner, {}).setdefault(fat, []).append((cte, nf, v))
            resumo.append([fat, partner, qtd, ok, prob, valor, np, ap, " | ".join(pend_labels), status])
        for partner in sorted(msg_map):
            fat_map = msg_map[partner]
            qtd = sum(len(v) for v in fat_map.values())
            bloqueado = round(sum(x[2] for v in fat_map.values() for x in v), 2)
            pend = []
            linhas = []
            fat_labels = []
            for fat in sorted(fat_map):
                recs = fat_map[fat]
                fat_labels.append(f"{fat} ({len(recs)} CT-e)")
                linhas.append(f"Fatura {fat}:")
                for cte, nf, val in recs:
                    pend.append(f"CT-e {cte}" + (f" / NF {nf}" if nf and nf != "-" else ""))
                    linhas.append(f"- CT-e {cte} | NF {nf or '-'} | Valor a retirar {_money(val)} | Motivo: sem comprovante de entrega")
            msg = (
                "Prezados,\n\n"
                f"Identificamos CT-e(s) sem comprovante de entrega na fatura do parceiro {partner}.\n\n"
                "Solicitamos, por gentileza, retirar o(s) CT-e(s) abaixo da fatura atual e incluí-lo(s) em uma próxima fatura somente após o envio/regularização do comprovante de entrega.\n\n"
                "CT-e(s) a retirar da fatura atual:\n" + "\n".join(linhas) + "\n\n"
                f"Valor a retirar da fatura atual: {_money(bloqueado)}.\n"
                "Após o envio do comprovante, o(s) CT-e(s) poderá(ão) ser reapresentado(s) nas próximas faturas para nova análise.\n"
            )
            mensagens.append([partner, " | ".join(fat_labels), qtd, bloqueado, " | ".join(pend), msg])
        return [
            ("1_Resumo_Faturas", resumo, [18, 42, 8, 8, 10, 15, 16, 15, 70, 18]),
            ("2_CTes_Comprovantes", detalhes, [16, 42, 16, 16, 14, 14, 18, 16, 18, 22, 22, 60]),
            ("3_Divergencias", diverg, [16, 42, 16, 16, 16, 20, 22, 60, 60]),
            ("4_Mensagem_Parceiro", mensagens, [42, 58, 18, 22, 70, 110]),
        ]

    def _safe_build_sheets(self):
        try:
            fixer = getattr(self, "corrigir_base_faturas_2660", None)
            if callable(fixer):
                fixer()
        except Exception:
            pass
        try:
            sheets = _orig_build(self, False) if callable(_orig_build) else []
            if _valid_sheets(sheets):
                return sheets
        except Exception as exc:
            _log_error(exc, "build_invoice_report_sheets")
        sheets = _fallback_visual_sheets(self)
        if _valid_sheets(sheets):
            return sheets
        raise RuntimeError("Não havia dados válidos para montar o relatório de faturas.")

    def _apply_status_colors_xlsx(path):
        """Aplica cores, formatos inteiros e navegação às cinco abas.

        Verde = OK/liberado; amarelo = parcial/revisão/informativo;
        vermelho = não pagar/sem comprovante/fora da base.
        Também congela cabeçalhos, mantém Fatura/Parceiro/CT-e/NF visíveis nas
        abas largas e oculta somente colunas técnicas secundárias.
        """
        import zipfile as _zipfile_local
        from xml.etree import ElementTree as _ET_local

        path = _Path(path)
        ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
        _ET_local.register_namespace("", ns)
        q = lambda tag: "{%s}%s" % (ns, tag)

        with _zipfile_local.ZipFile(path, "r") as zin:
            files = {name: zin.read(name) for name in zin.namelist()}

        styles_root = _ET_local.fromstring(files["xl/styles.xml"])
        fonts = styles_root.find(q("fonts"))
        fills = styles_root.find(q("fills"))
        cell_xfs = styles_root.find(q("cellXfs"))
        if fonts is None or fills is None or cell_xfs is None:
            return

        def add_font(color):
            font = _ET_local.Element(q("font"))
            _ET_local.SubElement(font, q("b"))
            _ET_local.SubElement(font, q("sz"), {"val": "11"})
            _ET_local.SubElement(font, q("color"), {"rgb": color})
            _ET_local.SubElement(font, q("name"), {"val": "Calibri"})
            fonts.append(font)
            return len(fonts) - 1

        def add_fill(color):
            fill = _ET_local.Element(q("fill"))
            pattern = _ET_local.SubElement(fill, q("patternFill"), {"patternType": "solid"})
            _ET_local.SubElement(pattern, q("fgColor"), {"rgb": color})
            _ET_local.SubElement(pattern, q("bgColor"), {"indexed": "64"})
            fills.append(fill)
            return len(fills) - 1

        def add_xf(font_id, fill_id, num_fmt_id="0", centered=False):
            attrs = {
                "numFmtId": str(num_fmt_id), "fontId": str(font_id), "fillId": str(fill_id),
                "borderId": "1", "xfId": "0", "applyFont": "1", "applyFill": "1", "applyBorder": "1",
            }
            if str(num_fmt_id) != "0":
                attrs["applyNumberFormat"] = "1"
            if centered:
                attrs["applyAlignment"] = "1"
            xf = _ET_local.Element(q("xf"), attrs)
            if centered:
                _ET_local.SubElement(xf, q("alignment"), {"horizontal": "center", "vertical": "center"})
            cell_xfs.append(xf)
            return len(cell_xfs) - 1

        green_style = add_xf(add_font("FF006100"), add_fill("FFC6EFCE"))
        yellow_style = add_xf(add_font("FF9C6500"), add_fill("FFFFEB9C"))
        red_style = add_xf(add_font("FF9C0006"), add_fill("FFFFC7CE"))
        integer_style = add_xf(0, 0, num_fmt_id="1", centered=True)  # formato Excel 0

        def cell_text(cell):
            if cell.get("t") == "inlineStr":
                return "".join((node.text or "") for node in cell.iter(q("t")))
            value = cell.find(q("v"))
            return value.text if value is not None else ""

        def col_letters(ref):
            match = _re.match(r"[A-Z]+", str(ref or ""))
            return match.group(0) if match else ""

        def col_number(ref):
            letters = col_letters(ref)
            number = 0
            for char in letters:
                number = number * 26 + ord(char) - 64
            return number

        def norm_header(value):
            return _norm(value)

        def choose_style(header, value):
            v = _strip_accents(str(value or "")).upper()
            h = norm_header(header)
            if not v:
                return None
            if h in {"STATUSVALOR", "STATUSTABELAPARCEIRO"}:
                if v.startswith("OK"):
                    return green_style
                if any(token in v for token in ("NAO PAGAR", "NÃO PAGAR", "FORA DA BASE")):
                    return red_style
                return yellow_style
            if any(token in v for token in ("NAO PAGAR", "NÃO PAGAR", "SEM COMPROVANTE", "FORA DA BASE")):
                return red_style
            if "PAGAR PARCIAL" in v or "PARCIAL" in v or "REVISAR" in v:
                return yellow_style
            if v.startswith("OK"):
                return green_style
            return yellow_style

        def ensure_freeze(root, x_split=0, y_split=1):
            sheet_views = root.find(q("sheetViews"))
            if sheet_views is None:
                sheet_views = _ET_local.Element(q("sheetViews"))
                # sheetViews deve vir antes de sheetFormatPr/sheetData.
                insert_at = 0
                for idx, child in enumerate(list(root)):
                    if child.tag in {q("sheetPr"), q("dimension")}:
                        insert_at = idx + 1
                root.insert(insert_at, sheet_views)
            view = sheet_views.find(q("sheetView"))
            if view is None:
                view = _ET_local.SubElement(sheet_views, q("sheetView"), {"workbookViewId": "0"})
            for child in list(view):
                if child.tag in {q("pane"), q("selection")}:
                    view.remove(child)
            attrs = {"state": "frozen"}
            if x_split:
                attrs["xSplit"] = str(x_split)
            if y_split:
                attrs["ySplit"] = str(y_split)
            col = "A"
            n = int(x_split) + 1
            letters = ""
            while n:
                n, rem = divmod(n - 1, 26)
                letters = chr(65 + rem) + letters
            col = letters
            attrs["topLeftCell"] = f"{col}{int(y_split) + 1}"
            attrs["activePane"] = "bottomRight" if x_split and y_split else ("bottomLeft" if y_split else "topRight")
            _ET_local.SubElement(view, q("pane"), attrs)
            _ET_local.SubElement(view, q("selection"), {"pane": attrs["activePane"], "activeCell": attrs["topLeftCell"], "sqref": attrs["topLeftCell"]})

        def hide_columns(root, indices):
            indices = sorted(set(int(i) for i in indices if int(i) > 0))
            if not indices:
                return
            cols = root.find(q("cols"))
            if cols is None:
                cols = _ET_local.Element(q("cols"))
                sheet_data = root.find(q("sheetData"))
                pos = list(root).index(sheet_data) if sheet_data is not None else len(list(root))
                root.insert(pos, cols)
            existing = list(cols.findall(q("col")))
            for idx in indices:
                found = None
                for col in existing:
                    try:
                        if int(col.get("min", "0")) <= idx <= int(col.get("max", "0")):
                            found = col
                            break
                    except Exception:
                        continue
                if found is not None and found.get("min") == found.get("max") == str(idx):
                    found.set("hidden", "1")
                else:
                    col = _ET_local.Element(q("col"), {"min": str(idx), "max": str(idx), "hidden": "1", "customWidth": "1", "width": "2"})
                    cols.append(col)
                    existing.append(col)

        target_headers = {"STATUS", "STATUSVALOR", "STATUSTABELAPARCEIRO", "STATUSCTE", "STATUSFINAL"}
        count_headers = {"QTD", "OK", "PROBLEMA", "QTDCTESSEMCOMPROVANTE"}
        detail_hidden = {"ORIGEMVALIDACAOVALOR", "REGRATABELA", "FONTEBASETABELA", "CONFIANCAVALOR", "CAMINHOCALCULOTABELA", "CAMINHODOSTATUS", "AVISOS"}
        log_hidden = {
            "CHAVEFATURA", "CTRCORIGEMPDF", "FATURABASEEXP", "FATURABASEREC", "FONTEREGRA",
            "BASECALCULOTABELA", "FONTEBASETABELA", "PERCENTUALTABELA", "MINIMOTABELA", "TOLERANCIATABELA",
            "MODOTABELA", "VALORXML", "DIFERENCAXML", "ORIGEMVALIDACAOVALOR", "CONFIANCAVALOR",
            "VINCULOVALIDACAOVALOR", "REGRAAPLICADA", "STATUSVALORLEGADO",
        }

        for name, raw in list(files.items()):
            if not (name.startswith("xl/worksheets/sheet") and name.endswith(".xml")):
                continue
            root = _ET_local.fromstring(raw)
            sheet_data = root.find(q("sheetData"))
            if sheet_data is None:
                continue
            rows = sheet_data.findall(q("row"))
            if not rows:
                continue
            header_map = {}
            header_by_index = {}
            for cell in rows[0].findall(q("c")):
                header = cell_text(cell)
                letters = col_letters(cell.get("r"))
                header_map[letters] = header
                header_by_index[col_number(cell.get("r"))] = norm_header(header)

            header_norms = set(header_by_index.values())
            is_summary = {"NUMERODAFATURA", "NOMEDOPARCEIRO", "QTD", "VALORFATURA", "STATUS"}.issubset(header_norms)
            is_details = {"FATURA", "PARCEIRO", "CTE", "NF", "STATUSCTE", "CAMINHODOSTATUS"}.issubset(header_norms)
            is_log = {"FATURA", "PARCEIRO", "SEQ", "ARQUIVOPDF", "STATUSFINAL", "CAMINHODOSTATUS"}.issubset(header_norms)

            # Congela a primeira linha em todas as abas. Nas duas abas largas,
            # congela também Fatura/Parceiro/CT-e/NF (quatro primeiras colunas).
            ensure_freeze(root, x_split=4 if (is_details or is_log) else 0, y_split=1)

            hidden = []
            if is_details:
                hidden = [idx for idx, header in header_by_index.items() if header in detail_hidden]
            elif is_log:
                hidden = [idx for idx, header in header_by_index.items() if header in log_hidden]
            hide_columns(root, hidden)

            for row in rows[1:]:
                for cell in row.findall(q("c")):
                    col = col_letters(cell.get("r"))
                    header = header_map.get(col, "")
                    header_norm = norm_header(header)
                    if is_summary and header_norm in count_headers:
                        cell.set("s", str(integer_style))
                        continue
                    if header_norm in target_headers:
                        style_id = choose_style(header, cell_text(cell))
                        if style_id is not None:
                            cell.set("s", str(style_id))
            files[name] = _ET_local.tostring(root, encoding="utf-8", xml_declaration=True)

        fonts.set("count", str(len(fonts)))
        fills.set("count", str(len(fills)))
        cell_xfs.set("count", str(len(cell_xfs)))
        files["xl/styles.xml"] = _ET_local.tostring(styles_root, encoding="utf-8", xml_declaration=True)

        temp_path = path.with_suffix(path.suffix + ".tmp")
        with _zipfile_local.ZipFile(temp_path, "w", compression=_zipfile_local.ZIP_DEFLATED) as zout:
            for name, data in files.items():
                zout.writestr(name, data)
        _os.replace(temp_path, path)

    def _write_report_file(self, sheets):
        rel_dir = _app_dir() / "relatorios"
        rel_dir.mkdir(parents=True, exist_ok=True)
        stamp = _datetime.now().strftime("%Y%m%d_%H%M%S")
        path = rel_dir / f"relatorio_faturas_5_abas_{stamp}.xlsx"
        writer = globals().get("write_simple_xlsx")
        if not callable(writer):
            raise RuntimeError("write_simple_xlsx não está disponível no motor.")
        writer(path, sheets)
        _apply_status_colors_xlsx(path)
        return path

    def _notify(self, title, text, error=False):
        shown = False
        try:
            QMessageBox = getattr(_main, "QMessageBox", None)
            if QMessageBox is not None:
                if error:
                    QMessageBox.critical(self, title, text)
                else:
                    QMessageBox.information(self, title, text)
                shown = True
        except Exception:
            pass
        if not shown:
            try:
                import tkinter.messagebox as _mb
                (_mb.showerror if error else _mb.showinfo)(title, text)
                shown = True
            except Exception:
                pass
        try:
            if hasattr(self, "set_status"):
                self.set_status(text.replace("\n", " "))
        except Exception:
            pass

    def _export_2663(self, *args, **kwargs):
        try:
            sheets = _safe_build_sheets(self)
            path = _write_report_file(self, sheets)
            try:
                log_fn = getattr(self, "gerar_log_faturas_2655", None)
                if callable(log_fn):
                    log_fn("exportação/relatório de faturas 2.6.63")
            except Exception:
                pass
            _notify(self, "Central CT-e / DACTE", f"Relatório de faturas gerado com sucesso:\n\n{path}", error=False)
            return str(path)
        except Exception as exc:
            log_path = _log_error(exc, "exportar_relatorio_2663")
            extra = f"\n\nLog do erro:\n{log_path}" if log_path else ""
            _notify(self, "Central CT-e / DACTE", f"Erro ao gerar relatório de faturas.\n{exc}{extra}", error=True)
            return None

    # Substitui todos os nomes usados pelo botão/exportador em versões anteriores.
    for _name in ("export_report", "export_invoice_report", "exportar_relatorio", "exportar_relatorio_faturas", "export_faturas_report"):
        try:
            setattr(FaturasPage, _name, _export_2663)
        except Exception:
            pass

    try:
        FaturasPage._hotfix_faturas_2663 = True
        FaturasPage.exportar_relatorio_faturas_2663 = _export_2663
    except Exception:
        pass
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.63 Exportador Relatório Faturas"
    except Exception:
        pass


_central_cte_hotfix_faturas_2663_start()

# ============================================================================
# HOTFIX Faturas Parceiros 2.6.64 / estabilização 2.6.65
# Motor canônico de faturas: depois que o parser lê os PDFs, a lista do PDF
# passa a ser a fonte única da verdade. A base Rodovitor serve apenas para
# validar cada item canônico, sem adicionar CT-e extra/clonado.
# ============================================================================

def _central_cte_hotfix_faturas_2664_start():
    import sys as _sys, time as _time, threading as _threading

    def _find_main():
        mod = _sys.modules.get("__main__")
        if mod is not None and hasattr(mod, "FaturasPage"):
            return mod
        for mod in list(_sys.modules.values()):
            try:
                if mod is not None and hasattr(mod, "FaturasPage"):
                    return mod
            except Exception:
                pass
        return None

    def _worker():
        for _ in range(1200):
            mod = _find_main()
            if mod is not None:
                try:
                    _central_cte_hotfix_faturas_2664_apply(mod)
                except Exception as exc:
                    try:
                        print("[HOTFIX FATURAS 2.6.64] falhou:", exc)
                    except Exception:
                        pass
                return
            _time.sleep(0.05)

    try:
        _threading.Thread(target=_worker, daemon=True, name="hotfix_faturas_2664_canonico").start()
    except Exception:
        pass


def _central_cte_hotfix_faturas_2664_apply(_main):
    import sys as _sys
    import os as _os
    import re as _re
    import traceback as _traceback
    import unicodedata as _unicodedata
    from pathlib import Path as _Path
    from datetime import datetime as _datetime

    FaturasPage = getattr(_main, "FaturasPage", None)
    if FaturasPage is None or getattr(FaturasPage, "_hotfix_faturas_2664", False):
        return

    _prev_process = getattr(FaturasPage, "process_invoices", None)
    _prev_build = getattr(FaturasPage, "build_invoice_report_sheets", None)

    def _strip_accents(value):
        try:
            return "".join(c for c in _unicodedata.normalize("NFD", str(value or "")) if _unicodedata.category(c) != "Mn")
        except Exception:
            return str(value or "")

    def _norm_space(value):
        return _re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()

    def _route_norm(value):
        text = _strip_accents(str(value or "")).upper()
        return _re.sub(r"\s+", " ", _re.sub(r"[^A-Z0-9]+", " ", text)).strip()

    def _norm(value):
        return _re.sub(r"[^A-Z0-9]+", "", _strip_accents(str(value or "")).upper())

    def _digits(value):
        return _re.sub(r"\D+", "", str(value or ""))

    def _clean_num(value):
        d = _digits(value)
        return d.lstrip("0") or ("0" if d else "")

    def _fmt_fatura(value):
        s = _norm_space(value)
        if not s:
            return ""
        m = _re.search(r"(?<!\d)(0*\d{3,9})\s*[-/]\s*(\d)(?!\d)", s)
        if m:
            return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        m = _re.search(r"\bFAT(?:URA|UARA)?\.?\s*0*(\d{3,9})\s*[-/]\s*(\d)\b", s, _re.I)
        if m:
            return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        return s

    def _fatura_key(value):
        """Chave da fatura usada na base: numero sem zeros e sem o DV."""
        if isinstance(value, (int, float)):
            try:
                return str(int(value))
            except Exception:
                return ""
        s = _norm_space(value)
        if not s:
            return ""
        m = _re.search(r"(?<!\d)0*(\d{1,9})\s*[-/]\s*\d(?!\d)", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"(?<!\d)0*(\d{1,9})(?:[.,]0+)?(?!\d)", s)
        return _clean_num(m.group(1)) if m else ""

    def _parse_money(value):
        fn = globals().get("parse_money_br") or getattr(_main, "parse_money_br", None)
        if callable(fn):
            try:
                return float(fn(value) or 0.0)
            except Exception:
                pass
        if isinstance(value, (int, float)):
            return float(value or 0.0)
        s = str(value or "").replace("R$", "").strip()
        if not s:
            return 0.0
        if "," in s:
            s = s.replace(".", "").replace(",", ".")
        try:
            return float(s)
        except Exception:
            return 0.0

    def _money(value):
        try:
            return "R$ " + f"{float(value or 0):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "R$ 0,00"

    def _money_values(line):
        return _re.findall(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", str(line or ""))

    def _clean_cte(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        s = _re.sub(r"\b(CT\s*-?\s*E|CTE|CTRC|SUBCONTRATO|ORIGEM)\b", "", s, flags=_re.I)
        s = _norm_space(s.strip(" :-"))
        m = _re.search(r"[A-Z]{2,8}\s*/?\s*0*(\d{3,12})\s*[-/]\s*(\d)", s, _re.I)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        m = _re.search(r"\b0*(\d{3,12})\s*[-/]\s*(\d)\b", s)
        if m:
            return f"{_clean_num(m.group(1))}-{m.group(2)}"
        m = _re.search(r"(?:^|\s)\d{1,4}\s+0*(\d{5,12})(?:\s|$)", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{3,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _cte_key(value):
        c = _clean_cte(value)
        d = _digits(c).lstrip("0") or _digits(c)
        return d

    def _valid_base_cte(value):
        k = _cte_key(value)
        if not k or len(k) < 4:
            return False
        if len(set(k)) <= 1:
            return False
        if k in {"111111111", "111111114", "11111111", "1111"}:
            return False
        if str(value or "").strip().upper() in {"1111/11111111-4", "11111111-4"}:
            return False
        return True

    def _clean_nf(value):
        s = _norm_space(value)
        if not s or s in {"-", "None", "nan"}:
            return ""
        # A NF pode ter somente 1, 2 ou 3 dígitos. Quando o trecho traz
        # série + número (ex.: "1 000000494"), conserva apenas a NF.
        m = _re.match(r"^\s*\d{1,3}\s+0*(\d{1,12})\s*$", s)
        if m:
            return _clean_num(m.group(1))
        m = _re.search(r"\b0*(\d{1,12})\b", s)
        if m:
            return _clean_num(m.group(1))
        return s

    def _find_idx(headers, *names):
        nh = [_norm(h) for h in headers or []]
        for name in names:
            nn = _norm(name)
            for i, h in enumerate(nh):
                if h == nn or nn in h or h in nn:
                    return i
        return None

    def _find_idx_exact(headers, *names):
        nh = [_norm(h) for h in headers or []]
        wanted = {_norm(name) for name in names}
        for i, h in enumerate(nh):
            if h in wanted:
                return i
        return None

    def _is_nf_number_header(line):
        u = _norm(line)
        return u in {"NFISCALN", "NFISCALNO", "NFISCALNUMERO", "NUMERONFISCAL"}

    def _is_nf_value_header(line):
        u = _norm(line)
        return u in {"NFISCALR", "NFISCALRS", "VALORNFISCAL"}

    def _line_is_money(s):
        return bool(_re.fullmatch(r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}", _norm_space(s)))

    def _extract_nf_list(lines, start_idx):
        out = []
        if start_idx is None:
            return out
        for j in range(start_idx + 1, min(len(lines), start_idx + 220)):
            line = _norm_space(lines[j])
            u = _norm(line)
            if not line or u in {"NFISCAL", "R", "RS"}:
                continue
            if _is_nf_number_header(line):
                if out:
                    break
                continue
            if _is_nf_value_header(line):
                if out:
                    break
                continue
            if any(k in u for k in ("PESOKG", "PESO", "BCALCULO", "ICMS", "FRETE", "CTRCORIGEM", "TRATAMENTO", "QUANTIDADE", "RESUMO", "TOTAL")):
                if out:
                    break
                continue
            if _line_is_money(line) or "," in line:
                continue
            # A coluna N Fiscal Nº pode conter NFs curtas (1, 2 ou 3 dígitos),
            # normalmente preenchidas com zeros à esquerda no PDF. Como já estamos
            # dentro do bloco específico da NF, aceitamos de 1 a 12 dígitos.
            m = _re.match(r"^\s*(?:(\d{1,3})\s+)?(\d{1,12})\s*$", line)
            if m:
                nf = _clean_num(m.group(2))
                if nf:
                    out.append(nf)
                continue
            if any(k in u for k in ("BENEFICIARIOFINAL", "PAGADOR", "LOCALDEPAGAMENTO", "CODIGOBENEFICIARIO")):
                break
        return out

    def _extract_all_nf_numbers(lines):
        out = []
        for i, line in enumerate(lines or []):
            if _is_nf_number_header(line):
                out.extend(_extract_nf_list(lines, i))
        return out

    def _extract_origin_cte(line):
        s = _norm_space(line)
        pats = [
            r"\b\d{4}\s*/\s*\d{5,12}\s*[-/]\s*\d\b",
            r"\b[A-Z]{2,6}\s*/?\s*\d{3,12}\s*[-/]\s*\d\b",
            r"\b0*\d{5,12}\s*[-/]\s*\d\b",
        ]
        for pat in pats:
            ms = list(_re.finditer(pat, s, _re.I))
            if ms:
                return _norm_space(ms[-1].group(0))
        return ""

    def _extract_value_before_origin(line, origin):
        vals = _money_values(line)
        if not vals:
            return 0.0
        if origin and origin in line:
            before = line.split(origin)[0]
            bvals = _money_values(before)
            if bvals:
                vals = bvals
        # Colunas do frete terceiro: N Fiscal R$, ICMS, Comissão, Frete Origem, ICMS Origem.
        if len(vals) >= 5:
            return _parse_money(vals[-3])
        return _parse_money(vals[-1])

    def _parse_weight_invoice(value):
        s = _norm_space(value).replace(" ", "")
        if not s:
            return 0.0
        try:
            if "," in s:
                return float(s.replace(".", "").replace(",", "."))
            if _re.fullmatch(r"\d{1,3}(?:\.\d{3})+", s):
                return float(s.replace(".", ""))
            return float(s)
        except Exception:
            return 0.0

    def _clean_scan_value(value):
        text = str(value or "").strip()
        return "" if text.upper() in {"", "NONE", "NULL", "NAN", "-"} else text

    def _format_scan_date(value):
        if isinstance(value, datetime):
            return value.strftime("%d/%m/%Y")
        if isinstance(value, (int, float)):
            try:
                return (datetime(1899, 12, 30) + timedelta(days=float(value))).strftime("%d/%m/%Y")
            except Exception:
                return ""
        text = _clean_scan_value(value)
        if not text:
            return ""
        try:
            number = float(text.replace(",", "."))
            if number > 1000:
                return (datetime(1899, 12, 30) + timedelta(days=number)).strftime("%d/%m/%Y")
        except Exception:
            pass
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"):
            try:
                return datetime.strptime(text, fmt).strftime("%d/%m/%Y")
            except Exception:
                pass
        return text

    def _format_scan_time(value):
        if isinstance(value, datetime):
            return value.strftime("%H:%M")
        if isinstance(value, (int, float)):
            try:
                fraction = float(value) % 1.0
                total_seconds = int(round(fraction * 86400)) % 86400
                return f"{total_seconds // 3600:02d}:{(total_seconds % 3600) // 60:02d}"
            except Exception:
                return ""
        text = _clean_scan_value(value)
        if not text:
            return ""
        try:
            number = float(text.replace(",", "."))
            if 0 <= number < 1:
                total_seconds = int(round(number * 86400)) % 86400
                return f"{total_seconds // 3600:02d}:{(total_seconds % 3600) // 60:02d}"
        except Exception:
            pass
        match = _re.search(r"(\d{1,2}):(\d{2})", text)
        return f"{int(match.group(1)):02d}:{match.group(2)}" if match else text

    def _extract_frete_invoice_fields(line):
        """Lê valores diretamente da linha FRETE TERCEIRO PAGADOR.

        Ordem do layout: N Fiscal R$, Peso Kg, ICMS R$, Comissão R$,
        CTRC Origem, Frete R$, ICMS R$. A fatura é a fonte principal para
        peso, comissão cobrada e frete do CTRC Origem.
        """
        text = str(line or "")
        pattern = r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}"
        matches = list(_re.finditer(pattern, text))
        values = [_parse_money(m.group(0)) for m in matches]
        result = {
            "valor_nota_fatura": 0.0,
            "peso_fatura": 0.0,
            "icms_fatura": 0.0,
            "comissao_fatura": 0.0,
            "frete_origem_fatura": 0.0,
            "icms_origem_fatura": 0.0,
            "peso_valor_candidatos": [],
        }
        if len(values) >= 5:
            result["valor_nota_fatura"] = round(values[0], 2)
            result["icms_fatura"] = round(values[1], 2)
            result["comissao_fatura"] = round(values[2], 2)
            result["frete_origem_fatura"] = round(values[-2], 2)
            result["icms_origem_fatura"] = round(values[-1], 2)

            between = text[matches[0].end():matches[1].start()]
            weight_match = _re.search(r"(?<!\d)(\d{1,3}(?:\.\d{3})+|\d+(?:[.,]\d+)?)(?!\d)", between)
            if not weight_match and matches[0].start() > 0 and text[matches[0].start() - 1].isspace():
                # Layout MRV/Exclusiva: o peso aparece imediatamente antes do
                # primeiro valor monetário, separado por espaço. Se o valor
                # começa colado ao peso (Rodotec), mantém a geração de
                # candidatos para confirmação pela linha exata da base.
                before_first = text[:matches[0].start()]
                weight_match = _re.search(r"(?<![\d.,])(\d{1,6}(?:[.,]\d{1,3})?)(?![\d.,])\s*$", before_first)
            if weight_match:
                # Layout normal: o peso está em sua própria coluna. Não cria
                # candidatos de separação, evitando substituir um valor correto.
                result["peso_fatura"] = round(_parse_weight_invoice(weight_match.group(1)), 3)
            else:
                # Layout colado: Peso + N Fiscal R$ formam um único token.
                # Em vez de tratar apenas cinco formatos conhecidos, enumera
                # todas as divisões entre o prefixo do peso e a parte inteira
                # do valor monetário. A linha já confirmada da base escolhe a
                # única separação compatível.
                prefix_match = _re.search(r"(\d+)$", text[:matches[0].start()])
                first_token = matches[0].group(0).replace("R$", "").strip()
                combined = (prefix_match.group(1) if prefix_match else "") + first_token
                token_match = _re.search(r"([0-9.]+),([0-9]{2})$", combined)
                candidates = []
                if token_match:
                    integer_digits = _re.sub(r"\D", "", token_match.group(1))
                    cents = token_match.group(2)
                    for split_at in range(1, len(integer_digits)):
                        weight_raw = integer_digits[:split_at]
                        money_integer = integer_digits[split_at:]
                        if not weight_raw or not money_integer:
                            continue
                        # A parte monetária não pode ganhar zero artificial à
                        # esquerda. Ex.: 2705.043,02 deve virar peso 270 +
                        # R$ 5.043,02, nunca peso 27 + R$ 05.043,02.
                        if len(money_integer) > 1 and money_integer.startswith("0"):
                            continue
                        weight_val = _parse_weight_invoice(weight_raw)
                        try:
                            money_val = float(int(money_integer)) + float(int(cents)) / 100.0
                        except Exception:
                            continue
                        if 0 < weight_val <= 100000 and 0 < money_val <= 1000000000:
                            candidates.append({
                                "peso": round(weight_val, 3),
                                "valor_nota": round(money_val, 2),
                                "split_at": split_at,
                                "raw": combined,
                            })
                # Remove candidatos duplicados mantendo a ordem.
                dedup = []
                seen = set()
                for candidate in candidates:
                    key = (candidate["peso"], candidate["valor_nota"])
                    if key in seen:
                        continue
                    seen.add(key)
                    dedup.append(candidate)
                result["peso_valor_candidatos"] = dedup
        return result

    def _extract_nf_from_freight_row(line):
        """Extrai a NF da mesma linha do CT-e, inclusive NFs de 1 a 3 dígitos."""
        s = _norm_space(line)

        # No layout tabular, os últimos dois números antes do primeiro valor
        # monetário são a série e a NF. Ex.: "... 1 000000494 2.590,00".
        # Essa âncora evita confundir CNPJ, subcontrato, peso ou valor da nota.
        vals = _money_values(s)

        # Alguns PDFs colam a NF de 9 posições ao primeiro valor monetário:
        # "1 00000063838.490,00" = série 1, NF 638, valor 38.490,00.
        m = _re.search(
            r"(?:^|\s)(\d{1,3})\s+(\d{9})(?=(?:\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2}))",
            s,
        )
        if m:
            nf = _clean_num(m.group(2))
            if nf:
                return nf

        before_money = s.split(vals[0], 1)[0].rstrip() if vals else s
        m = _re.search(r"(?:^|\s)(\d{1,3})\s+0*(\d{1,12})\s*$", before_money)
        if m:
            nf = _clean_num(m.group(2))
            if nf:
                return nf

        # Fallback para PDFs cujo texto venha colado ao CNPJ/remetente.
        parts = _re.split(r"\d{2}/\d{2}/\d{2}", s, maxsplit=1)
        if len(parts) < 2:
            return ""
        prefix = parts[1].split(" - ", 1)[0]
        cnpj = _re.search(r"(\d{14})\s*$", prefix)
        if cnpj:
            prefix = prefix[:cnpj.start(1)]
        nums = _re.findall(r"\d+", prefix)
        for raw in reversed(nums):
            nf = _clean_num(raw)
            if 1 <= len(nf) <= 12:
                return nf
        return ""

    def _extract_frete_terceiro_items(text):
        raw = str(text or "").replace("\xa0", " ")
        upraw = _strip_accents(raw).upper()
        if "SUBCONTRATO" not in upraw and "FRETE TERCEIRO PAGADOR" not in upraw:
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        sub_idx = None
        for i, line in enumerate(lines):
            u = _norm(line)
            if u == "SUBCONTRATO" and sub_idx is None:
                sub_idx = i
        nfs = _extract_all_nf_numbers(lines)
        rows = []
        start = sub_idx + 1 if sub_idx is not None else 0
        for j in range(start, min(len(lines), start + 260)):
            line = lines[j]
            u = _norm(line)
            if "QUANTIDADEDESUBCONTRATOS" in u or u.startswith("RESUMO"):
                break
            m = _re.match(r"^\s*(\d{1,4})\s+0*(\d{5,12})\s+\d{2}/\d{2}/\d{2}\b", line)
            if not m:
                continue
            sub = _clean_num(m.group(2))

            # Há linhas que quebram no meio da tabela. Junta até duas linhas de
            # continuação quando CTRC/NF não aparecem na primeira parte.
            row_line = line
            continuation = []
            if not _extract_origin_cte(row_line) or not _extract_nf_from_freight_row(row_line):
                for k in range(j + 1, min(len(lines), j + 3)):
                    nxt = lines[k]
                    if _re.match(r"^\s*\d{1,4}\s+0*\d{5,12}\s+\d{2}/\d{2}/\d{2}\b", nxt):
                        break
                    nu = _norm(nxt)
                    if "QUANTIDADEDESUBCONTRATOS" in nu or nu.startswith("RESUMO"):
                        break
                    continuation.append(nxt)
                    row_line = _norm_space(row_line + " " + nxt)
                    if _extract_origin_cte(row_line) and _extract_nf_from_freight_row(row_line):
                        break

            origin = _extract_origin_cte(row_line)
            value = _extract_value_before_origin(row_line, origin)
            nf = _extract_nf_from_freight_row(row_line)

            # No caso quebrado, a continuação pode começar com "série NF" após
            # o valor mercantil da primeira linha.
            if not nf and continuation:
                cont = _norm_space(" ".join(continuation))
                mc = _re.match(r"^\s*(\d{1,3})\s+0*(\d{1,12})(?=\s|$)", cont)
                if mc:
                    nf = _clean_num(mc.group(2))

            if not nf:
                nf = nfs[len(rows)] if len(rows) < len(nfs) else ""
            if not nf:
                after_date = _re.split(r"\d{2}/\d{2}/\d{2}", row_line, maxsplit=1)[-1]
                vals = _money_values(after_date)
                segment = after_date.split(vals[0])[0] if vals else after_date
                nums2 = _re.findall(r"\b0*\d{1,12}\b", segment)
                for cand in reversed(nums2):
                    c = _clean_num(cand)
                    if 1 <= len(c) <= 12:
                        nf = c
                        break
            invoice_fields = _extract_frete_invoice_fields(row_line)
            if invoice_fields.get("comissao_fatura", 0.0) > 0:
                value = invoice_fields["comissao_fatura"]
            rows.append({
                "cte": sub,
                "subcontrato": sub,
                "nf": _clean_nf(nf),
                "valor": round(float(value or 0.0), 2),
                "base_cte": origin if _valid_base_cte(origin) else "",
                "ctrc_origem_raw": origin,
                "layout": "FRETE TERCEIRO PAGADOR",
                **invoice_fields,
            })
        return rows

    def _extract_cte_rps_invoice_fields_266511(line):
        """Extrai mercadoria, peso e comissão do layout CT-e/RPS/NFS-e."""
        text = str(line or "")
        pattern = r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}"
        matches = list(_re.finditer(pattern, text))
        values = [_parse_money(match.group(0)) for match in matches]
        result = {
            "valor_nota_fatura": 0.0,
            "peso_fatura": 0.0,
            "icms_fatura": 0.0,
            "comissao_fatura": 0.0,
            "frete_origem_fatura": 0.0,
            "icms_origem_fatura": 0.0,
            "peso_valor_candidatos": [],
        }
        if not values:
            return result
        result["valor_nota_fatura"] = round(values[0], 2)
        result["comissao_fatura"] = round(values[-1], 2)
        if len(values) >= 3:
            result["icms_fatura"] = round(values[2], 2)
        if len(matches) >= 2:
            between = text[matches[0].end():matches[1].start()]
            weight_matches = list(_re.finditer(r"(?<!\d)(\d{1,3}(?:\.\d{3})+|\d+(?:[.,]\d+)?)(?!\d)", between))
            if weight_matches:
                result["peso_fatura"] = round(_parse_weight_invoice(weight_matches[-1].group(1)), 3)
        return result

    def _extract_cte_rps_items(text):
        raw = str(text or "").replace("\xa0", " ")
        upraw = _strip_accents(raw).upper()
        if "CT-e / RPS / NFS-e" not in raw and "CTE / RPS / NFSE" not in upraw and "CT E RPS NFSE" not in _norm(raw[:2000]):
            return []
        lines = [_norm_space(x) for x in raw.splitlines() if _norm_space(x)]
        nfs = _extract_all_nf_numbers(lines)
        rows = []
        for line in lines:
            if not _re.search(r"\d{2}/\d{2}/\d{2}", line):
                continue
            m = _re.match(r"^\s*(\d{1,4})\s+0*(\d{5,12})\s+\d{2}/\d{2}/\d{2}\b", line)
            if not m:
                m2 = _re.match(r"^\s*([A-Z]{2,8}\s*0*\d{3,12}\s*[-/]\s*\d)", line, _re.I)
                if not m2:
                    continue
                cte = _clean_cte(m2.group(1))
            else:
                cte = _clean_num(m.group(2))
            vals = _money_values(line)
            invoice_fields = _extract_cte_rps_invoice_fields_266511(line)
            value = invoice_fields.get("comissao_fatura") or (_parse_money(vals[-1]) if vals else 0.0)
            # O layout CT-e/RPS/NFS-e pode não trazer série antes da NF.
            # Extrai a última sequência numérica válida entre a data e o
            # primeiro valor monetário, descartando CNPJ de 14 dígitos. Essa
            # NF vem diretamente do PDF e deve ser preservada mesmo quando o
            # documento estiver fora da base.
            nf = ""
            first_money_match = _re.search(
                r"(?:R\$\s*)?\d{1,3}(?:\.\d{3})*,\d{2}|(?:R\$\s*)?\d+,\d{2}",
                line,
            )
            prefix = line[:first_money_match.start()] if first_money_match else line
            after_date = _re.split(r"\d{2}/\d{2}/\d{2}", prefix, maxsplit=1)
            if len(after_date) == 2:
                number_tokens = _re.findall(r"(?<!\d)0*(\d{1,14})(?!\d)", after_date[1])
                valid_tokens = []
                for raw_nf in number_tokens:
                    clean_nf = _clean_num(raw_nf)
                    if not clean_nf or len(clean_nf) > 12:
                        continue
                    if _cte_key(clean_nf) == _cte_key(cte):
                        continue
                    valid_tokens.append(clean_nf)
                if valid_tokens:
                    nf = valid_tokens[-1]
            if not nf:
                nf = _extract_nf_from_freight_row(line)
            if not nf:
                nf = nfs[len(rows)] if len(rows) < len(nfs) else ""
            if not nf:
                first_money = vals[0] if vals else ""
                segment = line.split(first_money)[0] if first_money else line
                nums2 = _re.findall(r"(?:^|\s)(?:\d{1,3}\s+)?0*(\d{1,12})(?=\s|$)", segment)
                for cand in reversed(nums2):
                    c = _clean_num(cand)
                    if 1 <= len(c) <= 12 and c != _cte_key(cte):
                        nf = c
                        break
            rows.append({
                "cte": cte,
                "subcontrato": cte,
                "nf": _clean_nf(nf),
                "valor": round(float(value or 0.0), 2),
                "base_cte": "",
                "ctrc_origem_raw": "",
                "layout": "CT-e/RPS/NFS-e",
                **invoice_fields,
            })
        return rows

    def _items_from_doc_existing(doc):
        clean = []
        items = []
        if isinstance(doc, dict):
            for key in ("items", "itens", "ctes", "rows"):
                val = doc.get(key)
                if isinstance(val, list):
                    items = val
                    break
        for it in items or []:
            if not isinstance(it, dict):
                continue
            cte = _clean_cte(it.get("subcontrato") or it.get("cte") or it.get("CT-e") or it.get("CT-e fatura"))
            nf = _clean_nf(it.get("nf") or it.get("NF") or it.get("nota") or it.get("NF fatura"))
            val = round(_parse_money(it.get("valor_fatura") or it.get("valor") or it.get("frete") or it.get("Valor fatura") or it.get("Valor CT-e")), 2)
            if not cte:
                continue
            clean.append({
                "cte": cte, "subcontrato": cte, "nf": nf, "valor": val,
                "base_cte": it.get("base_cte") or "",
                "ctrc_origem_raw": it.get("ctrc_origem_raw") or "",
                "layout": it.get("layout") or "DOC_ITEMS",
                "valor_nota_fatura": _parse_money(it.get("valor_nota_fatura") or it.get("N Fiscal R$")),
                "peso_fatura": _parse_weight_invoice(it.get("peso_fatura") or it.get("Peso Kg")),
                "icms_fatura": _parse_money(it.get("icms_fatura") or it.get("ICMS R$")),
                "comissao_fatura": _parse_money(it.get("comissao_fatura") or it.get("Comissão R$")),
                "frete_origem_fatura": _parse_money(it.get("frete_origem_fatura") or it.get("Frete Origem R$")),
                "icms_origem_fatura": _parse_money(it.get("icms_origem_fatura") or it.get("ICMS Origem R$")),
                "peso_valor_candidatos": list(it.get("peso_valor_candidatos") or []),
            })
        return clean

    def _doc_invoice(doc):
        if not isinstance(doc, dict):
            return ""
        for k in ("fatura", "Fatura", "numero_fatura", "invoice"):
            fat = _fmt_fatura(doc.get(k))
            if fat:
                return fat
        txt = str(doc.get("texto") or doc.get("text") or "")
        for pat in (
            r"N\s*[ºO°.]?\s*do\s+Documento\s*:\s*(0*\d{3,9}\s*[-/]\s*\d)",
            r"FATU?RA\s*(?:N[ºO°.]*)?\s*[:#-]?\s*(?:Emiss[aã]o\s*:\s*\d{2}/\d{2}/\d{4})?\s*(0*\d{3,9}\s*[-/]\s*\d)",
        ):
            m = _re.search(pat, txt, _re.I)
            if m:
                return _fmt_fatura(m.group(1))
        try:
            p = str(doc.get("path") or doc.get("arquivo") or "")
            m = _re.search(r"(?:FAT(?:URA|UARA)?\.?|Fat)\s*0*(\d{3,9})\s*[- ]?\s*(\d)?", _Path(p).stem, _re.I)
            if m and m.group(2):
                return f"{(_clean_num(m.group(1)) or '0').zfill(7)}-{m.group(2)}"
        except Exception:
            pass
        return ""

    def _doc_partner(doc):
        if not isinstance(doc, dict):
            return ""
        for k in ("parceiro", "Parceiro", "partner", "nome_parceiro"):
            v = _norm_space(doc.get(k))
            if v and _norm(v) not in {"FATURA", "FATURAMENSAL", "RODOVITOR"}:
                return v
        txt = str(doc.get("texto") or "")
        invalid = ("AGENCIA", "CODIGO DO BENEFICIARIO", "NOSSO NUMERO", "VENCIMENTO", "VALOR DO DOCUMENTO", "PROCESSADO POR")
        pats = [
            r"Transportador\s*[:\-]?\s*([^\n\r]+)",
            r"Cedente\s*[:\-]?\s*([^\n\r]+)",
            # Cabeçalho principal das faturas SSW: empresa imediatamente antes de Pág.
            r"(?m)^\s*([A-Z0-9À-Ü&. /'\-]{5,100}?)\s+P[áa]g\s*:\s*\d+\s*/\s*\d+",
            # Beneficiário costuma vir na linha seguinte ao título da coluna.
            r"Benefici[áa]rio[^\n\r]*[\n\r]+\s*([^\n\r]+)",
            r"Benefici[áa]rio\s*[:\-]?\s*([^\n\r]+)",
        ]
        for pat in pats:
            for m in _re.finditer(pat, txt, _re.I):
                val = _norm_space(m.group(1))
                val_norm = _strip_accents(val).upper()
                if not val or any(token in val_norm for token in invalid):
                    continue
                # Remove endereço/CNPJ que às vezes vêm colados após o nome.
                val = _re.split(r"\s+-\s+CNPJ\s*:|\s+CNPJ\s*:", val, maxsplit=1, flags=_re.I)[0]
                if val:
                    return val[:100]
        return ""

    def _doc_items_map(self):
        out = {}
        order = []
        partner_by_fat = {}
        seen_docs = set()
        for doc in getattr(self, "invoice_docs", []) or []:
            if not isinstance(doc, dict):
                continue
            fat = _doc_invoice(doc)
            txt = doc.get("texto") or doc.get("text") or ""
            if not fat:
                continue
            path = _norm_space(doc.get("path") or doc.get("arquivo") or "")
            doc_key = (fat, _norm(path), len(str(txt)), str(txt)[:200])
            if doc_key in seen_docs:
                continue
            seen_docs.add(doc_key)
            if fat not in out:
                out[fat] = []
                order.append(fat)
            items = []
            if txt:
                items = _extract_frete_terceiro_items(txt) or _extract_cte_rps_items(txt)
            if not items:
                items = _items_from_doc_existing(doc)
            clean = []
            for seq, it in enumerate(items or [], 1):
                c = _clean_cte(it.get("cte") or it.get("subcontrato"))
                n = _clean_nf(it.get("nf"))
                v = round(float(it.get("valor") or 0.0), 2)
                if not c:
                    continue
                clean.append({
                    "cte": c,
                    "subcontrato": c,
                    "nf": n,
                    "valor": v,
                    "base_cte": it.get("base_cte") or "",
                    "ctrc_origem_raw": it.get("ctrc_origem_raw") or "",
                    "layout": it.get("layout") or "FATURA",
                    "valor_nota_fatura": round(float(it.get("valor_nota_fatura") or 0.0), 2),
                    "peso_fatura": round(float(it.get("peso_fatura") or 0.0), 3),
                    "icms_fatura": round(float(it.get("icms_fatura") or 0.0), 2),
                    "comissao_fatura": round(float(it.get("comissao_fatura") or v or 0.0), 2),
                    "frete_origem_fatura": round(float(it.get("frete_origem_fatura") or 0.0), 2),
                    "icms_origem_fatura": round(float(it.get("icms_origem_fatura") or 0.0), 2),
                    "peso_valor_candidatos": list(it.get("peso_valor_candidatos") or []),
                    "fatura": fat,
                    "fatura_chave": _fatura_key(fat),
                    "sequencia": seq,
                    "arquivo": path,
                })
            if clean:
                out[fat].extend(clean)
            explicit_partner = ""
            for partner_key in ("parceiro", "Parceiro", "partner", "nome_parceiro"):
                explicit_partner = _norm_space(doc.get(partner_key))
                if explicit_partner:
                    break
            partner = explicit_partner or _doc_partner(doc)
            if explicit_partner:
                partner_by_fat[fat] = explicit_partner
            elif partner and fat not in partner_by_fat:
                partner_by_fat[fat] = partner
        return out, order, partner_by_fat

    def _read_base_rows_from_xlsx(path):
        rows = []
        try:
            reader = globals().get("read_xlsx_sheet")
            if callable(reader):
                rows = reader(path)
        except Exception:
            rows = []
        if not rows:
            try:
                import openpyxl as _openpyxl
                wb = _openpyxl.load_workbook(path, read_only=True, data_only=True)
                ws = wb.active
                rows = [list(r) for r in ws.iter_rows(values_only=True)]
                wb.close()
            except Exception:
                rows = []
        if not rows:
            return []
        headers = list(rows[0])
        idx = {_norm(h): i for i, h in enumerate(headers) if str(h or "").strip()}
        def pick(*names):
            for name in names:
                exact = idx.get(_norm(name))
                if exact is not None:
                    return exact
            for name in names:
                nn = _norm(name)
                for h, i in idx.items():
                    if h == nn or nn in h or h in nn:
                        return i
            return None
        c_nf = pick("Numero da Nota Fiscal", "Número da Nota Fiscal", "Nota Fiscal", "NF")
        c_ctrc = pick("Serie/Numero CTRC", "Série/Número CTRC")
        c_cte = pick("Serie/Numero CT-e", "Série/Número CT-e", "Serie/Numero CTe")
        c_tipo = pick("Tipo do Documento")
        c_val = pick("Valor do Frete")
        c_val_origem = pick("Valor do Frete do CTRC Origem", "Valor do Frete CT-e Origem", "Valor Frete Origem")
        c_com_exp = pick("Valor da Comissao de Expedicao")
        c_com_rec = pick("Valor da Comissao de Recepcao")
        c_dy = pick("Compr. de Entrega Escaneado", "Comprovante de Entrega Escaneado", "Comprovante")
        c_dt = pick("Data do Escaneamento")
        c_hr = pick("Hora do Escaneamento")
        c_ctrc_origem = pick("CTRC Origem")
        c_cte_origem = pick("CTe Origem", "CT-e Origem")
        c_fatura_exp = pick("Fatura do Subcon Exp Conferida Opcao 607")
        c_fatura_rec = pick("Fatura do Subcon Rec Conferida Opcao 607")
        c_origem_cidade = pick("Cidade origem da prestacao", "Cidade do Expedidor", "Cidade do Remetente")
        c_origem_uf = pick("UF origem da prestacao", "UF do Expedidor", "UF do Remetente")
        c_destino_cidade = pick("Cidade de Entrega", "Cidade do Destinatario")
        c_destino_uf = pick("UF de Entrega", "UF do Destinatario")
        c_destinatario_cidade = pick("Cidade do Destinatario")
        c_destinatario_uf = pick("UF do Destinatario")
        c_destinatario_nome = pick("Cliente Destinatario", "Destinatario")
        c_destinatario_endereco = pick("Endereco do Destinatario")
        c_destinatario_bairro = pick("Bairro do Destinatario")
        c_remetente_nome = pick("Cliente Remetente", "Remetente")
        c_recebedor_nome = pick("Cliente Recebedor", "Recebedor")
        c_recebedor_municipio = pick("Municipio do Recebedor", "Cidade do Recebedor")
        c_local_entrega = pick("Local de Entrega")
        c_endereco_entrega = pick("Endereco de Entrega", "Endereco")
        c_bairro_entrega = pick("Bairro de Entrega", "Bairro")
        c_cep_entrega = pick("CEP de Entrega", "CEP")
        c_peso_real = pick("Peso Real em Kg")
        c_peso_calc = pick("Peso Calculado em Kg")
        c_cubagem = pick("Cubagem em m3")
        c_val_sem_icms = pick("Valor do Frete sem ICMS")
        c_val_mercadoria = pick("Valor da Mercadoria")
        c_frete_peso = pick("Frete Peso")
        c_frete_valor = pick("Frete Valor")
        c_pedagio = pick("Pedagio", "Pedágio")
        c_modalidade = pick("Modalidade")
        out = []
        if c_nf is None:
            return out
        for row in rows[1:]:
            try:
                nf = _clean_nf(row[c_nf] if c_nf < len(row) else "")
                if not nf:
                    continue
                val = _parse_money(row[c_val] if c_val is not None and c_val < len(row) else 0)
                val_org = _parse_money(row[c_val_origem] if c_val_origem is not None and c_val_origem < len(row) else 0)
                tipo = str(row[c_tipo] if c_tipo is not None and c_tipo < len(row) else "").strip()
                cte = str(row[c_cte] if c_cte is not None and c_cte < len(row) else "").strip()
                ctrc = str(row[c_ctrc] if c_ctrc is not None and c_ctrc < len(row) else "").strip()
                ctrc_org = str(row[c_ctrc_origem] if c_ctrc_origem is not None and c_ctrc_origem < len(row) else "").strip()
                cte_org = str(row[c_cte_origem] if c_cte_origem is not None and c_cte_origem < len(row) else "").strip()
                fat_exp_raw = row[c_fatura_exp] if c_fatura_exp is not None and c_fatura_exp < len(row) else ""
                fat_rec_raw = row[c_fatura_rec] if c_fatura_rec is not None and c_fatura_rec < len(row) else ""
                fat_exp_key = _fatura_key(fat_exp_raw)
                fat_rec_key = _fatura_key(fat_rec_raw)
                fat_keys = tuple(k for k in (fat_exp_key, fat_rec_key) if k)
                out.append({
                    "nf": nf,
                    "cte": cte,
                    "ctrc": ctrc,
                    "ctrc_origem": ctrc_org,
                    "cte_origem": cte_org,
                    "tipo_doc": tipo,
                    "valor": round(val, 2),
                    "valor_origem": round(val_org, 2),
                    "comissao_exp": round(_parse_money(row[c_com_exp] if c_com_exp is not None and c_com_exp < len(row) else 0), 2),
                    "comissao_rec": round(_parse_money(row[c_com_rec] if c_com_rec is not None and c_com_rec < len(row) else 0), 2),
                    "dy": str(row[c_dy] if c_dy is not None and c_dy < len(row) else "").strip().upper(),
                    "data_scan": str(row[c_dt] if c_dt is not None and c_dt < len(row) else "").strip(),
                    "hora_scan": str(row[c_hr] if c_hr is not None and c_hr < len(row) else "").strip(),
                    "fatura_exp": _norm_space(fat_exp_raw),
                    "fatura_rec": _norm_space(fat_rec_raw),
                    "fatura_exp_key": fat_exp_key,
                    "fatura_rec_key": fat_rec_key,
                    "fatura_keys": fat_keys,
                    "fatura_base": " / ".join(k for k in (_norm_space(fat_exp_raw), _norm_space(fat_rec_raw)) if k),
                    "origem_cidade": _route_norm(row[c_origem_cidade] if c_origem_cidade is not None and c_origem_cidade < len(row) else ""),
                    "origem_uf": _route_norm(row[c_origem_uf] if c_origem_uf is not None and c_origem_uf < len(row) else ""),
                    "destino_cidade": _route_norm(row[c_destino_cidade] if c_destino_cidade is not None and c_destino_cidade < len(row) else ""),
                    "destino_uf": _route_norm(row[c_destino_uf] if c_destino_uf is not None and c_destino_uf < len(row) else ""),
                    "destinatario_cidade": _route_norm(row[c_destinatario_cidade] if c_destinatario_cidade is not None and c_destinatario_cidade < len(row) else ""),
                    "destinatario_uf": _route_norm(row[c_destinatario_uf] if c_destinatario_uf is not None and c_destinatario_uf < len(row) else ""),
                    "destinatario_nome": _norm_space(row[c_destinatario_nome] if c_destinatario_nome is not None and c_destinatario_nome < len(row) else ""),
                    "destinatario_endereco": _norm_space(row[c_destinatario_endereco] if c_destinatario_endereco is not None and c_destinatario_endereco < len(row) else ""),
                    "destinatario_bairro": _norm_space(row[c_destinatario_bairro] if c_destinatario_bairro is not None and c_destinatario_bairro < len(row) else ""),
                    "remetente_nome": _norm_space(row[c_remetente_nome] if c_remetente_nome is not None and c_remetente_nome < len(row) else ""),
                    "recebedor_nome": _norm_space(row[c_recebedor_nome] if c_recebedor_nome is not None and c_recebedor_nome < len(row) else ""),
                    "recebedor_municipio": _route_norm(row[c_recebedor_municipio] if c_recebedor_municipio is not None and c_recebedor_municipio < len(row) else ""),
                    "local_entrega": _norm_space(row[c_local_entrega] if c_local_entrega is not None and c_local_entrega < len(row) else ""),
                    "endereco_entrega": _norm_space(row[c_endereco_entrega] if c_endereco_entrega is not None and c_endereco_entrega < len(row) else ""),
                    "bairro_entrega": _norm_space(row[c_bairro_entrega] if c_bairro_entrega is not None and c_bairro_entrega < len(row) else ""),
                    "cep_entrega": _norm_space(row[c_cep_entrega] if c_cep_entrega is not None and c_cep_entrega < len(row) else ""),
                    "peso_real": round(_parse_money(row[c_peso_real] if c_peso_real is not None and c_peso_real < len(row) else 0), 3),
                    "peso_calculado": round(_parse_money(row[c_peso_calc] if c_peso_calc is not None and c_peso_calc < len(row) else 0), 3),
                    "cubagem": round(_parse_money(row[c_cubagem] if c_cubagem is not None and c_cubagem < len(row) else 0), 6),
                    "valor_sem_icms": round(_parse_money(row[c_val_sem_icms] if c_val_sem_icms is not None and c_val_sem_icms < len(row) else 0), 2),
                    "valor_mercadoria": round(_parse_money(row[c_val_mercadoria] if c_val_mercadoria is not None and c_val_mercadoria < len(row) else 0), 2),
                    "frete_peso": round(_parse_money(row[c_frete_peso] if c_frete_peso is not None and c_frete_peso < len(row) else 0), 2),
                    "frete_valor": round(_parse_money(row[c_frete_valor] if c_frete_valor is not None and c_frete_valor < len(row) else 0), 2),
                    "pedagio": round(_parse_money(row[c_pedagio] if c_pedagio is not None and c_pedagio < len(row) else 0), 2),
                    "modalidade": _norm_space(row[c_modalidade] if c_modalidade is not None and c_modalidade < len(row) else ""),
                })
            except Exception:
                continue
        return out

    def _app_dir():
        candidates = []
        try:
            fn = globals().get("app_runtime_dir")
            if callable(fn):
                candidates.append(_Path(fn()))
        except Exception:
            pass
        try:
            candidates.append(_Path(_sys.executable).resolve().parent)
        except Exception:
            pass
        try:
            candidates.append(_Path.cwd())
        except Exception:
            pass
        try:
            candidates.append(_Path(__file__).resolve().parents[1])
        except Exception:
            pass
        for p in candidates:
            try:
                if p and p.exists():
                    return p
            except Exception:
                pass
        return _Path.cwd()

    def _find_base_path(self):
        candidates = []
        for obj in (self, getattr(self, "master", None), getattr(self, "app", None), getattr(self, "controller", None), _main):
            try:
                p = getattr(obj, "base_path", "")
                if p:
                    candidates.append(p)
            except Exception:
                pass
        for rel in ("bases/base_rodovitor.xlsx", "_internal/bases/base_rodovitor.xlsx"):
            try:
                candidates.append(str(_app_dir() / rel))
            except Exception:
                pass
        for p in candidates:
            try:
                pp = _Path(p)
                if pp.exists():
                    return str(pp)
            except Exception:
                pass
        return ""

    def _base_index(self):
        cache = getattr(self, "_faturas_base_index_2664", None)
        base_path = _find_base_path(self)
        try:
            st = _Path(base_path).stat() if base_path else None
            key = f"{base_path}|{getattr(st, 'st_size', 0)}|{getattr(st, 'st_mtime', 0)}"
        except Exception:
            key = str(base_path or "")
        if isinstance(cache, dict) and cache.get("key") == key:
            return cache
        rows = _read_base_rows_from_xlsx(base_path) if base_path else []
        by_nf = {}; by_cte = {}; by_fatura = {}
        for r in rows:
            nf = r.get("nf") or ""
            if nf:
                by_nf.setdefault(nf, []).append(r)
            for fk in r.get("fatura_keys") or ():
                by_fatura.setdefault(fk, []).append(r)
            for k in (r.get("cte"), r.get("ctrc"), r.get("ctrc_origem"), r.get("cte_origem")):
                ck = _cte_key(k)
                if ck and _valid_base_cte(k):
                    by_cte.setdefault(ck, []).append(r)
        idx = {"key": key, "path": base_path, "rows": rows, "by_nf": by_nf, "by_cte": by_cte, "by_fatura": by_fatura}
        try:
            self._faturas_base_index_2664 = idx
        except Exception:
            pass
        return idx

    def _is_complementar_base(row):
        t = _strip_accents(str((row or {}).get("tipo_doc") or "")).upper()
        return any(k in t for k in ("COMPLEMENT", "COMPL", "CUSTO EXTRA", "CUSTO ADICIONAL"))

    def _value_close(a, b, tol=0.06):
        try:
            return abs(float(a or 0.0) - float(b or 0.0)) <= tol
        except Exception:
            return False

    def _row_values(row, fat_key=""):
        row = row or {}
        vals = []
        if fat_key and row.get("fatura_exp_key") == fat_key:
            vals.append(float(row.get("comissao_exp") or 0.0))
        if fat_key and row.get("fatura_rec_key") == fat_key:
            vals.append(float(row.get("comissao_rec") or 0.0))
        if not vals:
            vals.append(float(row.get("valor") or 0.0))
        return list(dict.fromkeys(round(v, 2) for v in vals))

    def _row_value(row, fat_key="", item_value=None):
        vals = _row_values(row, fat_key)
        if item_value is None or not vals:
            return vals[0] if vals else 0.0
        return min(vals, key=lambda v: abs(float(v) - float(item_value or 0.0)))

    def _row_has_cte(row, value):
        key = _cte_key(value)
        if not key or not _valid_base_cte(value):
            return False
        return any(_cte_key((row or {}).get(k)) == key for k in ("cte", "ctrc", "ctrc_origem", "cte_origem"))

    def _match_base(self, fat, item):
        idx = _base_index(self)
        if not idx or not idx.get("rows"):
            return None, "BASE NÃO CARREGADA"
        fat_key = _fatura_key(fat)
        nf = _clean_nf(item.get("nf"))
        val = round(float(item.get("valor") or 0.0), 2)
        base_cte = item.get("base_cte") or ""
        layout = _norm(item.get("layout") or "")
        candidates = []

        # Prioridade segura para complementar/custo extra: NF + valor exatos e
        # tipo complementar. Isso acontece antes do fallback por NF global.
        # A fatura EN/ER pode estar desatualizada pelo parceiro; por isso uma
        # única linha complementar exata pode ser aceita e o vínculo divergente
        # permanece apenas como aviso no log.
        if nf and val:
            comp_rows = [
                r for r in (idx.get("by_nf", {}).get(nf, []) or [])
                if _is_complementar_base(r) and _value_close(_row_value(r, fat_key, val), val)
            ]
            anchors = [value for value in (base_cte, item.get("cte")) if _valid_base_cte(value)]
            anchored_comp = [r for r in comp_rows if any(_row_has_cte(r, anchor) for anchor in anchors)]
            selected_comp = anchored_comp if len(anchored_comp) == 1 else comp_rows
            normal_same_value = [
                r for r in (idx.get("by_nf", {}).get(nf, []) or [])
                if not _is_complementar_base(r) and _value_close(_row_value(r, fat_key, val), val)
            ]
            if len(selected_comp) == 1 and (anchored_comp or not normal_same_value):
                candidates.append((1000, selected_comp[0], "COMPLEMENTAR_NF_VALOR_PRIORITARIO"))

        # Regra principal: primeiro a fatura de subcontratação (EN/ER), depois NF/CTRC/valor.
        fatura_rows = list(idx.get("by_fatura", {}).get(fat_key, []) or []) if fat_key else []
        if fatura_rows:
            scoped = [r for r in fatura_rows if nf and r.get("nf") == nf]
            if not nf:
                anchors = []
                if _valid_base_cte(base_cte):
                    anchors.append(base_cte)
                if "FRETETERCEIRO" not in layout and _valid_base_cte(item.get("cte")):
                    anchors.append(item.get("cte"))
                scoped = [r for r in fatura_rows if any(_row_has_cte(r, anchor) for anchor in anchors)]
            for r in scoped:
                expected = _row_value(r, fat_key, val)
                score = 200
                if nf and r.get("nf") == nf:
                    score += 100
                if _valid_base_cte(base_cte) and _row_has_cte(r, base_cte):
                    score += 80
                if "FRETETERCEIRO" not in layout and _valid_base_cte(item.get("cte")) and _row_has_cte(r, item.get("cte")):
                    score += 70
                if val and _value_close(expected, val):
                    score += 60
                elif val:
                    score -= min(int(abs(expected - val)), 60)
                if _is_complementar_base(r):
                    score += 5
                candidates.append((score, r, "FATURA_EN_ER"))

        # CT-e/CTRC exato para layouts sem EN/ER. O candidato não pode estar
        # atribuído a outra fatura. Em FRETE TERCEIRO usa somente o CTRC Origem,
        # pois o número exibido é o subcontrato do parceiro.
        if not candidates:
            anchors = []
            if _valid_base_cte(base_cte):
                anchors.append((base_cte, "CTRC_ORIGEM_EXATO"))
            if "FRETETERCEIRO" not in layout and _valid_base_cte(item.get("cte")):
                anchors.append((item.get("cte"), "CTE_CTRC_EXATO"))
            seen_rows = set()
            for anchor, anchor_mode in anchors:
                for r in idx.get("by_cte", {}).get(_cte_key(anchor), []) or []:
                    row_id = id(r)
                    if row_id in seen_rows:
                        continue
                    seen_rows.add(row_id)
                    keys = set(r.get("fatura_keys") or ())
                    if keys and fat_key not in keys:
                        continue
                    if nf and r.get("nf") != nf:
                        continue
                    expected = _row_value(r, fat_key, val)
                    score = 180
                    if nf and r.get("nf") == nf:
                        score += 80
                    if val and _value_close(expected, val):
                        score += 30
                    candidates.append((score, r, anchor_mode))

        # Exceção controlada: complementar sem EN/ER, com NF e valor exatos.
        # Uma linha atribuída a outra fatura nunca participa deste fallback.
        if not candidates and nf and val:
            for r in idx.get("by_nf", {}).get(nf, []) or []:
                keys = set(r.get("fatura_keys") or ())
                if keys and fat_key not in keys:
                    continue
                if not _is_complementar_base(r):
                    continue
                expected = _row_value(r, fat_key, val)
                if not _value_close(expected, val):
                    continue
                score = 150
                if _valid_base_cte(base_cte) and _row_has_cte(r, base_cte):
                    score += 40
                candidates.append((score, r, "COMPLEMENTAR_NF_VALOR"))

        # Reapresentação: EN/ER pode conservar a fatura anterior. Se a NF for
        # única na base, ela continua sendo uma prova determinística do item.
        # Havendo repetição, só aceita um único candidato desempatado por CT-e,
        # CTRC Origem ou valor exato.
        if not candidates and nf:
            nf_rows = list(idx.get("by_nf", {}).get(nf, []) or [])
            chosen = []
            if len(nf_rows) == 1:
                chosen = nf_rows
            elif nf_rows:
                anchors = []
                if _valid_base_cte(base_cte):
                    anchors.append(base_cte)
                if "FRETETERCEIRO" not in layout and _valid_base_cte(item.get("cte")):
                    anchors.append(item.get("cte"))
                anchored = [r for r in nf_rows if any(_row_has_cte(r, anchor) for anchor in anchors)]
                if len(anchored) == 1:
                    chosen = anchored
                else:
                    valued = [r for r in nf_rows if val and _value_close(_row_value(r, fat_key, val), val)]
                    if len(valued) == 1:
                        chosen = valued
            for r in chosen:
                candidates.append((120, r, "NF_GLOBAL_REAPRESENTACAO"))

        if not candidates:
            return None, "NÃO LOCALIZADO NA BASE"
        candidates.sort(key=lambda x: x[0], reverse=True)
        best_score, best, mode = candidates[0]
        if len(candidates) > 1 and candidates[1][0] == best_score and candidates[1][1] is not best:
            return None, "MATCH AMBÍGUO NA BASE"

        # Proteção adicional: quando a NF não saiu do PDF, só a preenche pela
        # base se o CTRC Origem apontar para uma única linha em toda a base.
        # Assim não existe preenchimento por NF global nem por aproximação.
        if not nf and _valid_base_cte(base_cte):
            exact_rows = []
            seen_exact = set()
            for r in idx.get("by_cte", {}).get(_cte_key(base_cte), []) or []:
                if not _row_has_cte(r, base_cte):
                    continue
                rid = id(r)
                if rid in seen_exact:
                    continue
                seen_exact.add(rid)
                exact_rows.append(r)
            if len(exact_rows) == 1 and exact_rows[0] is best and best.get("nf"):
                item["_nf_base_fallback"] = _clean_nf(best.get("nf"))
                item["_nf_source"] = "BASE_CTRC_ORIGEM_UNICO"
        return best, mode

    def _existing_partner_map(self):
        out = {}
        for row in getattr(self, "invoice_rows", []) or []:
            try:
                fat = _fmt_fatura(row[0])
                partner = _norm_space(row[1]) if len(row) > 1 else ""
                if fat and partner:
                    out[fat] = partner
            except Exception:
                pass
        for rec in getattr(self, "invoice_detail_records", []) or []:
            try:
                fat = _fmt_fatura(rec.get("Fatura"))
                partner = _norm_space(rec.get("Parceiro"))
                if fat and partner and fat not in out:
                    out[fat] = partner
            except Exception:
                pass
        return out


    def _base_fatura_link(base_row, fat_key):
        """Classifica o vínculo EN/ER apenas para auditoria, sem bloquear lançamentos manuais."""
        if not base_row:
            return "SEM BASE", "Base Rodovitor não localizada.", ""
        exp_key = str(base_row.get("fatura_exp_key") or "")
        rec_key = str(base_row.get("fatura_rec_key") or "")
        exp_raw = _norm_space(base_row.get("fatura_exp") or "")
        rec_raw = _norm_space(base_row.get("fatura_rec") or "")
        if fat_key and exp_key == fat_key and rec_key == fat_key:
            return "CONFIRMADA EN/ER", "Fatura confirmada nas colunas de expedição e recepção.", ""
        if fat_key and exp_key == fat_key:
            return "CONFIRMADA EN", "Fatura confirmada na coluna de expedição (EN).", ""
        if fat_key and rec_key == fat_key:
            return "CONFIRMADA ER", "Fatura confirmada na coluna de recepção (ER).", ""
        if not exp_key and not rec_key:
            return (
                "LANÇAMENTO MANUAL",
                "Colunas EN/ER vazias. Tratado como lançamento manual válido no sistema Rodovitor.",
                "Lançamento manual: ausência de vínculo EN/ER é informativa e não altera o status.",
            )
        base_labels = " / ".join(x for x in (exp_raw, rec_raw) if x) or "não informada"
        return (
            "FATURA BASE DIVERGENTE - INFORMATIVO",
            f"A base registra a fatura {base_labels}. Divergência atribuída à atualização do parceiro e não usada para bloquear o CT-e.",
            f"Fatura divergente na base ({base_labels}); aviso informativo, sem alterar o status final.",
        )

    def _match_mode_text(mode):
        labels = {
            "FATURA_EN_ER": "Fatura EN/ER + NF/CTRC",
            "CTRC_ORIGEM_EXATO": "CTRC Origem exato",
            "CTE_CTRC_EXATO": "CT-e/CTRC exato",
            "COMPLEMENTAR_NF_VALOR": "Complementar por NF + valor",
            "NF_GLOBAL_REAPRESENTACAO": "NF global única/reapresentação",
            "BASE NÃO CARREGADA": "Base não carregada",
            "NÃO LOCALIZADO NA BASE": "Não localizado na base",
            "MATCH AMBÍGUO NA BASE": "Correspondência ambígua",
        }
        return labels.get(str(mode or ""), str(mode or "Não informado"))

    def _decision_trace(rec, item, base_row, mode):
        fat_key = str(rec.get("Fatura chave") or "")
        cte_pdf = str(rec.get("CT-e fatura") or rec.get("CT-e") or "-")
        nf_usada = str(rec.get("NF fatura") or rec.get("NF") or "-")
        nf_pdf_original = str(rec.get("NF PDF original") or "-")
        origem_nf = str(rec.get("Origem NF") or "NÃO IDENTIFICADA")
        arquivo = ""
        try:
            arquivo = _Path(str(item.get("arquivo") or "")).name
        except Exception:
            arquivo = str(item.get("arquivo") or "")
        etapa_pdf = f"PDF {arquivo or '-'}: CT-e {cte_pdf}, NF original {nf_pdf_original}, valor {_money(rec.get('Valor fatura') or 0.0)}"
        metodo = _match_mode_text(mode)
        if base_row:
            etapa_busca = f"Base localizada por {metodo}"
            nf_base = str(base_row.get("nf") or "-")
            if origem_nf == "BASE_CTRC_ORIGEM_UNICO" and nf_usada != "-":
                etapa_nf = f"NF {nf_usada} preenchida pela base porque o CTRC Origem possui correspondência única"
                nf_check = "PREENCHIDA PELA BASE - CTRC ÚNICO"
            elif nf_pdf_original != "-" and nf_base != "-" and _clean_nf(nf_pdf_original) == _clean_nf(nf_base):
                etapa_nf = f"NF confirmada na mesma linha da base ({nf_base})"
                nf_check = "CONFERE"
            elif nf_pdf_original == "-":
                etapa_nf = f"NF não extraída do PDF; base informa {nf_base}, mas o CTRC não foi único para preenchimento automático"
                nf_check = "NF AUSENTE NO PDF"
            else:
                etapa_nf = f"NF do PDF {nf_pdf_original} difere da NF da base {nf_base}"
                nf_check = "DIVERGE"
        else:
            etapa_busca = f"Base não localizada ({metodo})"
            etapa_nf = "NF não pôde ser confirmada na base"
            nf_check = "NÃO VALIDADA"

        vinculo, etapa_vinculo, aviso_vinculo = _base_fatura_link(base_row, fat_key)
        tipo = str(rec.get("Tipo documento base") or "-")
        tipo_norm = _strip_accents(tipo).upper()
        avisos = []
        if aviso_vinculo:
            avisos.append(aviso_vinculo)
        if "CORTESIA" in tipo_norm:
            etapa_tipo = "Tipo CORTESIA/DEVOLUÇÃO: valor base simbólico; a cobrança do serviço do parceiro é permitida"
            avisos.append("Cortesia/devolução: diferença de valor é apenas informativa e não bloqueia o pagamento.")
        elif "COMPLEMENT" in tipo_norm:
            etapa_tipo = f"Tipo {tipo}: documento complementar"
        else:
            etapa_tipo = f"Tipo de documento: {tipo}"

        status_final = str(rec.get("Status final CT-e") or rec.get("Status CT-e") or "-")
        if "OK COMPLEMENTAR" in status_final:
            etapa_comprovante = "Documento complementar: comprovante de entrega dispensado"
        elif str(rec.get("DY") or "").upper() == "S":
            etapa_comprovante = "DY=S: comprovante de entrega localizado"
        elif base_row:
            etapa_comprovante = "DY=N/vazio: comprovante de entrega não localizado"
        else:
            etapa_comprovante = "Comprovante não validado porque o documento não foi localizado na base"

        status_valor = str(rec.get("Status valor") or "-")
        detalhe_valor = str(rec.get("Detalhe validação valor") or "").strip()
        etapa_valor = f"Valor: {status_valor}" + (f" ({detalhe_valor})" if detalhe_valor else "")
        if "DIVERGENTE" in _strip_accents(status_valor).upper() and "INFORMATIVO" in _strip_accents(status_valor).upper():
            avisos.append("Divergência de valor registrada apenas como informativa nesta versão; o status financeiro não foi alterado.")

        caminho = " → ".join([
            etapa_pdf,
            etapa_busca,
            etapa_nf,
            etapa_vinculo,
            etapa_tipo,
            etapa_comprovante,
            etapa_valor,
            f"STATUS FINAL: {status_final}",
        ])
        return {
            "Confirmação NF": nf_check,
            "Origem NF": origem_nf,
            "Vínculo fatura": vinculo,
            "Etapa leitura PDF": etapa_pdf,
            "Etapa busca base": etapa_busca,
            "Etapa confirmação NF": etapa_nf,
            "Etapa vínculo fatura": etapa_vinculo,
            "Etapa tipo documento": etapa_tipo,
            "Etapa comprovante": etapa_comprovante,
            "Etapa valor": etapa_valor,
            "Método de busca": metodo,
            "Caminho do status": caminho,
            "Avisos auditoria": " | ".join(dict.fromkeys(avisos)) if avisos else "-",
        }

    def _record_first(rec, *keys):
        if not isinstance(rec, dict):
            return ""
        for key in keys:
            try:
                value = rec.get(key)
            except Exception:
                value = None
            if value is not None and str(value).strip() != "":
                return value
        return ""

    def _legacy_value_signature(entry):
        return (
            str(entry.get("classificacao") or ""),
            round(float(entry.get("valor_xml") or 0.0), 2),
            round(float(entry.get("valor_calculado") or 0.0), 2),
            round(float(entry.get("diferenca") or 0.0), 2),
            str(entry.get("regra") or ""),
            bool(entry.get("confiavel")),
        )

    def _capture_legacy_value_results(self):
        """Captura somente a validação de valor do fluxo anterior.

        A lista canônica, NF, comprovante e status financeiro continuam sendo
        reconstruídos pelo motor 2.6.65. A ponte guarda apenas metadados de
        validação de valor para evitar o retorno dos clones do fluxo legado.
        """
        exact = {}
        fallback = {}
        captured = []
        for raw in list(getattr(self, "invoice_detail_records", []) or []):
            if not isinstance(raw, dict):
                continue
            fat_key = _fatura_key(_record_first(raw, "Fatura", "fatura", "numero_fatura", "Número da Fatura"))
            cte_key = _cte_key(_record_first(raw, "CT-e fatura", "CT-e", "CT-e base", "CTRC base", "cte", "cte_ref", "Subcontrato"))
            nf_key = _clean_nf(_record_first(raw, "NF fatura", "NF", "NF base", "nf", "nota_fiscal"))
            valor_fatura = round(_parse_money(_record_first(raw, "Valor fatura", "Valor CT-e", "Valor Fat.", "valor_fatura", "valor")), 2)
            valor_xml = round(_parse_money(_record_first(raw, "Valor XML", "Valor Xml", "valor_xml", "XML valor")), 2)
            valor_calculado = round(_parse_money(_record_first(raw, "Valor esperado", "Valor calculado", "Valor Calculado", "Valor tabela", "Valor Regra")), 2)
            diferenca_raw = _record_first(raw, "Diferença", "Diferenca", "Diferença XML", "Diferenca XML")
            diferenca = round(_parse_money(diferenca_raw), 2) if str(diferenca_raw or "").strip() else round(valor_fatura - valor_xml, 2) if valor_xml else 0.0
            status_raw = _norm_space(_record_first(raw, "Status valor", "Valor OK?", "Status Valor", "status_valor", "Resultado valor"))
            regra = _norm_space(_record_first(raw, "Regra aplicada", "Regra", "Regra parceiro", "Detalhe regra", "Componente XML"))
            status_norm = _strip_accents(status_raw).upper()

            classificacao = "NAO_CONFIAVEL"
            confiavel = False
            if "XML OPCIONAL" in status_norm or "OPCIONAL" in status_norm:
                classificacao = "XML_OPCIONAL"
            elif valor_xml > 0.004 and any(token in status_norm for token in ("VALOR OK", "OK - XML", "XML OK")):
                classificacao = "OK_REGRA" if regra else "OK_XML"
                confiavel = True
            elif valor_xml > 0.004 and status_norm in {"OK", "SIM", "APROVADO"}:
                classificacao = "OK_REGRA" if regra else "OK_XML"
                confiavel = True
            elif valor_xml > 0.004 and any(token in status_norm for token in ("DIVERG", "VALOR NAO", "VALOR NÃO", "NAO CONFERE", "NÃO CONFERE")):
                classificacao = "DIVERGENTE_XML"
                confiavel = True

            # Não importa registros sem chave mínima. Isso impede casamento por NF isolada.
            if not cte_key or valor_fatura <= 0:
                continue
            entry = {
                "fatura_key": fat_key,
                "cte_key": cte_key,
                "nf_key": nf_key,
                "valor_fatura": valor_fatura,
                "valor_xml": valor_xml,
                "valor_calculado": valor_calculado,
                "diferenca": diferenca,
                "status_raw": status_raw or "NÃO INFORMADO",
                "regra": regra,
                "classificacao": classificacao,
                "confiavel": confiavel,
            }
            captured.append(entry)
            if fat_key and nf_key:
                exact.setdefault((fat_key, cte_key, nf_key, valor_fatura), []).append(entry)
            if nf_key:
                fallback.setdefault((cte_key, nf_key, valor_fatura), []).append(entry)

        cache = {
            "exact": exact,
            "fallback": fallback,
            "captured": captured,
            "total": len(captured),
        }
        try:
            self._legacy_value_audit_26656 = cache
        except Exception:
            pass
        return cache

    def _unique_legacy_candidate(candidates):
        candidates = list(candidates or [])
        if not candidates:
            return None, "SEM RESULTADO LEGADO"
        unique = {}
        for candidate in candidates:
            unique[_legacy_value_signature(candidate)] = candidate
        if len(unique) == 1:
            return next(iter(unique.values())), ""
        return None, "RESULTADO LEGADO AMBÍGUO"

    def _find_legacy_value_result(self, fat, cte, nf, valor):
        cache = getattr(self, "_legacy_value_audit_26656", None) or {}
        fat_key = _fatura_key(fat)
        cte_key = _cte_key(cte)
        nf_key = _clean_nf(nf)
        valor_key = round(float(valor or 0.0), 2)
        if not cte_key or not nf_key or valor_key <= 0:
            return None, "CHAVE INCOMPLETA", "NÃO REAPROVEITADO"

        candidate, reason = _unique_legacy_candidate((cache.get("exact") or {}).get((fat_key, cte_key, nf_key, valor_key), []))
        if candidate:
            return candidate, "FATURA + CT-e + NF + VALOR", "EXATA"
        if reason == "RESULTADO LEGADO AMBÍGUO":
            return None, reason, "AMBÍGUA"

        candidate, reason = _unique_legacy_candidate((cache.get("fallback") or {}).get((cte_key, nf_key, valor_key), []))
        if candidate:
            return candidate, "CT-e + NF + VALOR (ÚNICO)", "ÚNICA"
        if reason == "RESULTADO LEGADO AMBÍGUO":
            return None, reason, "AMBÍGUA"
        return None, "SEM CORRESPONDÊNCIA EXATA", "NÃO REAPROVEITADO"

    def _apply_value_audit(self, rec, base_row, legacy, legacy_match, legacy_confidence):
        val = round(float(rec.get("Valor fatura") or 0.0), 2)
        expected = round(float(rec.get("Valor base") or 0.0), 2)
        tipo_norm = _strip_accents(str(rec.get("Tipo documento base") or "")).upper()

        rec["Valor XML"] = round(float((legacy or {}).get("valor_xml") or 0.0), 2) if legacy else 0.0
        rec["Valor calculado regra"] = round(float((legacy or {}).get("valor_calculado") or 0.0), 2) if legacy else 0.0
        rec["Diferença XML"] = round(float((legacy or {}).get("diferenca") or 0.0), 2) if legacy else 0.0
        rec["Regra aplicada valor"] = (legacy or {}).get("regra") or "-"
        rec["Confiança validação valor"] = legacy_confidence
        rec["Vínculo validação valor"] = legacy_match
        rec["Status valor legado"] = (legacy or {}).get("status_raw") or "-"

        if _is_complementar_base(base_row):
            rec["Status valor"] = "OK - COMPLEMENTAR"
            rec["Origem validação valor"] = "TIPO DOCUMENTO"
            rec["Detalhe validação valor"] = "Documento complementar/custo extra: valor tratado pela natureza do documento."
            return
        if "CORTESIA" in tipo_norm or "DEVOLU" in tipo_norm:
            rec["Status valor"] = "OK - SERVIÇO DO PARCEIRO"
            rec["Origem validação valor"] = "CORTESIA/DEVOLUÇÃO"
            rec["Detalhe validação valor"] = "Valor da base é simbólico ou referente à devolução; a cobrança do serviço do parceiro é permitida."
            return

        if legacy and legacy.get("confiavel"):
            classification = legacy.get("classificacao")
            if classification == "OK_REGRA":
                rec["Status valor"] = "OK - REGRA DO PARCEIRO"
                rec["Origem validação valor"] = "PROCESSAMENTO ANTERIOR / REGRA"
            elif classification == "OK_XML":
                rec["Status valor"] = "OK - XML"
                rec["Origem validação valor"] = "PROCESSAMENTO ANTERIOR / XML"
            elif classification == "DIVERGENTE_XML":
                rec["Status valor"] = "DIVERGENTE - XML (INFORMATIVO)"
                rec["Origem validação valor"] = "PROCESSAMENTO ANTERIOR / XML"
            else:
                rec["Status valor"] = "INFORMATIVO - VALIDAÇÃO LEGADA NÃO CLASSIFICADA"
                rec["Origem validação valor"] = "PROCESSAMENTO ANTERIOR"
            rec["Detalhe validação valor"] = (
                f"Resultado anterior reaproveitado por {legacy_match}; status original: {legacy.get('status_raw') or '-'}; "
                f"valor XML {_money(legacy.get('valor_xml') or 0.0)}; diferença {_money(legacy.get('diferenca') or 0.0)}."
            )
            return

        if _value_close(expected, val):
            rec["Status valor"] = "OK - BASE"
            rec["Origem validação valor"] = "BASE RODOVITOR"
            rec["Detalhe validação valor"] = f"Valor cobrado confere com o valor comparável da base ({_money(expected)})."
            return

        if legacy and legacy.get("classificacao") == "XML_OPCIONAL":
            rec["Status valor"] = "INFORMATIVO - XML NÃO UTILIZADO"
            rec["Origem validação valor"] = "XML OPCIONAL"
            rec["Detalhe validação valor"] = "O processamento anterior classificou o XML como opcional; isso não é convertido em valor validado."
            return

        rec["Status valor"] = "INFORMATIVO - BASE NÃO COMPARÁVEL"
        rec["Origem validação valor"] = "SEM VALIDAÇÃO DE VALOR CONFIÁVEL"
        rec["Detalhe validação valor"] = (
            f"O valor bruto/comissão da base ({_money(expected)}) não é usado sozinho para reprovar a cobrança do parceiro. "
            f"Validação legada: {legacy_match}."
        )

    def _find_partner_tables_path():
        candidates = [
            _app_dir() / "tabelas" / "cadastro_tabelas_parceiros.xlsx",
            _app_dir() / "_internal" / "tabelas" / "cadastro_tabelas_parceiros.xlsx",
        ]
        try:
            candidates.append(_Path(__file__).resolve().parents[1] / "tabelas" / "cadastro_tabelas_parceiros.xlsx")
        except Exception:
            pass
        for candidate in candidates:
            try:
                if candidate.exists():
                    return candidate
            except Exception:
                pass
        return None

    def _load_table_validator_module():
        cached = getattr(_main, "_faturas_table_validator_26657", None)
        if cached is not None:
            return cached
        module = None
        try:
            import importlib.util as _importlib_util
            module_path = _Path(__file__).resolve().parent / "faturas_table_validator_2_6_65_7.py"
            if module_path.exists():
                spec = _importlib_util.spec_from_file_location("faturas_table_validator_2_6_65_7", module_path)
                module = _importlib_util.module_from_spec(spec)
                spec.loader.exec_module(module)
        except Exception:
            module = None
        try:
            setattr(_main, "_faturas_table_validator_26657", module)
        except Exception:
            pass
        return module

    def _partner_tables_cache(self):
        path = _find_partner_tables_path()
        if not path:
            return None, "TABELA NÃO ENCONTRADA"
        try:
            stat = path.stat()
            cache_key = f"{path}|{stat.st_size}|{stat.st_mtime}"
        except Exception:
            cache_key = str(path)
        cache = getattr(self, "_partner_tables_faturas_26657", None)
        if isinstance(cache, dict) and cache.get("key") == cache_key:
            return cache.get("tables"), "CACHE"
        loader = globals().get("load_partner_tables")
        if not callable(loader):
            return None, "CARREGADOR DE TABELAS INDISPONÍVEL"
        try:
            tables = loader(path)
            self._partner_tables_faturas_26657 = {"key": cache_key, "tables": tables}
            return tables, str(path)
        except Exception as exc:
            return None, f"ERRO AO CARREGAR TABELA: {exc}"

    def _apply_table_validation_shadow(self, rec, item, base_row, partner):
        rec.update({
            "Status tabela parceiro": "NÃO CALCULADO - TABELA",
            "Parceiro tabela ID": "-",
            "Regra tabela ID": "-",
            "Fonte regra tabela": "-",
            "Valor esperado tabela": 0.0,
            "Diferença tabela": 0.0,
            "Tolerância tabela": 0.0,
            "Base cálculo tabela": 0.0,
            "Fonte base tabela": "-",
            "Peso usado tabela": 0.0,
            "Fonte peso tabela": "-",
            "Percentual tabela": 0.0,
            "Mínimo tabela": 0.0,
            "Caminho cálculo tabela": "-",
            "Aviso tabela": "-",
            "Destino original tabela": "-",
            "Destino comercial tabela": "-",
            "Fonte destino tabela": "-",
            "Aviso rota tabela": "-",
            "Modo tabela": "SOMBRA - NÃO ALTERA PAGAMENTO",
        })
        if not base_row or _is_complementar_base(base_row):
            return
        tipo_norm = _strip_accents(str(rec.get("Tipo documento base") or "")).upper()
        if "CORTESIA" in tipo_norm or "DEVOLU" in tipo_norm:
            return
        module = _load_table_validator_module()
        tables, table_source = _partner_tables_cache(self)
        if module is None or not tables:
            rec["Status tabela parceiro"] = "VALIDADOR/TABELA INDISPONÍVEL"
            rec["Aviso tabela"] = table_source
            return
        try:
            result = module.validate_invoice_value(
                partner_name=partner,
                item=item,
                base_row=base_row,
                tables=tables,
                choose_rule=globals().get("choose_partner_rule"),
                choose_weight_rule=globals().get("choose_weight_special_rule"),
            )
        except Exception as exc:
            rec["Status tabela parceiro"] = "ERRO NA VALIDAÇÃO DA TABELA"
            rec["Aviso tabela"] = str(exc)
            return
        rec.update({
            "Status tabela parceiro": result.get("status") or "NÃO CALCULADO - TABELA",
            "Parceiro tabela ID": result.get("partner_id") or "-",
            "Regra tabela ID": result.get("rule_id") or "-",
            "Fonte regra tabela": result.get("rule_source") or "-",
            "Valor esperado tabela": round(float(result.get("expected") or 0.0), 2),
            "Diferença tabela": round(float(result.get("difference") or 0.0), 2),
            "Tolerância tabela": round(float(result.get("tolerance") or 0.0), 2),
            "Base cálculo tabela": round(float(result.get("base_value") or 0.0), 2),
            "Fonte base tabela": result.get("base_source") or "-",
            "Peso usado tabela": round(float(result.get("weight") or 0.0), 3),
            "Fonte peso tabela": result.get("weight_source") or "-",
            "Percentual tabela": round(float(result.get("percent") or 0.0), 6),
            "Mínimo tabela": round(float(result.get("minimum") or 0.0), 2),
            "Caminho cálculo tabela": " → ".join(result.get("trace") or []) or "-",
            "Aviso tabela": result.get("warning") or "-",
            "Destino original tabela": result.get("route_original") or "-",
            "Destino comercial tabela": result.get("route_resolved") or "-",
            "Fonte destino tabela": result.get("route_source") or "-",
            "Aviso rota tabela": result.get("route_warning") or "-",
            "Modo tabela": f"SOMBRA - NÃO ALTERA PAGAMENTO | {result.get('calculation_mode') or 'MÉTODO NÃO INFORMADO'}",
        })
        code = result.get("code")
        if code == "OK":
            rec["Status valor"] = "OK - TABELA DO PARCEIRO"
        elif code == "OK_TOLERANCIA":
            rec["Status valor"] = "OK - TABELA COM TOLERÂNCIA"
        elif code == "DIVERGENTE":
            rec["Status valor"] = "DIVERGENTE - TABELA DO PARCEIRO (SOMBRA)"
        else:
            return
        rec["Origem validação valor"] = "TABELA DO PARCEIRO / DADOS DA FATURA"
        rec["Valor calculado regra"] = rec["Valor esperado tabela"]
        rec["Diferença XML"] = rec["Diferença tabela"]
        rec["Regra aplicada valor"] = rec["Regra tabela ID"]
        rec["Confiança validação valor"] = "CÁLCULO DETERMINÍSTICO - MODO SOMBRA"
        rec["Vínculo validação valor"] = f"{rec['Parceiro tabela ID']} | {rec['Fonte base tabela']}"
        rec["Detalhe validação valor"] = (
            f"Tabela {rec['Parceiro tabela ID']}; regra {rec['Regra tabela ID']}; "
            f"esperado {_money(rec['Valor esperado tabela'])}; cobrado {_money(rec.get('Valor fatura') or 0.0)}; "
            f"diferença {_money(rec['Diferença tabela'])}; tolerância {_money(rec['Tolerância tabela'])}. "
            "Validação em modo sombra: não altera comprovante nem valor não pagar."
        )

    def _resolve_invoice_fields_with_base(item, base_row):
        candidates = list((item or {}).get("peso_valor_candidatos") or [])
        if not candidates or not base_row or float((item or {}).get("peso_fatura") or 0.0) > 0:
            return item
        target_weight = float(base_row.get("peso_calculado") or base_row.get("peso_real") or 0.0)
        target_value = float(base_row.get("valor_mercadoria") or 0.0)
        if target_weight <= 0 and target_value <= 0:
            return item

        def score(candidate):
            weight = float(candidate.get("peso") or 0.0)
            value = float(candidate.get("valor_nota") or 0.0)
            sw = abs(weight - target_weight) / max(target_weight, 1.0) if target_weight > 0 else 0.0
            sv = abs(value - target_value) / max(target_value, 1.0) if target_value > 0 else 0.0
            # A mercadoria é a confirmação principal. Peso pode ser cubado e
            # diferir legitimamente da base.
            return sv * 20.0 + sw

        selected = min(candidates, key=score)
        selected_weight = float(selected.get("peso") or 0.0)
        selected_value = float(selected.get("valor_nota") or 0.0)
        value_ok = target_value <= 0 or abs(selected_value - target_value) <= max(1.0, target_value * 0.02)
        weight_ok = target_weight <= 0 or abs(selected_weight - target_weight) <= max(2.0, target_weight * 0.10)
        if not value_ok and not weight_ok:
            return item

        resolved = dict(item)
        resolved["peso_fatura"] = round(selected_weight, 3)
        resolved["valor_nota_fatura"] = round(selected_value, 2)
        resolved["peso_fatura_origem"] = "FATURA - CAMPO COLADO RESOLVIDO PELA LINHA BASE"
        resolved["valor_nota_fatura_origem"] = "FATURA - CAMPO COLADO RESOLVIDO PELA LINHA BASE"
        resolved["separacao_peso_valor"] = (
            f"{selected.get('raw') or '-'} → peso {selected_weight:.3f} kg + valor {_money(selected_value)}"
        )
        return resolved

    def _make_record(self, fat, partner, item, base_row, mode):
        item = _resolve_invoice_fields_with_base(item, base_row)
        cte = _clean_cte(item.get("cte"))
        nf_pdf_original = _clean_nf(item.get("nf"))
        nf_base_fallback = _clean_nf(item.get("_nf_base_fallback"))
        nf = nf_pdf_original or nf_base_fallback
        origem_nf = "PDF" if nf_pdf_original else (item.get("_nf_source") or "NÃO IDENTIFICADA")
        val = round(float(item.get("valor") or 0.0), 2)
        fat_key = _fatura_key(fat)
        rec = {
            "Fatura": fat,
            "Fatura chave": fat_key,
            "Parceiro": partner,
            "CT-e": cte,
            "CT-e fatura": cte,
            "Subcontrato": cte,
            "NF": nf,
            "NF fatura": nf,
            "NF PDF original": nf_pdf_original,
            "Origem NF": origem_nf,
            "Valor fatura": val,
            "Valor CT-e": val,
            "Valor não pagar": 0.0,
            "Arquivo fatura": item.get("arquivo") or "",
            "Sequência item": item.get("sequencia") or "",
            "Origem parser": f"2664:{item.get('layout') or ''}",
            "CTRC Origem fatura": item.get("ctrc_origem_raw") or "",
            "Valor mercadoria fatura": round(float(item.get("valor_nota_fatura") or 0.0), 2),
            "Peso fatura": round(float(item.get("peso_fatura") or 0.0), 3),
            "ICMS fatura": round(float(item.get("icms_fatura") or 0.0), 2),
            "Comissão fatura": round(float(item.get("comissao_fatura") or val or 0.0), 2),
            "Frete CTRC Origem fatura": round(float(item.get("frete_origem_fatura") or 0.0), 2),
            "ICMS CTRC Origem fatura": round(float(item.get("icms_origem_fatura") or 0.0), 2),
            "Match base": mode,
        }
        if base_row:
            expected = round(_row_value(base_row, fat_key, val), 2)
            rec["CT-e base"] = base_row.get("cte") or ""
            rec["CTRC base"] = base_row.get("ctrc") or ""
            rec["CTRC Origem base"] = base_row.get("ctrc_origem") or ""
            rec["NF base"] = base_row.get("nf") or ""
            rec["Valor base"] = expected
            rec["Valor frete base"] = base_row.get("valor") or 0.0
            rec["Fatura Base"] = base_row.get("fatura_base") or ""
            rec["Fatura Base Exp"] = base_row.get("fatura_exp") or ""
            rec["Fatura Base Rec"] = base_row.get("fatura_rec") or ""
            rec["DY"] = str(base_row.get("dy") or "").strip().upper()
            rec["Data escaneamento"] = _format_scan_date(base_row.get("data_scan"))
            rec["Hora escaneamento"] = _format_scan_time(base_row.get("hora_scan"))
            rec["Tipo documento base"] = base_row.get("tipo_doc") or ""
            rec["Origem cidade base"] = base_row.get("origem_cidade") or ""
            rec["Origem UF base"] = base_row.get("origem_uf") or ""
            rec["Destino cidade base"] = base_row.get("destino_cidade") or ""
            rec["Destino UF base"] = base_row.get("destino_uf") or ""
            rec["Bairro destinatário base"] = base_row.get("destinatario_bairro") or ""
            rec["Local entrega base"] = base_row.get("local_entrega") or ""
            rec["Endereço entrega base"] = base_row.get("endereco_entrega") or ""
            rec["Peso real base"] = base_row.get("peso_real") or 0.0
            rec["Peso calculado base"] = base_row.get("peso_calculado") or 0.0
            legacy_value, legacy_match, legacy_confidence = _find_legacy_value_result(self, fat, cte, nf, val)
            _apply_value_audit(self, rec, base_row, legacy_value, legacy_match, legacy_confidence)
            _apply_table_validation_shadow(self, rec, item, base_row, partner)
            if _is_complementar_base(base_row):
                rec["Status final CT-e"] = "OK COMPLEMENTAR"
                rec["Status CT-e"] = "OK COMPLEMENTAR"
                rec["Comprovante"] = "NÃO EXIGIDO - COMPLEMENTAR"
                rec["Motivo"] = "CT-e complementar/custo extra localizado na base. Comprovante de entrega não exigido."
                rec["Tipo Divergência"] = "-"
                rec["Ação recomendada"] = "Liberar se valor conferido."
            elif rec["DY"] == "S":
                rec["Status final CT-e"] = "OK"
                rec["Status CT-e"] = "OK"
                rec["Comprovante"] = "COMPROVANTE OK"
                rec["Motivo"] = "Comprovante localizado na base."
                rec["Tipo Divergência"] = "-"
                rec["Ação recomendada"] = "Liberar pagamento deste CT-e."
            else:
                rec["Status final CT-e"] = "SEM COMPROVANTE"
                rec["Status CT-e"] = "SEM COMPROVANTE"
                rec["Comprovante"] = "SEM COMPROVANTE"
                rec["Motivo"] = "Sem comprovante DY=N"
                rec["Tipo Divergência"] = "Comprovante"
                rec["Valor não pagar"] = val
                rec["Ação recomendada"] = "Solicitar comprovante ao parceiro e bloquear somente este CT-e até regularização."
        else:
            _apply_table_validation_shadow(self, rec, item, None, partner)
            legacy_value, legacy_match, legacy_confidence = _find_legacy_value_result(self, fat, cte, nf, val)
            rec["Valor XML"] = round(float((legacy_value or {}).get("valor_xml") or 0.0), 2) if legacy_value else 0.0
            rec["Diferença XML"] = round(float((legacy_value or {}).get("diferenca") or 0.0), 2) if legacy_value else 0.0
            rec["Origem validação valor"] = "SEM BASE"
            rec["Confiança validação valor"] = legacy_confidence
            rec["Vínculo validação valor"] = legacy_match
            rec["Regra aplicada valor"] = (legacy_value or {}).get("regra") or "-"
            rec["Status valor legado"] = (legacy_value or {}).get("status_raw") or "-"
            rec["Detalhe validação valor"] = "Documento fora da base; validação de valor não pode liberar pagamento."
            rec["Status valor"] = "NÃO VALIDADO - FORA DA BASE"
            rec["Status final CT-e"] = "FORA DA BASE"
            rec["Status CT-e"] = "FORA DA BASE"
            rec["Comprovante"] = "FORA DA BASE"
            rec["Motivo"] = "CT-e/NF fora ou não localizado na base"
            rec["Tipo Divergência"] = "Comprovante / Base"
            rec["Valor não pagar"] = val
            rec["Ação recomendada"] = "Localizar CT-e/NF na base Rodovitor ou devolver para conferência manual."
        try:
            rec.update(_decision_trace(rec, item, base_row, mode))
        except Exception as _trace_exc:
            rec["Caminho do status"] = f"Falha ao montar trilha de decisão: {_trace_exc}"
            rec["Avisos auditoria"] = "TRILHA DE DECISÃO INCOMPLETA"
        return rec

    def _is_problem_record(rec):
        st = _strip_accents(str(rec.get("Status final CT-e") or rec.get("Status CT-e") or "")).upper()
        if "OK COMPLEMENTAR" in st or st == "OK":
            return False
        return any(k in st for k in ("SEM COMPROVANTE", "FORA DA BASE", "DIVERG", "REVISAR"))

    def _detail_row(rec):
        esc = ""
        data = str(rec.get("Data escaneamento") or rec.get("data_scan") or "")
        hora = str(rec.get("Hora escaneamento") or rec.get("hora_scan") or "")
        if data or hora:
            esc = _norm_space(f"{data} {hora}")
        return [
            rec.get("CT-e fatura") or rec.get("CT-e") or "-",
            rec.get("NF fatura") or rec.get("NF") or "-",
            rec.get("Valor fatura") or 0.0,
            rec.get("Valor base") or "-",
            rec.get("Status valor") or "OK",
            rec.get("Fatura Base") or "-",
            rec.get("Comprovante") or "-",
            esc or "-",
            rec.get("Status final CT-e") or rec.get("Status CT-e") or "-",
            rec.get("Motivo") or "-",
        ]

    def _rebuild_canonical(self):
        fmap, order, partner_doc = _doc_items_map(self)
        if not fmap:
            return {"faturas": 0, "itens": 0, "ok": 0, "sem_comprovante": 0, "fora": 0, "complementares": 0, "revisar": 0, "valor_total": 0.0, "valor_nao_pagar": 0.0}
        partner_existing = _existing_partner_map(self)
        records = []
        invoice_rows = []
        detail_map = {}
        stats = {"faturas": len(fmap), "itens": 0, "ok": 0, "sem_comprovante": 0, "fora": 0, "complementares": 0, "revisar": 0, "valor_total": 0.0, "valor_nao_pagar": 0.0}
        for fat in order or sorted(fmap.keys()):
            items = fmap.get(fat) or []
            partner = partner_existing.get(fat) or partner_doc.get(fat) or "Parceiro não identificado"
            recs = []
            for item in items:
                base_row, mode = _match_base(self, fat, item)
                rec = _make_record(self, fat, partner, item, base_row, mode)
                recs.append(rec)
                records.append(rec)
            qtd = len(recs)
            ok = sum(1 for r in recs if not _is_problem_record(r))
            problema = qtd - ok
            valor_total = round(sum(float(r.get("Valor fatura") or 0.0) for r in recs), 2)
            valor_np = round(sum(float(r.get("Valor não pagar") or 0.0) for r in recs if _is_problem_record(r)), 2)
            stats["itens"] += qtd
            stats["ok"] += sum(1 for r in recs if str(r.get("Status final CT-e")) == "OK")
            stats["valor_total"] += valor_total
            stats["valor_nao_pagar"] += valor_np
            stats["sem_comprovante"] += sum(1 for r in recs if str(r.get("Status final CT-e")) == "SEM COMPROVANTE")
            stats["fora"] += sum(1 for r in recs if str(r.get("Status final CT-e")) == "FORA DA BASE")
            stats["complementares"] += sum(1 for r in recs if str(r.get("Status final CT-e")) == "OK COMPLEMENTAR")
            stats["revisar"] += sum(1 for r in recs if "REVISAR" in str(r.get("Status final CT-e") or "") or "DIVERGENTE" in str(r.get("Status final CT-e") or ""))
            if qtd == 0:
                problema = 1
                stats["revisar"] += 1
                status = "REVISAR PARSER"
            elif problema == 0:
                status = "OK PAGAR"
            elif ok > 0:
                status = "PAGAR PARCIAL"
            else:
                status = "NÃO PAGAR"
            pend = []
            for r in recs:
                if _is_problem_record(r):
                    pend.append(f"CT-e {r.get('CT-e fatura') or r.get('CT-e')} / NF {r.get('NF fatura') or r.get('NF') or '-'}")
            valores = f"Fatura {_money(valor_total)} | Não pagar {_money(valor_np)} | A pagar {_money(max(valor_total - valor_np, 0.0))}"
            revisar_qtd = 1 if qtd == 0 else sum(1 for r in recs if "REVISAR" in str(r.get("Status final CT-e") or "") or "DIVERGENTE" in str(r.get("Status final CT-e") or ""))
            comprovantes = f"OK {ok} | Pend. {problema} | Revisar {revisar_qtd}"
            row = [fat, partner, str(qtd), str(ok), str(problema), _money(valor_total), _money(valor_np), valores, comprovantes, status]
            invoice_rows.append(row)
            detail_map[fat] = [_detail_row(r) for r in recs] or [["-", "-", 0.0, "-", "NÃO VALIDADO", "-", "-", "-", "REVISAR PARSER", "Nenhum item canônico foi extraído deste PDF."]]
        try:
            self.invoice_detail_records = records
            self.invoice_rows = invoice_rows
            self.detail_rows_by_invoice = detail_map
            self._faturas_2664_stats = stats
        except Exception:
            pass
        return stats

    def _refresh_ui_from_cache(self):
        try:
            table = getattr(self, "invoice_table", None)
            if table is not None:
                try:
                    table.setRowCount(0)
                except Exception:
                    pass
                add = getattr(self, "add_invoice_row", None)
                for row in getattr(self, "invoice_rows", []) or []:
                    try:
                        if callable(add):
                            add(row)
                    except Exception:
                        pass
        except Exception:
            pass
        for fn_name in ("update_cards", "load_details_for_selected"):
            try:
                fn = getattr(self, fn_name, None)
                if callable(fn):
                    fn()
            except Exception:
                pass

    def _log_canonical(self, stats):
        try:
            log_dir = _app_dir() / "logs"
            log_dir.mkdir(parents=True, exist_ok=True)
            path = log_dir / f"faturas_motor_canonico_{_datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
            linhas = [
                "MOTOR CANÔNICO FATURAS 2.6.65.13 - ROTA DO RECEBEDOR E MÉTODO PERCENTUAL",
                "=" * 80,
                f"Data/hora: {_datetime.now().strftime('%d/%m/%Y %H:%M:%S')}",
                f"Faturas canônicas: {stats.get('faturas', 0)}",
                f"Itens canônicos: {stats.get('itens', 0)}",
                f"CT-es normais OK: {stats.get('ok', 0)}",
                f"Sem comprovante: {stats.get('sem_comprovante', 0)}",
                f"Complementares OK: {stats.get('complementares', 0)}",
                f"Fora da base: {stats.get('fora', 0)}",
                f"Revisar/divergência: {stats.get('revisar', 0)}",
                f"Valor total: {_money(stats.get('valor_total', 0.0))}",
                f"Valor não pagar: {_money(stats.get('valor_nao_pagar', 0.0))}",
                "",
                "Regra aplicada: a lista de itens vem exclusivamente das faturas PDF lidas. A base Rodovitor apenas valida esses itens.",
            ]
            path.write_text("\n".join(linhas), encoding="utf-8")
            return str(path)
        except Exception:
            return ""

    def _build_sheets_canonical(self, only_problem_invoices=False):
        stats = _rebuild_canonical(self)
        records = list(getattr(self, "invoice_detail_records", []) or [])
        invoice_rows = list(getattr(self, "invoice_rows", []) or [])
        if not invoice_rows:
            raise RuntimeError("Nenhuma fatura canônica foi produzida. Reprocesse os PDFs antes de exportar.")
        resumo = [["Número da Fatura", "Nome do Parceiro", "Qtd.", "OK", "Problema", "Valor Fatura", "Valor Não Pagar", "Valor a Pagar", "CT-e/NF com Divergência", "Status"]]
        detalhes = [["Fatura", "Parceiro", "CT-e", "NF", "Valor CT-e", "Peso Fatura", "Frete CTRC Origem Fatura", "Valor Base/Comissão", "Valor Esperado Tabela", "Diferença Tabela", "Status Tabela Parceiro", "Destino Comercial Tabela", "Fonte Destino Tabela", "Status valor", "Origem Validação Valor", "Regra Tabela", "Fonte Base Tabela", "Confiança Valor", "Fatura Base", "Comprovante", "Escaneamento", "Status CT-e", "Motivo", "Vínculo Fatura", "Método de Busca", "Caminho Cálculo Tabela", "Caminho do Status", "Avisos"]]
        diverg = [["Fatura", "Parceiro", "CT-e", "NF", "Valor Não Pagar", "Tipo Divergência", "Status CT-e", "Motivo", "Ação recomendada"]]
        mensagens = [["Parceiro", "Faturas com DY=N", "Qtd. CT-es sem comprovante", "Valor bloqueado por comprovante", "CT-es pendentes", "Mensagem pronta"]]
        log_status = [["Fatura", "Parceiro", "Seq.", "Arquivo PDF", "CT-e PDF", "NF PDF Original", "NF Utilizada", "Origem NF", "Valor CT-e", "Peso Fatura", "Frete CTRC Origem Fatura", "Comissão Fatura", "Chave Fatura", "CTRC Origem PDF", "Método de Busca", "CT-e Base", "CTRC Base", "NF Base", "Confirmação NF", "Fatura Base Exp", "Fatura Base Rec", "Vínculo da Fatura", "Origem Rota", "Destino Rota Base", "Destino Comercial Tabela", "Fonte Destino Tabela", "Aviso Rota", "Tipo Documento", "DY", "Valor Base/Comissão", "Parceiro Tabela ID", "Regra Tabela ID", "Fonte Regra", "Base Cálculo Tabela", "Fonte Base Tabela", "Percentual Tabela", "Mínimo Tabela", "Valor Esperado Tabela", "Diferença Tabela", "Tolerância Tabela", "Status Tabela Parceiro", "Peso Usado Tabela", "Fonte Peso Tabela", "Modo Tabela", "Caminho Cálculo Tabela", "Valor XML", "Diferença XML", "Status Valor", "Origem Validação Valor", "Confiança Valor", "Vínculo Validação Valor", "Regra Aplicada", "Status Valor Legado", "Status Final", "Motivo Final", "Caminho do Status", "Avisos"]]
        msg_map = {}
        problem_by_fat = {}
        records_by_fat = {}
        for rec in records:
            records_by_fat.setdefault(rec.get("Fatura") or "", []).append(rec)
        problem_fats = {
            rec.get("Fatura") or "" for rec in records if _is_problem_record(rec)
        }
        problem_fats.update(
            row[0] for row in invoice_rows if row and str(row[9] if len(row) > 9 else "").upper() != "OK PAGAR"
        )
        for rec in records:
            if only_problem_invoices and (rec.get("Fatura") or "") not in problem_fats:
                continue
            detalhes.append([
                rec.get("Fatura"), rec.get("Parceiro"), rec.get("CT-e fatura") or rec.get("CT-e"), rec.get("NF fatura") or rec.get("NF"),
                rec.get("Valor fatura") or 0.0, rec.get("Peso fatura") or 0.0, rec.get("Frete CTRC Origem fatura") or 0.0, rec.get("Valor base") or "-",
                rec.get("Valor esperado tabela") or 0.0, rec.get("Diferença tabela") or 0.0, rec.get("Status tabela parceiro") or "-",
                rec.get("Destino comercial tabela") or "-", rec.get("Fonte destino tabela") or "-",
                rec.get("Status valor") or "-", rec.get("Origem validação valor") or "-", rec.get("Regra tabela ID") or "-", rec.get("Fonte base tabela") or "-",
                rec.get("Confiança validação valor") or "-", rec.get("Fatura Base") or "-", rec.get("Comprovante") or "-",
                _norm_space(f"{rec.get('Data escaneamento') or ''} {rec.get('Hora escaneamento') or ''}") or "-", rec.get("Status final CT-e") or rec.get("Status CT-e") or "-", rec.get("Motivo") or "-",
                rec.get("Vínculo fatura") or "-", rec.get("Método de busca") or rec.get("Match base") or "-", rec.get("Caminho cálculo tabela") or "-", rec.get("Caminho do status") or "-", rec.get("Avisos auditoria") or "-",
            ])
            log_status.append([
                rec.get("Fatura") or "-", rec.get("Parceiro") or "-", rec.get("Sequência item") or "-",
                _Path(str(rec.get("Arquivo fatura") or "")).name if rec.get("Arquivo fatura") else "-",
                rec.get("CT-e fatura") or rec.get("CT-e") or "-", rec.get("NF PDF original") or "-",
                rec.get("NF fatura") or rec.get("NF") or "-", rec.get("Origem NF") or "-",
                rec.get("Valor fatura") or 0.0, rec.get("Peso fatura") or 0.0, rec.get("Frete CTRC Origem fatura") or 0.0, rec.get("Comissão fatura") or 0.0,
                rec.get("Fatura chave") or "-", rec.get("CTRC Origem fatura") or "-", rec.get("Método de busca") or rec.get("Match base") or "-",
                rec.get("CT-e base") or "-", rec.get("CTRC base") or "-", rec.get("NF base") or "-", rec.get("Confirmação NF") or "-",
                rec.get("Fatura Base Exp") or "-", rec.get("Fatura Base Rec") or "-", rec.get("Vínculo fatura") or "-",
                _norm_space(f"{rec.get('Origem cidade base') or ''}/{rec.get('Origem UF base') or ''}") or "-",
                _norm_space(f"{rec.get('Destino cidade base') or ''}/{rec.get('Destino UF base') or ''}") or "-",
                rec.get("Destino comercial tabela") or "-", rec.get("Fonte destino tabela") or "-", rec.get("Aviso rota tabela") or "-",
                rec.get("Tipo documento base") or "-", rec.get("DY") or "-", rec.get("Valor base") or 0.0,
                rec.get("Parceiro tabela ID") or "-", rec.get("Regra tabela ID") or "-", rec.get("Fonte regra tabela") or "-", rec.get("Base cálculo tabela") or 0.0,
                rec.get("Fonte base tabela") or "-", rec.get("Percentual tabela") or 0.0, rec.get("Mínimo tabela") or 0.0, rec.get("Valor esperado tabela") or 0.0,
                rec.get("Diferença tabela") or 0.0, rec.get("Tolerância tabela") or 0.0, rec.get("Status tabela parceiro") or "-", rec.get("Peso usado tabela") or 0.0,
                rec.get("Fonte peso tabela") or "-", rec.get("Modo tabela") or "-", rec.get("Caminho cálculo tabela") or "-",
                rec.get("Valor XML") or 0.0, rec.get("Diferença XML") or 0.0, rec.get("Status valor") or "-", rec.get("Origem validação valor") or "-",
                rec.get("Confiança validação valor") or "-", rec.get("Vínculo validação valor") or "-", rec.get("Regra aplicada valor") or "-", rec.get("Status valor legado") or "-",
                rec.get("Status final CT-e") or rec.get("Status CT-e") or "-", rec.get("Motivo") or "-", rec.get("Caminho do status") or "-", rec.get("Avisos auditoria") or "-",
            ])
            if _is_problem_record(rec):
                fat = rec.get("Fatura") or ""
                label = f"CT-e {rec.get('CT-e fatura') or rec.get('CT-e')} / NF {rec.get('NF fatura') or rec.get('NF') or '-'}"
                problem_by_fat.setdefault(fat, []).append(label)
                diverg.append([
                    fat, rec.get("Parceiro"), rec.get("CT-e fatura") or rec.get("CT-e"), rec.get("NF fatura") or rec.get("NF"),
                    rec.get("Valor não pagar") or 0.0, rec.get("Tipo Divergência") or "Revisar", rec.get("Status final CT-e") or rec.get("Status CT-e") or "-",
                    rec.get("Motivo") or "-", rec.get("Ação recomendada") or "Validar manualmente antes de liberar pagamento.",
                ])
                if str(rec.get("Status final CT-e")) == "SEM COMPROVANTE":
                    partner = rec.get("Parceiro") or "Parceiro não identificado"
                    msg_map.setdefault(partner, {}).setdefault(fat, []).append((rec.get("CT-e fatura") or rec.get("CT-e"), rec.get("NF fatura") or rec.get("NF"), float(rec.get("Valor não pagar") or 0.0)))
        for row in invoice_rows:
            fat = row[0] if row else ""
            if only_problem_invoices and fat not in problem_fats:
                continue
            recs = records_by_fat.get(fat, [])
            valor_total = round(sum(float(r.get("Valor fatura") or 0.0) for r in recs), 2)
            valor_np = round(sum(float(r.get("Valor não pagar") or 0.0) for r in recs if _is_problem_record(r)), 2)
            resumo.append([
                fat,
                row[1] if len(row) > 1 else "Parceiro não identificado",
                int(row[2] or 0) if len(row) > 2 else len(recs),
                int(row[3] or 0) if len(row) > 3 else sum(1 for r in recs if not _is_problem_record(r)),
                int(row[4] or 0) if len(row) > 4 else sum(1 for r in recs if _is_problem_record(r)),
                valor_total,
                valor_np,
                round(max(valor_total - valor_np, 0.0), 2),
                " | ".join(problem_by_fat.get(fat, [])),
                row[9] if len(row) > 9 else "",
            ])
        for partner in sorted(msg_map):
            fat_map = msg_map[partner]
            qtd = sum(len(v) for v in fat_map.values())
            bloqueado = round(sum(x[2] for v in fat_map.values() for x in v), 2)
            pend = []
            linhas = []
            fat_labels = []
            for fat in sorted(fat_map):
                recs = fat_map[fat]
                fat_labels.append(f"{fat} ({len(recs)} CT-e)")
                linhas.append(f"Fatura {fat}:")
                for cte, nf, val in recs:
                    pend.append(f"CT-e {cte}" + (f" / NF {nf}" if nf else ""))
                    linhas.append(f"- CT-e {cte} | NF {nf or '-'} | Valor a retirar {_money(val)} | Motivo: sem comprovante de entrega")
            msg = (
                "Prezados,\n\n"
                f"Identificamos CT-e(s) sem comprovante de entrega na fatura do parceiro {partner}.\n\n"
                "Solicitamos, por gentileza, retirar o(s) CT-e(s) abaixo da fatura atual e incluí-lo(s) em uma próxima fatura somente após o envio/regularização do comprovante de entrega.\n\n"
                "CT-e(s) a retirar da fatura atual:\n" + "\n".join(linhas) + "\n\n"
                f"Valor a retirar da fatura atual: {_money(bloqueado)}.\n"
                "Após o envio do comprovante, o(s) CT-e(s) poderá(ão) ser reapresentado(s) nas próximas faturas para nova análise.\n"
            )
            mensagens.append([partner, " | ".join(fat_labels), qtd, bloqueado, " | ".join(pend), msg])
        return [
            ("1_Resumo_Faturas", resumo, [18, 42, 8, 8, 10, 15, 16, 15, 70, 18]),
            ("2_CTes_Comprovantes", detalhes, [16, 42, 16, 16, 14, 14, 18, 16, 18, 16, 34, 28, 30, 32, 30, 28, 34, 22, 18, 20, 22, 22, 58, 34, 26, 120, 120, 70]),
            ("3_Divergencias", diverg, [16, 42, 16, 16, 16, 20, 22, 60, 60]),
            ("4_Mensagem_Parceiro", mensagens, [42, 58, 18, 22, 70, 110]),
            ("5_Log_Status", log_status, [16, 42, 8, 58, 16, 18, 16, 28, 14, 14, 18, 16, 14, 22, 28, 18, 18, 16, 24, 18, 18, 38, 28, 28, 28, 30, 60, 26, 8, 16, 22, 28, 22, 18, 34, 16, 14, 18, 16, 16, 36, 16, 30, 28, 120, 14, 14, 30, 30, 22, 32, 30, 28, 22, 60, 120, 72]),
        ]

    def _apply_status_colors_xlsx(path):
        """Aplica cores, formatos inteiros e navegação às cinco abas.

        Verde = OK/liberado; amarelo = parcial/revisão/informativo;
        vermelho = não pagar/sem comprovante/fora da base.
        Também congela cabeçalhos, mantém Fatura/Parceiro/CT-e/NF visíveis nas
        abas largas e oculta somente colunas técnicas secundárias.
        """
        import zipfile as _zipfile_local
        from xml.etree import ElementTree as _ET_local

        path = _Path(path)
        ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
        _ET_local.register_namespace("", ns)
        q = lambda tag: "{%s}%s" % (ns, tag)

        with _zipfile_local.ZipFile(path, "r") as zin:
            files = {name: zin.read(name) for name in zin.namelist()}

        styles_root = _ET_local.fromstring(files["xl/styles.xml"])
        fonts = styles_root.find(q("fonts"))
        fills = styles_root.find(q("fills"))
        cell_xfs = styles_root.find(q("cellXfs"))
        if fonts is None or fills is None or cell_xfs is None:
            return

        def add_font(color):
            font = _ET_local.Element(q("font"))
            _ET_local.SubElement(font, q("b"))
            _ET_local.SubElement(font, q("sz"), {"val": "11"})
            _ET_local.SubElement(font, q("color"), {"rgb": color})
            _ET_local.SubElement(font, q("name"), {"val": "Calibri"})
            fonts.append(font)
            return len(fonts) - 1

        def add_fill(color):
            fill = _ET_local.Element(q("fill"))
            pattern = _ET_local.SubElement(fill, q("patternFill"), {"patternType": "solid"})
            _ET_local.SubElement(pattern, q("fgColor"), {"rgb": color})
            _ET_local.SubElement(pattern, q("bgColor"), {"indexed": "64"})
            fills.append(fill)
            return len(fills) - 1

        def add_xf(font_id, fill_id, num_fmt_id="0", centered=False):
            attrs = {
                "numFmtId": str(num_fmt_id), "fontId": str(font_id), "fillId": str(fill_id),
                "borderId": "1", "xfId": "0", "applyFont": "1", "applyFill": "1", "applyBorder": "1",
            }
            if str(num_fmt_id) != "0":
                attrs["applyNumberFormat"] = "1"
            if centered:
                attrs["applyAlignment"] = "1"
            xf = _ET_local.Element(q("xf"), attrs)
            if centered:
                _ET_local.SubElement(xf, q("alignment"), {"horizontal": "center", "vertical": "center"})
            cell_xfs.append(xf)
            return len(cell_xfs) - 1

        green_style = add_xf(add_font("FF006100"), add_fill("FFC6EFCE"))
        yellow_style = add_xf(add_font("FF9C6500"), add_fill("FFFFEB9C"))
        red_style = add_xf(add_font("FF9C0006"), add_fill("FFFFC7CE"))
        integer_style = add_xf(0, 0, num_fmt_id="1", centered=True)  # formato Excel 0

        def cell_text(cell):
            if cell.get("t") == "inlineStr":
                return "".join((node.text or "") for node in cell.iter(q("t")))
            value = cell.find(q("v"))
            return value.text if value is not None else ""

        def col_letters(ref):
            match = _re.match(r"[A-Z]+", str(ref or ""))
            return match.group(0) if match else ""

        def col_number(ref):
            letters = col_letters(ref)
            number = 0
            for char in letters:
                number = number * 26 + ord(char) - 64
            return number

        def norm_header(value):
            return _norm(value)

        def choose_style(header, value):
            v = _strip_accents(str(value or "")).upper()
            h = norm_header(header)
            if not v:
                return None
            if h in {"STATUSVALOR", "STATUSTABELAPARCEIRO"}:
                if v.startswith("OK"):
                    return green_style
                if any(token in v for token in ("NAO PAGAR", "NÃO PAGAR", "FORA DA BASE")):
                    return red_style
                return yellow_style
            if any(token in v for token in ("NAO PAGAR", "NÃO PAGAR", "SEM COMPROVANTE", "FORA DA BASE")):
                return red_style
            if "PAGAR PARCIAL" in v or "PARCIAL" in v or "REVISAR" in v:
                return yellow_style
            if v.startswith("OK"):
                return green_style
            return yellow_style

        def ensure_freeze(root, x_split=0, y_split=1):
            sheet_views = root.find(q("sheetViews"))
            if sheet_views is None:
                sheet_views = _ET_local.Element(q("sheetViews"))
                # sheetViews deve vir antes de sheetFormatPr/sheetData.
                insert_at = 0
                for idx, child in enumerate(list(root)):
                    if child.tag in {q("sheetPr"), q("dimension")}:
                        insert_at = idx + 1
                root.insert(insert_at, sheet_views)
            view = sheet_views.find(q("sheetView"))
            if view is None:
                view = _ET_local.SubElement(sheet_views, q("sheetView"), {"workbookViewId": "0"})
            for child in list(view):
                if child.tag in {q("pane"), q("selection")}:
                    view.remove(child)
            attrs = {"state": "frozen"}
            if x_split:
                attrs["xSplit"] = str(x_split)
            if y_split:
                attrs["ySplit"] = str(y_split)
            col = "A"
            n = int(x_split) + 1
            letters = ""
            while n:
                n, rem = divmod(n - 1, 26)
                letters = chr(65 + rem) + letters
            col = letters
            attrs["topLeftCell"] = f"{col}{int(y_split) + 1}"
            attrs["activePane"] = "bottomRight" if x_split and y_split else ("bottomLeft" if y_split else "topRight")
            _ET_local.SubElement(view, q("pane"), attrs)
            _ET_local.SubElement(view, q("selection"), {"pane": attrs["activePane"], "activeCell": attrs["topLeftCell"], "sqref": attrs["topLeftCell"]})

        def hide_columns(root, indices):
            indices = sorted(set(int(i) for i in indices if int(i) > 0))
            if not indices:
                return
            cols = root.find(q("cols"))
            if cols is None:
                cols = _ET_local.Element(q("cols"))
                sheet_data = root.find(q("sheetData"))
                pos = list(root).index(sheet_data) if sheet_data is not None else len(list(root))
                root.insert(pos, cols)
            existing = list(cols.findall(q("col")))
            for idx in indices:
                found = None
                for col in existing:
                    try:
                        if int(col.get("min", "0")) <= idx <= int(col.get("max", "0")):
                            found = col
                            break
                    except Exception:
                        continue
                if found is not None and found.get("min") == found.get("max") == str(idx):
                    found.set("hidden", "1")
                else:
                    col = _ET_local.Element(q("col"), {"min": str(idx), "max": str(idx), "hidden": "1", "customWidth": "1", "width": "2"})
                    cols.append(col)
                    existing.append(col)

        target_headers = {"STATUS", "STATUSVALOR", "STATUSTABELAPARCEIRO", "STATUSCTE", "STATUSFINAL"}
        count_headers = {"QTD", "OK", "PROBLEMA", "QTDCTESSEMCOMPROVANTE"}
        detail_hidden = {"ORIGEMVALIDACAOVALOR", "REGRATABELA", "FONTEBASETABELA", "CONFIANCAVALOR", "CAMINHOCALCULOTABELA", "CAMINHODOSTATUS", "AVISOS"}
        log_hidden = {
            "CHAVEFATURA", "CTRCORIGEMPDF", "FATURABASEEXP", "FATURABASEREC", "FONTEREGRA",
            "BASECALCULOTABELA", "FONTEBASETABELA", "PERCENTUALTABELA", "MINIMOTABELA", "TOLERANCIATABELA",
            "MODOTABELA", "VALORXML", "DIFERENCAXML", "ORIGEMVALIDACAOVALOR", "CONFIANCAVALOR",
            "VINCULOVALIDACAOVALOR", "REGRAAPLICADA", "STATUSVALORLEGADO",
        }

        for name, raw in list(files.items()):
            if not (name.startswith("xl/worksheets/sheet") and name.endswith(".xml")):
                continue
            root = _ET_local.fromstring(raw)
            sheet_data = root.find(q("sheetData"))
            if sheet_data is None:
                continue
            rows = sheet_data.findall(q("row"))
            if not rows:
                continue
            header_map = {}
            header_by_index = {}
            for cell in rows[0].findall(q("c")):
                header = cell_text(cell)
                letters = col_letters(cell.get("r"))
                header_map[letters] = header
                header_by_index[col_number(cell.get("r"))] = norm_header(header)

            header_norms = set(header_by_index.values())
            is_summary = {"NUMERODAFATURA", "NOMEDOPARCEIRO", "QTD", "VALORFATURA", "STATUS"}.issubset(header_norms)
            is_details = {"FATURA", "PARCEIRO", "CTE", "NF", "STATUSCTE", "CAMINHODOSTATUS"}.issubset(header_norms)
            is_log = {"FATURA", "PARCEIRO", "SEQ", "ARQUIVOPDF", "STATUSFINAL", "CAMINHODOSTATUS"}.issubset(header_norms)

            # Congela a primeira linha em todas as abas. Nas duas abas largas,
            # congela também Fatura/Parceiro/CT-e/NF (quatro primeiras colunas).
            ensure_freeze(root, x_split=4 if (is_details or is_log) else 0, y_split=1)

            hidden = []
            if is_details:
                hidden = [idx for idx, header in header_by_index.items() if header in detail_hidden]
            elif is_log:
                hidden = [idx for idx, header in header_by_index.items() if header in log_hidden]
            hide_columns(root, hidden)

            for row in rows[1:]:
                for cell in row.findall(q("c")):
                    col = col_letters(cell.get("r"))
                    header = header_map.get(col, "")
                    header_norm = norm_header(header)
                    if is_summary and header_norm in count_headers:
                        cell.set("s", str(integer_style))
                        continue
                    if header_norm in target_headers:
                        style_id = choose_style(header, cell_text(cell))
                        if style_id is not None:
                            cell.set("s", str(style_id))
            files[name] = _ET_local.tostring(root, encoding="utf-8", xml_declaration=True)

        fonts.set("count", str(len(fonts)))
        fills.set("count", str(len(fills)))
        cell_xfs.set("count", str(len(cell_xfs)))
        files["xl/styles.xml"] = _ET_local.tostring(styles_root, encoding="utf-8", xml_declaration=True)

        temp_path = path.with_suffix(path.suffix + ".tmp")
        with _zipfile_local.ZipFile(temp_path, "w", compression=_zipfile_local.ZIP_DEFLATED) as zout:
            for name, data in files.items():
                zout.writestr(name, data)
        _os.replace(temp_path, path)

    def _write_report_file(self, sheets):
        rel_dir = _app_dir() / "relatorios"
        rel_dir.mkdir(parents=True, exist_ok=True)
        stamp = _datetime.now().strftime("%Y%m%d_%H%M%S")
        path = rel_dir / f"relatorio_faturas_5_abas_{stamp}.xlsx"
        writer = globals().get("write_simple_xlsx")
        if not callable(writer):
            raise RuntimeError("write_simple_xlsx não está disponível no motor.")
        writer(path, sheets)
        _apply_status_colors_xlsx(path)
        return path

    def _notify(self, title, text, error=False):
        shown = False
        try:
            QMessageBox = getattr(_main, "QMessageBox", None)
            if QMessageBox is not None:
                if error:
                    QMessageBox.critical(self, title, text)
                else:
                    QMessageBox.information(self, title, text)
                shown = True
        except Exception:
            pass
        if not shown:
            try:
                import tkinter.messagebox as _mb
                (_mb.showerror if error else _mb.showinfo)(title, text)
                shown = True
            except Exception:
                pass
        try:
            if hasattr(self, "set_status"):
                self.set_status(text.replace("\n", " "))
        except Exception:
            pass

    def _log_error(exc, etapa="exportar_relatorio_2664"):
        try:
            log_dir = _app_dir() / "logs"
            log_dir.mkdir(parents=True, exist_ok=True)
            path = log_dir / f"erro_faturas_2664_{_datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
            path.write_text(
                "ERRO MOTOR CANÔNICO FATURAS 2.6.65.13 - ROTA DO RECEBEDOR E MÉTODO PERCENTUAL\n" + "=" * 80 + "\n"
                + f"Etapa: {etapa}\nData/hora: {_datetime.now().strftime('%d/%m/%Y %H:%M:%S')}\n\n"
                + _traceback.format_exc(),
                encoding="utf-8",
            )
            return path
        except Exception:
            return None

    def patched_process_2664(self, *args, **kwargs):
        result = _prev_process(self, *args, **kwargs) if callable(_prev_process) else None
        try:
            _capture_legacy_value_results(self)
            stats = _rebuild_canonical(self)
            _refresh_ui_from_cache(self)
            log_path = _log_canonical(self, stats)
            try:
                if hasattr(self, "set_status"):
                    self.set_status(f"Faturas revisadas 2.6.65.13: {stats.get('faturas',0)} faturas, {stats.get('itens',0)} itens canônicos, {stats.get('sem_comprovante',0)} sem comprovante, {stats.get('complementares',0)} complementares OK, {stats.get('fora',0)} fora da base.")
            except Exception:
                pass
        except Exception as exc:
            try:
                print("[HOTFIX FATURAS 2.6.64] erro no process:", exc)
            except Exception:
                pass
            _log_error(exc, "process_invoices_2664")
        return result

    def patched_build_2664(self, only_problem_invoices=False):
        try:
            return _build_sheets_canonical(self, only_problem_invoices)
        except Exception as exc:
            _log_error(exc, "build_invoice_report_sheets_2664")
            raise RuntimeError(f"Falha ao construir o relatório canônico: {exc}") from exc

    def _export_2664(self, *args, **kwargs):
        try:
            sheets = _build_sheets_canonical(self, False)
            path = _write_report_file(self, sheets)
            _refresh_ui_from_cache(self)
            _notify(self, "Central CT-e / DACTE", f"Relatório de faturas gerado com sucesso:\n\n{path}", error=False)
            return str(path)
        except Exception as exc:
            log_path = _log_error(exc, "exportar_relatorio_2664")
            extra = f"\n\nLog do erro:\n{log_path}" if log_path else ""
            _notify(self, "Central CT-e / DACTE", f"Erro ao gerar relatório de faturas.\n{exc}{extra}", error=True)
            return None

    try:
        FaturasPage.process_invoices = patched_process_2664
        FaturasPage.build_invoice_report_sheets = patched_build_2664
        for _name in ("export_report", "export_invoice_report", "exportar_relatorio", "exportar_relatorio_faturas", "export_faturas_report"):
            try:
                setattr(FaturasPage, _name, _export_2664)
            except Exception:
                pass
        FaturasPage._hotfix_faturas_2664 = True
        FaturasPage.rebuild_faturas_canonicas_2664 = _rebuild_canonical
    except Exception:
        pass
    try:
        if hasattr(_main, "APP_VERSION"):
            _main.APP_VERSION = "Beta 2.6.65.13 Rota do Recebedor e Método Percentual"
    except Exception:
        pass


_central_cte_hotfix_faturas_2664_start()

# ============================================================================
# HOTFIX 2.6.65.16 - INFORMAÇÃO COMPLEMENTAR + HTML DOS XMLs MARCADOS
#
# A interface oficial do EXE é PySide6 e carrega este motor dinamicamente.
# O patch abaixo substitui a antiga ação "Auditar peso", habilita seleção
# múltipla de linhas e limita a geração de HTML às linhas marcadas. Na ausência
# de marcação, preserva-se o comportamento anterior usando o filtro visível.
# ============================================================================
def _central_cte_selected_or_visible_infos_266516(page):
    selected_infos = []
    try:
        table = getattr(page, "xml_table", None)
        rows = set()
        if table is not None and table.selectionModel() is not None:
            try:
                rows.update(index.row() for index in table.selectionModel().selectedRows())
            except Exception:
                rows.update(index.row() for index in table.selectedIndexes())
        role = 256  # Qt.UserRole
        try:
            from PySide6.QtCore import Qt as _Qt266516
            role = getattr(getattr(_Qt266516, "ItemDataRole", _Qt266516), "UserRole", getattr(_Qt266516, "UserRole", 256))
        except Exception:
            pass
        xml_rows = list(getattr(page, "xml_rows", []) or [])
        for row in sorted(rows):
            item = table.item(row, 0) if table is not None else None
            if item is None:
                continue
            try:
                idx = int(item.data(role))
            except Exception:
                continue
            if 0 <= idx < len(xml_rows):
                info = xml_rows[idx]
                if _central_cte_is_cte_info(info):
                    selected_infos.append(info)
    except Exception:
        selected_infos = []

    if selected_infos:
        return selected_infos, "marcados"
    try:
        visible = [info for info in list(page.visible_infos() or []) if _central_cte_is_cte_info(info)]
    except Exception:
        visible = [info for info in list(getattr(page, "xml_rows", []) or []) if _central_cte_is_cte_info(info)]
    return visible, "visíveis no filtro atual"


def _central_cte_hotfix_info_complementar_266516_start():
    import sys as _sys266516

    def _patch_class(_module, CTePage):
        if not isinstance(CTePage, type) or getattr(CTePage, "_hotfix_info_complementar_266516", False):
            return False

        _prev_build_actions = getattr(CTePage, "build_actions", None)
        _prev_setup_table = getattr(CTePage, "setup_table", None)

        def _qt_message(self, level, text):
            try:
                from PySide6.QtWidgets import QMessageBox
                func = getattr(QMessageBox, level)
                return func(self, APP_TITLE, text)
            except Exception:
                return None

        def patched_setup_table(self, table, *args, **kwargs):
            result = _prev_setup_table(self, table, *args, **kwargs) if callable(_prev_setup_table) else None
            try:
                from PySide6.QtWidgets import QAbstractItemView
                mode_enum = getattr(QAbstractItemView, "SelectionMode", QAbstractItemView)
                table.setSelectionMode(getattr(mode_enum, "ExtendedSelection"))
                behavior_enum = getattr(QAbstractItemView, "SelectionBehavior", QAbstractItemView)
                table.setSelectionBehavior(getattr(behavior_enum, "SelectRows"))
            except Exception:
                pass
            return result

        def patched_build_actions(self, root, *args, **kwargs):
            result = _prev_build_actions(self, root, *args, **kwargs) if callable(_prev_build_actions) else None
            try:
                from PySide6.QtWidgets import QMenu
                replacements = {
                    "Auditar peso": ("Adicionar informação complementar", self.audit_weight),
                    "Gerar HTML do selecionado": ("Gerar HTML único dos marcados", self.generate_single_html),
                    "Gerar HTMLs separados": ("Gerar HTMLs dos marcados", self.generate_htmls),
                }
                for menu in self.findChildren(QMenu):
                    for action in menu.actions():
                        current = str(action.text() or "").strip()
                        if current not in replacements:
                            continue
                        new_text, callback = replacements[current]
                        action.setText(new_text)
                        try:
                            action.triggered.disconnect()
                        except Exception:
                            pass
                        action.triggered.connect(callback)
            except Exception:
                pass
            return result

        def patched_add_complementary_information(self):
            infos = [info for info in list(getattr(self, "xml_rows", []) or []) if _central_cte_is_cte_info(info)]
            if not infos:
                _qt_message(self, "information", "Adicione ao menos um XML de CT-e antes de inserir a informação complementar.")
                return
            try:
                from PySide6.QtWidgets import (
                    QDialog, QVBoxLayout, QHBoxLayout, QLabel, QTextEdit,
                    QPushButton, QMessageBox,
                )
            except Exception as exc:
                _qt_message(self, "critical", f"Não foi possível abrir a janela de informação complementar:\n{exc}")
                return

            dialog = QDialog(self)
            dialog.setWindowTitle("Adicionar informação complementar")
            dialog.resize(650, 410)
            layout = QVBoxLayout(dialog)
            title = QLabel(f"A mesma informação será aplicada aos {len(infos)} CT-e(s) listados.")
            try:
                title.setStyleSheet("font-size:15px;font-weight:700;")
            except Exception:
                pass
            layout.addWidget(title)
            note = QLabel(
                "Ela será impressa abaixo do cálculo compacto. Quando o cálculo não existir, ficará na posição reservada a ele. "
                "O XML fiscal autorizado e assinado não será alterado."
            )
            note.setWordWrap(True)
            layout.addWidget(note)

            editor = QTextEdit()
            editor.setPlaceholderText("Digite aqui a informação complementar que será impressa em todos os CT-es listados...")
            existing = {get_complementary_print_information(info) for info in infos}
            existing.discard("")
            if len(existing) == 1:
                editor.setPlainText(next(iter(existing)))
            layout.addWidget(editor, 1)

            counter = QLabel()
            try:
                counter.setAlignment(2)  # Qt.AlignRight
            except Exception:
                pass
            layout.addWidget(counter)

            buttons = QHBoxLayout()
            buttons.addStretch(1)
            cancel_button = QPushButton("Cancelar")
            apply_button = QPushButton("Aplicar a todos")
            buttons.addWidget(cancel_button)
            buttons.addWidget(apply_button)
            layout.addLayout(buttons)

            def update_counter():
                length = len(editor.toPlainText())
                counter.setText(f"{length}/{CENTRAL_CTE_COMPLEMENTARY_INFO_MAX_CHARS} caracteres")
                try:
                    counter.setStyleSheet("color:#ed1b2f;" if length > CENTRAL_CTE_COMPLEMENTARY_INFO_MAX_CHARS else "")
                except Exception:
                    pass

            def apply_text():
                raw = _central_cte_clean_complementary_information(editor.toPlainText(), limit=False)
                if not raw:
                    QMessageBox.warning(dialog, APP_TITLE, "Digite a informação complementar.")
                    return
                if len(raw) > CENTRAL_CTE_COMPLEMENTARY_INFO_MAX_CHARS:
                    QMessageBox.warning(
                        dialog,
                        APP_TITLE,
                        f"O texto ultrapassa o limite de {CENTRAL_CTE_COMPLEMENTARY_INFO_MAX_CHARS} caracteres.",
                    )
                    return
                answer = QMessageBox.question(
                    dialog,
                    APP_TITLE,
                    f"Aplicar esta informação aos {len(infos)} CT-e(s) listados?\n\nO XML fiscal original permanecerá intacto.",
                )
                yes_value = getattr(getattr(QMessageBox, "StandardButton", QMessageBox), "Yes", getattr(QMessageBox, "Yes", None))
                if yes_value is not None and answer != yes_value:
                    return
                try:
                    count = apply_complementary_print_information(infos, raw)
                    try:
                        if hasattr(self, "set_status"):
                            self.set_status(f"Informação complementar aplicada a {count} CT-e(s).")
                    except Exception:
                        pass
                    dialog.accept()
                    QMessageBox.information(self, APP_TITLE, f"Informação complementar aplicada a {count} CT-e(s).")
                except Exception as exc:
                    QMessageBox.critical(dialog, APP_TITLE, f"Erro ao aplicar a informação complementar:\n\n{exc}")

            editor.textChanged.connect(update_counter)
            cancel_button.clicked.connect(dialog.reject)
            apply_button.clicked.connect(apply_text)
            update_counter()
            dialog.exec()

        def _clean_output_component_266520(value, fallback="ARQUIVO"):
            text = unicodedata.normalize("NFKD", str(value or ""))
            text = "".join(ch for ch in text if not unicodedata.combining(ch))
            text = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', ' ', text)
            text = re.sub(r'[^A-Za-z0-9. -]+', ' ', text)
            text = re.sub(r'[\s._-]+', ' ', text).strip(' .')
            return text or fallback

        def _partner_output_266520(info):
            result = info.get("validacao") or info.get("validation") or {}
            emit = info.get("emit") or {}
            for value in (
                result.get("partner_name"), result.get("nome_parceiro"), result.get("partner_id"),
                info.get("parceiro"), info.get("partner_name"), info.get("emitente"),
                emit.get("nome"), emit.get("fant"),
            ):
                if str(value or "").strip():
                    return _clean_output_component_266520(value, "PARCEIRO NAO IDENTIFICADO")
            return "PARCEIRO NAO IDENTIFICADO"

        def _cte_output_name_266520(info, used, extension):
            numero = _clean_output_component_266520(info.get("numero"), "SEM NUMERO")
            parceiro = _partner_output_266520(info)
            base_name = f"CT-e {numero} {parceiro}".strip()
            candidate = base_name
            serial = 2
            while candidate.casefold() in used:
                candidate = f"{base_name} ({serial})"
                serial += 1
            used.add(candidate.casefold())
            return candidate + extension

