# ============================================================================
# HOTFIX 2.6.65.17 - FILTRO XML/CT-e UNIFICADO COM OS STATUS ATUAIS
#
# Centraliza a classificação dos status usada pelo filtro e pelo relatório.
# Também separa status operacional de revisão manual, observação e NFs
# ignoradas, sem alterar o resultado financeiro ou a validação do CT-e.
# ============================================================================
CENTRAL_CTE_FILTER_GROUPS_266517 = (
    "Todos",
    "Não processado",
    "OK",
    "Divergente",
    "Revisão necessária",
    "Sem base ou vínculo",
    "Sem cadastro ou tabela",
    "Erro de leitura",
    "Outros",
)


def central_cte_status_group_266517(status):
    """Retorna a família única de um status de validação."""
    normalized = norm_text(str(status or "").strip())

    if not normalized or normalized in {
        "NAO VALIDADO", "NAO PROCESSADO", "AGUARDANDO", "PENDENTE DE PROCESSAMENTO"
    }:
        return "NÃO PROCESSADO"

    if normalized.startswith("OK"):
        return "OK"

    if "DIVERGENTE" in normalized:
        return "DIVERGENTE"

    # Casos que exigem decisão humana ou dados adicionais. Esta verificação
    # precisa vir antes das famílias genéricas de NF/REGRA.
    review_tokens = (
        "REVISAR", "REVISAO", "AMBIG", "MULTIPLAS ROTAS", "MULTIPLA ROTA",
        "REGRA PENDENTE", "REGRA EXTRA PENDENTE", "REGRA SEM VALOR",
        "REGRA EXTRA SEM VALOR", "FRETE PESO SEM DADOS", "EXTRA REVISAR",
        "DADOS INSUFICIENTES",
    )
    if any(token in normalized for token in review_tokens):
        return "REVISÃO NECESSÁRIA"

    error_tokens = (
        "ERRO XML", "ERRO DE LEITURA", "ERRO AO LER", "NAO E CT-E",
        "NAO E CTE", "NF NAO LIDA", "XML INVALIDO", "XML MALFORMADO",
    )
    if any(token in normalized for token in error_tokens) or normalized.startswith("ERRO"):
        return "ERRO DE LEITURA"

    base_tokens = (
        "NF INCOMPATIVEL", "NF NAO ENCONTRADA", "NF FORA DA BASE",
        "FORA DA BASE", "FORA DO PERIODO", "FORA DA BASE / PERIODO",
        "ORIGINAL NAO ENCONTRADO", "BASE NAO CARREGADA", "SEM BASE",
        "SEM VINCULO", "VINCULO NAO ENCONTRADO",
    )
    if any(token in normalized for token in base_tokens):
        return "SEM BASE OU VÍNCULO"

    cadastro_tokens = (
        "TABELAS NAO CARREGADAS", "TABELA NAO CARREGADA", "SEM TABELA",
        "PARCEIRO SEM CADASTRO", "SEM PARCEIRO", "PARCEIRO NAO IDENTIFICADO",
        "REGRA NAO ENCONTRADA", "SEM REGRA", "CADASTRO NAO ENCONTRADO",
    )
    if any(token in normalized for token in cadastro_tokens):
        return "SEM CADASTRO OU TABELA"

    # Fallbacks para status antigos e variantes ainda existentes no histórico.
    if "BASE" in normalized or normalized.startswith("NF") or "ORIGINAL" in normalized or "PERIODO" in normalized:
        return "SEM BASE OU VÍNCULO"
    if "PARCEIRO" in normalized or "REGRA" in normalized or "TABELA" in normalized:
        return "SEM CADASTRO OU TABELA"

    return "OUTROS"


def _central_cte_has_ignored_nfs_266517(info):
    result = (info or {}).get("validacao") or {}
    ignored = []
    for key in ("nfs_ignoradas", "nfs_nao_encontradas", "nfs_incompativeis"):
        value = result.get(key)
        if isinstance(value, (list, tuple, set)):
            ignored.extend(str(item).strip() for item in value if str(item).strip())
        elif str(value or "").strip():
            ignored.append(str(value).strip())
    return bool(ignored or result.get("validacao_parcial"))


def _central_cte_raw_status_266517(info):
    result = (info or {}).get("validacao") or {}
    status = str(result.get("status") or "").strip()
    return status or "NÃO PROCESSADO"


def _central_cte_filter_info_matches_266517(info, filters=None, ui=None):
    """Função pura usada pelo filtro PySide e pelos testes de regressão."""
    filters = filters or {}
    info = info or {}
    result = info.get("validacao") or {}
    ui = ui or {}

    raw_status = _central_cte_raw_status_266517(info)
    group = str(filters.get("group") or "Todos")
    if norm_text(group) not in ("", "TODOS"):
        if norm_text(central_cte_status_group_266517(raw_status)) != norm_text(group):
            return False

    exact = str(filters.get("exact") or "Todos")
    if norm_text(exact) not in ("", "TODOS") and norm_text(raw_status) != norm_text(exact):
        return False

    review_mode = norm_text(filters.get("review") or "Todos")
    reviewed = norm_text(info.get("revisao_manual", "")) == "REVISADO"
    if review_mode == "REVISADO" and not reviewed:
        return False
    if review_mode == "NAO REVISADO" and reviewed:
        return False

    observation_mode = norm_text(filters.get("observation") or "Todos")
    has_observation = bool(str(info.get("observacao_manual", "") or "").strip())
    if observation_mode == "COM OBSERVACAO" and not has_observation:
        return False
    if observation_mode == "SEM OBSERVACAO" and has_observation:
        return False

    ignored_mode = norm_text(filters.get("ignored") or "Todos")
    has_ignored = _central_cte_has_ignored_nfs_266517(info)
    if ignored_mode == "COM NFS IGNORADAS" and not has_ignored:
        return False
    if ignored_mode == "SEM NFS IGNORADAS" and has_ignored:
        return False

    text = norm_text(filters.get("search") or "")
    nf_query = norm_text(filters.get("nf") or "")
    partner_query = norm_text(filters.get("partner") or "")
    city_query = norm_text(filters.get("city") or "")
    charge = str(filters.get("charge") or "Todos")
    component = str(filters.get("component") or "Todos")

    ignored_text = " ".join(
        str(value or "") for key in ("nfs_ignoradas", "nfs_nao_encontradas", "nfs_incompativeis")
        for value in ((result.get(key) or []) if isinstance(result.get(key), (list, tuple, set)) else [result.get(key)])
    )
    hay_parts = [
        ui.get("numero", info.get("numero", "")), ui.get("serie", info.get("serie", "")),
        ui.get("emitente", info.get("emitente", "")), ui.get("destinatario", info.get("destinatario", "")),
        ui.get("nf", result.get("nf", "")), ui.get("cidade", info.get("destino", "")),
        ui.get("tipo_cob", result.get("tipo_cobranca", "")),
        ui.get("componente", result.get("componente_comparado", "")), raw_status,
        ui.get("arquivo", info.get("arquivo", "")), result.get("detalhe", ""),
        info.get("observacao_manual", ""), info.get("revisao_manual", ""), ignored_text,
    ]
    hay = norm_text(" ".join(str(value or "") for value in hay_parts))
    if text and text not in hay:
        return False

    nf_text = norm_text(" ".join(str(value or "") for value in [ui.get("nf", ""), result.get("nf", ""), ignored_text]))
    if nf_query and nf_query not in nf_text:
        return False

    partner_text = norm_text(" ".join(str(value or "") for value in [ui.get("emitente", ""), info.get("emitente", ""), result.get("partner_id", "")]))
    if partner_query and partner_query not in partner_text:
        return False

    city_text = norm_text(" ".join(str(value or "") for value in [ui.get("cidade", ""), info.get("destino", ""), (info.get("dest") or {}).get("mun", "")]))
    if city_query and city_query not in city_text:
        return False

    if norm_text(charge) not in ("", "TODOS"):
        actual_charge = norm_text(ui.get("tipo_cob", result.get("tipo_cobranca", "")))
        if actual_charge != norm_text(charge):
            return False

    if norm_text(component) not in ("", "TODOS"):
        actual_component = norm_text(ui.get("componente", result.get("componente_comparado", "")))
        if norm_text(component) not in actual_component:
            return False

    return True


def _central_cte_report_bucket_266517(status):
    group = central_cte_status_group_266517(status)
    return {
        "OK": "OK",
        "DIVERGENTE": "DIVERGENTES",
        "SEM BASE OU VÍNCULO": "SEM_BASE",
        "SEM CADASTRO OU TABELA": "SEM_PARCEIRO_REGRA",
        "REVISÃO NECESSÁRIA": "REVISAO_ERROS",
        "ERRO DE LEITURA": "REVISAO_ERROS",
    }.get(group, "OUTROS")


# O relatório e o filtro passam a usar a mesma família de status.
report_bucket = _central_cte_report_bucket_266517


